#!/usr/bin/env Rscript
# TYROBP transcriptome figure-code collection
# All executable stages use actual saved input tables. No synthetic data and no
# code digitized from screenshots are used. Original native R plotting functions
# are retained wherever recovered. See README and figure_code_map.csv for scope.
# Running this file with no options prints help; it does not start heavy analyses.
if (.Platform$OS.type=="windows") {
  invisible(suppressWarnings(try(Sys.setlocale("LC_CTYPE","English_United States.utf8"),silent=TRUE)))
}
options(encoding="UTF-8")
.script_arg <- grep("^--file=",commandArgs(trailingOnly=FALSE),value=TRUE)
.tyrobp_package_root <- if(length(.script_arg)) dirname(normalizePath(sub("^--file=","",.script_arg[[1]]),winslash="/",mustWork=TRUE)) else getwd()
options(tyrobp.package.root=.tyrobp_package_root)

# Transcriptome code integration: native R stages for supplied Images 1-3.
# Original plotting functions/styles are preserved wherever recovered.
# Default stages redraw verified cached results rather than refit inconsistent legacy models.
# Each function accepts data_root (the preserved code/ directory structure) and output_root.
# No package installation, network download, or writing into source inputs occurs.

bulk_require_packages <- function(packages) {
  missing <- packages[!vapply(packages,requireNamespace,logical(1),quietly=TRUE)]
  if(length(missing))stop("Install required R packages before this stage: ",paste(missing,collapse=", "))
  for(pkg in packages)suppressPackageStartupMessages(library(pkg,character.only=TRUE))
}
bulk_plot_functions <- list()
bulk_stage_specs <- list()


# ===== Native source section: fig1_pca =====

bulk_plot_functions[["fig1_pca"]] <- function() {
  pca_advanced_plot <- function(mat, batch_info, title, file=NULL, variance_pct){
    data_pca <- list(x=as.matrix(mat[, c("PC1", "PC2")]))
    pc_var <- variance_pct / 100  # \u65b9\u5dee\u89e3\u91ca\u6bd4\u4f8b
    pca_df <- data.frame(
      Sample = rownames(data_pca$x),
      PC1   = data_pca$x[,1],
      PC2   = data_pca$x[,2],
      Batch = factor(batch_info, levels=unique(batch_info))
    )
    n_batch <- length(unique(batch_info))
    mycol <- brewer.pal(min(n_batch, 8), "Set1")
    if(n_batch > 8) mycol <- colorRampPalette(brewer.pal(9,"Set1"))(n_batch)
    pc1_lab <- paste0("PC1 (", round(pc_var[1]*100, 1),"%)")
    pc2_lab <- paste0("PC2 (", round(pc_var[2]*100, 1),"%)")
    
    p <- ggplot(pca_df, aes(x = PC1, y = PC2, color = Batch)) +
      geom_point(size=4, alpha=0.90) +
      stat_ellipse(aes(fill=Batch), geom="polygon", alpha=0.14, linetype=2, show.legend=FALSE) +
      scale_color_manual(values = mycol) +
      scale_fill_manual(values = mycol) +
      labs(title=title, x=pc1_lab, y=pc2_lab, color="Batch") +
      theme_bw(base_size=14) +
      theme(
        panel.grid.major = element_line(colour="gray90", linetype=2),
        legend.title = element_text(face="bold"),
        legend.background = element_rect(colour="black", fill=NA, size=0.25),
        plot.title = element_text(size=16, face="bold"),
        axis.title = element_text(face="bold")
      )
    if(!is.null(file)){
      ggsave(file, p, width=8, height=6)
    }
    return(p)
  }
  
  
  # Cached PC coordinates preserve the analysis version shown in the supplied figure.
  # Variance percentages below were read from the original vector PDF axis labels.
  # They cannot be re-estimated from only the first two PC coordinate columns.
  for (when in c("before","after")) {
    tab <- read.delim(paste0("PCA_scores_",when,".txt"), check.names=FALSE)
    rownames(tab) <- tab$Sample
    vv <- if (when=="before") c(64.6,6.5) else c(15.3,12.7)
    tt <- if(when=="before") "PCA Before Batch Effect Removal" else "PCA After Batch Effect Removal"
    pca_advanced_plot(tab, tab$Batch, tt, paste0("Fig1_",if(when=="before")"A" else "B","_PCA.pdf"), variance_pct=vv)
  }
}

bulk_stage_specs[["fig1_pca"]] <- list(files=c("06.\u6570\u636e\u5408\u5e76\u53bb\u6279\u6b21\u5f52\u4e00\u5316/Processed_Data/PCA_scores_before.txt","06.\u6570\u636e\u5408\u5e76\u53bb\u6279\u6b21\u5f52\u4e00\u5316/Processed_Data/PCA_scores_after.txt"),packages=c("ggplot2","RColorBrewer"))


# ===== Native source section: fig1_volcano =====

bulk_plot_functions[["fig1_volcano"]] <- function() {
  threshold_logFC <- 1
  threshold_adjP <- 0.05
  label_top_each <- 20
  all_diff_results <- read.csv("DE_results.csv", check.names=FALSE)
  rownames(all_diff_results) <- all_diff_results$Gene
  all_diff_results$Gene <- NULL
  # ========================== 7. \u7f8e\u5316\u706b\u5c71\u56fe\uff1a\u6e10\u53d8\u8272 + \u6c14\u6ce1\u5927\u5c0f + Top\u57fa\u56e0\u6807\u7b7e ==========================
  step7_start <- Sys.time()
  cat("[Step 7] \u5f00\u59cb\u7ed8\u5236\u7f8e\u5316\u706b\u5c71\u56fe...\n")
  
  volcano_data <- all_diff_results
  volcano_data$Gene <- rownames(volcano_data)
  volcano_data$logFC <- as.numeric(volcano_data$logFC)
  volcano_data$adj.P.Val <- as.numeric(volcano_data$adj.P.Val)
  
  # \u9632\u6b62adj.P.Val\u4e3a0\u5bfc\u81f4-log10\u4e3aInf
  min_positive_p <- suppressWarnings(min(volcano_data$adj.P.Val[volcano_data$adj.P.Val > 0], na.rm = TRUE))
  if (!is.finite(min_positive_p)) min_positive_p <- 1e-300
  volcano_data$adj.P.Val[!is.finite(volcano_data$adj.P.Val) | volcano_data$adj.P.Val <= 0] <- min_positive_p * 0.1
  
  volcano_data$negLog10FDR <- -log10(volcano_data$adj.P.Val)
  
  volcano_data$Group <- "Not Significant"
  volcano_data$Group[volcano_data$logFC > threshold_logFC & volcano_data$adj.P.Val < threshold_adjP] <- "Up regulated"
  volcano_data$Group[volcano_data$logFC < -threshold_logFC & volcano_data$adj.P.Val < threshold_adjP] <- "Down regulated"
  
  up_count <- sum(volcano_data$Group == "Up regulated", na.rm = TRUE)
  down_count <- sum(volcano_data$Group == "Down regulated", na.rm = TRUE)
  not_count <- sum(volcano_data$Group == "Not Significant", na.rm = TRUE)
  
  # \u9009\u62e9\u6807\u7b7e\u57fa\u56e0\uff1a\u5982\u679c\u663e\u8457\u57fa\u56e0\u4e0d\u591a\u5c31\u5168\u90e8\u6807\uff1b\u5426\u5219\u6bcf\u4fa7\u6309adj.P.Val\u6700\u5c0f\u4f18\u5148\u6807\u6ce8
  sig_data <- volcano_data[volcano_data$Group != "Not Significant", , drop = FALSE]
  
  if (nrow(sig_data) <= label_top_each * 2) {
    label_genes <- sig_data$Gene
    cat("\u663e\u8457\u5dee\u5f02\u57fa\u56e0\u6570\u91cf\u4e0d\u591a\uff0c\u5168\u90e8\u6807\u8bb0\uff1a", length(label_genes), "\u4e2a\u57fa\u56e0\n")
  } else {
    up_data <- sig_data[sig_data$Group == "Up regulated", , drop = FALSE]
    down_data <- sig_data[sig_data$Group == "Down regulated", , drop = FALSE]
  
    up_data <- up_data[order(up_data$adj.P.Val, -abs(up_data$logFC)), , drop = FALSE]
    down_data <- down_data[order(down_data$adj.P.Val, -abs(down_data$logFC)), , drop = FALSE]
  
    up_label <- head(up_data$Gene, min(label_top_each, nrow(up_data)))
    down_label <- head(down_data$Gene, min(label_top_each, nrow(down_data)))
  
    label_genes <- unique(c(up_label, down_label))
    cat("\u6807\u8bb0\u4e0a\u8c03Top", length(up_label), "\u548c\u4e0b\u8c03Top", length(down_label),
        "\uff0c\u5171", length(label_genes), "\u4e2a\u57fa\u56e0\n")
  }
  
  volcano_data$label_gene <- ifelse(volcano_data$Gene %in% label_genes, volcano_data$Gene, "")
  
  # \u8ba1\u7b97\u5750\u6807\u8303\u56f4
  x_limit <- max(abs(volcano_data$logFC), threshold_logFC * 2, na.rm = TRUE) * 1.12
  y_max <- max(volcano_data$negLog10FDR, -log10(threshold_adjP) * 1.5, na.rm = TRUE) * 1.12
  
  size_breaks <- pretty(volcano_data$negLog10FDR, n = 5)
  size_breaks <- size_breaks[size_breaks > 0 & size_breaks <= max(volcano_data$negLog10FDR, na.rm = TRUE)]
  
  gradient_volcano <- ggplot(volcano_data, aes(x = logFC, y = negLog10FDR)) +
  
    # \u70b9\u989c\u8272\u6309\u7167logFC\u8fde\u7eed\u6e10\u53d8\uff0c\u5927\u5c0f\u6309\u7167\u663e\u8457\u6027\u5f3a\u5f31\u53d8\u5316
    geom_point(aes(color = logFC, size = negLog10FDR), alpha = 0.85) +
  
    # \u88ab\u6807\u6ce8\u57fa\u56e0\u52a0\u9ed1\u8272\u5916\u6846\uff0c\u4fbf\u4e8e\u5b9a\u4f4d
    geom_point(data = subset(volcano_data, label_gene != ""),
               aes(size = negLog10FDR),
               shape = 21,
               fill = NA,
               color = "black",
               stroke = 1.1,
               show.legend = FALSE) +
  
    scale_color_gradientn(
      colors = c("#2B83BA", "#5AAE61", "#A6D96A", "#FFFFBF", "#FEE08B", "#FDAE61", "#D7191C"),
      values = scales::rescale(seq(-x_limit, x_limit, length.out = 7)),
      limits = c(-x_limit, x_limit),
      oob = scales::squish,
      name = "log2FC"
    ) +
  
    scale_size_continuous(
      range = c(0.7, 6.5),
      name = "-log10(FDR)",
      breaks = size_breaks,
      labels = round(size_breaks, 1)
    ) +
  
    geom_vline(xintercept = c(-threshold_logFC, threshold_logFC),
               linetype = "dashed", color = "grey45", size = 0.6) +
    geom_hline(yintercept = -log10(threshold_adjP),
               linetype = "dashed", color = "grey45", size = 0.6) +
  
    geom_text_repel(
      data = subset(volcano_data, label_gene != ""),
      aes(label = label_gene),
      size = 3.1,
      max.overlaps = Inf,
      box.padding = 0.45,
      point.padding = 0.25,
      segment.color = "grey40",
      segment.size = 0.3,
      fontface = "italic",
      color = "black",
      show.legend = FALSE
    ) +
  
    # \u4e0a\u4e0b\u8c03\u65b9\u5411\u4e0e\u6570\u91cf\u6807\u6ce8
    annotate("segment", x = -x_limit * 0.50, xend = -x_limit * 0.88,
             y = y_max * 0.94, yend = y_max * 0.94,
             arrow = arrow(length = unit(0.22, "cm"), type = "closed"),
             color = "#2B83BA", size = 1.0) +
    annotate("text", x = -x_limit * 0.69, y = y_max * 0.94,
             label = paste0("Down (", down_count, ")"),
             color = "#2B83BA", fontface = "bold", size = 4.2, vjust = -0.8) +
  
    annotate("segment", x = x_limit * 0.50, xend = x_limit * 0.88,
             y = y_max * 0.94, yend = y_max * 0.94,
             arrow = arrow(length = unit(0.22, "cm"), type = "closed"),
             color = "#D7191C", size = 1.0) +
    annotate("text", x = x_limit * 0.69, y = y_max * 0.94,
             label = paste0("Up (", up_count, ")"),
             color = "#D7191C", fontface = "bold", size = 4.2, vjust = -0.8) +
  
    annotate("text", x = x_limit * 0.98, y = -log10(threshold_adjP),
             label = paste0("FDR = ", threshold_adjP),
             hjust = 1, vjust = -0.5, size = 3.3, color = "grey30") +
  
    coord_cartesian(xlim = c(-x_limit, x_limit), ylim = c(0, y_max), clip = "off") +
  
    labs(
      title = "Volcano Plot",
      subtitle = paste0("Up: ", up_count, " | Down: ", down_count, " | Not significant: ", not_count),
      x = "Log2 Fold Change",
      y = "-Log10 Adjusted P-value"
    ) +
  
    theme_bw(base_size = 12) +
    theme(
      plot.title = element_text(face = "bold", hjust = 0.5, size = 16),
      plot.subtitle = element_text(hjust = 0.5, size = 11, color = "grey30"),
      axis.title = element_text(face = "bold", size = 12),
      axis.text = element_text(color = "black", size = 10),
      panel.grid.major = element_blank(),
      panel.grid.minor = element_blank(),
      panel.border = element_rect(color = "black", size = 1.1),
      legend.position = "right",
      legend.background = element_rect(fill = "white", color = "grey80", size = 0.4),
      legend.key = element_rect(fill = "white"),
      legend.title = element_text(face = "bold", size = 10),
      legend.text = element_text(size = 9),
      plot.margin = margin(15, 20, 12, 12)
    ) +
  
    guides(
      color = guide_colorbar(
        title = "log2FC",
        title.position = "top",
        title.hjust = 0.5,
        barwidth = 1.1,
        barheight = 9,
        frame.colour = "black",
        frame.linewidth = 0.4,
        ticks.colour = "black",
        order = 1
      ),
      size = guide_legend(
        title = "-log10(FDR)",
        title.position = "top",
        title.hjust = 0.5,
        override.aes = list(alpha = 1, color = "grey30"),
        order = 2
      )
    )
  
  # \u540c\u65f6\u4fdd\u5b58\u4e3a\u65b0\u6587\u4ef6\u540d\u548c\u539f\u6587\u4ef6\u540d\uff0c\u65b9\u4fbf\u66ff\u6362\u539f\u7ed3\u679c
  ggsave("DE_volcano_gradient.pdf", gradient_volcano, width = 9, height = 7.5, dpi = 300)
  ggsave("DE_volcano.pdf", gradient_volcano, width = 9, height = 7.5, dpi = 300)
  ggsave("DE_volcano_with_labels.pdf", gradient_volcano, width = 9, height = 7.5, dpi = 300)
  
  step7_end <- Sys.time()
  cat("[Step 7] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:", round(difftime(step7_end, step7_start, units="secs"), 2), "\u79d2\n\n")
  
  
}

bulk_stage_specs[["fig1_volcano"]] <- list(files=c("07.\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u7684\u5dee\u5f02\u5206\u6790-\u591a\u6570\u636e/DE_results.csv"),packages=c("ggplot2","ggrepel","RColorBrewer","scales","grid"))


# ===== Native source section: fig1_wgcna_cached =====

bulk_plot_functions[["fig1_wgcna_cached"]] <- function() {
  
  sf <- read.delim("SoftThreshold_FitIndices.txt", check.names=FALSE)
  selection <- read.delim("Selected_soft_power.txt", check.names=FALSE)
  power <- selection$optimalPower[1]
  pdf("Fig1_D_SoftThreshold.pdf",width=10,height=5)
  par(mfrow=c(1,2))
  plot(sf$Power,sf$signedR2,type="n",xlab="Soft Threshold (power)",ylab="Signed Scale-Free Topology Fit Index",main="Scale Independence")
  text(sf$Power,sf$signedR2,labels=sf$Power,col="blue",cex=.8)
  abline(h=selection$r2Cut[1],col="red",lwd=2,lty=2)
  abline(v=power,col="darkgreen",lwd=2,lty=2)
  plot(sf$Power,sf$mean.k.,type="n",xlab="Soft Threshold (power)",ylab="Mean Connectivity",main="Mean Connectivity")
  text(sf$Power,sf$mean.k.,labels=sf$Power,col="blue",cex=.8)
  abline(v=power,col="darkgreen",lwd=2,lty=2)
  dev.off()
  moduleTraitCor <- as.matrix(read.delim("Module_trait_correlation.txt",row.names=1,check.names=FALSE))
  moduleTraitPvalues <- as.matrix(read.delim("Module_trait_pvalue.txt",row.names=1,check.names=FALSE))
  corDF <- melt(moduleTraitCor)
  pvalDF <- melt(moduleTraitPvalues)
  heatmapDF <- merge(corDF, pvalDF, by = c("Var1", "Var2"))
  colnames(heatmapDF) <- c("Module", "Trait", "Correlation", "Pvalue")
  
  pdf("Module_trait_Heatmap.pdf", width = 7, height = 6)
  ggplot(heatmapDF, aes(x = Trait, y = Module, fill = Correlation)) +
    geom_tile(color = "white") +                              # \u7ed8\u5236\u5e26\u767d\u8272\u8fb9\u6846\u7684\u65b9\u683c
    scale_fill_gradient2(low = "blue", high = "red", mid = "white",
                         midpoint = 0, limit = c(-1,1), space = "Lab",
                         name = "Correlation") +
    geom_text(aes(label = sprintf("%.2f\n(%.1e)", Correlation, Pvalue)), size = 3) +
    theme_minimal() +                                         # \u4f7f\u7528\u7b80\u6d01\u4e3b\u9898
    theme(axis.text.x = element_text(angle = 45, vjust = 1, hjust = 1, size = 12),
          axis.text.y = element_text(size = 12),
          plot.title = element_text(hjust = 0.5, size = 16)) +
    ggtitle("Module-Trait Correlation Heatmap")
  dev.off()
  
  df <- read.delim("MM_GS_distribution_data.txt", check.names=FALSE)
  for (mod in unique(df$Module)) {
    z <- df[df$Module==mod,]
    MM <- z$MM; GS <- z$GS
    if(sum(is.finite(MM)&is.finite(GS))<3)next
    ct <- cor.test(MM,GS); corVal <- ct$estimate; pVal <- ct$p.value
    pdf(paste0("MM_vs_GS_",mod,".pdf"),width=6,height=6)
    plot(MM,GS,xlab=paste("Module Membership in",mod,"module"),ylab="Gene Significance for Disease",
         main=paste0("Module: ",mod,"\ncor=",signif(corVal,3),", p=",format(pVal,scientific=TRUE,digits=2)),
         pch=21,bg=adjustcolor(mod,alpha.f=.6),col="black",cex=1.5)
    abline(lm(GS~MM),col="blue",lwd=2,lty=2)
    abline(v=.8,h=.2,col="orange",lty=3,lwd=1.5)
    dev.off()
  }
}

bulk_stage_specs[["fig1_wgcna_cached"]] <- list(files=c("08.\u4e24\u7ec4\u7684WGCNA\u5206\u6790/WGCNA_results_modified/SoftThreshold_FitIndices.txt","08.\u4e24\u7ec4\u7684WGCNA\u5206\u6790/WGCNA_results_modified/Selected_soft_power.txt","08.\u4e24\u7ec4\u7684WGCNA\u5206\u6790/WGCNA_results_modified/Module_trait_correlation.txt","08.\u4e24\u7ec4\u7684WGCNA\u5206\u6790/WGCNA_results_modified/Module_trait_pvalue.txt","08.\u4e24\u7ec4\u7684WGCNA\u5206\u6790/WGCNA_results_modified/MM_GS_distribution_data.txt"),packages=c("ggplot2","reshape2"))


# ===== Native source section: fig1_intersection =====

bulk_plot_functions[["fig1_intersection"]] <- function() {
  gene_list <- list(DEGs=unique(readLines("DEG_gene.txt")),ModuleGenes_green=unique(readLines("ModuleGenes_green.txt")))
  stopifnot(length(gene_list$DEGs)==880,length(gene_list$ModuleGenes_green)==1305,
            length(intersect(gene_list$DEGs,gene_list$ModuleGenes_green))==399)
  pdf("Fig1_H_DEG_WGCNA_venn.pdf",width=10,height=10)
  print(ggvenn(gene_list,show_percentage=TRUE,stroke_color="white",stroke_size=1.5,
               fill_color=viridis::viridis(2),set_name_color="black",set_name_size=8,text_size=6,text_color="black"))
  dev.off()
  write.csv(data.frame(Gene=Reduce(intersect,gene_list)),"IntersectionGenes.csv",row.names=FALSE,quote=FALSE)
}

bulk_stage_specs[["fig1_intersection"]] <- list(files=c("09.\u5dee\u5f02\u5206\u6790\u548cWGCNA\u6a21\u5757\u57fa\u56e0\u53d6\u4ea4\u96c6/DEG_gene.txt","09.\u5dee\u5f02\u5206\u6790\u548cWGCNA\u6a21\u5757\u57fa\u56e0\u53d6\u4ea4\u96c6/ModuleGenes_green.txt"),packages=c("ggplot2","ggvenn","viridis"))


# ===== Native source section: fig2_kegg =====

bulk_plot_functions[["fig2_kegg"]] <- function() {
  pvalueFilter <- .05;adjPvalFilter <- 1
  KEGG <- read.delim("KEGG.txt",check.names=FALSE)
  # Define the number of pathways to display
  showNum <- 30
  if (nrow(KEGG) < showNum) {
    showNum <- nrow(KEGG)
  }
  
  # ---------------------------------------------------
  # 10. Create a bar plot (\u7528 pvalue \u5c55\u793a)
  # ---------------------------------------------------
  # Top pathways\uff1a\u6309 pvalue \u6392\u5e8f
  topKEGG <- KEGG[order(KEGG$pvalue), ][1:showNum, ]
  topKEGG$Description <- factor(topKEGG$Description, levels = rev(topKEGG$Description))
  
  # y\u8f74/\u586b\u5145\uff1a-log10(pvalue)
  p_bar <- ggplot(topKEGG, aes(x = Description, y = -log10(pvalue), fill = -log10(pvalue))) +
    geom_bar(stat = "identity", width = 0.8) +
    coord_flip() +
    scale_fill_gradientn(colors = brewer.pal(7, "YlOrRd")) +
    theme_minimal(base_size = 14) +
    labs(x = "KEGG Pathway", y = "-log10(p-value)", title = "KEGG Pathway Enrichment Analysis (p-value)") +
    theme(plot.title = element_text(hjust = 0.5, face = "bold", color = "darkblue"))
  
  ggsave("barplot_custom_pvalue.pdf", p_bar, width = 8, height = 7)
  
  # ---------------------------------------------------
  # 11. Create a dot plot (\u7528 pvalue \u5c55\u793a)
  # ---------------------------------------------------
  if (all(grepl("/", topKEGG$GeneRatio))) {
    topKEGG$GeneRatio_num <- sapply(topKEGG$GeneRatio, function(x) {
      parts <- unlist(strsplit(x, "/"))
      as.numeric(parts[1]) / as.numeric(parts[2])
    })
  } else {
    topKEGG$GeneRatio_num <- as.numeric(topKEGG$GeneRatio)
  }
  
  # \u989c\u8272\uff1apvalue\uff08\u800c\u4e0d\u662f p.adjust\uff09
  p_dot <- ggplot(topKEGG, aes(x = GeneRatio_num, y = Description, size = Count, color = pvalue)) +
    geom_point(alpha = 0.8) +
    scale_color_gradientn(colors = brewer.pal(7, "Spectral")) +
    theme_classic(base_size = 14) +
    labs(x = "Gene Ratio", y = "KEGG Pathway", title = "KEGG Dotplot (p-value)") +
    theme(plot.title = element_text(hjust = 0.5, face = "bold", color = "darkred"))
  
  ggsave("dotplot_custom_pvalue.pdf", p_dot, width = 8, height = 7)
  
}

bulk_stage_specs[["fig2_kegg"]] <- list(files=c("KEGG/KEGG.txt"),packages=c("ggplot2","RColorBrewer"))


# ===== Native source section: fig2_go =====

bulk_plot_functions[["fig2_go"]] <- function() {
  library(dplyr)
  library(ggplot2)
  library(RColorBrewer)
  
  # \u8bfb\u53d6GO\u5bcc\u96c6\u5206\u6790\u7684\u7ed3\u679c\uff08\u4f60\u7684filteredGO\uff09
  # \u786e\u4fdd\u8fd9\u91cc\u8bfb\u53d6\u7684\u662f\u7ecf\u8fc7 pvalue \u8fc7\u6ee4\u540e\u7684 GO_results.txt
  filteredGO <- read.table("GO_results.txt", header=TRUE, sep="	", stringsAsFactors=FALSE, check.names=FALSE)
  
  # TRUE\u5219\u5168\u90e8\u4e09\u7c7b\uff08BP, CC, MF\uff09\uff0c\u5982\u679c\u53ea\u8981\u5176\u4e2d\u67d0\u51e0\u7c7b\uff0c\u6539\u4e3a\u53ea\u7559\u9700\u8981\u7684\u7c7b\u522b\u540d\u79f0
  filteredGO_sub <- filteredGO %>% filter(ONTOLOGY %in% c("BP", "CC", "MF"))
  
  # \u5206\u522b\u5bf9\u6bcf\u4e2a\u5927\u7c7b\u53d6Top10\u6700\u663e\u8457\u7684GO term\uff0c\u4f9d\u636e pvalue
  topGO <- filteredGO_sub %>%
    group_by(ONTOLOGY) %>%
    slice_min(order_by = pvalue, n = 10) %>% # \u4f9d\u636e pvalue \u6392\u5e8f
    ungroup() %>%
    arrange(ONTOLOGY, pvalue) # \u4f9d\u636e pvalue \u6392\u5e8f
  
  # \u9ad8\u7ea7\uff1a\u4fdd\u8bc1\u6bcf\u4e00\u7c7b\u5185\uff0cDescription\u662f\u4ece\u6700\u663e\u8457\u5230\u6700\u4e0d\u663e\u8457\u6392\u5e8f\uff0c\u663e\u793a\u65f6\u4e0d\u4e71
  topGO <- topGO %>% 
    group_by(ONTOLOGY) %>%
    mutate(Description = factor(Description, levels = rev(unique(Description)))) %>%
    ungroup()
  
  # GeneRatio\u8f6c\u6570\u503c\uff08\u4e3b\u8981\u7528\u4e8e\u6c14\u6ce1\u56fe\u6a2a\u8f74\uff09
  topGO$GeneRatio_num <- sapply(topGO$GeneRatio, function(x) {
    sp <- unlist(strsplit(as.character(x), "/"))
    as.numeric(sp[1]) / as.numeric(sp[2])
  })
  
  # GO\u5bcc\u96c6\u6c14\u6ce1\u56fe\uff08\u5206\u9762\uff0c\u548cKEGG\u4e00\u6837\uff09
  dot_colors <- brewer.pal(7, "Spectral")
  p_dot <- ggplot(topGO, aes(x = GeneRatio_num, y = Description, size = Count, color = pvalue)) + # \u989c\u8272\u6539\u4e3a pvalue
    geom_point(alpha = 0.8) +
    facet_wrap(~ ONTOLOGY, scales = "free_y", ncol = 1) +
    scale_color_gradientn(colors = dot_colors) +
    labs(x = "Gene Ratio", y = "GO Term", title = "GO Dotplot (BP/CC/MF)") +
    theme_classic(base_size = 14) +
    theme(
      plot.title = element_text(hjust = 0.5, face = "bold", color = "darkred"),
      strip.text = element_text(size = 15, face = "bold", color = "black"),
      axis.text.y = element_text(size = 11)
    )
  ggsave("GO_dotplot_custom.pdf", p_dot, width = 12, height = 12)
}

bulk_stage_specs[["fig2_go"]] <- list(files=c("GO/GO_results.txt"),packages=c("ggplot2","dplyr","RColorBrewer"))


# ===== Native source section: fig2_ppi_export =====

bulk_plot_functions[["fig2_ppi_export"]] <- function() {
  ed <- read.delim("string_interactions_short.tsv",check.names=FALSE)
  rank <- read.csv("rank.csv",skip=1,check.names=FALSE)
  nodes <- head(rank,25)
  sub <- ed[ed[[1]]%in%nodes$Name & ed[[2]]%in%nodes$Name,,drop=FALSE]
  write.table(ed,"PPI_full_STRING_edges.tsv",sep="\t",row.names=FALSE,quote=FALSE)
  write.csv(nodes,"PPI_top25_degree_nodes.csv",row.names=FALSE)
  write.table(sub,"PPI_top25_induced_edges.tsv",sep="\t",row.names=FALSE,quote=FALSE)
  writeLines(c("The original STRING/Cytoscape network view is external-software output.",
               "The available archive contains the STRING edges and cytoHubba Degree ranks.",
               "The original Cytoscape .cys session, node positions, layout parameters and style were not found.",
               "Import the exported node/edge tables in Cytoscape; no synthetic layout is substituted here."),
             "PPI_REPRODUCTION_NOTE.txt")
}

