# ===== Native source section: fig3_lasso =====

bulk_plot_functions[["fig3_lasso"]] <- function() {
  path_long_active <- read.csv("LASSO_path_plot_data_original_result.csv",check.names=FALSE)
  cv_results_table <- read.csv("LASSO_CV_plot_data_original_result.csv",check.names=FALSE)
  coef_dataframe <- read.csv("LASSO_selected_coefficients_plot_data_original_result.csv",check.names=FALSE)
  selected_genes <- unique(path_long_active$Gene[path_long_active$Selected=="Selected genes"])
  stopifnot(length(selected_genes)==12)
  imin <- which.min(cv_results_table$cvm)
  lambda_min <- cv_results_table$lambda[imin]
  one_se_limit <- cv_results_table$cvup[imin]
  lambda_1se <- max(cv_results_table$lambda[cv_results_table$cvm<=one_se_limit])
  cv_model <- list(lambda.min=lambda_min,lambda.1se=lambda_1se)
  label_df <- path_long_active %>% dplyr::filter(Gene%in%selected_genes) %>% dplyr::group_by(Gene) %>%
              dplyr::filter(log_lambda==min(log_lambda,na.rm=TRUE)) %>% dplyr::ungroup()
  theme_lasso_beauty <- function(base_size = 14) {
    theme_classic(base_size = base_size) +
      theme(
        plot.title = element_text(
          face = "bold",
          size = base_size + 2,
          hjust = 0.5,
          color = "black"
        ),
        plot.subtitle = element_text(
          size = base_size - 1,
          hjust = 0.5,
          color = "grey35"
        ),
        axis.title = element_text(
          face = "bold",
          size = base_size,
          color = "black"
        ),
        axis.text = element_text(
          color = "black",
          size = base_size - 1
        ),
        axis.line = element_line(
          linewidth = 0.7,
          color = "black"
        ),
        axis.ticks = element_line(
          linewidth = 0.6,
          color = "black"
        ),
        panel.grid.major = element_line(
          color = "grey88",
          linewidth = 0.35
        ),
        panel.grid.minor = element_blank(),
        legend.position = "top",
        legend.title = element_blank(),
        legend.text = element_text(size = base_size - 1),
        plot.caption = element_text(
          size = base_size - 3,
          color = "grey40",
          hjust = 0
        ),
        plot.margin = margin(10, 15, 10, 10)
      )
  }
  
  
  ############################################################
  ## 4. \u4fdd\u5b58\u51fd\u6570\uff1a\u540c\u65f6\u4fdd\u5b58 PDF \u548c 600 dpi PNG
  ############################################################
  
  save_beauty_plot <- function(p, filename, width = 6.5, height = 5.5) {
    
    ggsave(
      filename = paste0(filename, ".pdf"),
      plot = p,
      width = width,
      height = height,
      units = "in"
    )
    
    ggsave(
      filename = paste0(filename, ".png"),
      plot = p,
      width = width,
      height = height,
      units = "in",
      dpi = 600
    )
  }
  
  p_lasso_path <- ggplot(
    path_long_active,
    aes(
      x = log_lambda,
      y = Coefficient,
      group = Gene
    )
  ) +
    geom_line(
      data = path_long_active %>% dplyr::filter(Selected == "Other genes"),
      color = "grey75",
      linewidth = 0.55,
      alpha = 0.75
    ) +
    geom_line(
      data = path_long_active %>% dplyr::filter(Selected == "Selected genes"),
      aes(color = Gene),
      linewidth = 1.05,
      alpha = 0.95
    ) +
    geom_vline(
      xintercept = log(cv_model$lambda.min),
      linetype = "dashed",
      linewidth = 0.8,
      color = "#D62828"
    ) +
    geom_vline(
      xintercept = log(cv_model$lambda.1se),
      linetype = "dotted",
      linewidth = 0.8,
      color = "#2B6CB0"
    ) +
    ggrepel::geom_text_repel(
      data = label_df,
      aes(label = Gene),
      size = 3.6,
      fontface = "bold",
      color = "black",
      box.padding = 0.35,
      point.padding = 0.25,
      min.segment.length = 0,
      segment.color = "grey50",
      seed = 1993,
      max.overlaps = Inf
    ) +
    annotate(
      "text",
      x = log(cv_model$lambda.min),
      y = max(path_long_active$Coefficient, na.rm = TRUE),
      label = "lambda.min",
      hjust = -0.05,
      vjust = 1.2,
      size = 3.6,
      fontface = "bold",
      color = "#D62828"
    ) +
    annotate(
      "text",
      x = log(cv_model$lambda.1se),
      y = max(path_long_active$Coefficient, na.rm = TRUE),
      label = "lambda.1se",
      hjust = -0.05,
      vjust = 2.4,
      size = 3.6,
      fontface = "bold",
      color = "#2B6CB0"
    ) +
    labs(
      title = "LASSO Coefficient Profiles",
      subtitle = paste0(
        "Selected genes at lambda.min: ",
        length(selected_genes)
      ),
      x = "Log(lambda)",
      y = "Coefficient",
      caption = "Dashed red line: lambda.min; dotted blue line: lambda.1se."
    ) +
    theme_lasso_beauty() +
    theme(
      legend.position = "none"
    )
  
  save_beauty_plot(
    p_lasso_path,
    filename = "LASSO_path_beauty_original_result",
    width = 7.2,
    height = 5.8
  )
  
  
  ############################################################
  ## 7. \u6574\u7406\u4ea4\u53c9\u9a8c\u8bc1\u66f2\u7ebf\u6570\u636e
  ############################################################
  
  cv_plot_df <- cv_results_table %>%
    dplyr::mutate(
      log_lambda = log(lambda)
    )
  
  lambda_min_df <- cv_plot_df %>%
    dplyr::filter(abs(lambda - cv_model$lambda.min) == min(abs(lambda - cv_model$lambda.min)))
  
  lambda_1se_df <- cv_plot_df %>%
    dplyr::filter(abs(lambda - cv_model$lambda.1se) == min(abs(lambda - cv_model$lambda.1se)))
  
  
  ############################################################
  ## 8. \u7f8e\u5316 LASSO \u4ea4\u53c9\u9a8c\u8bc1\u8bef\u5dee\u56fe
  ############################################################
  
  p_cv <- ggplot(
    cv_plot_df,
    aes(x = log_lambda, y = cvm)
  ) +
    geom_errorbar(
      aes(ymin = cvlo, ymax = cvup),
      width = 0.03,
      color = "grey70",
      linewidth = 0.45
    ) +
    geom_line(
      color = "#2B6CB0",
      linewidth = 1.1
    ) +
    geom_point(
      size = 2.6,
      shape = 21,
      fill = "white",
      color = "#2B6CB0",
      stroke = 0.8
    ) +
    geom_vline(
      xintercept = log(cv_model$lambda.min),
      linetype = "dashed",
      linewidth = 0.8,
      color = "#D62828"
    ) +
    geom_vline(
      xintercept = log(cv_model$lambda.1se),
      linetype = "dotted",
      linewidth = 0.8,
      color = "#2B6CB0"
    ) +
    geom_point(
      data = lambda_min_df,
      aes(x = log_lambda, y = cvm),
      size = 4.2,
      shape = 21,
      fill = "#D62828",
      color = "black",
      stroke = 0.8
    ) +
    geom_point(
      data = lambda_1se_df,
      aes(x = log_lambda, y = cvm),
      size = 4.2,
      shape = 21,
      fill = "#2B6CB0",
      color = "black",
      stroke = 0.8
    ) +
    ggrepel::geom_label_repel(
      data = lambda_min_df,
      aes(
        x = log_lambda,
        y = cvm,
        label = paste0(
          "lambda.min\n",
          "log(lambda) = ",
          sprintf("%.2f", log_lambda),
          "\nDeviance = ",
          sprintf("%.3f", cvm)
        )
      ),
      size = 3.6,
      fontface = "bold",
      fill = "white",
      label.size = 0.35,
      box.padding = 0.45,
      point.padding = 0.35,
      seed = 1993
    ) +
    ggrepel::geom_label_repel(
      data = lambda_1se_df,
      aes(
        x = log_lambda,
        y = cvm,
        label = paste0(
          "lambda.1se\n",
          "log(lambda) = ",
          sprintf("%.2f", log_lambda),
          "\nDeviance = ",
          sprintf("%.3f", cvm)
        )
      ),
      size = 3.6,
      fontface = "bold",
      fill = "white",
      label.size = 0.35,
      box.padding = 0.45,
      point.padding = 0.35,
      seed = 1993
    ) +
    scale_x_continuous(
      breaks = scales::pretty_breaks(n = 7)
    ) +
    scale_y_continuous(
      breaks = scales::pretty_breaks(n = 6)
    ) +
    labs(
      title = "Cross-Validation Curve for LASSO Model",
      subtitle = "Binomial deviance based on 10-fold cross-validation",
      x = "Log(lambda)",
      y = "Mean cross-validated deviance",
      caption = "Error bars indicate upper and lower cross-validation estimates."
    ) +
    theme_lasso_beauty()
  
  save_beauty_plot(
    p_cv,
    filename = "LASSO_CV_curve_beauty_original_result",
    width = 7.2,
    height = 5.8
  )
  
  
  p_lasso_combined <- p_lasso_path + p_cv +
    patchwork::plot_annotation(
      tag_levels = "A",
      theme = theme(
        plot.tag = element_text(
          face = "bold",
          size = 18
        )
      )
    )
  
  save_beauty_plot(
    p_lasso_combined,
    filename = "LASSO_combined_beauty_original_result",
    width = 13.5,
    height = 5.8
  )
  
  
}

bulk_stage_specs[["fig3_lasso"]] <- list(files=c("11.marching learning/15lasso\u56de\u5f52/LASSO_path_plot_data_original_result.csv","11.marching learning/15lasso\u56de\u5f52/LASSO_CV_plot_data_original_result.csv","11.marching learning/15lasso\u56de\u5f52/LASSO_selected_coefficients_plot_data_original_result.csv"),packages=c("ggplot2","dplyr","tidyr","ggrepel","patchwork","scales"))


# ===== Native source section: fig3_svm =====

bulk_plot_functions[["fig3_svm"]] <- function() {
  curve <- read.csv("SVM_RFE_curve_data_original.csv",check.names=FALSE)
  errors <- curve$CV_Error
  optimalFeatureCount <- which.min(errors);optimalError <- min(errors);optimalAccuracy <- 1-optimalError
  # Original cohort class proportions (39 controls, 273 UC) supply the original no-information reference.
  no.info <- 39/(39+273)
  theme_svm_beauty <- function(base_size = 14) {
    theme_classic(base_size = base_size) +
      theme(
        plot.title = element_text(
          face = "bold",
          size = base_size + 2,
          hjust = 0.5,
          color = "black"
        ),
        plot.subtitle = element_text(
          size = base_size - 1,
          hjust = 0.5,
          color = "grey35"
        ),
        axis.title = element_text(
          face = "bold",
          size = base_size,
          color = "black"
        ),
        axis.text = element_text(
          color = "black",
          size = base_size - 1
        ),
        axis.line = element_line(
          linewidth = 0.7,
          color = "black"
        ),
        axis.ticks = element_line(
          linewidth = 0.6,
          color = "black"
        ),
        panel.grid.major = element_line(
          color = "grey88",
          linewidth = 0.35
        ),
        panel.grid.minor = element_blank(),
        legend.position = "top",
        legend.title = element_blank(),
        legend.text = element_text(size = base_size - 1),
        plot.caption = element_text(
          size = base_size - 3,
          color = "grey40",
          hjust = 0
        ),
        plot.margin = margin(10, 15, 10, 10)
      )
  }
  
  
  ############################################################
  ## 5. \u4fdd\u5b58\u51fd\u6570\uff1a\u540c\u65f6\u4fdd\u5b58 PDF \u548c 600 dpi PNG
  ############################################################
  
  save_beauty_plot <- function(p, filename, width = 6, height = 5) {
    
    ggsave(
      filename = paste0(filename, ".pdf"),
      plot = p,
      width = width,
      height = height,
      units = "in"
    )
    
    ggsave(
      filename = paste0(filename, ".png"),
      plot = p,
      width = width,
      height = height,
      units = "in",
      dpi = 600
    )
  }
  
  
  ############################################################
  ## 6. \u7f8e\u5316\u66f2\u7ebf\u7ed8\u56fe\u51fd\u6570
  ############################################################
  
  PlotSVMRFECurve <- function(values,
                              optimal_n,
                              baseline,
                              metric = c("error", "accuracy")) {
    
    metric <- match.arg(metric)
    
    df <- data.frame(
      Feature_Number = seq_along(values),
      Value = as.numeric(values)
    )
    
    df <- df[is.finite(df$Value), , drop = FALSE]
    
    if (nrow(df) == 0) {
      stop("\u7ed8\u56fe\u6570\u636e\u4e3a\u7a7a\uff0c\u8bf7\u68c0\u67e5 errors \u662f\u5426\u6b63\u5e38\u3002")
    }
    
    opt_df <- df[df$Feature_Number == optimal_n, , drop = FALSE]
    
    if (nrow(opt_df) == 0) {
      if (metric == "error") {
        opt_df <- df[which.min(df$Value), , drop = FALSE]
      } else {
        opt_df <- df[which.max(df$Value), , drop = FALSE]
      }
    }
    
    if (metric == "error") {
      
      main_title <- "SVM-RFE Cross-Validation Error"
      sub_title <- "Lower error indicates better feature subset"
      y_lab <- "10-fold CV error"
      line_col <- "#2B6CB0"
      point_col <- "#2B6CB0"
      opt_col <- "#D62828"
      
      opt_label <- sprintf(
        "Optimal features = %d\nCV error = %.1f%%",
        opt_df$Feature_Number,
        100 * opt_df$Value
      )
      
    } else {
      
      main_title <- "SVM-RFE Cross-Validation Accuracy"
      sub_title <- "Higher accuracy indicates better feature subset"
      y_lab <- "10-fold CV accuracy"
      line_col <- "#2F855A"
      point_col <- "#2F855A"
      opt_col <- "#D62828"
      
      opt_label <- sprintf(
        "Optimal features = %d\nCV accuracy = %.1f%%",
        opt_df$Feature_Number,
        100 * opt_df$Value
      )
    }
    
    y_min <- max(
      0,
      min(c(df$Value, baseline), na.rm = TRUE) - 0.05
    )
    
    y_max <- min(
      1,
      max(c(df$Value, baseline), na.rm = TRUE) + 0.05
    )
    
    p <- ggplot(df, aes(x = Feature_Number, y = Value)) +
      geom_hline(
        yintercept = baseline,
        linetype = "dashed",
        linewidth = 0.7,
        color = "grey45"
      ) +
      geom_line(
        linewidth = 1.2,
        color = line_col
      ) +
      geom_point(
        size = 2.8,
        shape = 21,
        stroke = 0.8,
        fill = "white",
        color = point_col
      ) +
      geom_vline(
        xintercept = opt_df$Feature_Number,
        linetype = "dotted",
        linewidth = 0.8,
        color = opt_col
      ) +
      geom_point(
        data = opt_df,
        aes(x = Feature_Number, y = Value),
        size = 4.2,
        shape = 21,
        stroke = 1,
        fill = opt_col,
        color = "black"
      ) +
      ggrepel::geom_label_repel(
        data = opt_df,
        aes(label = opt_label),
        size = 4,
        fontface = "bold",
        color = "black",
        fill = "white",
        label.size = 0.35,
        box.padding = 0.5,
        point.padding = 0.4,
        min.segment.length = 0,
        segment.color = "grey40",
        seed = 1993
      ) +
      scale_x_continuous(
        breaks = scales::pretty_breaks(n = 8),
        expand = expansion(mult = c(0.03, 0.08))
      ) +
      scale_y_continuous(
        labels = scales::percent_format(accuracy = 1),
        limits = c(y_min, y_max),
        expand = expansion(mult = c(0.02, 0.06))
      ) +
      labs(
        title = main_title,
        subtitle = sub_title,
        x = "Number of selected features",
        y = y_lab,
        caption = "Dashed horizontal line indicates the no-information baseline."
      ) +
      theme_svm_beauty()
    
    return(p)
  }
  
  
  ############################################################
  ## 7. \u7ed8\u5236\u539f\u59cb\u7ed3\u679c\u5bf9\u5e94\u7684\u9519\u8bef\u7387\u66f2\u7ebf
  ############################################################
  
  p_error <- PlotSVMRFECurve(
    values = errors,
    optimal_n = optimalFeatureCount,
    baseline = no.info,
    metric = "error"
  )
  
  save_beauty_plot(
    p_error,
    filename = "SVM_RFE_error_curve_beauty_original_result",
    width = 6.2,
    height = 5.2
  )
  
  
  ############################################################
  ## 8. \u7ed8\u5236\u539f\u59cb\u7ed3\u679c\u5bf9\u5e94\u7684\u51c6\u786e\u7387\u66f2\u7ebf
  ############################################################
  
  # \u6ce8\u610f\uff1a
  # \u4f60\u7684\u539f\u59cb\u4ee3\u7801\u4e2d accuracy \u56fe\u7684 no.info \u4ecd\u7136\u4f7f\u7528\u4e86 no.info\u3002
  # \u4e3a\u4e86\u4e0d\u6539\u53d8\u539f\u56fe\u903b\u8f91\uff0c\u8fd9\u91cc\u4e5f\u4fdd\u7559\u540c\u6837\u7684 baseline\u3002
  # \u5982\u679c\u4f60\u60f3\u66f4\u4e25\u8c28\uff0caccuracy \u7684 baseline \u5e94\u8be5\u4f7f\u7528 1 - no.info\u3002
  
  p_accuracy <- PlotSVMRFECurve(
    values = 1 - errors,
    optimal_n = optimalFeatureCount,
    baseline = no.info,
    metric = "accuracy"
  )
  
  save_beauty_plot(
    p_accuracy,
    filename = "SVM_RFE_accuracy_curve_beauty_original_result",
    width = 6.2,
    height = 5.2
  )
  
  
  ############################################################
  ## 9. \u5408\u5e76\u9519\u8bef\u7387\u548c\u51c6\u786e\u7387\u66f2\u7ebf
  ############################################################
  
  p_combined <- p_error + p_accuracy +
    patchwork::plot_annotation(
      tag_levels = "A",
      theme = theme(
        plot.tag = element_text(
          face = "bold",
          size = 18
        )
      )
    )
  
  save_beauty_plot(
    p_combined,
    filename = "SVM_RFE_combined_plots_beauty_original_result",
    width = 12,
    height = 5.4
  )
  
  
}

