# ===== Native source section: fig3_rf =====

bulk_plot_functions[["fig3_rf"]] <- function() {
  geneScores <- read.table("All_Gene_Scores.txt",header=TRUE,sep="\t",check.names=FALSE)
  geneScores <- geneScores[order(-geneScores$Importance),]
  topGenes <- readLines("Top_RF_Genes.txt")
  theme_rf_beauty <- function(base_size = 14) {
    theme_classic(base_size = base_size) +
      theme(
        plot.title = element_text(
          face = "bold",
          size = base_size + 2,
          hjust = 0.5,
          color = "black"
        ),
        plot.subtitle = element_text(
          size = base_size - 1,
          hjust = 0.5,
          color = "grey35"
        ),
        axis.title = element_text(
          face = "bold",
          size = base_size,
          color = "black"
        ),
        axis.text = element_text(
          color = "black",
          size = base_size - 1
        ),
        axis.text.y = element_text(
          face = "bold",
          color = "black"
        ),
        axis.line = element_line(
          linewidth = 0.7,
          color = "black"
        ),
        axis.ticks = element_line(
          linewidth = 0.6,
          color = "black"
        ),
        panel.grid.major.x = element_line(
          color = "grey88",
          linewidth = 0.35
        ),
        panel.grid.major.y = element_blank(),
        panel.grid.minor = element_blank(),
        legend.position = "top",
        legend.title = element_blank(),
        legend.text = element_text(size = base_size - 1),
        plot.caption = element_text(
          size = base_size - 3,
          color = "grey40",
          hjust = 0
        ),
        plot.margin = margin(10, 20, 10, 10)
      )
  }
  
  
  ############################################################
  ## 4. \u4fdd\u5b58\u51fd\u6570\uff1a\u540c\u65f6\u4fdd\u5b58 PDF \u548c 600 dpi PNG
  ############################################################
  
  save_rf_plot <- function(p, filename, width = 7, height = 5.5) {
    
    ggsave(
      filename = paste0(filename, ".pdf"),
      plot = p,
      width = width,
      height = height,
      units = "in"
    )
    
    ggsave(
      filename = paste0(filename, ".png"),
      plot = p,
      width = width,
      height = height,
      units = "in",
      dpi = 600
    )
  }
  
  
  top10_df <- geneScores %>%
    dplyr::filter(Gene %in% topGenes) %>%
    dplyr::arrange(Importance)
  
  # \u4e3a\u4e86\u4e25\u683c\u6309\u539f\u59cbTop_RF_Genes.txt\u6392\u5e8f\uff0c\u4e5f\u4fdd\u5b58\u539f\u59cb\u6392\u540d
  top_rank_df <- data.frame(
    Gene = topGenes,
    Original_Rank = seq_along(topGenes),
    stringsAsFactors = FALSE
  )
  
  top10_df <- top10_df %>%
    dplyr::left_join(top_rank_df, by = "Gene") %>%
    dplyr::arrange(desc(Importance))
  
  top10_df$Gene <- factor(
    top10_df$Gene,
    levels = rev(top10_df$Gene)
  )
  
  p_top10_bar <- ggplot(
    top10_df,
    aes(
      x = Gene,
      y = Importance
    )
  ) +
    geom_col(
      width = 0.72,
      fill = "#D62828",
      color = "black",
      linewidth = 0.25
    ) +
    geom_text(
      aes(
        label = sprintf("%.3f", Importance)
      ),
      hjust = -0.15,
      size = 3.6,
      fontface = "bold",
      color = "black"
    ) +
    coord_flip(clip = "off") +
    scale_y_continuous(
      expand = expansion(mult = c(0.02, 0.22)),
      breaks = scales::pretty_breaks(n = 6)
    ) +
    labs(
      title = "Top 10 Genes Selected by Random Forest",
      subtitle = "Original RF-selected genes without recalculation",
      x = NULL,
      y = "MeanDecreaseGini"
    ) +
    theme_rf_beauty() +
    theme(
      legend.position = "none"
    )
  
  save_rf_plot(
    p_top10_bar,
    filename = "RF_Top10_Gene_Importance_Barplot_beauty_original_result",
    width = 7.0,
    height = 5.5
  )
  
  
  
  rf_error_df <- read.csv("RF_error_curve_plot_data_original_result.csv",check.names=FALSE)
  rf_error_long <- tidyr::pivot_longer(rf_error_df,cols=-Trees,names_to="Error_Type",values_to="Error")
  rf_error_long$Error_Type <- factor(rf_error_long$Error_Type,levels=unique(rf_error_long$Error_Type))
  best_tree <- max(50,which.min(rf_error_df[["Overall OOB error"]]))
  best_error <- rf_error_df[best_tree,"Overall OOB error"]
  theme_rf_error_beauty <- function(base_size = 14) {
    theme_classic(base_size = base_size) +
      theme(
        plot.title = element_text(
          face = "bold",
          size = base_size + 2,
          hjust = 0.5,
          color = "black"
        ),
        plot.subtitle = element_text(
          size = base_size - 1,
          hjust = 0.5,
          color = "grey35"
        ),
        axis.title = element_text(
          face = "bold",
          size = base_size,
          color = "black"
        ),
        axis.text = element_text(
          color = "black",
          size = base_size - 1
        ),
        axis.line = element_line(
          linewidth = 0.7,
          color = "black"
        ),
        axis.ticks = element_line(
          linewidth = 0.6,
          color = "black"
        ),
        panel.grid.major = element_line(
          color = "grey88",
          linewidth = 0.35
        ),
        panel.grid.minor = element_blank(),
        legend.position = "top",
        legend.title = element_blank(),
        legend.text = element_text(size = base_size - 1),
        plot.caption = element_text(
          size = base_size - 3,
          color = "grey40",
          hjust = 0
        ),
        plot.margin = margin(10, 15, 10, 10)
      )
  }
  
  
  ############################################################
  ## 6. \u7f8e\u5316\u7ed8\u5236 OOB error \u66f2\u7ebf
  ############################################################
  
  # \u6839\u636e\u66f2\u7ebf\u6570\u91cf\u81ea\u52a8\u8bbe\u7f6e\u989c\u8272
  error_types <- levels(rf_error_long$Error_Type)
  
  my_cols <- c(
    "Overall OOB error" = "#111111",
    "con OOB error" = "#D62828",
    "tra OOB error" = "#2B6CB0",
    "tre OOB error" = "#2B6CB0",
    "Control OOB error" = "#D62828",
    "Treat OOB error" = "#2B6CB0",
    "Normal OOB error" = "#D62828",
    "UC OOB error" = "#2B6CB0"
  )
  
  # \u5982\u679c\u7c7b\u522b\u540d\u79f0\u4e0d\u5728\u4e0a\u9762\uff0c\u81ea\u52a8\u8865\u5145\u989c\u8272
  missing_types <- setdiff(error_types, names(my_cols))
  if (length(missing_types) > 0) {
    extra_cols <- scales::hue_pal()(length(missing_types))
    names(extra_cols) <- missing_types
    my_cols <- c(my_cols, extra_cols)
  }
  
  my_cols <- my_cols[error_types]
  
  p_rf_error <- ggplot(
    rf_error_long,
    aes(
      x = Trees,
      y = Error,
      color = Error_Type,
      linetype = Error_Type
    )
  ) +
    geom_line(
      linewidth = 1.05,
      alpha = 0.95
    ) +
    geom_vline(
      xintercept = best_tree,
      linetype = "dashed",
      linewidth = 0.8,
      color = "#D62828"
    ) +
    geom_point(
      data = data.frame(
        Trees = best_tree,
        Error = best_error,
        Error_Type = "Overall OOB error"
      ),
      aes(x = Trees, y = Error),
      inherit.aes = FALSE,
      size = 4.0,
      shape = 21,
      fill = "#D62828",
      color = "black",
      stroke = 0.8
    ) +
    ggrepel::geom_label_repel(
      data = data.frame(
        Trees = best_tree,
        Error = best_error,
        Label = paste0(
          "Selected trees = ",
          best_tree,
          "\nOOB error = ",
          sprintf("%.2f%%", 100 * best_error)
        )
      ),
      aes(
        x = Trees,
        y = Error,
        label = Label
      ),
      inherit.aes = FALSE,
      size = 3.8,
      fontface = "bold",
      fill = "white",
      label.size = 0.35,
      box.padding = 0.5,
      point.padding = 0.4,
      segment.color = "grey45",
      seed = 1993
    ) +
    scale_color_manual(values = my_cols) +
    scale_linetype_manual(
      values = rep(
        c("solid", "dashed", "dotted", "dotdash", "longdash"),
        length.out = length(error_types)
      )
    ) +
    scale_x_continuous(
      breaks = scales::pretty_breaks(n = 8),
      expand = expansion(mult = c(0.02, 0.05))
    ) +
    scale_y_continuous(
      labels = scales::percent_format(accuracy = 1),
      breaks = scales::pretty_breaks(n = 6),
      expand = expansion(mult = c(0.03, 0.08))
    ) +
    labs(
      title = "Random Forest OOB Error Curve",
      subtitle = "Out-of-bag error changes with the number of trees",
      x = "Number of trees",
      y = "OOB error rate",
      caption = "The vertical dashed line indicates the selected tree number from the original RF analysis."
    ) +
    theme_rf_error_beauty()
  
  print(p_rf_error)
  
  
  ############################################################
  ## 7. \u4fdd\u5b58 PDF \u548c 600 dpi PNG
  ############################################################
  
  ggsave(
    filename = "RF_error_curve_beauty_original_result.pdf",
    plot = p_rf_error,
    width = 7.2,
    height = 5.6,
    units = "in"
  )
  
  ggsave(
    filename = "RF_error_curve_beauty_original_result.png",
    plot = p_rf_error,
    width = 7.2,
    height = 5.6,
    units = "in",
    dpi = 600
  )
  
  
  ############################################################
}

bulk_stage_specs[["fig3_rf"]] <- list(files=c("11.marching learning/16.\u968f\u673a\u751f\u6210\u6811/All_Gene_Scores.txt","11.marching learning/16.\u968f\u673a\u751f\u6210\u6811/Top_RF_Genes.txt","11.marching learning/16.\u968f\u673a\u751f\u6210\u6811/RF_error_curve_plot_data_original_result.csv"),packages=c("ggplot2","dplyr","tidyr","ggrepel","scales"))


# ===== Native source section: fig3_knn =====

bulk_plot_functions[["fig3_knn"]] <- function() {
  acc_df <- read.csv("KNN_RFE_Accuracy_Curve_Data_original_result.csv",check.names=FALSE)
  best_vars <- acc_df$Variables[which.max(acc_df$Accuracy)]
  best_point <- acc_df[acc_df$Variables==best_vars,,drop=FALSE][1,,drop=FALSE]
  gene_rank_df <- read.csv("KNN_Selected_Gene_Ranking_Data_original_result.csv",check.names=FALSE)
  imp_genes_best <- as.character(gene_rank_df$Gene)
  gene_rank_df$Gene <- factor(gene_rank_df$Gene,levels=rev(gene_rank_df$Gene))
  theme_knn_beauty <- function(base_size = 14) {
    theme_classic(base_size = base_size) +
      theme(
        plot.title = element_text(
          face = "bold",
          size = base_size + 2,
          hjust = 0.5,
          color = "black"
        ),
        plot.subtitle = element_text(
          size = base_size - 1,
          hjust = 0.5,
          color = "grey35"
        ),
        axis.title = element_text(
          face = "bold",
          size = base_size,
          color = "black"
        ),
        axis.text = element_text(
          color = "black",
          size = base_size - 1
        ),
        axis.line = element_line(
          linewidth = 0.7,
          color = "black"
        ),
        axis.ticks = element_line(
          linewidth = 0.6,
          color = "black"
        ),
        panel.grid.major = element_line(
          color = "grey88",
          linewidth = 0.35
        ),
        panel.grid.minor = element_blank(),
        legend.position = "top",
        legend.title = element_blank(),
        legend.text = element_text(size = base_size - 1),
        strip.background = element_rect(
          fill = "grey95",
          color = "black",
          linewidth = 0.5
        ),
        strip.text = element_text(
          face = "bold",
          size = base_size - 1,
          color = "black"
        ),
        plot.caption = element_text(
          size = base_size - 3,
          color = "grey40",
          hjust = 0
        ),
        plot.margin = margin(10, 15, 10, 10)
      )
  }
  
  
  ############################################################
  ## 5. \u4fdd\u5b58\u51fd\u6570\uff1aPDF + 600 dpi PNG
  ############################################################
  
  save_knn_plot <- function(p, filename, width = 7, height = 5.5) {
    
    ggsave(
      filename = paste0(filename, ".pdf"),
      plot = p,
      width = width,
      height = height,
      units = "in"
    )
    
    ggsave(
      filename = paste0(filename, ".png"),
      plot = p,
      width = width,
      height = height,
      units = "in",
      dpi = 600
    )
  }
  
  
  ############################################################
  ## 6. \u7f8e\u5316 KNN-RFE \u53d8\u91cf\u6570-\u51c6\u786e\u7387\u66f2\u7ebf
  ############################################################
  
  acc_df_plot <- acc_df %>%
    dplyr::mutate(
      ymin = pmax(0, Accuracy - sd),
      ymax = pmin(1, Accuracy + sd)
    )
  
  best_label <- paste0(
    "Best subset\n",
    best_point$Variables,
    " genes\nAccuracy = ",
    sprintf("%.3f", best_point$Accuracy)
  )
  
  p_acc <- ggplot(
    acc_df_plot,
    aes(x = Variables, y = Accuracy)
  ) +
    geom_ribbon(
      aes(ymin = ymin, ymax = ymax),
      fill = "#BDD7E7",
      alpha = 0.35
    ) +
    geom_line(
      linewidth = 1.25,
      color = "#2B6CB0"
    ) +
    geom_point(
      size = 3.2,
      shape = 21,
      fill = "white",
      color = "#2B6CB0",
      stroke = 0.9
    ) +
    geom_point(
      data = best_point,
      aes(x = Variables, y = Accuracy),
      size = 5,
      shape = 21,
      fill = "#D62828",
      color = "black",
      stroke = 0.9
    ) +
    geom_vline(
      xintercept = best_point$Variables,
      linetype = "dashed",
      linewidth = 0.75,
      color = "#D62828"
    ) +
    geom_text(
      aes(label = sprintf("%.3f", Accuracy)),
      vjust = -1.1,
      size = 3.8,
      fontface = "bold",
      color = "black"
    ) +
    ggrepel::geom_label_repel(
      data = best_point,
      aes(
        x = Variables,
        y = Accuracy,
        label = best_label
      ),
      size = 4,
      fontface = "bold",
      fill = "white",
      label.size = 0.35,
      box.padding = 0.5,
      point.padding = 0.4,
      segment.color = "grey45",
      seed = 1993
    ) +
    scale_x_continuous(
      breaks = acc_df_plot$Variables,
      expand = expansion(mult = c(0.05, 0.08))
    ) +
    scale_y_continuous(
      labels = scales::percent_format(accuracy = 1),
      limits = c(
        max(0.5, min(acc_df_plot$ymin, na.rm = TRUE) - 0.03),
        min(1, max(acc_df_plot$ymax, na.rm = TRUE) + 0.04)
      ),
      breaks = scales::pretty_breaks(n = 6)
    ) +
    labs(
      title = "KNN-RFE Model Performance",
      subtitle = "Cross-validated accuracy across different feature subset sizes",
      x = "Number of selected features",
      y = "Cross-validated accuracy",
      caption = "The red point indicates the original best feature subset."
    ) +
    theme_knn_beauty()
  
  save_knn_plot(
    p_acc,
    filename = "KNN_RFE_Accuracy_Curve_Beauty_original_result",
    width = 7.2,
    height = 5.6
  )
  
  
  ############################################################
  p_gene_rank <- ggplot(
    gene_rank_df,
    aes(
      x = Gene,
      y = RFE_Score
    )
  ) +
    geom_col(
      width = 0.72,
      fill = "#D62828",
      color = "black",
      linewidth = 0.25
    ) +
    geom_text(
      aes(label = paste0("#", Rank)),
      hjust = -0.15,
      size = 3.8,
      fontface = "bold",
      color = "black"
    ) +
    coord_flip(clip = "off") +
    scale_y_continuous(
      expand = expansion(mult = c(0.02, 0.20)),
      breaks = scales::pretty_breaks(n = 6)
    ) +
    labs(
      title = "Top Genes Selected by KNN-RFE",
      subtitle = paste0(
        "Original selected feature subset: ",
        length(imp_genes_best),
        " genes"
      ),
      x = NULL,
      y = "Relative RFE ranking score"
    ) +
    theme_knn_beauty() +
    theme(
      legend.position = "none",
      axis.text.y = element_text(face = "bold")
    )
  
  save_knn_plot(
    p_gene_rank,
    filename = "KNN_Selected_Gene_Ranking_Beauty_original_result",
    width = 7.0,
    height = 5.8
  )
  
  write.csv(
    gene_rank_df,
    file = "KNN_Selected_Gene_Ranking_Data_original_result.csv",
    row.names = FALSE
  )
  
  
  ############################################################
}

bulk_stage_specs[["fig3_knn"]] <- list(files=c("11.marching learning/KNN/KNN_RFE_Accuracy_Curve_Data_original_result.csv","11.marching learning/KNN/KNN_Selected_Gene_Ranking_Data_original_result.csv"),packages=c("ggplot2","dplyr","tidyr","ggrepel","patchwork","scales"))


# ===== Native source section: fig3_selection_intersection =====

bulk_plot_functions[["fig3_selection_intersection"]] <- function() {
  ls <- read.csv("LASSO_selected_coefficients_plot_data_original_result.csv",check.names=FALSE)
  sets <- list(Lasso=unique(ls$Gene),`SVM-RFE`=unique(readLines("SVM-RFE.gene.txt")),
               RF=unique(readLines("Top_RF_Genes.txt")),KNN=read.csv("KNN_BestModel_Gene_Names.csv")$Gene)
  core <- Reduce(intersect,sets)
  stopifnot(setequal(core,c("CASP1","MMP9","PECAM1","TYROBP")))
  write.csv(data.frame(Gene=core),"Four_method_common_genes.csv",row.names=FALSE)
  pdf("Fig3_E_Four_method_Venn_reconstructed.pdf",width=8,height=7)
  grid::grid.newpage()
  grid::grid.draw(VennDiagram::venn.diagram(sets,filename=NULL,
    fill=c("#8C8BC5","#FFFF99","#8FC98E","#EF9B9F"),alpha=.7,col="grey40",lwd=1,
    cex=1.2,cat.cex=1.2,cat.col=c("#4D4DA4","#8C8D36","#559C55","#D55C63")))
  dev.off()
}

