# ===== Native source section: fig3_gene_boxplots =====

bulk_plot_functions[["fig3_gene_boxplots"]] <- function() {
  cached <- read.csv("Filtered_Expression_Matrix.csv",row.names=1,check.names=FALSE)
  model_vars <- c("CASP1","MMP9","TYROBP","PECAM1")
  stopifnot(all(model_vars%in%names(cached)))
  df_expr <- cached[,intersect(c(model_vars,"GroupType"),names(cached)),drop=FALSE]
  set.seed(1993) # Fix jitter only; no statistical results are altered.
  # 2. \u521b\u5efa\u7bb1\u7ebf\u56fe\u8f93\u51fa\u6587\u4ef6\u5939
  # ===============================
  boxplot_dir <- "Individual_Gene_Boxplots"
  if (!dir.exists(boxplot_dir)) {
  dir.create(boxplot_dir)
  }
  # ===============================
  # 3. \u91cd\u65b0\u4ece\u6837\u672c\u540d\u63d0\u53d6\u5206\u7ec4
  # ===============================
  # \u6ce8\u610f\uff1a
  # \u8fd9\u91cc\u4e0d\u7528 df_expr$GroupType\uff0c\u56e0\u4e3a\u524d\u9762DCA\u6b65\u9aa4\u53ef\u80fd\u5df2\u7ecf\u628aGroupType\u8f6c\u62100/1
  # \u8fd9\u91cc\u91cd\u65b0\u4ece\u6837\u672c\u540d\u6700\u540e\u4e00\u4e2a\u4e0b\u5212\u7ebf\u540e\u7684\u5185\u5bb9\u63d0\u53d6\u5206\u7ec4
  plot_group <- gsub("(.*)_([A-Za-z0-9]+)$", "\\2", rownames(df_expr))
  plot_group <- trimws(plot_group)
  # ===============================
  # 4. \u624b\u52a8\u89c4\u8303\u5206\u7ec4\u540d\u79f0
  # ===============================
  # \u628a tra \u6539\u6210 UC
  plot_group[tolower(plot_group) %in% c("tra", "treat", "treated", "treatment")] <- "UC"
  # \u5176\u4ed6\u53ef\u80fd\u4ee3\u8868UC/\u75be\u75c5\u7ec4\u7684\u540d\u79f0\u4e5f\u7edf\u4e00\u6210UC
  plot_group[tolower(plot_group) %in% c("uc", "disease", "case", "patient")] <- "UC"
  # \u628a\u6b63\u5e38\u7ec4\u7edf\u4e00\u6210Control
  plot_group[tolower(plot_group) %in% c("normal", "control", "ctrl", "con", "healthy")] <- "Control"
  # \u5982\u679c\u4f60\u7684\u5206\u7ec4\u662f0/1\uff0c\u4e5f\u53ef\u4ee5\u81ea\u52a8\u8f6c\u6362
  plot_group[plot_group == "0"] <- "Control"
  plot_group[plot_group == "1"] <- "UC"
  # \u56fa\u5b9a\u663e\u793a\u987a\u5e8f\uff1aControl\u5728\u5de6\uff0cUC\u5728\u53f3
  if (all(c("Control", "UC") %in% unique(plot_group))) {
  plot_group <- factor(plot_group, levels = c("Control", "UC"))
  } else {
  plot_group <- factor(plot_group)
  }
  # \u68c0\u67e5\u662f\u5426\u4e3a\u4e8c\u5206\u7c7b
  if (nlevels(plot_group) != 2) {
  cat("\u5f53\u524d\u8bc6\u522b\u5230\u7684\u5206\u7ec4\u5982\u4e0b\uff1a\n")
  print(table(plot_group))
  stop("\u9519\u8bef\uff1a\u7bb1\u7ebf\u56fe\u7ed8\u5236\u8981\u6c42\u53ea\u6709\u4e24\u4e2a\u5206\u7ec4\uff0c\u8bf7\u68c0\u67e5\u6837\u672c\u540d\u4e2d\u7684\u5206\u7ec4\u4fe1\u606f\u3002")
  }
  group_levels <- levels(plot_group)
  cat("\u7bb1\u7ebf\u56fe\u5206\u7ec4\u4e3a\uff1a", group_levels[1], " vs ", group_levels[2], "\n")
  print(table(plot_group))
  # ===============================
  # 5. \u6574\u7406\u957f\u6570\u636e
  # ===============================
  df_boxplot <- data.frame(
  Sample = rownames(df_expr),
  Group = plot_group,
  df_expr[, model_vars, drop = FALSE],
  check.names = FALSE
  )
  df_boxplot_long <- tidyr::pivot_longer(
  df_boxplot,
  cols = dplyr::all_of(model_vars),
  names_to = "Gene",
  values_to = "Expression"
  )
  df_boxplot_long$Group <- factor(
  df_boxplot_long$Group,
  levels = group_levels
  )
  # ===============================
  # 6. \u8ba1\u7b97\u6bcf\u4e2a\u57fa\u56e0\u7684P\u503c
  # ===============================
  p_value_df <- data.frame()
  for (gene in model_vars) {
  temp_data <- df_boxplot_long[df_boxplot_long$Gene == gene, ]
  group1 <- temp_data$Expression[temp_data$Group == group_levels[1]]
  group2 <- temp_data$Expression[temp_data$Group == group_levels[2]]
  # \u4f7f\u7528Wilcoxon\u68c0\u9a8c\uff0c\u9002\u5408\u8868\u8fbe\u91cf\u6570\u636e\uff0c\u66f4\u7a33\u5065
  p_val <- tryCatch(
  wilcox.test(group1, group2, exact = FALSE)$p.value,
  error = function(e) NA
  )
  p_value_df <- rbind(
  p_value_df,
  data.frame(
  Gene = gene,
  Group1 = group_levels[1],
  Group2 = group_levels[2],
  Mean_Group1 = mean(group1, na.rm = TRUE),
  Mean_Group2 = mean(group2, na.rm = TRUE),
  Median_Group1 = median(group1, na.rm = TRUE),
  Median_Group2 = median(group2, na.rm = TRUE),
  P_Value = p_val,
  stringsAsFactors = FALSE
  )
  )
  }
  # FDR\u6821\u6b63
  p_value_df$FDR <- p.adjust(p_value_df$P_Value, method = "BH")
  # \u6dfb\u52a0\u663e\u8457\u6027\u6807\u7b7e
  p_value_df$Significance <- ifelse(
  is.na(p_value_df$P_Value), "NA",
  ifelse(
  p_value_df$P_Value < 0.001, "***",
  ifelse(
  p_value_df$P_Value < 0.01, "**",
  ifelse(p_value_df$P_Value < 0.05, "*", "ns")
  )
  )
  )
  # \u6dfb\u52a0\u8868\u8fbe\u65b9\u5411
  p_value_df$Expression_Trend <- ifelse(
  p_value_df$Mean_Group2 > p_value_df$Mean_Group1,
  paste0(group_levels[2], " higher"),
  paste0(group_levels[1], " higher")
  )
  # \u8f93\u51faP\u503c\u8868\u683c
  write.csv(
  p_value_df,
  file = "Individual_Gene_Boxplot_Pvalues.csv",
  row.names = FALSE
  )
  cat(">> \u6bcf\u4e2a\u57fa\u56e0\u7684P\u503c\u5df2\u8f93\u51fa\u81f3 Individual_Gene_Boxplot_Pvalues.csv\n")
  # ===============================
  # 7. \u8bbe\u7f6e\u989c\u8272
  # ===============================
  my_colors <- c("#4DBBD5", "#E64B35")
  names(my_colors) <- group_levels
  # ===============================
  # 8. \u4fdd\u5b58\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7bb1\u7ebf\u56fe
  # ===============================
  for (gene in model_vars) {
  temp_data <- df_boxplot_long[df_boxplot_long$Gene == gene, ]
  temp_p <- p_value_df[p_value_df$Gene == gene, ]
  y_max <- max(temp_data$Expression, na.rm = TRUE)
  y_min <- min(temp_data$Expression, na.rm = TRUE)
  y_range <- y_max - y_min
  if (y_range == 0) {
  y_range <- abs(y_max) * 0.1 + 1
  }
  # ===============================
  # \u5173\u952e\u4fee\u6539\uff1a
  # \u628aP\u503c\u62ec\u53f7\u7ebf\u3001\u661f\u53f7\u3001P\u503c\u6587\u5b57\u5206\u5f00\uff0c\u907f\u514d\u91cd\u53e0
  # ===============================
  y_bracket <- y_max + 0.20 * y_range
  y_tick_bottom <- y_bracket - 0.04 * y_range
  y_p_text <- y_bracket + 0.07 * y_range
  y_star <- y_bracket + 0.14 * y_range
  y_upper <- y_bracket + 0.24 * y_range
  p_text <- ifelse(
  is.na(temp_p$P_Value),
  "P = NA",
  ifelse(
  temp_p$P_Value < 0.001,
  "P < 0.001",
  paste0("P = ", signif(temp_p$P_Value, 3))
  )
  )
  p_single <- ggplot(
  temp_data,
  aes(x = Group, y = Expression, fill = Group)
  ) +
  geom_boxplot(
  width = 0.55,
  alpha = 0.88,
  outlier.shape = NA,
  linewidth = 0.8,
  color = "black"
  ) +
  geom_jitter(
  aes(color = Group),
  width = 0.15,
  size = 2.3,
  alpha = 0.78
  ) +
  stat_summary(
  fun = median,
  geom = "crossbar",
  width = 0.42,
  linewidth = 0.35,
  color = "black"
  ) +
  annotate(
  "segment",
  x = 1,
  xend = 2,
  y = y_bracket,
  yend = y_bracket,
  linewidth = 0.75,
  color = "black"
  ) +
  annotate(
  "segment",
  x = 1,
  xend = 1,
  y = y_bracket,
  yend = y_tick_bottom,
  linewidth = 0.75,
  color = "black"
  ) +
  annotate(
  "segment",
  x = 2,
  xend = 2,
  y = y_bracket,
  yend = y_tick_bottom,
  linewidth = 0.75,
  color = "black"
  ) +
  annotate(
  "text",
  x = 1.5,
  y = y_star,
  label = temp_p$Significance,
  size = 5.2,
  fontface = "bold"
  ) +
  annotate(
  "text",
  x = 1.5,
  y = y_p_text,
  label = p_text,
  size = 4.1,
  fontface = "bold"
  ) +
  scale_fill_manual(values = my_colors) +
  scale_color_manual(values = my_colors) +
  labs(
  title = gene,
  x = NULL,
  y = "Expression level"
  ) +
  theme_classic(base_size = 14) +
  theme(
  plot.title = element_text(
  face = "bold",
  hjust = 0.5,
  size = 18
  ),
  axis.title.y = element_text(
  face = "bold",
  size = 14
  ),
  axis.text.x = element_text(
  color = "black",
  face = "bold",
  size = 13
  ),
  axis.text.y = element_text(
  color = "black",
  size = 12
  ),
  legend.position = "none",
  axis.line = element_line(
  linewidth = 0.8,
  color = "black"
  ),
  plot.margin = margin(18, 18, 18, 18)
  ) +
  coord_cartesian(
  ylim = c(y_min - 0.05 * y_range, y_upper),
  clip = "off"
  )
  # \u6587\u4ef6\u540d\u5b89\u5168\u5904\u7406
  safe_gene <- gsub("[^A-Za-z0-9_\\-]", "_", gene)
  # \u8f93\u51faPDF
  ggsave(
  filename = file.path(boxplot_dir, paste0(safe_gene, "_Boxplot.pdf")),
  plot = p_single,
  width = 4.2,
  height = 5.4
  )
  # \u8f93\u51fa600 dpi TIFF\uff0c\u9002\u5408SCI\u6295\u7a3f
  ggsave(
  filename = file.path(boxplot_dir, paste0(safe_gene, "_Boxplot.tiff")),
  plot = p_single,
  width = 4.2,
  height = 5.4,
  dpi = 600,
  compression = "lzw"
  )
  }
  cat(">> \u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7bb1\u7ebf\u56fe\u5df2\u8f93\u51fa\u81f3\u6587\u4ef6\u5939\uff1aIndividual_Gene_Boxplots\n")
  # ===============================
}

bulk_stage_specs[["fig3_gene_boxplots"]] <- list(files=c("11.marching learning/Analysis_Result/Filtered_Expression_Matrix.csv"),packages=c("ggplot2","ggpubr","dplyr","tidyr"))


# Text form is retained for syntax inspection/provenance only; users edit the
# ordinary R function bodies above, without escaped source strings.
bulk_embedded_code <- lapply(bulk_plot_functions,function(f)paste(deparse(body(f)),collapse="\n"))
bulk_run_stage <- function(id,data_root,output_root,...) {
  spec <- bulk_stage_specs[[id]]
  if(is.null(spec))stop("Unknown bulk stage: ",id)
  data_root <- normalizePath(data_root,winslash="/",mustWork=TRUE)
  dest <- file.path(output_root,id);dir.create(dest,recursive=TRUE,showWarnings=FALSE)
  dest <- normalizePath(dest,winslash="/",mustWork=TRUE)
  paths <- file.path(data_root,spec$files)
  absent <- paths[!file.exists(paths)]
  if(length(absent))stop("Missing input(s) for ",id,": ",paste(absent,collapse="; "))
  if(length(paths)) {
    stopifnot(!anyDuplicated(basename(paths)))
    same <- normalizePath(dirname(paths),winslash="/",mustWork=TRUE)==dest
    if(any(same))stop("Output folder must differ from input folder.")
    if(!all(file.copy(paths,file.path(dest,basename(paths)),overwrite=TRUE)))stop("Could not stage all inputs")
  }
  bulk_require_packages(spec$packages)
  previous <- getwd();on.exit(setwd(previous),add=TRUE);setwd(dest)
  devices_before <- dev.list()
  on.exit({
    after <- dev.list();extra <- setdiff(after,devices_before)
    for(k in rev(extra))try(dev.off(k),silent=TRUE)
  },add=TRUE)
  # Explicit screen-print calls in the original snippets go to an in-memory
  # device instead of creating an accidental Rplots.pdf in the output folder.
  grDevices::pdf(file=NULL)
  env <- new.env(parent=globalenv())
  exprs <- as.list(body(bulk_plot_functions[[id]]))[-1]
  for(expr in exprs) {
    val <- withVisible(eval(expr,envir=env))
    # Source scripts were originally run interactively: print visible ggplot
    # expressions so native plots between pdf()/dev.off() are also drawn.
    if(val$visible && inherits(val$value,c("ggplot","gg")))print(val$value)
  }
  writeLines(capture.output(sessionInfo()),"R_sessionInfo.txt")
  invisible(list(stage=id,output_dir=dest,files=list.files(dest,full.names=TRUE)))
}
bulk_stage_function <- function(id) {
  force(id)
  function(data_root,output_root,...)bulk_run_stage(id,data_root,output_root,...)
}
if(!exists("r_stages",inherits=FALSE))r_stages <- list()
for(id in names(bulk_stage_specs))r_stages[[id]] <- bulk_stage_function(id)

# Image1 E: native replay interface, only if the actual original objects are supplied.
# Required RDS fields: geneDendro, originalModuleColors, mergedModuleColors.
bulk_plot_original_wgcna_tree <- function(cache_file,output_file) {
  bulk_require_packages("WGCNA")
  if(!file.exists(cache_file))stop("Original WGCNA tree/color cache is missing; do not substitute a newly fitted tree.")
  obj <- readRDS(cache_file)
  stopifnot(all(c("geneDendro","originalModuleColors","mergedModuleColors")%in%names(obj)))
  pdf(output_file,width=10,height=6);on.exit(dev.off())
  WGCNA::plotDendroAndColors(obj$geneDendro,cbind(obj$originalModuleColors,obj$mergedModuleColors),
    c("Original Modules","Merged Modules"),dendroLabels=FALSE,hang=.03,
    addGuide=TRUE,guideHang=.05,main="Module Comparison Pre- and Post-Merging")
}

# Native R sections for supplied images 5 and 7. Original plotting code is embedded verbatim.

.immune_source_fig05_cibersort <- paste0("# ============================================================\n# \u7b2c\u4e09\u90e8\u5206\uff1a\u5173\u952e\u57fa\u56e0\u4e0e\u514d\u75ab\u6d78\u6da6\u7ec6\u80de\u7684\u76f8\u5173\u6027\u5206\u6790\n# \u7f8e\u5316\u7248\uff1a\u76f8\u5173\u6027\u70ed\u56fe + \u5706\u5f62\u6c14\u6ce1\u56fe + \u5355\u57fa\u56e0\u76f8\u5173\u6027\u6563\u70b9\u56fe\n# ============================================================\n\ncat(\"\\n==== \u7b2c\u4e09\u90e8\u5206\uff1a\u57fa\u56e0-\u514d\u75ab\u6d78\u6da6\u7ec6\u80de\u76f8\u5173\u6027\u5206\u6790\uff1a\u7f8e\u5316\u7248 ====\\n\")\n\nlibrary(ggplot2)\nlibrary(dplyr)\nlibrary(tidyr)\nlibrary(reshape2)\nlibrary(limma)\nlibrary(pheatmap)\nlibrary(RColorBrewer)\nlibrary(ggpubr)\nlibrary(scales)\nlibrary(stringr)\n\n# ----------------------------\n# 1. \u8bfb\u53d6\u57fa\u56e0\u8868\u8fbe\u6570\u636e\n# ----------------------------\nexprRaw <- read.table(\n  input_file,\n  header = TRUE,\n  sep = \",\",\n  check.names = FALSE\n)\n\nexprMat <- as.matrix(exprRaw)\nrownames(exprMat) <- exprMat[, 1]\n\nexprVals <- exprMat[, -1, drop = FALSE]\nrowNamesTmp <- rownames(exprVals)\ncolNamesTmp <- colnames(exprVals)\n\nnumExpr <- matrix(\n  as.numeric(as.matrix(exprVals)),\n  nrow = nrow(exprVals),\n  dimnames = list(rowNamesTmp, colNamesTmp)\n)\n\nnumExpr <- avereps(numExpr)\n\n# ----------------------------\n# 2. \u8bfb\u53d6\u76ee\u6807\u57fa\u56e0\u5217\u8868\n# ----------------------------\ngene_list <- read.csv(\n  gene_list_file,\n  header = TRUE,\n  stringsAsFactors = FALSE,\n  check.names = FALSE\n)\n\ntargetGene <- unique(trimws(as.character(gene_list[, 1])))\ntargetGene <- targetGene[targetGene != \"\" & !is.na(targetGene)]\n\nmatched_genes <- targetGene[targetGene %in% rownames(numExpr)]\n\ncat(\"\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(targetGene), \"\\n\")\ncat(\"\u8868\u8fbe\u77e9\u9635\u4e2d\u5339\u914d\u5230\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(matched_genes), \"\\n\")\n\nif (length(matched_genes) == 0) {\n  stop(\"\u76ee\u6807\u57fa\u56e0\u5728\u8868\u8fbe\u77e9\u9635\u4e2d\u5747\u672a\u5339\u914d\u5230\uff0c\u8bf7\u68c0\u67e5\u57fa\u56e0\u540d\u3002\")\n}\n\nexprSelected <- t(numExpr[matched_genes, , drop = FALSE])\n\n# ----------------------------\n# 3. \u63d0\u53d6\u514d\u75ab\u6d78\u6da6\u77e9\u9635\n# ----------------------------\nimmune_cols <- setdiff(colnames(rt), c(\"Sample\", \"Group\"))\n\nimmuneMat <- as.matrix(rt[, immune_cols, drop = FALSE])\nimmuneMat <- apply(immuneMat, 2, as.numeric)\nrownames(immuneMat) <- rownames(rt)\n\n# ----------------------------\n#",
" 4. \u6837\u672c\u53d6\u4ea4\u96c6\n# ----------------------------\ncommonSamples <- intersect(rownames(exprSelected), rownames(immuneMat))\n\ncat(\"\u5171\u540c\u6837\u672c\u6570\uff1a\", length(commonSamples), \"\\n\")\n\nif (length(commonSamples) < 3) {\n  stop(\"\u5171\u540c\u6837\u672c\u6570\u8fc7\u5c11\uff0c\u65e0\u6cd5\u8fdb\u884c\u76f8\u5173\u6027\u5206\u6790\u3002\")\n}\n\nexprSelected <- exprSelected[commonSamples, , drop = FALSE]\nimmuneMat    <- immuneMat[commonSamples, , drop = FALSE]\n\n# \u53bb\u9664\u6807\u51c6\u5dee\u4e3a0\u7684\u514d\u75ab\u7ec6\u80de\nvalidImmune <- immuneMat[, apply(immuneMat, 2, sd, na.rm = TRUE) > 0, drop = FALSE]\n\ncat(\"\u6709\u6548\u514d\u75ab\u7ec6\u80de\u7c7b\u578b\u6570\uff1a\", ncol(validImmune), \"\\n\")\n\nif (ncol(validImmune) == 0) {\n  stop(\"\u6240\u6709\u514d\u75ab\u7ec6\u80de\u5217\u6807\u51c6\u5dee\u5747\u4e3a0\uff0c\u65e0\u6cd5\u8ba1\u7b97\u76f8\u5173\u6027\u3002\")\n}\n\n# ----------------------------\n# 5. \u8ba1\u7b97 Spearman \u76f8\u5173\u6027\n# ----------------------------\ncor_mat <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\np_val_matrix <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\nfor (i in seq_len(ncol(exprSelected))) {\n  for (j in seq_len(ncol(validImmune))) {\n    \n    x <- as.numeric(exprSelected[, i])\n    y <- as.numeric(validImmune[, j])\n    \n    test_result <- tryCatch(\n      cor.test(\n        x,\n        y,\n        method = \"spearman\",\n        use = \"pairwise.complete.obs\",\n        exact = FALSE\n      ),\n      error = function(e) NULL\n    )\n    \n    if (!is.null(test_result)) {\n      cor_mat[i, j] <- as.numeric(test_result$estimate)\n      p_val_matrix[i, j] <- test_result$p.value\n    }\n  }\n}\n\n# ----------------------------\n# 6. \u5bfc\u51fa\u76f8\u5173\u6027\u7ed3\u679c\u957f\u8868\n# ----------------------------\ncorrDF <- data.frame()\n\nfor (i in 1:nrow(cor_mat)) {\n  for (j in 1:ncol(cor_mat)) {\n    \n    p_now <- p_val_matrix[i, j]\n    cor_now <- cor_mat[i, j]\n    \n    sig_now <- ifelse(\n      is.na(p_now), \"\",\n      ifelse(p_now < 0.001, \"***\",\n             ifelse",
"(p_now < 0.01, \"**\",\n                    ifelse(p_now < 0.05, \"*\", \"\")))\n    )\n    \n    corrDF <- rbind(\n      corrDF,\n      data.frame(\n        Gene = rownames(cor_mat)[i],\n        ImmuneCell = colnames(cor_mat)[j],\n        Correlation = cor_now,\n        P.Value = p_now,\n        Significance = sig_now,\n        stringsAsFactors = FALSE\n      )\n    )\n  }\n}\n\ncorrDF$AbsCorrelation <- abs(corrDF$Correlation)\n\nwrite.csv(\n  corrDF,\n  file = \"Gene_Immune_Correlation_Results_beautified.csv\",\n  row.names = FALSE\n)\n\ncat(\">> \u76f8\u5173\u6027\u7ed3\u679c\u8868\u5df2\u4fdd\u5b58\uff1aGene_Immune_Correlation_Results_beautified.csv\\n\")\n\n# ============================================================\n# \u56fe1\uff1a\u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe...\\n\")\n\n# \u6807\u7b7e\u77e9\u9635\uff1a\u53ea\u663e\u793a\u663e\u8457\u6027\u661f\u53f7\uff0c\u56fe\u66f4\u5e72\u51c0\nlabels_star <- matrix(\n  \"\",\n  nrow = nrow(cor_mat),\n  ncol = ncol(cor_mat),\n  dimnames = dimnames(cor_mat)\n)\n\nfor (i in 1:nrow(p_val_matrix)) {\n  for (j in 1:ncol(p_val_matrix)) {\n    p_now <- p_val_matrix[i, j]\n    if (!is.na(p_now)) {\n      if (p_now < 0.001) labels_star[i, j] <- \"***\"\n      else if (p_now < 0.01) labels_star[i, j] <- \"**\"\n      else if (p_now < 0.05) labels_star[i, j] <- \"*\"\n    }\n  }\n}\n\n# \u989c\u8272\uff1a\u84dd\u8272\u8d1f\u76f8\u5173\uff0c\u767d\u8272\u65e0\u76f8\u5173\uff0c\u7ea2\u8272\u6b63\u76f8\u5173\nheat_cols <- colorRampPalette(c(\"#2166AC\", \"white\", \"#B2182B\"))(100)\n\ngene_num <- nrow(cor_mat)\nimmune_num <- ncol(cor_mat)\n\npdf_width  <- max(9, 4 + 0.45 * immune_num)\npdf_height <- max(5, 2.5 + 0.55 * gene_num)\n\npdf(\n  file = \"Gene_Immune_Correlation_Heatmap_beautified.pdf\",\n  width = pdf_width,\n  height = pdf_height\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1, length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color ",
"= \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and Immune Cells\",\n  legend = TRUE\n)\n\ndev.off()\n\npng(\n  file = \"Gene_Immune_Correlation_Heatmap_beautified.png\",\n  width = pdf_width,\n  height = pdf_height,\n  units = \"in\",\n  res = 300\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1, length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color = \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and Immune Cells\",\n  legend = TRUE\n)\n\ndev.off()\n\ncat(\">> \u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe2\uff1aNature\u98ce\u683c\u5706\u5f62\u6c14\u6ce1\u56fe\n# \u989c\u8272\u4ee3\u8868\u76f8\u5173\u7cfb\u6570\u65b9\u5411\u548c\u5927\u5c0f\uff1b\u5706\u70b9\u5927\u5c0f\u4ee3\u8868\u76f8\u5173\u6027\u7edd\u5bf9\u503c\uff1b\u661f\u53f7\u4ee3\u8868P\u503c\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248\u5706\u5f62\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_df <- corrDF %>%\n  filter(!is.na(Correlation), !is.na(P.Value))\n\n# \u6392\u5e8f\uff1a\u57fa\u56e0\u6309\u8f93\u5165\u987a\u5e8f\uff0c\u514d\u75ab\u7ec6\u80de\u6309\u805a\u7c7b\u6216\u5b57\u6bcd\u987a\u5e8f\nbubble_df$Gene <- factor(\n  bubble_df$Gene,\n  levels = matched_genes[matched_genes %in% unique(bubble_df$Gene)]\n)\n\n# \u514d\u75ab\u7ec6\u80de\u6309\u5e73\u5747\u76f8\u5173\u6027\u6392\u5e8f\uff0c\u8ba9\u56fe\u66f4\u6709\u89c4\u5f8b\nimmune_order <- bubble_df %>%\n  group_by(ImmuneCell) %>%\n  summarise(mean_cor = mean(Correlation, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(mean_cor) %>%\n  pull(ImmuneCell)\n\nbubble_df$ImmuneCell <- factor(\n  bubble_df$ImmuneCell,\n  levels = immune_order\n)\n\nbubble_df$SigLabel <- ifelse(\n  bubble_df$P.Value < 0.001, \"***\",\n  ifelse(bubble_df$P.Value < 0.01, \"**\",\n         ifelse(bubble_df$P.Value < 0.05, \"*\", \"\"))\n)\n\nmax_abs_cor <- max(abs(bubble_df$Correlation), na.rm = TRUE)\n\nfig_width  <- max(8, 3.5 + length(unique(bubble_df$Gene)) * 0.8)\nfig_height <- max(7, 2.5 + length(unique(bubble_df$ImmuneCell)) * 0.35)\n\np_bubble <- ggplot(\n  bubble_df,\n  aes(x = G",
"ene, y = ImmuneCell)\n) +\n  geom_point(\n    aes(size = AbsCorrelation, fill = Correlation),\n    shape = 21,\n    color = \"grey25\",\n    stroke = 0.25,\n    alpha = 0.95\n  ) +\n  geom_text(\n    aes(label = SigLabel),\n    size = 3.2,\n    color = \"black\",\n    fontface = \"bold\"\n  ) +\n  scale_fill_gradient2(\n    low = \"#2166AC\",\n    mid = \"white\",\n    high = \"#B2182B\",\n    midpoint = 0,\n    limits = c(-max_abs_cor, max_abs_cor),\n    name = \"Spearman\\ncorrelation\"\n  ) +\n  scale_size_continuous(\n    range = c(2.5, 9),\n    name = \"|Correlation|\"\n  ) +\n  labs(\n    x = NULL,\n    y = NULL,\n    title = \"Gene\u2013Immune Cell Correlation\"\n  ) +\n  theme_bw(base_size = 13) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 17\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      face = \"bold.italic\",\n      color = \"black\",\n      size = 11\n    ),\n    axis.text.y = element_text(\n      color = \"black\",\n      size = 10\n    ),\n    panel.grid.major = element_line(\n      color = \"grey88\",\n      linewidth = 0.35\n    ),\n    panel.grid.minor = element_blank(),\n    panel.border = element_rect(\n      color = \"black\",\n      fill = NA,\n      linewidth = 0.8\n    ),\n    legend.position = \"right\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 11\n    ),\n    legend.text = element_text(size = 10),\n    plot.margin = margin(10, 15, 10, 10)\n  )\n\nggsave(\n  filename = \"Gene_Immune_Correlation_Bubble_beautified.pdf\",\n  plot = p_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"Gene_Immune_Correlation_Bubble_beautified.png\",\n  plot = p_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> \u7f8e\u5316\u7248\u5706\u5f62\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================",
"================================\n# \u56fe3\uff1a\u53ea\u663e\u793a\u663e\u8457\u76f8\u5173\u7684\u6c14\u6ce1\u56fe\n# \u9002\u5408\u653e\u4e3b\u56fe\uff0c\u51cf\u5c11\u4fe1\u606f\u566a\u97f3\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_sig <- bubble_df %>%\n  filter(P.Value < 0.05)\n\nif (nrow(bubble_sig) > 0) {\n  \n  bubble_sig$Gene <- factor(\n    bubble_sig$Gene,\n    levels = levels(bubble_df$Gene)\n  )\n  \n  bubble_sig$ImmuneCell <- factor(\n    bubble_sig$ImmuneCell,\n    levels = levels(bubble_df$ImmuneCell)\n  )\n  \n  fig_width_sig  <- max(6, 3.5 + length(unique(bubble_sig$Gene)) * 0.85)\n  fig_height_sig <- max(5, 2.5 + length(unique(bubble_sig$ImmuneCell)) * 0.4)\n  \n  p_bubble_sig <- ggplot(\n    bubble_sig,\n    aes(x = Gene, y = ImmuneCell)\n  ) +\n    geom_point(\n      aes(size = AbsCorrelation, fill = Correlation),\n      shape = 21,\n      color = \"grey20\",\n      stroke = 0.25,\n      alpha = 0.95\n    ) +\n    geom_text(\n      aes(label = SigLabel),\n      size = 3.4,\n      color = \"black\",\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(3, 10),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      x = NULL,\n      y = NULL,\n      title = \"Significant Gene\u2013Immune Cell Correlations\"\n    ) +\n    theme_bw(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 16\n      ),\n      axis.text.x = element_text(\n        angle = 45,\n        hjust = 1,\n        vjust = 1,\n        face = \"bold.italic\",\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 10\n      ),\n      panel.grid.major = element_line",
"(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      panel.border = element_rect(\n        color = \"black\",\n        fill = NA,\n        linewidth = 0.8\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 11\n      ),\n      legend.text = element_text(size = 10),\n      plot.margin = margin(10, 15, 10, 10)\n    )\n  \n  ggsave(\n    filename = \"Gene_Immune_Correlation_Bubble_significant_only.pdf\",\n    plot = p_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = \"Gene_Immune_Correlation_Bubble_significant_only.png\",\n    plot = p_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\",\n    dpi = 300\n  )\n  \n  cat(\">> \u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n  \n} else {\n  cat(\">> \u6ca1\u6709 P < 0.05 \u7684\u663e\u8457\u76f8\u5173\u5173\u7cfb\uff0c\u8df3\u8fc7\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u3002\\n\")\n}\n\n\n# ============================================================\n# \u56fe4\uff1a\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe\n# \u5c55\u793a\u8be5\u57fa\u56e0\u4e0e\u5168\u90e8\u514d\u75ab\u7ec6\u80de\u7684\u76f8\u5173\u6027\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684\u514d\u75ab\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe...\\n\")\n\nlollipop_dir <- \"Gene_Immune_Lollipop_Plots\"\n\nif (!dir.exists(lollipop_dir)) {\n  dir.create(lollipop_dir)\n}\n\nfor (g in unique(as.character(bubble_df$Gene))) {\n  \n  plot_g <- bubble_df %>%\n    filter(Gene == g) %>%\n    arrange(Correlation)\n  \n  plot_g$ImmuneCell <- factor(plot_g$ImmuneCell, levels = plot_g$ImmuneCell)\n  plot_g$SigColor <- ifelse(plot_g$P.Value < 0.05, \"P < 0.05\", \"NS\")\n  \n  p_lollipop <- ggplot(plot_g, aes(x = Correlation, y = ImmuneCell)) +\n    geom_vline(\n      xintercept = 0,\n      linetype = \"dashed\",\n      color = \"grey50\",\n      linewidth = 0.7\n    ) +\n    geom_segment(\n      aes(x = 0, xend = Correlation, y = ImmuneCell, yend = ImmuneCell),\n      color = \"grey60\",\n",
"      linewidth = 0.8\n    ) +\n    geom_point(\n      aes(fill = Correlation, size = AbsCorrelation),\n      shape = 21,\n      color = \"black\",\n      stroke = 0.25\n    ) +\n    geom_text(\n      aes(\n        label = ifelse(P.Value < 0.05, SigLabel, \"\")\n      ),\n      nudge_x = 0.05,\n      size = 4,\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(2.8, 8),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      title = paste0(g, \" - Immune Cell Correlation\"),\n      x = \"Spearman correlation\",\n      y = NULL\n    ) +\n    theme_classic(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 16\n      ),\n      axis.title.x = element_text(\n        face = \"bold\",\n        size = 13\n      ),\n      axis.text.x = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 10\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 10\n      ),\n      legend.text = element_text(size = 9)\n    )\n  \n  safe_g <- gsub(\"[^A-Za-z0-9_]\", \"_\", g)\n  \n  ggsave(\n    filename = file.path(lollipop_dir, paste0(safe_g, \"_Immune_Correlation_Lollipop.pdf\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(5, 2.5 + nrow(plot_g) * 0.25),\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = file.path(lollipop_dir, paste0(safe_g, \"_Immune_Correlation_Lollipop.png\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(5, 2.5 + nrow(plot_g) * 0.25),\n    units = \"in\",\n    dpi = 300\n  )",
"\n}\n\ncat(\">> \u5355\u57fa\u56e0\u68d2\u68d2\u7cd6\u56fe\u5df2\u4fdd\u5b58\u81f3\u6587\u4ef6\u5939\uff1aGene_Immune_Lollipop_Plots\\n\")\n\ncat(\"\\n==== \u57fa\u56e0-\u514d\u75ab\u6d78\u6da6\u76f8\u5173\u6027\u7f8e\u5316\u5206\u6790\u5b8c\u6210\uff01====\\n\")\n\n\n\n\n\n# ============================================================\n# \u7f8e\u5316\u7248\u514d\u75ab\u7ec6\u80de\u6d78\u6da6\u7bb1\u7ebf\u56fe\n# Control vs UC\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248\u514d\u75ab\u7ec6\u80de\u7bb1\u7ebf\u56fe...\\n\")\n\nlibrary(ggplot2)\nlibrary(ggpubr)\nlibrary(dplyr)\nlibrary(reshape2)\nlibrary(RColorBrewer)\n\n# ----------------------------\n# 1. \u91cd\u65b0\u6574\u7406 CIBERSORT \u7ed3\u679c\n# ----------------------------\n\nrt <- read.table(\n  \"CIBERSORT-Results.csv\",\n  header = TRUE,\n  sep = \",\",\n  check.names = FALSE,\n  row.names = 1\n)\n\n# \u6839\u636e\u6837\u672c\u540e\u7f00\u5224\u65ad\u5206\u7ec4\n# \u628a tra / traat \u7edf\u4e00\u6539\u6210 UC\nrt$Group <- ifelse(\n  grepl(\"_con$\", rownames(rt), ignore.case = TRUE),\n  \"Control\",\n  ifelse(\n    grepl(\"_tra$|_traat$|_UC$\", rownames(rt), ignore.case = TRUE),\n    \"UC\",\n    NA\n  )\n)\n\nrt$Sample <- rownames(rt)\n\n# \u53bb\u9664\u65e0\u6cd5\u8bc6\u522b\u5206\u7ec4\u7684\u6837\u672c\nrt <- rt[!is.na(rt$Group), ]\n\n# \u8bbe\u7f6e\u5206\u7ec4\u987a\u5e8f\nrt$Group <- factor(rt$Group, levels = c(\"Control\", \"UC\"))\n\ncat(\"\u5206\u7ec4\u60c5\u51b5\uff1a\\n\")\nprint(table(rt$Group))\n\n# ----------------------------\n# 2. \u8f6c\u6210\u957f\u683c\u5f0f\n# ----------------------------\n\ndata_long <- melt(\n  rt,\n  id.vars = c(\"Sample\", \"Group\"),\n  variable.name = \"Immune\",\n  value.name = \"Fraction\"\n)\n\ndata_long$Fraction <- as.numeric(data_long$Fraction)\n\n# \u53bb\u9664\u975e\u514d\u75ab\u7ec6\u80de\u5217\uff0c\u9632\u6b62 P-value / Correlation / RMSE \u6df7\u5165\ndata_long <- data_long %>%\n  filter(\n    !Immune %in% c(\"P-value\", \"Correlation\", \"RMSE\"),\n    !is.na(Fraction)\n  )\n\n# ----------------------------\n# 3. \u514d\u75ab\u7ec6\u80de\u6392\u5e8f\n# \u6309 UC \u7ec4\u4e2d\u4f4d\u6570\u4ece\u9ad8\u5230\u4f4e\u6392\u5e8f\uff0c\u56fe\u66f4\u6709\u903b\u8f91\n# ----------------------------\n\nimmune_order <- data_long %>%\n  filter(Group == \"UC\") %>%\n  group_by(Immune) %>%\n  summarise(median_fraction = median(Fraction, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(desc(median_fraction)) %>%\n  pull(Immune)\n\ndata_long$Immune <- factor(data_long$Immune, levels = immune_order)\n\ncountControl <- length(un",
"ique(data_long$Sample[data_long$Group == \"Control\"]))\ncountUC      <- length(unique(data_long$Sample[data_long$Group == \"UC\"]))\n\n# ----------------------------\n# 4. \u8ba1\u7b97\u6bcf\u79cd\u514d\u75ab\u7ec6\u80de\u7684 Wilcoxon P \u503c\n# ----------------------------\n\npvalue_table <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    p.value = tryCatch(\n      wilcox.test(Fraction ~ Group)$p.value,\n      error = function(e) NA\n    ),\n    .groups = \"drop\"\n  ) %>%\n  mutate(\n    p.adj = p.adjust(p.value, method = \"BH\"),\n    Significance = case_when(\n      is.na(p.value) ~ \"ns\",\n      p.value < 0.001 ~ \"***\",\n      p.value < 0.01  ~ \"**\",\n      p.value < 0.05  ~ \"*\",\n      TRUE ~ \"ns\"\n    )\n  )\n\nwrite.csv(\n  pvalue_table,\n  file = \"Immune_Cell_Comparison_Pvalues_beautified.csv\",\n  row.names = FALSE\n)\n\n# ----------------------------\n# 5. \u4e3a\u663e\u8457\u6027\u6807\u6ce8\u51c6\u5907\u4f4d\u7f6e\n# ----------------------------\n\nlabel_df <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    y.position = max(Fraction, na.rm = TRUE) * 1.08 + 0.01,\n    .groups = \"drop\"\n  ) %>%\n  left_join(pvalue_table, by = \"Immune\")\n\n# ----------------------------\n# 6. \u7ed8\u5236\u7f8e\u5316\u7248\u7bb1\u7ebf\u56fe\n# ----------------------------\n\np_immune_box <- ggplot(\n  data_long,\n  aes(x = Immune, y = Fraction, fill = Group)\n) +\n  geom_boxplot(\n    aes(color = Group),\n    position = position_dodge(width = 0.75),\n    width = 0.58,\n    outlier.shape = NA,\n    alpha = 0.70,\n    linewidth = 0.65\n  ) +\n  geom_jitter(\n    aes(color = Group),\n    position = position_jitterdodge(\n      jitter.width = 0.12,\n      dodge.width = 0.75\n    ),\n    size = 0.65,\n    alpha = 0.35\n  ) +\n  geom_text(\n    data = label_df,\n    aes(\n      x = Immune,\n      y = y.position,\n      label = Significance\n    ),\n    inherit.aes = FALSE,\n    size = 4.2,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  scale_fill_manual(\n    values = c(\"Control\" = ",
"\"#4DBBD5\", \"UC\" = \"#E64B35\"),\n    name = \"Group\"\n  ) +\n  scale_color_manual(\n    values = c(\"Control\" = \"#0073C2\", \"UC\" = \"#CD201F\"),\n    name = \"Group\"\n  ) +\n  scale_y_continuous(\n    expand = expansion(mult = c(0.02, 0.15))\n  ) +\n  labs(\n    title = \"Immune Cell Infiltration Comparison\",\n    subtitle = paste0(\"Control n = \", countControl, \", UC n = \", countUC),\n    x = NULL,\n    y = \"Estimated fraction\"\n  ) +\n  theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 18,\n      color = \"black\"\n    ),\n    plot.subtitle = element_text(\n      hjust = 0.5,\n      size = 13,\n      color = \"black\"\n    ),\n    axis.title.y = element_text(\n      face = \"bold\",\n      size = 15,\n      color = \"black\"\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      size = 10.5,\n      color = \"black\"\n    ),\n    axis.text.y = element_text(\n      size = 12,\n      color = \"black\"\n    ),\n    axis.line = element_line(\n      linewidth = 0.8,\n      color = \"black\"\n    ),\n    axis.ticks = element_line(\n      linewidth = 0.7,\n      color = \"black\"\n    ),\n    legend.position = \"top\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 12\n    ),\n    legend.text = element_text(size = 12),\n    panel.grid = element_blank(),\n    plot.margin = margin(15, 20, 20, 20)\n  ) +\n  coord_cartesian(clip = \"off\")\n\nggsave(\n  filename = \"Immune_Cell_Boxplot_beautified.pdf\",\n  plot = p_immune_box,\n  width = 13,\n  height = 7,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"Immune_Cell_Boxplot_beautified.png\",\n  plot = p_immune_box,\n  width = 13,\n  height = 7,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> \u7f8e\u5316\u7248\u514d\u75ab\u7ec6\u80de\u7bb1\u7ebf\u56fe\u5df2\u4fdd\u5b58\uff1aImmune_Cell_Boxplot_beautified.pdf/png\\n\")\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n")

.immune_source_fig05_mcpcounter <- paste0("# ============================================================\n# \u7b2c\u4e8c\u90e8\u5206\uff1aMCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u53ef\u89c6\u5316\uff1a\u7f8e\u5316\u7248\n# ============================================================\n\ncat(\"\\n==== \u7b2c\u4e8c\u90e8\u5206\uff1aMCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u53ef\u89c6\u5316\uff1a\u7f8e\u5316\u7248 ====\\n\")\n\nlibrary(reshape2)\nlibrary(ggplot2)\nlibrary(ggpubr)\nlibrary(dplyr)\nlibrary(broom)\nlibrary(limma)\nlibrary(pheatmap)\nlibrary(RColorBrewer)\nlibrary(scales)\nlibrary(stringr)\n\n# ----------------------------\n# 1. \u6574\u7406MCP-counter\u7ed3\u679c\n# ----------------------------\nrt <- immune_df\n\n# \u6839\u636e\u6837\u672c\u540e\u7f00\u5224\u65ad\u5206\u7ec4\n# con -> Control\uff1btra / treat / UC -> UC\nrt$Group <- ifelse(\n  grepl(\"_con$\", rownames(rt), ignore.case = TRUE),\n  \"Control\",\n  ifelse(\n    grepl(\"_tra$|_treat$|_treatment$|_UC$\", rownames(rt), ignore.case = TRUE),\n    \"UC\",\n    NA\n  )\n)\n\nrt$Sample <- rownames(rt)\n\n# \u53bb\u9664\u5206\u7ec4\u65e0\u6cd5\u8bc6\u522b\u7684\u6837\u672c\nrt <- rt[!is.na(rt$Group), ]\n\nrt$Group <- factor(rt$Group, levels = c(\"Control\", \"UC\"))\n\ncat(\"\u5206\u7ec4\u60c5\u51b5\uff1a\\n\")\nprint(table(rt$Group))\n\n# ----------------------------\n# 2. \u8f6c\u6210\u957f\u683c\u5f0f\n# ----------------------------\ndata_long <- melt(\n  rt,\n  id.vars = c(\"Sample\", \"Group\"),\n  variable.name = \"Immune\",\n  value.name = \"Abundance\"\n)\n\ndata_long$Abundance <- as.numeric(data_long$Abundance)\n\ndata_long <- data_long %>%\n  filter(!is.na(Abundance), !is.na(Group))\n\ncountControl <- length(unique(data_long$Sample[data_long$Group == \"Control\"]))\ncountUC      <- length(unique(data_long$Sample[data_long$Group == \"UC\"]))\n\n# ----------------------------\n# 3. \u514d\u75ab\u7ec6\u80de\u6309UC\u7ec4\u4e2d\u4f4d\u6570\u6392\u5e8f\n# ----------------------------\nimmune_order <- data_long %>%\n  filter(Group == \"UC\") %>%\n  group_by(Immune) %>%\n  summarise(median_abundance = median(Abundance, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(desc(median_abundance)) %>%\n  pull(Immune)\n\ndata_long$Immune <- factor(data_long$Immune, levels = immune_order)\n\n# ----------------------------\n# 4. \u7edf\u8ba1\u68c0\u9a8c\n# --------------",
"--------------\npvalue_table <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    p.value = tryCatch(\n      wilcox.test(Abundance ~ Group)$p.value,\n      error = function(e) NA\n    ),\n    .groups = \"drop\"\n  ) %>%\n  mutate(\n    p.adj = p.adjust(p.value, method = \"BH\"),\n    Significance = case_when(\n      is.na(p.value) ~ \"ns\",\n      p.value < 0.001 ~ \"***\",\n      p.value < 0.01  ~ \"**\",\n      p.value < 0.05  ~ \"*\",\n      TRUE ~ \"ns\"\n    )\n  )\n\nwrite.csv(\n  pvalue_table,\n  file = \"MCPcounter_Immune_Cell_Pvalues_beautified.csv\",\n  row.names = FALSE\n)\n\nsummary_table <- data_long %>%\n  group_by(Immune, Group) %>%\n  summarise(\n    MeanAbundance = mean(Abundance, na.rm = TRUE),\n    MedianAbundance = median(Abundance, na.rm = TRUE),\n    SD = sd(Abundance, na.rm = TRUE),\n    Count = n(),\n    .groups = \"drop\"\n  )\n\nwrite.csv(\n  summary_table,\n  file = \"MCPcounter_Immune_Cell_Summary_beautified.csv\",\n  row.names = FALSE\n)\n\n# ----------------------------\n# 5. \u663e\u8457\u6027\u6807\u6ce8\u4f4d\u7f6e\n# ----------------------------\nlabel_df <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    y.position = max(Abundance, na.rm = TRUE) * 1.08,\n    .groups = \"drop\"\n  ) %>%\n  left_join(pvalue_table, by = \"Immune\")\n\n# ============================================================\n# \u56fe1\uff1a\u7f8e\u5316\u7248MCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u7bb1\u7ebf\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248MCP-counter\u514d\u75ab\u7ec6\u80de\u7bb1\u7ebf\u56fe...\\n\")\n\np_mcp_box <- ggplot(\n  data_long,\n  aes(x = Immune, y = Abundance, fill = Group)\n) +\n  geom_boxplot(\n    aes(color = Group),\n    position = position_dodge(width = 0.75),\n    width = 0.58,\n    outlier.shape = NA,\n    alpha = 0.72,\n    linewidth = 0.65\n  ) +\n  geom_jitter(\n    aes(color = Group),\n    position = position_jitterdodge(\n      jitter.width = 0.10,\n      dodge.width = 0.75\n    ),\n    size = 0.45,\n    a",
"lpha = 0.22\n  ) +\n  geom_text(\n    data = label_df,\n    aes(x = Immune, y = y.position, label = Significance),\n    inherit.aes = FALSE,\n    size = 4.3,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  scale_fill_manual(\n    values = c(\"Control\" = \"#4DBBD5\", \"UC\" = \"#E64B35\"),\n    name = \"Group\"\n  ) +\n  scale_color_manual(\n    values = c(\"Control\" = \"#0073C2\", \"UC\" = \"#CD201F\"),\n    name = \"Group\"\n  ) +\n  scale_y_continuous(\n    expand = expansion(mult = c(0.02, 0.16))\n  ) +\n  labs(\n    title = \"MCP-counter Immune Cell Abundance\",\n    subtitle = paste0(\"Control n = \", countControl, \", UC n = \", countUC),\n    x = NULL,\n    y = \"Abundance score\"\n  ) +\n  theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 18,\n      color = \"black\"\n    ),\n    plot.subtitle = element_text(\n      hjust = 0.5,\n      size = 13,\n      color = \"black\"\n    ),\n    axis.title.y = element_text(\n      face = \"bold\",\n      size = 15,\n      color = \"black\"\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      size = 11,\n      color = \"black\"\n    ),\n    axis.text.y = element_text(\n      size = 12,\n      color = \"black\"\n    ),\n    axis.line = element_line(\n      linewidth = 0.8,\n      color = \"black\"\n    ),\n    axis.ticks = element_line(\n      linewidth = 0.7,\n      color = \"black\"\n    ),\n    legend.position = \"top\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 12\n    ),\n    legend.text = element_text(size = 12),\n    panel.grid = element_blank(),\n    plot.margin = margin(15, 20, 20, 20)\n  ) +\n  coord_cartesian(clip = \"off\")\n\nggsave(\n  filename = \"MCPcounter_Immune_Boxplot_beautified.pdf\",\n  plot = p_mcp_box,\n  width = 11,\n  height = 6.8,\n  units = \"in\"\n)\n\nggsave(\n  fil",
"ename = \"MCPcounter_Immune_Boxplot_beautified.png\",\n  plot = p_mcp_box,\n  width = 11,\n  height = 6.8,\n  units = \"in\",\n  dpi = 300\n)\n\n# \u6a2a\u5411\u7248\u672c\uff0c\u9002\u5408\u8865\u5145\u56fe\np_mcp_box_flip <- p_mcp_box +\n  coord_flip(clip = \"off\") +\n  theme(\n    axis.text.x = element_text(angle = 0, size = 11),\n    axis.text.y = element_text(size = 11, color = \"black\")\n  )\n\nggsave(\n  filename = \"MCPcounter_Immune_Boxplot_beautified_horizontal.pdf\",\n  plot = p_mcp_box_flip,\n  width = 8,\n  height = 7,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"MCPcounter_Immune_Boxplot_beautified_horizontal.png\",\n  plot = p_mcp_box_flip,\n  width = 8,\n  height = 7,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> MCP-counter\u514d\u75ab\u7bb1\u7ebf\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe2\uff1a\u7f8e\u5316\u7248MCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u5806\u53e0\u6761\u5f62\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248MCP-counter\u5806\u53e0\u6761\u5f62\u56fe...\\n\")\n\n# \u6309\u5206\u7ec4\u548c\u6837\u672c\u603b\u4e30\u5ea6\u6392\u5e8f\nsample_order <- data_long %>%\n  group_by(Sample, Group) %>%\n  summarise(total_abundance = sum(Abundance, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(Group, total_abundance) %>%\n  pull(Sample)\n\ndata_long$Sample <- factor(data_long$Sample, levels = sample_order)\n\nimmune_types <- levels(data_long$Immune)\nnColors <- length(immune_types)\nmyColors <- colorRampPalette(brewer.pal(12, \"Set3\"))(nColors)\n\np_mcp_bar <- ggplot(\n  data_long,\n  aes(x = Sample, y = Abundance, fill = Immune)\n) +\n  geom_bar(\n    stat = \"identity\",\n    width = 0.95,\n    color = NA\n  ) +\n  scale_fill_manual(\n    values = myColors,\n    name = \"Immune cell type\"\n  ) +\n  labs(\n    title = \"MCP-counter Immune Cell Abundance Distribution\",\n    subtitle = \"Control vs UC\",\n    x = NULL,\n    y = \"Relative abundance score\"\n  ) +\n  theme_minimal(base_size = 14) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      ",
"size = 17\n    ),\n    plot.subtitle = element_text(\n      hjust = 0.5,\n      size = 12\n    ),\n    axis.text.x = element_blank(),\n    axis.ticks.x = element_blank(),\n    axis.text.y = element_text(\n      color = \"black\",\n      size = 11\n    ),\n    axis.title.y = element_text(\n      face = \"bold\",\n      size = 13\n    ),\n    panel.grid.major.x = element_blank(),\n    panel.grid.minor = element_blank(),\n    legend.position = \"right\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 11\n    ),\n    legend.text = element_text(size = 9),\n    plot.margin = margin(10, 20, 10, 10)\n  )\n\nggsave(\n  filename = \"MCPcounter_Immune_StackedBar_beautified.pdf\",\n  plot = p_mcp_bar,\n  width = 13,\n  height = 7,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"MCPcounter_Immune_StackedBar_beautified.png\",\n  plot = p_mcp_bar,\n  width = 13,\n  height = 7,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> MCP-counter\u5806\u53e0\u6761\u5f62\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u7b2c\u4e09\u90e8\u5206\uff1a\u5173\u952e\u57fa\u56e0\u4e0eMCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u76f8\u5173\u6027\u5206\u6790\uff1a\u7f8e\u5316\u7248\n# ============================================================\n\ncat(\"\\n==== \u7b2c\u4e09\u90e8\u5206\uff1a\u57fa\u56e0-MCPcounter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u76f8\u5173\u6027\u5206\u6790\uff1a\u7f8e\u5316\u7248 ====\\n\")\n\n# ----------------------------\n# 1. \u8bfb\u53d6\u76ee\u6807\u57fa\u56e0\u5217\u8868\n# ----------------------------\ngene_list <- read.csv(\n  gene_list_file,\n  header = TRUE,\n  stringsAsFactors = FALSE,\n  check.names = FALSE\n)\n\ntargetGene <- unique(trimws(as.character(gene_list[, 1])))\ntargetGene <- targetGene[targetGene != \"\" & !is.na(targetGene)]\n\nmatched_genes <- targetGene[targetGene %in% rownames(numExpr)]\n\ncat(\"\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(targetGene), \"\\n\")\ncat(\"\u8868\u8fbe\u77e9\u9635\u4e2d\u5339\u914d\u5230\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(matched_genes), \"\\n\")\n\nif (length(matched_genes) == 0) {\n  stop(\"\u76ee\u6807\u57fa\u56e0\u5728\u8868\u8fbe\u77e9\u9635\u4e2d\u5747\u672a\u5339\u914d\u5230\uff0c\u8bf7\u68c0\u67e5\u57fa\u56e0\u540d\u3002\")\n}\n\nexprSelected <- t(numExpr[matched_genes, , drop = FALSE])\n\n# ----------------------------\n# 2. \u63d0\u53d6\u514d\u75ab\u4e30\u5ea6\u77e9\u9635\n# ---------------------",
"-------\nimmune_cols <- setdiff(colnames(rt), c(\"Sample\", \"Group\"))\n\nimmuneMat <- as.matrix(rt[, immune_cols, drop = FALSE])\nimmuneMat <- apply(immuneMat, 2, as.numeric)\nrownames(immuneMat) <- rownames(rt)\n\n# ----------------------------\n# 3. \u5171\u540c\u6837\u672c\n# ----------------------------\ncommonSamples <- intersect(rownames(exprSelected), rownames(immuneMat))\n\ncat(\"\u5171\u540c\u6837\u672c\u6570\uff1a\", length(commonSamples), \"\\n\")\n\nif (length(commonSamples) < 3) {\n  stop(\"\u5171\u540c\u6837\u672c\u6570\u8fc7\u5c11\uff0c\u65e0\u6cd5\u8fdb\u884c\u76f8\u5173\u6027\u5206\u6790\u3002\")\n}\n\nexprSelected <- exprSelected[commonSamples, , drop = FALSE]\nimmuneMat    <- immuneMat[commonSamples, , drop = FALSE]\n\n# \u53bb\u9664\u6807\u51c6\u5dee\u4e3a0\u7684\u514d\u75ab\u7ec6\u80de\nvalidImmune <- immuneMat[, apply(immuneMat, 2, sd, na.rm = TRUE) > 0, drop = FALSE]\n\ncat(\"\u6709\u6548\u514d\u75ab\u7ec6\u80de\u7c7b\u578b\u6570\uff1a\", ncol(validImmune), \"\\n\")\n\nif (ncol(validImmune) == 0) {\n  stop(\"\u6240\u6709\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u5217\u6807\u51c6\u5dee\u5747\u4e3a0\uff0c\u65e0\u6cd5\u8ba1\u7b97\u76f8\u5173\u6027\u3002\")\n}\n\n# ----------------------------\n# 4. Spearman\u76f8\u5173\u6027\n# ----------------------------\ncor_mat <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\np_val_matrix <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\nfor (i in seq_len(ncol(exprSelected))) {\n  for (j in seq_len(ncol(validImmune))) {\n    \n    x <- as.numeric(exprSelected[, i])\n    y <- as.numeric(validImmune[, j])\n    \n    test_result <- tryCatch(\n      cor.test(\n        x,\n        y,\n        method = \"spearman\",\n        use = \"pairwise.complete.obs\",\n        exact = FALSE\n      ),\n      error = function(e) NULL\n    )\n    \n    if (!is.null(test_result)) {\n      cor_mat[i, j] <- as.numeric(test_result$estimate)\n      p_val_matrix[i, j] <- test_result$p.value\n    }\n  }\n}\n\n# ----------------------------\n# 5. \u5bfc\u51fa\u76f8\u5173\u6027\u7ed3\u679c\u957f\u8868\n# ----------------------------\ncorrDF <- data.frame(",
")\n\nfor (i in 1:nrow(cor_mat)) {\n  for (j in 1:ncol(cor_mat)) {\n    \n    p_now <- p_val_matrix[i, j]\n    cor_now <- cor_mat[i, j]\n    \n    sig_now <- ifelse(\n      is.na(p_now), \"\",\n      ifelse(\n        p_now < 0.001, \"***\",\n        ifelse(\n          p_now < 0.01, \"**\",\n          ifelse(p_now < 0.05, \"*\", \"\")\n        )\n      )\n    )\n    \n    corrDF <- rbind(\n      corrDF,\n      data.frame(\n        Gene = rownames(cor_mat)[i],\n        ImmuneCell = colnames(cor_mat)[j],\n        Correlation = cor_now,\n        P.Value = p_now,\n        Significance = sig_now,\n        stringsAsFactors = FALSE\n      )\n    )\n  }\n}\n\ncorrDF$AbsCorrelation <- abs(corrDF$Correlation)\n\nwrite.csv(\n  corrDF,\n  file = \"MCPcounter_Gene_Immune_Correlation_Results_beautified.csv\",\n  row.names = FALSE\n)\n\ncat(\">> MCP-counter\u76f8\u5173\u6027\u7ed3\u679c\u8868\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe3\uff1a\u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236MCP-counter\u76f8\u5173\u6027\u70ed\u56fe...\\n\")\n\nlabels_star <- matrix(\n  \"\",\n  nrow = nrow(cor_mat),\n  ncol = ncol(cor_mat),\n  dimnames = dimnames(cor_mat)\n)\n\nfor (i in 1:nrow(p_val_matrix)) {\n  for (j in 1:ncol(p_val_matrix)) {\n    p_now <- p_val_matrix[i, j]\n    if (!is.na(p_now)) {\n      if (p_now < 0.001) labels_star[i, j] <- \"***\"\n      else if (p_now < 0.01) labels_star[i, j] <- \"**\"\n      else if (p_now < 0.05) labels_star[i, j] <- \"*\"\n    }\n  }\n}\n\nheat_cols <- colorRampPalette(c(\"#2166AC\", \"white\", \"#B2182B\"))(100)\n\ngene_num <- nrow(cor_mat)\nimmune_num <- ncol(cor_mat)\n\npdf_width  <- max(8, 4 + 0.55 * immune_num)\npdf_height <- max(5, 2.5 + 0.55 * gene_num)\n\npdf(\n  file = \"MCPcounter_Gene_Immune_Correlation_Heatmap_beautified.pdf\",\n  width = pdf_width,\n  height = pdf_height\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1",
", length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color = \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and MCP-counter Immune Cells\"\n)\n\ndev.off()\n\npng(\n  file = \"MCPcounter_Gene_Immune_Correlation_Heatmap_beautified.png\",\n  width = pdf_width,\n  height = pdf_height,\n  units = \"in\",\n  res = 300\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1, length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color = \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and MCP-counter Immune Cells\"\n)\n\ndev.off()\n\ncat(\">> MCP-counter\u76f8\u5173\u6027\u70ed\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe4\uff1a\u7f8e\u5316\u7248\u5706\u5f62\u6c14\u6ce1\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236MCP-counter\u76f8\u5173\u6027\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_df <- corrDF %>%\n  filter(!is.na(Correlation), !is.na(P.Value))\n\nbubble_df$Gene <- factor(\n  bubble_df$Gene,\n  levels = matched_genes[matched_genes %in% unique(bubble_df$Gene)]\n)\n\nimmune_order_cor <- bubble_df %>%\n  group_by(ImmuneCell) %>%\n  summarise(mean_cor = mean(Correlation, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(mean_cor) %>%\n  pull(ImmuneCell)\n\nbubble_df$ImmuneCell <- factor(\n  bubble_df$ImmuneCell,\n  levels = immune_order_cor\n)\n\nbubble_df$SigLabel <- ifelse(\n  bubble_df$P.Value < 0.001, \"***\",\n  ifelse(\n    bubble_df$P.Value < 0.01, \"**\",\n    ifelse(bubble_df$P.Value < 0.05, \"*\", \"\")\n  )\n)\n\nmax_abs_cor <- max(abs(bubble_df$Correlation), na.rm = TRUE)\n\nfig_width  <- max(7, 3.5 + length(",
"unique(bubble_df$Gene)) * 0.8)\nfig_height <- max(5.5, 2.5 + length(unique(bubble_df$ImmuneCell)) * 0.45)\n\np_mcp_bubble <- ggplot(\n  bubble_df,\n  aes(x = Gene, y = ImmuneCell)\n) +\n  geom_point(\n    aes(size = AbsCorrelation, fill = Correlation),\n    shape = 21,\n    color = \"grey25\",\n    stroke = 0.25,\n    alpha = 0.95\n  ) +\n  geom_text(\n    aes(label = SigLabel),\n    size = 3.4,\n    color = \"black\",\n    fontface = \"bold\"\n  ) +\n  scale_fill_gradient2(\n    low = \"#2166AC\",\n    mid = \"white\",\n    high = \"#B2182B\",\n    midpoint = 0,\n    limits = c(-max_abs_cor, max_abs_cor),\n    name = \"Spearman\\ncorrelation\"\n  ) +\n  scale_size_continuous(\n    range = c(3, 10),\n    name = \"|Correlation|\"\n  ) +\n  labs(\n    title = \"Gene\u2013MCP-counter Immune Cell Correlation\",\n    x = NULL,\n    y = NULL\n  ) +\n  theme_bw(base_size = 13) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 17\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      face = \"bold.italic\",\n      color = \"black\",\n      size = 11\n    ),\n    axis.text.y = element_text(\n      color = \"black\",\n      size = 11\n    ),\n    panel.grid.major = element_line(\n      color = \"grey88\",\n      linewidth = 0.35\n    ),\n    panel.grid.minor = element_blank(),\n    panel.border = element_rect(\n      color = \"black\",\n      fill = NA,\n      linewidth = 0.8\n    ),\n    legend.position = \"right\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 11\n    ),\n    legend.text = element_text(size = 10),\n    plot.margin = margin(10, 15, 10, 10)\n  )\n\nggsave(\n  filename = \"MCPcounter_Gene_Immune_Correlation_Bubble_beautified.pdf\",\n  plot = p_mcp_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"MCPcounter_Gene_Imm",
"une_Correlation_Bubble_beautified.png\",\n  plot = p_mcp_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> MCP-counter\u76f8\u5173\u6027\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe5\uff1a\u53ea\u663e\u793a\u663e\u8457\u76f8\u5173\u7684\u6c14\u6ce1\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236MCP-counter\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_sig <- bubble_df %>%\n  filter(P.Value < 0.05)\n\nif (nrow(bubble_sig) > 0) {\n  \n  bubble_sig$Gene <- factor(\n    bubble_sig$Gene,\n    levels = levels(bubble_df$Gene)\n  )\n  \n  bubble_sig$ImmuneCell <- factor(\n    bubble_sig$ImmuneCell,\n    levels = levels(bubble_df$ImmuneCell)\n  )\n  \n  fig_width_sig  <- max(6.5, 3.5 + length(unique(bubble_sig$Gene)) * 0.85)\n  fig_height_sig <- max(4.8, 2.5 + length(unique(bubble_sig$ImmuneCell)) * 0.45)\n  \n  p_mcp_bubble_sig <- ggplot(\n    bubble_sig,\n    aes(x = Gene, y = ImmuneCell)\n  ) +\n    geom_point(\n      aes(size = AbsCorrelation, fill = Correlation),\n      shape = 21,\n      color = \"grey20\",\n      stroke = 0.25,\n      alpha = 0.95\n    ) +\n    geom_text(\n      aes(label = SigLabel),\n      size = 3.5,\n      color = \"black\",\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(3.2, 10),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      title = \"Significant Gene\u2013MCP-counter Immune Cell Correlations\",\n      x = NULL,\n      y = NULL\n    ) +\n    theme_bw(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 16\n      ),\n      axis.text.x = element_text(\n        angle = 45,\n        hjust = 1,\n ",
"       vjust = 1,\n        face = \"bold.italic\",\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      panel.grid.major = element_line(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      panel.border = element_rect(\n        color = \"black\",\n        fill = NA,\n        linewidth = 0.8\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 11\n      ),\n      legend.text = element_text(size = 10),\n      plot.margin = margin(10, 15, 10, 10)\n    )\n  \n  ggsave(\n    filename = \"MCPcounter_Gene_Immune_Correlation_Bubble_significant_only.pdf\",\n    plot = p_mcp_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = \"MCPcounter_Gene_Immune_Correlation_Bubble_significant_only.png\",\n    plot = p_mcp_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\",\n    dpi = 300\n  )\n  \n  cat(\">> MCP-counter\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n  \n} else {\n  cat(\">> \u6ca1\u6709P < 0.05\u7684\u663e\u8457\u76f8\u5173\u5173\u7cfb\uff0c\u8df3\u8fc7\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u3002\\n\")\n}\n\n\n# ============================================================\n# \u56fe6\uff1a\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684MCP-counter\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684MCP-counter\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe...\\n\")\n\nlollipop_dir <- \"MCPcounter_Gene_Immune_Lollipop_Plots\"\n\nif (!dir.exists(lollipop_dir)) {\n  dir.create(lollipop_dir)\n}\n\nfor (g in unique(as.character(bubble_df$Gene))) {\n  \n  plot_g <- bubble_df %>%\n    filter(Gene == g) %>%\n    arrange(Correlation)\n  \n  plot_g$ImmuneCell <- factor(plot_g$ImmuneCell, levels = plot_g$ImmuneCell)\n  \n  p_lollipop <- ggplot(plot_g, aes(x = Correlation, y = ImmuneCell)) +\n    geom_vline(\n      xinterc",
"ept = 0,\n      linetype = \"dashed\",\n      color = \"grey50\",\n      linewidth = 0.7\n    ) +\n    geom_segment(\n      aes(x = 0, xend = Correlation, y = ImmuneCell, yend = ImmuneCell),\n      color = \"grey60\",\n      linewidth = 0.8\n    ) +\n    geom_point(\n      aes(fill = Correlation, size = AbsCorrelation),\n      shape = 21,\n      color = \"black\",\n      stroke = 0.25\n    ) +\n    geom_text(\n      aes(label = ifelse(P.Value < 0.05, SigLabel, \"\")),\n      nudge_x = 0.05,\n      size = 4,\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(3, 8),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      title = paste0(g, \" - MCP-counter Immune Cell Correlation\"),\n      x = \"Spearman correlation\",\n      y = NULL\n    ) +\n    theme_classic(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 15\n      ),\n      axis.title.x = element_text(\n        face = \"bold\",\n        size = 13\n      ),\n      axis.text.x = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 10\n      ),\n      legend.text = element_text(size = 9)\n    )\n  \n  safe_g <- gsub(\"[^A-Za-z0-9_]\", \"_\", g)\n  \n  ggsave(\n    filename = file.path(lollipop_dir, paste0(safe_g, \"_MCPcounter_Immune_Correlation_Lollipop.pdf\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(4.8, 2.2 + nrow(plot_g) * 0.35),\n    units = \"in\"\n  )\n  \n  ggsave(\n ",
"   filename = file.path(lollipop_dir, paste0(safe_g, \"_MCPcounter_Immune_Correlation_Lollipop.png\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(4.8, 2.2 + nrow(plot_g) * 0.35),\n    units = \"in\",\n    dpi = 300\n  )\n}\n\ncat(\">> \u5355\u57fa\u56e0MCP-counter\u68d2\u68d2\u7cd6\u56fe\u5df2\u4fdd\u5b58\u81f3\u6587\u4ef6\u5939\uff1aMCPcounter_Gene_Immune_Lollipop_Plots\\n\")\n\ncat(\"\\n==== MCP-counter\u514d\u75ab\u4e30\u5ea6\u5206\u6790\u4e0e\u7f8e\u5316\u7ed8\u56fe\u5168\u90e8\u5b8c\u6210\uff01====\\n\")")

.immune_source_fig07_cohort_sensitivity <- paste0("# Cohort-wise box plots adapted from the two original Figure 5 R scripts.\n# Run from the directory containing this script and its data folder.\n\nsuppressPackageStartupMessages({\n  library(ggplot2)\n  library(dplyr)\n  library(reshape2)\n  library(patchwork)\n})\n\nargs <- commandArgs(trailingOnly = TRUE)\noutput_dir <- if (length(args)) args[[1]] else \".\"\ndir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n\ncohorts <- c(\"GSE87466\", \"GSE206285\")\nall_samples <- \"all\"\nfit_subset <- \"permutation_P_lt_0.05\"\nsubtypes <- paste(\"Macrophages\", c(\"M0\", \"M1\", \"M2\"))\nlineage <- \"Monocytic lineage\"\ngroup_levels <- c(\"Control\", \"UC\")\nfill_colors <- c(Control = \"#4DBBD5\", UC = \"#E64B35\")\noutline_colors <- c(Control = \"#0073C2\", UC = \"#CD201F\")\njitter_seed <- 20261121L\n\nread_scores <- function(cohort, method) {\n  file <- file.path(\"data\", paste0(cohort, \"_\", method, \".csv\"))\n  scores <- read.csv(file, check.names = FALSE, fileEncoding = \"UTF-8-BOM\")\n  stopifnot(all(scores$Group %in% group_levels), !anyDuplicated(scores$Sample))\n  scores$Cohort <- cohort\n  scores$Group <- factor(scores$Group, levels = group_levels)\n  scores\n}\n\nciber_scores <- bind_rows(lapply(cohorts, read_scores, method = \"cibersort\"))\nmcp_scores <- bind_rows(lapply(cohorts, read_scores, method = \"mcpcounter\"))\ncomparisons <- read.csv(file.path(\"data\", \"group_comparisons.csv\"),\n                       check.names = FALSE, fileEncoding = \"UTF-8-BOM\")\nnames(comparisons)[names(comparisons) == \"cell\"] <- \"Immune\"\n\nciber_data <- bind_rows(\n  mutate(ciber_scores, selection = all_samples),\n  mutate(filter(ciber_scores, .data[[\"P-value\"]] < 0.05), selection = fit_subset)\n) %>%\n  melt(id.vars = c(\"Sample\", \"Cohort\", \"Group\", \"selection\"),\n       measure.vars = subtypes,\n       variable.name = \"Immune\", value.name = \"Fraction\"",
")\nciber_data$Immune <- factor(ciber_data$Immune, levels = subtypes)\n\nmcp_data <- mcp_scores %>%\n  mutate(selection = all_samples) %>%\n  melt(id.vars = c(\"Sample\", \"Cohort\", \"Group\", \"selection\"),\n       measure.vars = lineage, variable.name = \"Immune\", value.name = \"Abundance\")\n\ngroup_labels <- function(data, score_name, method, extra_height) {\n  tests <- filter(comparisons, .data$method == .env$method)\n  labels <- data %>%\n    group_by(Cohort, selection, Immune) %>%\n    summarise(\n      count_UC = sum(Group == \"UC\"),\n      count_control = sum(Group == \"Control\"),\n      median_UC_plot = median(.data[[score_name]][Group == \"UC\"]),\n      median_control_plot = median(.data[[score_name]][Group == \"Control\"]),\n      y.position = max(.data[[score_name]]) * 1.08 + extra_height,\n      .groups = \"drop\"\n    ) %>%\n    left_join(tests, by = c(\"Cohort\", \"selection\", \"Immune\")) %>%\n    mutate(Significance = case_when(\n      BH_P < 0.001 ~ \"***\",\n      BH_P < 0.01 ~ \"**\",\n      BH_P < 0.05 ~ \"*\",\n      TRUE ~ \"ns\"\n    ))\n  stopifnot(all(is.finite(labels$BH_P)),\n            all(labels$n_UC == labels$count_UC),\n            all(labels$n_Control == labels$count_control),\n            all(abs(labels$median_UC - labels$median_UC_plot) < 1e-12),\n            all(abs(labels$median_Control - labels$median_control_plot) < 1e-12))\n  labels\n}\n\nciber_labels <- group_labels(ciber_data, \"Fraction\", \"CIBERSORT\", 0.01)\nmcp_labels <- group_labels(mcp_data, \"Abundance\", \"MCP-counter\", 0)\n\nciber_panels <- ciber_labels %>%\n  distinct(Cohort, selection, n_Control, n_UC) %>%\n  arrange(match(selection, c(all_samples, fit_subset)), match(Cohort, cohorts)) %>%\n  mutate(Panel = paste0(\n    Cohort, \"  |  \", if_else(selection == all_samples, \"All included samples\", \"Fit P < 0.05\"),\n    \"\\nControl n = \", n_Control, ",
"\", UC n = \", n_UC\n  ))\nmcp_panels <- mcp_labels %>%\n  distinct(Cohort, selection, n_Control, n_UC) %>%\n  arrange(match(Cohort, cohorts)) %>%\n  mutate(Panel = paste0(Cohort, \"\\nControl n = \", n_Control, \", UC n = \", n_UC))\n\nset_panels <- function(data, panels) {\n  data %>%\n    left_join(select(panels, Cohort, selection, Panel), by = c(\"Cohort\", \"selection\")) %>%\n    mutate(Panel = factor(Panel, levels = panels$Panel))\n}\nciber_data <- set_panels(ciber_data, ciber_panels)\nciber_labels <- set_panels(ciber_labels, ciber_panels)\nmcp_data <- set_panels(mcp_data, mcp_panels)\nmcp_labels <- set_panels(mcp_labels, mcp_panels)\n\n# Keep the original figures' boxplot and jitter layers, colors, and black axes.\n# In the sensitivity figure the original significance symbols use BH-adjusted P.\nbox_layers <- function(box_alpha, jitter_width, point_size, point_alpha) {\n  list(\n    geom_boxplot(\n      aes(color = Group),\n      position = position_dodge(width = 0.75),\n      width = 0.58, outlier.shape = NA, alpha = box_alpha, linewidth = 0.65\n    ),\n    geom_jitter(\n      aes(color = Group),\n      position = position_jitterdodge(\n        jitter.width = jitter_width, dodge.width = 0.75, seed = jitter_seed\n      ),\n      size = point_size, alpha = point_alpha\n    ),\n    scale_fill_manual(values = fill_colors, name = \"Group\"),\n    scale_color_manual(values = outline_colors, name = \"Group\")\n  )\n}\n\nfigure_theme <- theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(hjust = 0.5, face = \"bold\", size = 16, color = \"black\"),\n    plot.title.position = \"plot\",\n    plot.tag = element_text(family = \"serif\", size = 23, hjust = 0, vjust = 1, color = \"black\"),\n    plot.tag.position = c(0.016, 0.985),\n    strip.background = element_blank(),\n    strip.text = element_text(size = 11, color = \"b",
"lack\", lineheight = 0.95),\n    axis.title = element_text(face = \"bold\", size = 13, color = \"black\"),\n    axis.text = element_text(size = 11, color = \"black\"),\n    axis.line = element_line(linewidth = 0.8, color = \"black\"),\n    axis.ticks = element_line(linewidth = 0.7, color = \"black\"),\n    legend.position = \"top\",\n    legend.title = element_text(face = \"bold\", size = 12),\n    legend.text = element_text(size = 12),\n    panel.grid = element_blank(),\n    panel.spacing.x = grid::unit(1.3, \"lines\"),\n    panel.spacing.y = grid::unit(0.9, \"lines\"),\n    plot.margin = margin(9, 13, 5, 9)\n  )\n\np_cibersort <- ggplot(ciber_data, aes(x = Immune, y = Fraction, fill = Group)) +\n  box_layers(0.70, 0.12, 0.65, 0.35) +\n  geom_text(\n    data = ciber_labels,\n    aes(x = Immune, y = y.position, label = Significance),\n    inherit.aes = FALSE, size = 4.2, fontface = \"bold\", color = \"black\"\n  ) +\n  scale_x_discrete(labels = c(\"M0\", \"M1\", \"M2\")) +\n  scale_y_continuous(expand = expansion(mult = c(0.02, 0.11))) +\n  facet_wrap(vars(Panel), ncol = 2, axes = \"all_x\") +\n  labs(tag = \"A\", title = \"CIBERSORT macrophage fractions\", x = NULL,\n       y = \"Estimated fraction\") +\n  figure_theme +\n  coord_cartesian(clip = \"off\")\n\np_mcpcounter <- ggplot(mcp_data, aes(x = Immune, y = Abundance, fill = Group)) +\n  box_layers(0.72, 0.10, 0.45, 0.22) +\n  geom_text(\n    data = mcp_labels,\n    aes(x = Immune, y = y.position, label = Significance),\n    inherit.aes = FALSE, size = 4.3, fontface = \"bold\", color = \"black\"\n  ) +\n  scale_y_continuous(expand = expansion(mult = c(0.02, 0.14))) +\n  facet_wrap(vars(Panel), ncol = 2) +\n  labs(tag = \"B\", title = \"MCP-counter immune cell abundance\", x = NULL,\n       y = \"Abundance score\") +\n  figure_theme +\n  theme(legend.position = \"none\", plot.margin = margin(11, 13, 8, 9)) ",
"+\n  coord_flip(clip = \"off\")\n\nfigure <- wrap_plots(free(p_cibersort, side = \"l\"), p_mcpcounter,\n                     ncol = 1, heights = c(3.15, 1))\npdf_path <- file.path(output_dir, \"Supplementary_Figure_6.pdf\")\npng_path <- file.path(output_dir, \"Supplementary_Figure_6.png\")\nggsave(pdf_path, figure, device = grDevices::cairo_pdf, width = 8.5,\n       height = 7.15, units = \"in\", bg = \"white\")\nggsave(png_path, figure, device = ragg::agg_png, width = 8.5,\n       height = 7.15, units = \"in\", dpi = 600, bg = \"white\")\n\nbind_rows(select(ciber_labels, Cohort, selection, Immune, n_Control, n_UC, BH_P, Significance),\n          select(mcp_labels, Cohort, selection, Immune, n_Control, n_UC, BH_P, Significance)) %>%\n  arrange(match(selection, c(all_samples, fit_subset)), match(Cohort, cohorts), Immune) %>%\n  print(n = Inf)\n")


.immune_required <- function(packages) {
  missing <- packages[!vapply(packages, requireNamespace, logical(1), quietly=TRUE)]
  if (length(missing)) stop("Missing R packages: ", paste(missing, collapse=", "),
                             ". Install explicitly before running; no automatic installation is performed.")
}
.immune_find_input <- function(data_root, rel) {
  package_root <- getOption("tyrobp.package.root", getwd())
  candidates <- unique(c(file.path(data_root, rel),
      file.path(data_root, "immune_inputs", rel),
      file.path(package_root, "data", "immune_inputs", rel)))
  hit <- candidates[dir.exists(candidates)]
  if (!length(hit)) stop("Immune inputs not found. Expected directory: ", rel,
                         ". See input_manifest.csv / README.")
  normalizePath(hit[[1]], winslash="/", mustWork=TRUE)
}
.immune_group <- function(ids) {
  ifelse(grepl("_con$",ids,ignore.case=TRUE),"Control",
         ifelse(grepl("_tra$|_treat$|_treatment$|_UC$",ids,ignore.case=TRUE),"UC",NA))
}
.immune_prepare <- function(stage, data_root, output_root) {
  rel <- if (stage=="fig05_cibersort") "fig5/cibersort" else "fig5/mcpcounter"
  inp <- .immune_find_input(data_root,rel)
  dst <- file.path(output_root,stage)
  dir.create(dst,recursive=TRUE,showWarnings=FALSE)
  dst <- normalizePath(dst,winslash="/",mustWork=TRUE)
  env <- new.env(parent=globalenv())
  env$input_file <- file.path(inp,"four_gene_expression.csv")
  env$gene_list_file <- file.path(inp,"Intersect_Genes.csv")
  expr <- read.csv(env$input_file,row.names=1,check.names=FALSE)
  env$numExpr <- as.matrix(expr);storage.mode(env$numExpr)<-"double"
  if (stage=="fig05_cibersort") {
    scorefile <- "CIBERSORT-Results.csv"
    env$rt <- read.csv(file.path(inp,scorefile),row.names=1,check.names=FALSE)
    env$rt$Group <- .immune_group(rownames(env$rt))
    env$rt$Sample <- rownames(env$rt)
    stopifnot(!anyNA(env$rt$Group))
  } else {
    scorefile <- "MCP-counter-Results.csv"
    env$immune_df <- read.csv(file.path(inp,scorefile),row.names=1,check.names=FALSE)
  }
  # One original CIBERSORT plot re-reads a relative CSV. Use a working copy so
  # all writes remain in the new output directory, never in the source data.
  if (!file.copy(file.path(inp,scorefile),file.path(dst,scorefile),overwrite=TRUE))
    stop("Could not stage score file")
  list(input=inp,output=dst,env=env)
}
run_fig05_cibersort <- function(data_root,output_root,...) {
  .immune_required(c("ggplot2","dplyr","tidyr","reshape2","limma","pheatmap",
                     "RColorBrewer","ggpubr","scales","stringr"))
  x <- .immune_prepare("fig05_cibersort",data_root,output_root)
  old <- getwd();on.exit(setwd(old),add=TRUE);setwd(x$output)
  # The source used random jitter with no explicit seed. Fix only the jitter
  # stream for future reproducibility; numerical results are unchanged.
  set.seed(20261125L)
  eval(parse(text=.immune_source_fig05_cibersort,encoding="UTF-8"),envir=x$env)
  invisible(x$output)
}
run_fig05_mcpcounter <- function(data_root,output_root,...) {
  .immune_required(c("ggplot2","dplyr","reshape2","broom","limma","pheatmap",
                     "RColorBrewer","ggpubr","scales","stringr"))
  x <- .immune_prepare("fig05_mcpcounter",data_root,output_root)
  old <- getwd();on.exit(setwd(old),add=TRUE);setwd(x$output)
  set.seed(20261125L)
  eval(parse(text=.immune_source_fig05_mcpcounter,encoding="UTF-8"),envir=x$env)
  invisible(x$output)
}
run_fig07_cohort_sensitivity <- function(data_root,output_root,...) {
  .immune_required(c("ggplot2","dplyr","reshape2","patchwork","ragg"))
  inp <- .immune_find_input(data_root,"fig7")
  dst <- file.path(output_root,"fig07_cohort_sensitivity")
  dir.create(dst,recursive=TRUE,showWarnings=FALSE)
  dst <- normalizePath(dst,winslash="/",mustWork=TRUE)
  env <- new.env(parent=globalenv());env$.stage_output<-dst
  code <- .immune_source_fig07_cohort_sensitivity
  code <- sub('args <- commandArgs(trailingOnly = TRUE)',
              'args <- character(0)',code,fixed=TRUE)
  code <- sub('output_dir <- if (length(args)) args[[1]] else "."',
              'output_dir <- .stage_output',code,fixed=TRUE)
  old <- getwd();on.exit(setwd(old),add=TRUE);setwd(inp)
  eval(parse(text=code,encoding="UTF-8"),envir=env)
  invisible(dst)
}
IMMUNE_STAGES <- list(fig05_cibersort=run_fig05_cibersort,
                     fig05_mcpcounter=run_fig05_mcpcounter,
                     fig07_cohort_sensitivity=run_fig07_cohort_sensitivity)


R_STAGES <- c(r_stages, IMMUNE_STAGES)

