.R_ORIGINAL_SOURCES <- list(
"bulk/06.\u6570\u636e\u5408\u5e76\u53bb\u6279\u6b21\u5f52\u4e00\u5316/\u6570\u636e\u96c6\u5408\u5e76.R"=paste0("# ===========================\n# \u53c2\u6570\u8bbe\u7f6e\u90e8\u5206\n# ===========================\n\n# \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\nsetwd(\"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\06.\u6570\u636e\u5408\u5e76\u53bb\u6279\u6b21\u5f52\u4e00\u5316\")  # \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\n\n# \u83b7\u53d6\u76ee\u5f55\u4e2d\u6240\u6709\u7684CSV\u6587\u4ef6\nfiles = dir()  # \u83b7\u53d6\u5f53\u524d\u5de5\u4f5c\u76ee\u5f55\u4e0b\u7684\u6240\u6709\u6587\u4ef6\u540d\nfiles = grep(\"\\\\.csv$\", files, value = TRUE)  # \u7b5b\u9009\u51fa\u6240\u6709\u4ee5 \".csv\" \u7ed3\u5c3e\u7684\u6587\u4ef6\ncat(\"\u8bfb\u53d6\u5230\u4ee5\u4e0b\u6587\u4ef6:\\n\")\nprint(files)  # \u6253\u5370\u6587\u4ef6\u5217\u8868\uff0c\u67e5\u770b\u662f\u5426\u6b63\u786e\u52a0\u8f7d\u6587\u4ef6\n\n# \u5224\u65ad\u662f\u5426\u627e\u5230\u7b26\u5408\u6761\u4ef6\u7684\u6587\u4ef6\nif (length(files) == 0) {\n  stop(\"\u6ca1\u6709\u627e\u5230\u4efb\u4f55\u7b26\u5408\u6761\u4ef6\u7684\u6587\u4ef6\uff01\")  # \u5982\u679c\u6ca1\u6709\u627e\u5230\u7b26\u5408\u6761\u4ef6\u7684\u6587\u4ef6\uff0c\u7ec8\u6b62\u6267\u884c\n}\n\n# ===========================\n# \u52a0\u8f7d\u6240\u9700\u7684R\u5305\n# ===========================\n\n# \u52a0\u8f7d `limma` \u548c `sva` \u5305\u7528\u4e8e\u6570\u636e\u5904\u7406\u4e0e\u6279\u6b21\u6548\u5e94\u6821\u6b63\nlibrary(patchwork)\nlibrary(data.table)\nlibrary(limma)\nlibrary(ggplot2)\nlibrary(reshape2)\nlibrary(sva)   \nlibrary(tools)\nlibrary(ggpubr)\nlibrary(RColorBrewer)\n# ===========================\n# \u521d\u59cb\u5316\u53d8\u91cf\n# ===========================\n\n# \u521b\u5efa\u4e00\u4e2a\u7a7a\u5217\u8868\u5b58\u50a8\u57fa\u56e0\u4fe1\u606f\ngeneList = list()  \n\n# \u8fdb\u5ea6\u6761\u521d\u59cb\u5316\ntotalFiles = length(files)  # \u8ba1\u7b97\u603b\u6587\u4ef6\u6570\nprogressBar = txtProgressBar(min = 0, max = totalFiles, style = 3)  # \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\n\n# ===========================\n# \u8bfb\u53d6\u6587\u4ef6\u5e76\u63d0\u53d6\u57fa\u56e0\u4fe1\u606f\n# ===========================\n\n# \u904d\u5386\u6bcf\u4e2aCSV\u6587\u4ef6\uff0c\u63d0\u53d6\u57fa\u56e0\u4fe1\u606f\nfor (i in 1:totalFiles) {\n  \n  file = files[i]  # \u83b7\u53d6\u5f53\u524d\u6587\u4ef6\u540d\n  \n  # \u8df3\u8fc7\u5df2\u5904\u7406\u7684\u6807\u51c6\u5316\u524d\u548c\u6807\u51c6\u5316\u540e\u7684\u6587\u4ef6\n  if (file %in% c(\"combined_raw_data.csv\", \"batch_corrected_data.csv\")) next\n  \n  cat(\"\u6b63\u5728\u5904\u7406\u6587\u4ef6:\", file, \"\\n\")  # \u6253\u5370\u6b63\u5728\u5904\u7406\u7684\u6587\u4ef6\n  \n  # \u8bfb\u53d6CSV\u6587\u4ef6\n  dataMatrix = read.csv(file, header = TRUE, check.names = FALSE)  \n  geneNames = as.vector(dataMatrix[, 1])  # \u63d0\u53d6\u57fa\u56e0\u540d\u5217\n  uniqueGene = unique(geneNames)  # \u53bb\u9664\u91cd\u590d\u7684\u57fa\u56e0\u540d\n  \n  # \u4ece\u6587\u4ef6\u540d\u4e2d\u63d0\u53d6\u552f\u4e00\u6807\u8bc6\u7b26\n  header = unlist(strsplit(file, \"\\\\.|\\\\-\"))\n  geneList[[header[1]]] = uniqueGene  # \u5c06\u57fa\u56e0\u540d\u5b58\u5165 geneList\n  \n  # \u66f4\u65b0\u8fdb\u5ea6\u6761\n  setTxtProgressBar(progressBar, i)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\n  \n}\n\n# ===========================\n# \u8ba1\u7b97\u5171\u540c\u57fa\u56e0\n# ===========================\n\n# \u83b7\u53d6\u6240\u6709\u6587\u4ef6\u4e2d\u7684\u5171\u540c\u57fa\u56e0\ncommonGenes = Reduce(intersect, geneList)  # \u83b7\u53d6\u4ea4\u96c6\u57fa\u56e0\ncat(\"\u5171\u6709\", length(commonGenes), \"\u4e2a\u5171\u540c\u57fa\u56e0\\n\")\n\n# ===========================\n# \u6570\u636e\u5408\u5e76\n# =============",
"==============\n\n# \u521b\u5efa\u6570\u636e\u6846\u5b58\u50a8\u5408\u5e76\u540e\u7684\u6570\u636e\u548c\u6279\u6b21\u4fe1\u606f\ncombinedData = data.frame()  \nbatchType = c()  \n\n# \u904d\u5386\u6bcf\u4e2a\u6587\u4ef6\uff0c\u8bfb\u53d6\u5e76\u5408\u5e76\u6570\u636e\nfor (i in 1:totalFiles) {\n  \n  file = files[i]  # \u83b7\u53d6\u5f53\u524d\u6587\u4ef6\u540d\n  \n  # \u8df3\u8fc7\u5df2\u5408\u5e76\u7684\u6807\u51c6\u5316\u524d\u548c\u6807\u51c6\u5316\u540e\u7684\u6587\u4ef6\n  if (file %in% c(\"combined_raw_data.csv\", \"batch_corrected_data.csv\")) next\n  \n  # \u4ece\u6587\u4ef6\u540d\u4e2d\u63d0\u53d6\u552f\u4e00\u6807\u8bc6\u7b26\n  header = unlist(strsplit(file, \"\\\\.|\\\\-\"))\n  \n  # \u8bfb\u53d6\u8868\u8fbe\u77e9\u9635\u6570\u636e\n  rt = read.csv(file, header = TRUE, check.names = FALSE)\n  rt = as.matrix(rt)  # \u8f6c\u6362\u4e3a\u77e9\u9635\u683c\u5f0f\n  rownames(rt) = rt[, 1]  # \u8bbe\u7f6e\u884c\u540d\u4e3a\u57fa\u56e0\u540d\n  expr = rt[, -1]  # \u53bb\u9664\u57fa\u56e0\u540d\u5217\uff0c\u4ec5\u4fdd\u7559\u8868\u8fbe\u6570\u636e\n  dimnames = list(rownames(expr), colnames(expr))  # \u8bbe\u7f6e\u884c\u5217\u540d\n  \n  # \u8f6c\u6362\u4e3a\u6570\u503c\u77e9\u9635\u5e76\u5904\u7406\u91cd\u590d\u503c\n  numericData = matrix(as.numeric(as.matrix(expr)), nrow = nrow(expr), dimnames = dimnames)\n  rt = avereps(numericData)  # \u5e73\u5747\u91cd\u590d\u503c\u5904\u7406\n  \n  # \u4fee\u6539\u5217\u540d\uff0c\u6dfb\u52a0\u6587\u4ef6\u6807\u8bc6\u7b26\n  colnames(rt) = paste0(header[1], \"_\", colnames(rt))\n  \n  # \u5408\u5e76\u5f53\u524d\u6570\u636e\u5230\u603b\u6570\u636e\u6846\n  if (i == 1) {\n    combinedData = rt[commonGenes, ]  # \u7b2c\u4e00\u4e2a\u6587\u4ef6\u76f4\u63a5\u8d4b\u503c\n  } else {\n    combinedData = cbind(combinedData, rt[commonGenes, ])  # \u5176\u4f59\u6587\u4ef6\u6309\u5217\u5408\u5e76\n  }\n  \n  batchType = c(batchType, rep(header[1], ncol(rt)))  # \u7528\u6570\u636e\u96c6\u540d\u5b57\n}\n\n# ===========================\n# \u521b\u5efa\u8f93\u51fa\u6587\u4ef6\u5939\n# ===========================\n\n# \u521b\u5efa\u4e00\u4e2a\u540d\u4e3a \"Processed_Data\" \u7684\u6587\u4ef6\u5939\u6765\u5b58\u50a8\u8f93\u51fa\u6587\u4ef6\noutputDir = \"Processed_Data\"\nif (!dir.exists(outputDir)) {\n  dir.create(outputDir)  # \u5982\u679c\u6587\u4ef6\u5939\u4e0d\u5b58\u5728\uff0c\u5219\u521b\u5efa\n  cat(\"\u5df2\u521b\u5efa\u6587\u4ef6\u5939\uff1a\", outputDir, \"\\n\")\n}\n\n# ===========================\n# \u4fdd\u5b58\u5408\u5e76\u540e\u7684\u6570\u636e - \u5408\u5e76\u524d\u6807\u51c6\u5316\n# ===========================\n\n# \u5c06\u5408\u5e76\u540e\u7684\u6570\u636e\u4fdd\u5b58\u4e3a CSV \u6587\u4ef6\nfinalData = rbind(geneNames = colnames(combinedData), combinedData)\noutputFileRaw = file.path(outputDir, \"combined_raw_data.csv\")\nwrite.table(finalData, file = outputFileRaw, sep = \",\", quote = FALSE, col.names = FALSE)\ncat(\"\u6807\u51c6\u5316\u524d\u6570\u636e\u5df2\u4fdd\u5b58\uff1a\", outputFileRaw, \"\\n\")\n\n# ===========================\n# \u6279\u6b21\u6548\u5e94\u6821\u6b63 - \u4f7f\u7528ComBat\n# ===========================\n\n# \u5bf9\u5408\u5e76\u540e\u7684\u6570\u636e\u8fdb\u884c\u6279\u6b21\u6548\u5e94\u6821\u6b63\ncorrectedData = ComBat(combinedData, batchType, par.prior = TRU",
"E)  # \u4f7f\u7528ComBat\u8fdb\u884c\u6279\u6b21\u6548\u5e94\u6821\u6b63\ncorrectedData = rbind(geneNames = colnames(correctedData), correctedData)  # \u6dfb\u52a0\u57fa\u56e0\u540d\n\n# \u4fdd\u5b58\u6279\u6b21\u6548\u5e94\u6821\u6b63\u540e\u7684\u6570\u636e\noutputFileCorrected = file.path(outputDir, \"batch_corrected_data.csv\")\nwrite.table(correctedData, file = outputFileCorrected, sep = \",\", quote = FALSE, col.names = FALSE)\ncat(\"\u6279\u6b21\u6548\u5e94\u6821\u6b63\u540e\u7684\u6570\u636e\u5df2\u4fdd\u5b58\uff1a\", outputFileCorrected, \"\\n\")\n\n\n\n\n# 7. \u9ad8\u7ea7PCA\u51fd\u6570\npca_advanced_plot <- function(mat, batch_info, title, file=NULL){\n  data_pca <- prcomp(t(mat), scale. = TRUE)\n  pc_var   <- data_pca$sdev^2 / sum(data_pca$sdev^2)  # \u65b9\u5dee\u89e3\u91ca\u6bd4\u4f8b\n  pca_df <- data.frame(\n    Sample = rownames(data_pca$x),\n    PC1   = data_pca$x[,1],\n    PC2   = data_pca$x[,2],\n    Batch = factor(batch_info, levels=unique(batch_info))\n  )\n  n_batch <- length(unique(batch_info))\n  mycol <- brewer.pal(min(n_batch, 8), \"Set1\")\n  if(n_batch > 8) mycol <- colorRampPalette(brewer.pal(9,\"Set1\"))(n_batch)\n  pc1_lab <- paste0(\"PC1 (\", round(pc_var[1]*100, 1),\"%)\")\n  pc2_lab <- paste0(\"PC2 (\", round(pc_var[2]*100, 1),\"%)\")\n  \n  p <- ggplot(pca_df, aes(x = PC1, y = PC2, color = Batch)) +\n    geom_point(size=4, alpha=0.90) +\n    stat_ellipse(aes(fill=Batch), geom=\"polygon\", alpha=0.14, linetype=2, show.legend=FALSE) +\n    scale_color_manual(values = mycol) +\n    scale_fill_manual(values = mycol) +\n    labs(title=title, x=pc1_lab, y=pc2_lab, color=\"Batch\") +\n    theme_bw(base_size=14) +\n    theme(\n      panel.grid.major = element_line(colour=\"gray90\", linetype=2),\n      legend.title = element_text(face=\"bold\"),\n      legend.background = element_rect(colour=\"black\", fill=NA, size=0.25),\n      plot.title = element_text(size=16, face=\"bold\"),\n      axis.title = element_text(face=\"bold\")\n    )\n  if(!is.null(file)){\n    ggsave(file, p, width=8, height=6)\n  }\n  return(p)\n}\n\n# \u8f93\u51faPCA PDF\n# \u4e3aPCA\u5206\u6790\u51c6\u5907\u6570\u636e\ncorrectedDataForPCA <- as.mat",
"rix(correctedData[-1, ])  # \u53bb\u9664\u7b2c\u4e00\u884c\u57fa\u56e0\u540d\nmode(correctedDataForPCA) <- \"numeric\"  # \u786e\u4fdd\u662f\u6570\u503c\u77e9\u9635\n\npca_advanced_plot(combinedData, batchType, \"PCA Before Batch Effect Removal\",\n                  file.path(outputDir, \"PCA_Advanced_Before_Batch_Removal.pdf\"))\npca_advanced_plot(correctedDataForPCA, batchType, \"PCA After Batch Effect Removal\",\n                  file.path(outputDir, \"PCA_Advanced_After_Batch_Removal.pdf\"))\n\n# 8. \u6837\u672c\u6279\u6b21\u8868\nsample_batch_df <- data.frame(\n  Sample = colnames(combinedData),  # \u4f7f\u7528 combinedData\n  Batch  = batchType,  # \u4f7f\u7528 batchType\n  stringsAsFactors = FALSE\n)\nwrite.table(\n  sample_batch_df, file = file.path(outputDir, \"sample_batch_info.txt\"),  # \u4f7f\u7528 outputDir\n  sep = \"\\t\", row.names = FALSE, quote = FALSE\n)\n\n# 9. PCA \u5f97\u5206\u8868\uff08\u5408\u5e76\u524d/\u540e\uff09\ndata_pca_before <- prcomp(t(combinedData), scale. = TRUE)  # \u4f7f\u7528 combinedData\npca_score_before <- data.frame(\n  Sample = colnames(combinedData),\n  PC1 = data_pca_before$x[,1],\n  PC2 = data_pca_before$x[,2],\n  Batch = batchType\n)\nwrite.table(\n  pca_score_before, file = file.path(outputDir, \"PCA_scores_before.txt\"),\n  sep = \"\\t\", row.names = FALSE, quote = FALSE\n)\n\ndata_pca_after <- prcomp(t(correctedDataForPCA), scale. = TRUE)  # \u4f7f\u7528\u5904\u7406\u540e\u7684\u6821\u6b63\u6570\u636e\npca_score_after <- data.frame(\n  Sample = colnames(combinedData),\n  PC1 = data_pca_after$x[,1],\n  PC2 = data_pca_after$x[,2],\n  Batch = batchType\n)\nwrite.table(\n  pca_score_after, file = file.path(outputDir, \"PCA_scores_after.txt\"),\n  sep = \"\\t\", row.names = FALSE, quote = FALSE\n)\n"),
"bulk/07.\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u7684\u5dee\u5f02\u5206\u6790-\u591a\u6570\u636e/modified_DE_analysis_beautified_volcano_heatmap.R"=paste0("# ========================== 0. \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\uff08\u53ef\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u4fee\u6539\uff09 ==========================\nsetwd(\"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\07.\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u7684\u5dee\u5f02\u5206\u6790-\u591a\u6570\u636e\")  # \u5efa\u8bae\u4f7f\u7528\u6b63\u659c\u6760\uff0c\u907f\u514d Windows \u53cd\u659c\u6760\u5bfc\u81f4\u7684\u9519\u8bef\nthreshold_logFC <- 1        # log2\u6298\u53e0\u53d8\u5316\u9608\u503c\nthreshold_adjP  <- 0.05     # \u8c03\u6574\u540eP\u503c\u9608\u503c\nmax_display_genes <- 20     # \u70ed\u56fe\u4e2d\u6bcf\u4fa7\uff08\u4e0a\u8c03\u548c\u4e0b\u8c03\uff09\u5c55\u793a\u7684\u57fa\u56e0\u6700\u5927\u6570\u91cf\nlabel_top_each <- 20        # \u706b\u5c71\u56fe\u6bcf\u4fa7\u6700\u591a\u6807\u6ce8\u7684\u57fa\u56e0\u6570\n\nresult_dir <- \"result_csv\"\nif(!dir.exists(result_dir)) dir.create(result_dir)\n\n# ========================== 1. \u8f7d\u5165\u5fc5\u8981\u7684R\u5305 ==========================\nstep1_start <- Sys.time()\ncat(\"[Step 1] \u5f00\u59cb\u8f7d\u5165R\u5305...\\n\")\n\nload_pkg <- function(pkg, bioc = FALSE) {\n  if (!requireNamespace(pkg, quietly = TRUE)) {\n    if (bioc) {\n      if (!requireNamespace(\"BiocManager\", quietly = TRUE)) install.packages(\"BiocManager\")\n      BiocManager::install(pkg, update = FALSE, ask = FALSE)\n    } else {\n      install.packages(pkg)\n    }\n  }\n  suppressPackageStartupMessages(library(pkg, character.only = TRUE))\n}\n\nload_pkg(\"limma\", bioc = TRUE)\nload_pkg(\"ggplot2\")\nload_pkg(\"ggrepel\")\nload_pkg(\"RColorBrewer\")\nload_pkg(\"scales\")\nload_pkg(\"grid\")\nload_pkg(\"ComplexHeatmap\", bioc = TRUE)\nload_pkg(\"circlize\")\n\nstep1_end <- Sys.time()\ncat(\"[Step 1] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step1_end, step1_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 2. \u8bfb\u53d6\u8868\u8fbe\u77e9\u9635\u5e76\u4fdd\u8bc1\u6570\u503c\u578b ==========================\nstep2_start <- Sys.time()\ncat(\"[Step 2] \u5f00\u59cb\u8bfb\u53d6\u8868\u8fbe\u77e9\u9635...\\n\")\n\nfile_expr <- \"batch_corrected_data.csv\"\n\ntmp_head <- readLines(file_expr, 1)\nsep <- ifelse(grepl(\",\", tmp_head), \",\", \"\\t\")\n\nexpr_raw <- read.table(file_expr,\n                       header = TRUE,\n                       sep = sep,\n                       check.names = FALSE,\n                       stringsAsFactors = FALSE)\n\nrownames(expr_raw) <- expr_raw[, 1]\nexpr_mat <- expr_raw[, -1, drop = FALSE]\n\n# \u5f3a\u5236\u8f6c\u4e3a\u6570\u503c\u77e9\u9635\nexpr_mat <- as",
".matrix(expr_mat)\nexpr_mat <- apply(expr_mat, 2, as.numeric)\nrownames(expr_mat) <- rownames(expr_raw)\ncolnames(expr_mat) <- colnames(expr_raw)[-1]\ncombined_expr <- expr_mat\n\nif(!is.numeric(expr_mat)) stop(\"\u8868\u8fbe\u77e9\u9635\u4ecd\u5b58\u5728\u975e\u6570\u503c\u5217\uff01\")\ncat(\"\u8868\u8fbe\u77e9\u9635\u7ef4\u5ea6:\", dim(expr_mat)[1], \"\u57fa\u56e0 x\", dim(expr_mat)[2], \"\u6837\u672c\\n\")\n\nstep2_end <- Sys.time()\ncat(\"[Step 2] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step2_end, step2_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 3. \u81ea\u52a8\u5224\u65ad\u5206\u7ec4\u4fe1\u606f ==========================\nstep3_start <- Sys.time()\ncat(\"[Step 3] \u5f00\u59cb\u8bc6\u522b\u5206\u7ec4\u4fe1\u606f...\\n\")\n\nsample_names <- colnames(expr_mat)\ngroup_info <- ifelse(grepl(\"_con$\", sample_names, ignore.case = TRUE), \"Control\",\n                     ifelse(grepl(\"_tra$\", sample_names, ignore.case = TRUE), \"Treatment\", \"Unknown\"))\n\nif(any(group_info == \"Unknown\")) stop(\"\u5206\u7ec4\u672a\u77e5\u7684\u6837\u672c\u5b58\u5728\uff0c\u8bf7\u68c0\u67e5\u6837\u672c\u540d\u540e\u7f00\uff01\")\n\nnum_ctrl <- sum(group_info == \"Control\")\nnum_treat <- sum(group_info == \"Treatment\")\ncat(\"\u5206\u7ec4\u60c5\u51b5\uff1aControl =\", num_ctrl, \", Treatment =\", num_treat, \"\\n\")\n\nstep3_end <- Sys.time()\ncat(\"[Step 3] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step3_end, step3_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 4. \u5dee\u5f02\u8868\u8fbe\u5206\u6790\uff08limma\uff09 ==========================\nstep4_start <- Sys.time()\ncat(\"[Step 4] \u5f00\u59cb\u5dee\u5f02\u8868\u8fbe\u5206\u6790...\\n\")\n\ngroup_labels <- factor(group_info, levels = c(\"Control\", \"Treatment\"))\ndesign_mat <- model.matrix(~0 + group_labels)\ncolnames(design_mat) <- c(\"Control\", \"Treatment\")\n\nfit <- lmFit(expr_mat, design_mat)\ncontrast_mat <- makeContrasts(Treatment - Control, levels = design_mat)\nfit2 <- contrasts.fit(fit, contrast_mat)\nfit2 <- eBayes(fit2)\n\nall_diff_results <- topTable(fit2, adjust.method = \"fdr\", number = Inf)\ncat(\"\u5dee\u5f02\u5206\u6790\u5b8c\u6210\uff01\u53d1\u73b0 FDR < 0.05 \u57fa\u56e0\u6570\uff1a\", sum(all_diff_results$adj.P.Val < 0.05), \"\\n\")\n\nwrite.table(cbind(Gene = rownames(all_diff_results), all_diff_results),\n            file = \"DE_",
"results.csv\",\n            sep = \",\",\n            quote = FALSE,\n            row.names = FALSE)\n\nstep4_end <- Sys.time()\ncat(\"[Step 4] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step4_end, step4_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 5. \u7b5b\u9009\u663e\u8457\u5dee\u5f02\u57fa\u56e0\u5e76\u8f93\u51fa ==========================\nstep5_start <- Sys.time()\ncat(\"[Step 5] \u5f00\u59cb\u7b5b\u9009\u663e\u8457\u5dee\u5f02\u57fa\u56e0...\\n\")\n\nsignificant_DEGs <- all_diff_results[with(all_diff_results,\n                                          abs(logFC) > threshold_logFC & adj.P.Val < threshold_adjP), ]\n\noutput_DEGs <- cbind(Gene = rownames(significant_DEGs), significant_DEGs)\n\nSE <- ifelse(as.numeric(output_DEGs[, \"t\"]) != 0,\n             abs(as.numeric(output_DEGs[, \"logFC\"]) / as.numeric(output_DEGs[, \"t\"])),\n             NA)\n\noutput_DEGs <- cbind(output_DEGs, SE = SE)\noutput_DEGs <- as.data.frame(output_DEGs, stringsAsFactors = FALSE)\n\n# \u65b0\u589e\u4e0a\u4e0b\u8c03\u5217\noutput_DEGs$Regulation <- ifelse(as.numeric(output_DEGs$logFC) > 0, \"Up\", \"Down\")\n\ndesired_order <- c(\"Gene\", \"logFC\", \"Regulation\", \"SE\", \"AveExpr\", \"t\", \"P.Value\", \"adj.P.Val\", \"B\")\nexisting_cols <- intersect(desired_order, colnames(output_DEGs))\noutput_DEGs <- output_DEGs[, c(existing_cols, setdiff(colnames(output_DEGs), existing_cols))]\n\nwrite.csv(output_DEGs, file = \"DE_significant_genes.csv\", row.names = FALSE)\n\n# \u540c\u65f6\u8f93\u51fa\u5dee\u5f02\u57fa\u56e0\u5217\u8868\uff0c\u4fbf\u4e8e\u540e\u7eed\u5bcc\u96c6\u5206\u6790\nwrite.table(data.frame(gene = rownames(significant_DEGs)),\n            file = \"DEG_geneList.txt\",\n            sep = \"\\t\",\n            quote = FALSE,\n            row.names = FALSE,\n            col.names = TRUE)\n\nstep5_end <- Sys.time()\ncat(\"[Step 5] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step5_end, step5_start, units = \"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 6. \u7f8e\u5316\u70ed\u56fe\uff1aComplexHeatmap + \u9876\u90e8\u5206\u5e03\u5bc6\u5ea6\u56fe ==========================\nstep6_start <- Sys.time()\ncat(\"[Step 6] \u5f00\u59cb\u7ed8\u5236\u7f8e\u5316\u70ed\u56fe...\\n\")\n\nif(nrow(significant",
"_DEGs) == 0) {\n  cat(\"\u8b66\u544a\uff1a\u672a\u53d1\u73b0\u663e\u8457\u5dee\u5f02\u57fa\u56e0\uff0c\u8df3\u8fc7\u70ed\u56fe\u7ed8\u5236\u3002\\n\")\n} else {\n\n  # 1. \u9009\u62e9\u5c55\u793a\u57fa\u56e0\uff1a\u4e0b\u8c03Top + \u4e0a\u8c03Top\n  ordered_DEGs <- significant_DEGs[order(as.numeric(significant_DEGs$logFC)), ]\n  ordered_gene_names <- rownames(ordered_DEGs)\n  total_DEG_count <- length(ordered_gene_names)\n\n  if (total_DEG_count > (max_display_genes * 2)) {\n    selected_gene_set <- ordered_gene_names[c(\n      1:max_display_genes,\n      (total_DEG_count - max_display_genes + 1):total_DEG_count\n    )]\n  } else {\n    selected_gene_set <- ordered_gene_names\n  }\n\n  selected_gene_set <- intersect(selected_gene_set, rownames(combined_expr))\n  heatmap_expr <- combined_expr[selected_gene_set, , drop = FALSE]\n\n  # 2. \u6309\u884c\u505aZ-score\u6807\u51c6\u5316\uff1b\u82e5\u51fa\u73b0NA\u6216Inf\uff0c\u7f6e\u4e3a0\n  heatmap_expr_scaled <- t(scale(t(heatmap_expr)))\n  heatmap_expr_scaled[!is.finite(heatmap_expr_scaled)] <- 0\n\n  # 3. \u6309\u5206\u7ec4\u6392\u5e8f\u6837\u672c\uff0c\u4fdd\u8bc1Control\u5728\u524d\uff0cTreatment\u5728\u540e\n  sample_order <- order(factor(group_info, levels = c(\"Control\", \"Treatment\")))\n  heatmap_expr_scaled <- heatmap_expr_scaled[, sample_order, drop = FALSE]\n\n  sample_annotation <- data.frame(\n    Group = factor(group_info[sample_order], levels = c(\"Control\", \"Treatment\"))\n  )\n  rownames(sample_annotation) <- colnames(heatmap_expr_scaled)\n\n  annotation_colors <- list(\n    Group = c(\"Control\" = \"#66C2A5\",\n              \"Treatment\" = \"#FC8D62\")\n  )\n\n  # 4. \u9876\u90e8\u6ce8\u91ca\uff1a\u8868\u8fbe\u5206\u5e03\u5bc6\u5ea6\u56fe + \u5206\u7ec4\u6761\n  ha_top <- HeatmapAnnotation(\n    Distribution = anno_density(heatmap_expr_scaled,\n                                type = \"heatmap\",\n                                which = \"column\",\n                                height = unit(1.8, \"cm\")),\n    Group = sample_annotation$Group,\n    col = annotation_colors,\n    annotation_name_side = \"left\",\n    annotation_name_gp = gpar(fontsize = 11, fontface = \"bold\")\n  )\n\n  # 5. \u84dd-\u767d-\u7ea2\u914d\u8272\n  color_fun <- colorRamp2(c(-2, 0, 2), c(\"#31369",
"5\", \"white\", \"#A50026\"))\n\n  # 6. \u4e3a\u884c\u540d\u6dfb\u52a0\u4e0a\u4e0b\u8c03\u6807\u8bb0\n  gene_logFC <- significant_DEGs[rownames(heatmap_expr_scaled), \"logFC\"]\n  gene_labels <- paste0(\n    rownames(heatmap_expr_scaled),\n    ifelse(gene_logFC > 0, \" (Up)\", \" (Down)\")\n  )\n  names(gene_labels) <- rownames(heatmap_expr_scaled)\n\n  ht <- Heatmap(\n    heatmap_expr_scaled,\n    name = \"Expression\\n(Z-score)\",\n    col = color_fun,\n    top_annotation = ha_top,\n    cluster_columns = FALSE,\n    cluster_rows = TRUE,\n    show_column_names = FALSE,\n    row_labels = gene_labels[rownames(heatmap_expr_scaled)],\n    row_names_gp = gpar(fontsize = 8, fontface = \"italic\"),\n    column_title = paste0(\"Differential Expression Heatmap with Distribution\\n\",\n                          \"Control: \", num_ctrl, \" | Treatment: \", num_treat),\n    column_title_gp = gpar(fontsize = 14, fontface = \"bold\"),\n    heatmap_legend_param = list(\n      title_gp = gpar(fontsize = 11, fontface = \"bold\"),\n      labels_gp = gpar(fontsize = 9)\n    )\n  )\n\n  heatmap_height <- max(6, min(14, length(selected_gene_set) * 0.18 + 4))\n\n  save_heatmap_pdf <- function(file_name) {\n    pdf(file_name, width = 12, height = heatmap_height)\n    draw(ht, heatmap_legend_side = \"right\", annotation_legend_side = \"right\")\n    dev.off()\n  }\n\n  # \u540c\u65f6\u4fdd\u5b58\u4e3a\u65b0\u6587\u4ef6\u540d\u548c\u539f\u6587\u4ef6\u540d\uff0c\u65b9\u4fbf\u66ff\u6362\u539f\u7ed3\u679c\n  save_heatmap_pdf(\"DE_heatmap_with_distribution.pdf\")\n  save_heatmap_pdf(\"DE_heatmap.pdf\")\n\n  cat(\"\u7f8e\u5316\u70ed\u56fe\u5df2\u4fdd\u5b58\uff1aDE_heatmap_with_distribution.pdf \u548c DE_heatmap.pdf\\n\")\n}\n\nstep6_end <- Sys.time()\ncat(\"[Step 6] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step6_end, step6_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 7. \u7f8e\u5316\u706b\u5c71\u56fe\uff1a\u6e10\u53d8\u8272 + \u6c14\u6ce1\u5927\u5c0f + Top\u57fa\u56e0\u6807\u7b7e ==========================\nstep7_start <- Sys.time()\ncat(\"[Step 7] \u5f00\u59cb\u7ed8\u5236\u7f8e\u5316\u706b\u5c71\u56fe...\\n\")\n\nvolcano_data <- all_diff_results\nvolcano_data$Gene <- rownames(volcano_data)\nvolcano_data$logFC <",
"- as.numeric(volcano_data$logFC)\nvolcano_data$adj.P.Val <- as.numeric(volcano_data$adj.P.Val)\n\n# \u9632\u6b62adj.P.Val\u4e3a0\u5bfc\u81f4-log10\u4e3aInf\nmin_positive_p <- suppressWarnings(min(volcano_data$adj.P.Val[volcano_data$adj.P.Val > 0], na.rm = TRUE))\nif (!is.finite(min_positive_p)) min_positive_p <- 1e-300\nvolcano_data$adj.P.Val[!is.finite(volcano_data$adj.P.Val) | volcano_data$adj.P.Val <= 0] <- min_positive_p * 0.1\n\nvolcano_data$negLog10FDR <- -log10(volcano_data$adj.P.Val)\n\nvolcano_data$Group <- \"Not Significant\"\nvolcano_data$Group[volcano_data$logFC > threshold_logFC & volcano_data$adj.P.Val < threshold_adjP] <- \"Up regulated\"\nvolcano_data$Group[volcano_data$logFC < -threshold_logFC & volcano_data$adj.P.Val < threshold_adjP] <- \"Down regulated\"\n\nup_count <- sum(volcano_data$Group == \"Up regulated\", na.rm = TRUE)\ndown_count <- sum(volcano_data$Group == \"Down regulated\", na.rm = TRUE)\nnot_count <- sum(volcano_data$Group == \"Not Significant\", na.rm = TRUE)\n\n# \u9009\u62e9\u6807\u7b7e\u57fa\u56e0\uff1a\u5982\u679c\u663e\u8457\u57fa\u56e0\u4e0d\u591a\u5c31\u5168\u90e8\u6807\uff1b\u5426\u5219\u6bcf\u4fa7\u6309adj.P.Val\u6700\u5c0f\u4f18\u5148\u6807\u6ce8\nsig_data <- volcano_data[volcano_data$Group != \"Not Significant\", , drop = FALSE]\n\nif (nrow(sig_data) <= label_top_each * 2) {\n  label_genes <- sig_data$Gene\n  cat(\"\u663e\u8457\u5dee\u5f02\u57fa\u56e0\u6570\u91cf\u4e0d\u591a\uff0c\u5168\u90e8\u6807\u8bb0\uff1a\", length(label_genes), \"\u4e2a\u57fa\u56e0\\n\")\n} else {\n  up_data <- sig_data[sig_data$Group == \"Up regulated\", , drop = FALSE]\n  down_data <- sig_data[sig_data$Group == \"Down regulated\", , drop = FALSE]\n\n  up_data <- up_data[order(up_data$adj.P.Val, -abs(up_data$logFC)), , drop = FALSE]\n  down_data <- down_data[order(down_data$adj.P.Val, -abs(down_data$logFC)), , drop = FALSE]\n\n  up_label <- head(up_data$Gene, min(label_top_each, nrow(up_data)))\n  down_label <- head(down_data$Gene, min(label_top_each, nrow(down_data)))\n\n  label_genes <- unique(c(up_label, down_label))\n  cat(\"\u6807\u8bb0\u4e0a\u8c03Top\", length(up_label), \"\u548c\u4e0b\u8c03Top\", length(down_label)",
",\n      \"\uff0c\u5171\", length(label_genes), \"\u4e2a\u57fa\u56e0\\n\")\n}\n\nvolcano_data$label_gene <- ifelse(volcano_data$Gene %in% label_genes, volcano_data$Gene, \"\")\n\n# \u8ba1\u7b97\u5750\u6807\u8303\u56f4\nx_limit <- max(abs(volcano_data$logFC), threshold_logFC * 2, na.rm = TRUE) * 1.12\ny_max <- max(volcano_data$negLog10FDR, -log10(threshold_adjP) * 1.5, na.rm = TRUE) * 1.12\n\nsize_breaks <- pretty(volcano_data$negLog10FDR, n = 5)\nsize_breaks <- size_breaks[size_breaks > 0 & size_breaks <= max(volcano_data$negLog10FDR, na.rm = TRUE)]\n\ngradient_volcano <- ggplot(volcano_data, aes(x = logFC, y = negLog10FDR)) +\n\n  # \u70b9\u989c\u8272\u6309\u7167logFC\u8fde\u7eed\u6e10\u53d8\uff0c\u5927\u5c0f\u6309\u7167\u663e\u8457\u6027\u5f3a\u5f31\u53d8\u5316\n  geom_point(aes(color = logFC, size = negLog10FDR), alpha = 0.85) +\n\n  # \u88ab\u6807\u6ce8\u57fa\u56e0\u52a0\u9ed1\u8272\u5916\u6846\uff0c\u4fbf\u4e8e\u5b9a\u4f4d\n  geom_point(data = subset(volcano_data, label_gene != \"\"),\n             aes(size = negLog10FDR),\n             shape = 21,\n             fill = NA,\n             color = \"black\",\n             stroke = 1.1,\n             show.legend = FALSE) +\n\n  scale_color_gradientn(\n    colors = c(\"#2B83BA\", \"#5AAE61\", \"#A6D96A\", \"#FFFFBF\", \"#FEE08B\", \"#FDAE61\", \"#D7191C\"),\n    values = scales::rescale(seq(-x_limit, x_limit, length.out = 7)),\n    limits = c(-x_limit, x_limit),\n    oob = scales::squish,\n    name = \"log2FC\"\n  ) +\n\n  scale_size_continuous(\n    range = c(0.7, 6.5),\n    name = \"-log10(FDR)\",\n    breaks = size_breaks,\n    labels = round(size_breaks, 1)\n  ) +\n\n  geom_vline(xintercept = c(-threshold_logFC, threshold_logFC),\n             linetype = \"dashed\", color = \"grey45\", size = 0.6) +\n  geom_hline(yintercept = -log10(threshold_adjP),\n             linetype = \"dashed\", color = \"grey45\", size = 0.6) +\n\n  geom_text_repel(\n    data = subset(volcano_data, label_gene != \"\"),\n    aes(label = label_gene),\n    size = 3.1,\n    max.overlaps = Inf,\n    box.padding = 0.45,\n    point.padding = 0.25,\n    segment.color = \"",
"grey40\",\n    segment.size = 0.3,\n    fontface = \"italic\",\n    color = \"black\",\n    show.legend = FALSE\n  ) +\n\n  # \u4e0a\u4e0b\u8c03\u65b9\u5411\u4e0e\u6570\u91cf\u6807\u6ce8\n  annotate(\"segment\", x = -x_limit * 0.50, xend = -x_limit * 0.88,\n           y = y_max * 0.94, yend = y_max * 0.94,\n           arrow = arrow(length = unit(0.22, \"cm\"), type = \"closed\"),\n           color = \"#2B83BA\", size = 1.0) +\n  annotate(\"text\", x = -x_limit * 0.69, y = y_max * 0.94,\n           label = paste0(\"Down (\", down_count, \")\"),\n           color = \"#2B83BA\", fontface = \"bold\", size = 4.2, vjust = -0.8) +\n\n  annotate(\"segment\", x = x_limit * 0.50, xend = x_limit * 0.88,\n           y = y_max * 0.94, yend = y_max * 0.94,\n           arrow = arrow(length = unit(0.22, \"cm\"), type = \"closed\"),\n           color = \"#D7191C\", size = 1.0) +\n  annotate(\"text\", x = x_limit * 0.69, y = y_max * 0.94,\n           label = paste0(\"Up (\", up_count, \")\"),\n           color = \"#D7191C\", fontface = \"bold\", size = 4.2, vjust = -0.8) +\n\n  annotate(\"text\", x = x_limit * 0.98, y = -log10(threshold_adjP),\n           label = paste0(\"FDR = \", threshold_adjP),\n           hjust = 1, vjust = -0.5, size = 3.3, color = \"grey30\") +\n\n  coord_cartesian(xlim = c(-x_limit, x_limit), ylim = c(0, y_max), clip = \"off\") +\n\n  labs(\n    title = \"Volcano Plot\",\n    subtitle = paste0(\"Up: \", up_count, \" | Down: \", down_count, \" | Not significant: \", not_count),\n    x = \"Log2 Fold Change\",\n    y = \"-Log10 Adjusted P-value\"\n  ) +\n\n  theme_bw(base_size = 12) +\n  theme(\n    plot.title = element_text(face = \"bold\", hjust = 0.5, size = 16),\n    plot.subtitle = element_text(hjust = 0.5, size = 11, color = \"grey30\"),\n    axis.title = element_text(face = \"bold\", size = 12),\n    axis.text = element_text(color = \"black\", size = 10),\n    panel.grid.major = element_blank(),\n    panel.grid.minor =",
" element_blank(),\n    panel.border = element_rect(color = \"black\", size = 1.1),\n    legend.position = \"right\",\n    legend.background = element_rect(fill = \"white\", color = \"grey80\", size = 0.4),\n    legend.key = element_rect(fill = \"white\"),\n    legend.title = element_text(face = \"bold\", size = 10),\n    legend.text = element_text(size = 9),\n    plot.margin = margin(15, 20, 12, 12)\n  ) +\n\n  guides(\n    color = guide_colorbar(\n      title = \"log2FC\",\n      title.position = \"top\",\n      title.hjust = 0.5,\n      barwidth = 1.1,\n      barheight = 9,\n      frame.colour = \"black\",\n      frame.linewidth = 0.4,\n      ticks.colour = \"black\",\n      order = 1\n    ),\n    size = guide_legend(\n      title = \"-log10(FDR)\",\n      title.position = \"top\",\n      title.hjust = 0.5,\n      override.aes = list(alpha = 1, color = \"grey30\"),\n      order = 2\n    )\n  )\n\n# \u540c\u65f6\u4fdd\u5b58\u4e3a\u65b0\u6587\u4ef6\u540d\u548c\u539f\u6587\u4ef6\u540d\uff0c\u65b9\u4fbf\u66ff\u6362\u539f\u7ed3\u679c\nggsave(\"DE_volcano_gradient.pdf\", gradient_volcano, width = 9, height = 7.5, dpi = 300)\nggsave(\"DE_volcano.pdf\", gradient_volcano, width = 9, height = 7.5, dpi = 300)\nggsave(\"DE_volcano_with_labels.pdf\", gradient_volcano, width = 9, height = 7.5, dpi = 300)\n\nstep7_end <- Sys.time()\ncat(\"[Step 7] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step7_end, step7_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 8. PCA \u4e3b\u6210\u5206\u5206\u6790\uff08\u4fdd\u7559\u539f\u4ee3\u7801\u903b\u8f91\uff0c\u7565\u4f5c\u7f8e\u5316\uff09 ==========================\nstep8_start <- Sys.time()\ncat(\"[Step 8] \u5f00\u59cbPCA\u5206\u6790...\\n\")\n\npca_result <- prcomp(t(combined_expr), scale. = TRUE)\n\npca_df <- data.frame(\n  Sample = colnames(combined_expr),\n  PC1 = pca_result$x[, 1],\n  PC2 = pca_result$x[, 2],\n  Group = factor(group_info, levels = c(\"Control\", \"Treatment\"))\n)\n\npca_var <- pca_result$sdev^2\npca_var_perc <- round(100 * pca_var / sum(pca_var), 2)\n\npca_plot <- ggplot(pca_df, aes(x = PC1, y = PC2, color = Group, fill = Group)) +\n  s",
"tat_ellipse(geom = \"polygon\", level = 0.95, alpha = 0.18, size = 0.8) +\n  geom_point(size = 3, shape = 21, color = \"black\", stroke = 0.4) +\n  scale_color_manual(values = c(\"Control\" = \"#E64B35\", \"Treatment\" = \"#4DBBD5\")) +\n  scale_fill_manual(values = c(\"Control\" = \"#E64B35\", \"Treatment\" = \"#4DBBD5\")) +\n  labs(x = paste0(\"PCA1 (\", pca_var_perc[1], \"%)\"),\n       y = paste0(\"PCA2 (\", pca_var_perc[2], \"%)\"),\n       color = \"Group\",\n       fill = \"Group\") +\n  theme_bw(base_size = 14) +\n  theme(\n    axis.title = element_text(face = \"bold\", size = 14, color = \"black\"),\n    axis.text = element_text(size = 12, color = \"black\"),\n    legend.title = element_text(size = 12, face = \"bold\"),\n    legend.text = element_text(size = 11),\n    legend.position = \"right\",\n    panel.grid.major = element_blank(),\n    panel.grid.minor = element_blank(),\n    panel.border = element_rect(color = \"black\", size = 1)\n  )\n\nggsave(\"DE_PCA.pdf\", pca_plot, width = 7, height = 6, dpi = 300)\n\nstep8_end <- Sys.time()\ncat(\"[Step 8] PCA\u5206\u6790\u5b8c\u6210\uff0c\u8017\u65f6:\", round(difftime(step8_end, step8_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n# ========================== 9. \u57fa\u56e0\u6392\u5e8f\u70b9\u56fe\uff08\u4f7f\u7528\u771f\u5b9e\u5dee\u5f02\u5206\u6790\u7ed3\u679c\uff0c\u4e0d\u518d\u4f7f\u7528\u6a21\u62df\u6570\u636e\uff09 ==========================\nstep9_start <- Sys.time()\ncat(\"[Step 9] \u5f00\u59cb\u7ed8\u5236\u57fa\u56e0\u6392\u5e8f\u70b9\u56fe...\\n\")\n\ngene_data_real <- all_diff_results[order(all_diff_results$logFC, decreasing = TRUE), ]\ngene_data_real$Gene <- rownames(gene_data_real)\ngene_data_real$Rank <- seq_len(nrow(gene_data_real))\n\nranking_plot <- ggplot(gene_data_real, aes(x = Rank, y = logFC)) +\n  geom_point(aes(color = adj.P.Val, size = abs(logFC)), alpha = 0.75) +\n  scale_color_gradientn(\n    colors = rev(brewer.pal(9, \"RdYlBu\")),\n    values = scales::rescale(c(0, 0.25, 0.5, 0.75, 1)),\n    name = \"Adjusted P-value\"\n  ) +\n  scale_size_continuous(range = c(0.6, 3), name = \"|Log2FC|\") +\n  labs(\n  ",
"  title = \"Gene Ranking Dotplot\",\n    x = \"Ranking of Differentially Expressed Genes\",\n    y = \"Log2 Fold Change\"\n  ) +\n  theme_minimal(base_size = 15) +\n  theme(\n    plot.title = element_text(size = 17, face = \"bold\", color = \"#2F4F4F\", hjust = 0.5),\n    axis.title = element_text(size = 14, face = \"bold\", color = \"#2F4F4F\"),\n    axis.text = element_text(size = 11, color = \"#555555\"),\n    legend.position = \"right\",\n    legend.title = element_text(size = 12, face = \"bold\"),\n    legend.text = element_text(size = 10),\n    panel.grid = element_blank(),\n    axis.line = element_line(color = \"black\", size = 0.5)\n  )\n\nggsave(\"DE_gene_ranking_dotplot.pdf\", ranking_plot, width = 10, height = 8, dpi = 300)\n\nstep9_end <- Sys.time()\ncat(\"[Step 9] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step9_end, step9_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\ncat(\"\u6240\u6709\u6b65\u9aa4\u5df2\u6210\u529f\u5b8c\u6210\uff01\\n\")\n"),
"bulk/08.\u4e24\u7ec4\u7684WGCNA\u5206\u6790/GEOwgcna\u9ad8\u7ea7\u7248.R"=paste0("\n\n# ------------------------ \u57fa\u672c\u8bbe\u7f6e\u4e0e\u8fdb\u5ea6\u6761 ---------------------------\ntotalSteps <- 10                                 # \u603b\u6b65\u9aa4\u6570\npb <- txtProgressBar(min = 0, max = totalSteps, style = 3)  # \u521b\u5efa\u6587\u672c\u8fdb\u5ea6\u6761\nstep <- 0                                        # \u521d\u59cb\u5316\u6b65\u9aa4\u8ba1\u6570\u5668\n\n# ------------------------ \u52a0\u8f7d\u6240\u9700\u5305 -------------------------------\n#\u52a0\u8f7dWGCNA\u5305\nlibrary(reshape2)                                 # \u52a0\u8f7dreshape2\u5305\u7528\u4e8e\u6570\u636e\u8f6c\u6362\n  library(\"WGCNA\")                               # \u52a0\u8f7dWGCNA\u5305\n  library(\"limma\")     \nlibrary(pheatmap)\nlibrary(ggplot2)\nlibrary(grid)\nlibrary(RColorBrewer)\n\n                        \nset.seed(1234)                                    # \u8bbe\u7f6e\u968f\u673a\u79cd\u5b50\u4ee5\u786e\u4fdd\u7ed3\u679c\u53ef\u91cd\u590d\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n# ------------------------ \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\u548c\u8f93\u5165\u6587\u4ef6 ----------------------\nworkDir <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\09.\u4e24\u7ec4\u7684WGCNA\u5206\u6790\"\nexpFilePath <- \"GSE75214.csv\"  # \u8bf7\u786e\u4fdd\u8fd9\u4e2a\u6587\u4ef6\u548c\u5206\u6790\u8def\u5f84\u6b63\u786e\n\nif (!dir.exists(workDir)) {\n  stop(\"\u5de5\u4f5c\u76ee\u5f55\u4e0d\u5b58\u5728\uff01\u8bf7\u68c0\u67e5\u8def\u5f84\u3002\")\n}\nsetwd(workDir)\nif (!file.exists(expFilePath)) {\n  stop(\"\u8868\u8fbe\u77e9\u9635\u6587\u4ef6\u4e0d\u5b58\u5728\uff01\u8bf7\u68c0\u67e5\u8def\u5f84\u3002\")\n}\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)\n\n# ------------------------ \u6570\u636e\u8bfb\u53d6\u4e0e\u9884\u5904\u7406 ---------------------------\n# \u81ea\u52a8\u68c0\u6d4bcsv\u8fd8\u662ftsv\ntmp_head <- readLines(expFilePath, 1)\nsep <- ifelse(grepl(\",\", tmp_head), \",\", \"\\t\")\n\n# \u8bfb\u53d6\u8868\u8fbe\u77e9\u9635\uff0c\u7b2c\u4e00\u5217\u662fgene\u540d\uff0c\u5176\u4f59\u5217\u4e3a\u6837\u672c\nrawData <- read.table(expFilePath, sep = sep, header = TRUE, check.names = FALSE, stringsAsFactors = FALSE)\nrownames(rawData) <- rawData[, 1]\nexprData <- rawData[, -1]\nexprDataCopy <- exprData\n\n# \u8f6c\u4e3a\u6570\u503c\u77e9\u9635\ndimNames <- list(rownames(exprDataCopy), colnames(exprDataCopy))\nnumericData <- matrix(as.numeric(as.matrix(exprDataCopy)), nrow = nrow(exprDataCopy), dimnames = dimNames)\n\n# Log2\u8f6c\u6362\uff08\u5982\u679c\u6700\u5927\u503c\u8f83\u5927\uff0c\u8868\u660e\u8fd8\u672a\u505a\u8fc7log2\uff09\n\n #numericData <- log2(numericData + 1)\n\n\n# limma\u5f52\u4e00\u5316\nnormalizedData <- normalizeBetweenArrays(numericData)\n\n# \u8fc7\u6ee4\u4f4e\u65b9\u5dee\u884c\nfilteredData <- norm",
"alizedData[apply(normalizedData, 1, sd, na.rm = TRUE) > 0.5, ]\n\n# ------------------------ \u81ea\u52a8\u5206\u7ec4\u8bc6\u522b\u5e76\u8f6c\u7f6e ----------------------\n# \u5206\u7ec4\u8bc6\u522b\uff0c\u8ddf\u5dee\u5f02\u5206\u6790\u4e00\u81f4\nsample_names <- colnames(filteredData)\ngroup_info <- ifelse(grepl(\"_con$\", sample_names, ignore.case = TRUE), \"Control\",\n                     ifelse(grepl(\"_tra$\", sample_names, ignore.case = TRUE), \"Treatment\", \"Unknown\"))\nif (any(group_info == \"Unknown\")) stop(\"\u5b58\u5728\u672a\u8bc6\u522b\u5206\u7ec4\u7684\u6837\u672c\u540d\uff0c\u8bf7\u68c0\u67e5\u672b\u5c3e _con/_tra \u7b49\u6807\u8bb0\uff01\")\nnumControl <- sum(group_info == \"Control\")\nnumTreatment <- sum(group_info == \"Treatment\")\n\n# \u6309\u7ec4\u63d0\u53d6\ndataControl   <- filteredData[, which(group_info == \"Control\"), drop=FALSE]\ndataTreatment <- filteredData[, which(group_info == \"Treatment\"), drop=FALSE]\ncombinedData  <- cbind(dataControl, dataTreatment)\n# \u8f6c\u7f6e\uff0c\u540e\u7eedWGCNA\u884c=\u6837\u672c\uff0c\u5217=\u57fa\u56e0\nexprMatrix    <- t(combinedData)\n\n# \u68c0\u67e5\u6837\u672c\u6570\nif (nrow(exprMatrix) < 10) {\n  warning(\"\u6837\u672c\u6570\u91cf\u592a\u5c11\uff0c\u5206\u6790\u4e0d\u591f\u7a33\u5065\uff01\")\n}\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)\n\n\n# ------------------------ \u6837\u672c\u8d28\u91cf\u68c0\u67e5\u4e0e\u805a\u7c7b -------------------------\n# \u68c0\u67e5\u6570\u636e\u4e2d\u662f\u5426\u5b58\u5728\u7f3a\u5931\u503c\nsampleCheck <- goodSamplesGenes(exprMatrix, verbose = 3)  # \u68c0\u67e5\u6837\u672c\u548c\u57fa\u56e0\u8d28\u91cf\nif (!sampleCheck$allOK) {                         \n  if (sum(!sampleCheck$goodGenes) > 0) {           \n    cat(\"\u79fb\u9664\u7684\u57fa\u56e0\uff1a\", paste(names(exprMatrix)[!sampleCheck$goodGenes], collapse = \", \"), \"\\n\")\n  }\n  if (sum(!sampleCheck$goodSamples) > 0) {         \n    cat(\"\u79fb\u9664\u7684\u6837\u672c\uff1a\", paste(rownames(exprMatrix)[!sampleCheck$goodSamples], collapse = \", \"), \"\\n\")\n  }\n  exprMatrix <- exprMatrix[sampleCheck$goodSamples, sampleCheck$goodGenes]  # \u79fb\u9664\u4f4e\u8d28\u91cf\u6837\u672c/\u57fa\u56e0\n}\n\n# \u5bf9\u6837\u672c\u8fdb\u884c\u5c42\u6b21\u805a\u7c7b\u4ee5\u68c0\u6d4b\u5f02\u5e38\u503c\nsampleDendro <- hclust(dist(exprMatrix), method = \"average\")  # \u5c42\u6b21\u805a\u7c7b\npdf(\"Sample_Clustering.pdf\", width = 12, height = 9)  # \u6253\u5f00PDF\u8bbe\u5907\u4fdd\u5b58\u6837\u672c\u805a\u7c7b\u56fe\npar(cex = 0.8)                                    # \u8bbe\u7f6e\u6587\u5b57\u5927\u5c0f\npar(mar = c(0, 4, 2, 0))                          # \u8bbe\u7f6e\u7ed8\u56fe\u8fb9\u8ddd\nplot(sampleDendro, mai",
"n = \"Sample Clustering for Outlier Detection\", sub = \"\", xlab = \"\", \n     cex.lab = 1.5, cex.axis = 1.2, cex.main = 2)  # \u7ed8\u5236\u5e26\u82f1\u6587\u6807\u9898\u7684\u6811\u72b6\u56fe\nabline(h = 20000, col = \"red\", lwd = 2)           # \u6dfb\u52a0\u53c2\u8003\u7ebf\u7528\u4e8e\u6811\u5207\ndev.off()                                        # \u5173\u95edPDF\u8bbe\u5907\n\n# \u6839\u636e\u805a\u7c7b\u7ed3\u679c\u8fdb\u884c\u9759\u6001\u6811\u5207\u5272\nclusterCut <- cutreeStatic(sampleDendro, cutHeight = 20000, minSize = 10)\nif (length(unique(clusterCut)) > 1) {             # \u5982\u679c\u5b58\u5728\u591a\u4e2a\u7c07\n  keepSamples <- (clusterCut == 1)               # \u4fdd\u7559\u4e3b\u7c07\u6837\u672c\n  exprMatrix <- exprMatrix[keepSamples, ]        # \u66f4\u65b0\u8868\u8fbe\u77e9\u9635\n} else {\n  cat(\"\u672a\u68c0\u6d4b\u5230\u660e\u663e\u5f02\u5e38\u6837\u672c\uff0c\u4f7f\u7528\u6240\u6709\u6837\u672c\u3002\\n\")\n}\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n# ------------------------ \u4e34\u5e8a\u6570\u636e\u4e0e\u6837\u672c\u5339\u914d ---------------------------\n# \u521b\u5efa\u4e34\u5e8a\u6027\u72b6\u6570\u636e\u6846\uff1a\u5bf9\u7167\u7ec4\u4e3a1\uff0c\u5904\u7406\u7ec4\u4e3a0\nclinicalData <- data.frame(\n  Normal = c(rep(1, numControl), rep(0, numTreatment)),   # \u5bf9\u7167\u6837\u672c\u6807\u8bb0\u4e3a1\n  Disease = c(rep(0, numControl), rep(1, numTreatment))    # \u5904\u7406\u6837\u672c\u6807\u8bb0\u4e3a1\n)\nrownames(clinicalData) <- colnames(combinedData)  # \u5c06\u6837\u672c\u540d\u8bbe\u4e3a\u884c\u540d\n\n# \u5339\u914d\u8868\u8fbe\u6570\u636e\u548c\u4e34\u5e8a\u6570\u636e\u4e2d\u7684\u6837\u672c\u540d\u79f0\ncommonSamples <- intersect(rownames(exprMatrix), rownames(clinicalData))\nexprMatrix <- exprMatrix[commonSamples, ]        # \u66f4\u65b0\u8868\u8fbe\u77e9\u9635\nclinicalData <- clinicalData[commonSamples, ]      # \u66f4\u65b0\u4e34\u5e8a\u6570\u636e\n\n# \u6b21\u7ea7\u68c0\u67e5\uff1a\u786e\u4fdd\u8868\u8fbe\u77e9\u9635\u4e0e\u4e34\u5e8a\u6570\u636e\u6837\u672c\u6570\u4e00\u81f4\nif (nrow(exprMatrix) != nrow(clinicalData)) {\n  stop(\"\u8868\u8fbe\u77e9\u9635\u4e0e\u4e34\u5e8a\u6570\u636e\u4e2d\u7684\u6837\u672c\u6570\u91cf\u4e0d\u5339\u914d\uff01\")\n}\n\n# \u4f7f\u7528\u57fa\u7840\u56fe\u5f62\u7ed8\u5236\u6837\u672c\u6811\u72b6\u56fe\u4e0e\u4e34\u5e8a\u6027\u72b6\u70ed\u56fe\nsampleDendro2 <- hclust(dist(exprMatrix), method = \"average\")\ntraitColors <- numbers2colors(clinicalData, signed = FALSE)  # \u5c06\u6027\u72b6\u6570\u636e\u8f6c\u6362\u4e3a\u989c\u8272\npdf(\"Sample_Heatmap.pdf\", width = 12, height = 12)\nplotDendroAndColors(sampleDendro2, traitColors,\n                    groupLabels = names(clinicalData),\n                    main = \"Sample Dendrogram and Trait Heatmap\", dendroLabels = FALSE)\ndev.off()\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n# ------------------------ \u8f6f\u9608\u503c\u9009\u62e9\u4e0e\u7f51\u7edc\u6784\u5efa",
" ---------------------------\n# \u4e3a\u907f\u514d\u6587\u4ef6\u8fde\u63a5\u8fc7\u591a\u9519\u8bef\uff0c\u5148\u5173\u95ed\u6240\u6709\u8fde\u63a5\ncloseAllConnections()\n\n# \u542f\u7528WGCNA\u591a\u7ebf\u7a0b\nenableWGCNAThreads()                              \npowerVector <- 1:20                              # \u5b9a\u4e49\u8f6f\u9608\u503c\u5e42\u5411\u91cf\nsftResult <- pickSoftThreshold(exprMatrix, powerVector = powerVector, verbose = 5)\nif (is.null(sftResult$powerEstimate)) {           # \u68c0\u67e5\u662f\u5426\u627e\u5230\u6700\u4f73\u5e42\u503c\n  stop(\"\u672a\u80fd\u786e\u5b9a\u6700\u4f73\u8f6f\u9608\u503c\uff01\u8bf7\u68c0\u67e5\u6570\u636e\u3002\")\n} else {\n  optimalPower <- sftResult$powerEstimate         # \u8bb0\u5f55\u6700\u4f73\u5e42\u503c\n}\n\n# \u8f93\u51fa\u5c3a\u5ea6\u81ea\u7531\u62d3\u6251\u548c\u5e73\u5747\u8fde\u901a\u6027\u56fe\uff0c\u56fe\u5f62\u7f8e\u89c2\u589e\u5f3a\npdf(\"Scale_Independence_and_Mean_Connectivity.pdf\", width = 10, height = 6)\npar(mfrow = c(1, 2))\ncex1 <- 0.9\n# \u7ed8\u5236\u5c3a\u5ea6\u81ea\u7531\u6027\u56fe\nplot(sftResult$fitIndices[, 1], -sign(sftResult$fitIndices[, 3]) * sftResult$fitIndices[, 2],\n     xlab = \"Soft Threshold (power)\", ylab = \"Scale Free Topology Model Fit (signed R^2)\",\n     type = \"n\", main = \"Scale Independence Analysis\", cex.axis = 1.2, cex.lab = 1.3)\ntext(sftResult$fitIndices[, 1], -sign(sftResult$fitIndices[, 3]) * sftResult$fitIndices[, 2],\n     labels = powerVector, cex = cex1, col = \"blue\")\nabline(h = 0.90, col = \"red\", lwd = 2)\n# \u7ed8\u5236\u5e73\u5747\u8fde\u901a\u6027\u56fe\nplot(sftResult$fitIndices[, 1], sftResult$fitIndices[, 5],\n     xlab = \"Soft Threshold (power)\", ylab = \"Mean Connectivity\", type = \"n\",\n     main = \"Network Connectivity Analysis\", cex.axis = 1.2, cex.lab = 1.3)\ntext(sftResult$fitIndices[, 1], sftResult$fitIndices[, 5],\n     labels = powerVector, cex = cex1, col = \"blue\")\ndev.off()\n\n# \u4f7f\u7528\u6700\u4f73\u5e42\u6784\u5efa\u90bb\u63a5\u77e9\u9635\nadjacencyMatrix <- adjacency(exprMatrix, power = optimalPower)\ncat(\"\u6700\u4f73\u8f6f\u9608\u503c\uff08power\uff09\u4e3a:\", optimalPower, \"\\n\")   # \u8f93\u51fa\u6700\u4f73\u5e42\u503c\n\n# \u8ba1\u7b97\u62d3\u6251\u91cd\u53e0\u77e9\u9635\uff08TOM\uff09\u53ca\u5176\u4e0d\u76f8\u4f3c\u6027\nTOMMatrix <- TOMsimilarity(adjacencyMatrix)\ndissTOM <- 1 - TOMMatrix\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n# ------------------------ \u57fa\u56e0\u805a\u7c7b\u4e0e\u6a21\u5757\u68c0\u6d4b ---------------------------\n# \u4f7f\u7528TOM\u4e0d\u76f8\u4f3c\u6027\u8fdb\u884c\u57fa\u56e0\u5c42\u6b21\u805a\u7c7b\ngeneDendro <- hclust(as.d",
"ist(dissTOM), method = \"average\")\npdf(\"Gene_Clustering.pdf\", width = 12, height = 9)\nplot(geneDendro, xlab = \"\", sub = \"\", main = \"Gene Clustering Based on TOM\", labels = FALSE, hang = 0.04)\ndev.off()\n\n# \u4f7f\u7528\u52a8\u6001\u6811\u5207\u6cd5\u8bc6\u522b\u6a21\u5757\nminModuleSize <- 50                              # \u6a21\u5757\u6700\u5c0f\u5927\u5c0f\u9608\u503c\ndynamicModuleLabels <- cutreeDynamic(dendro = geneDendro, distM = dissTOM,\n                                     deepSplit = 2, pamRespectsDendro = FALSE,\n                                     minClusterSize = minModuleSize)\nmoduleColors <- labels2colors(dynamicModuleLabels)  # \u5c06\u6a21\u5757\u6807\u7b7e\u8f6c\u6362\u4e3a\u989c\u8272\u6807\u8bc6\npdf(\"Dynamic_trae_Modules.pdf\", width = 8, height = 6)\nplotDendroAndColors(geneDendro, moduleColors, \"Dynamic Tree Cut Modules\",\n                    dendroLabels = FALSE, hang = 0.03, addGuide = TRUE, guideHang = 0.05,\n                    main = \"Gene Dendrogram and Module Colors\")\ndev.off()\n\n# \u8ba1\u7b97\u6a21\u5757\u7279\u5f81\u503c\uff0c\u5bf9\u76f8\u4f3c\u6a21\u5757\u8fdb\u884c\u805a\u7c7b\nmoduleEigengenesList <- moduleEigengenes(exprMatrix, colors = moduleColors)\nMEs <- moduleEigengenesList$eigengenes\nmoduleDiss <- 1 - cor(MEs)                        # \u8ba1\u7b97\u6a21\u5757\u7279\u5f81\u503c\u95f4\u7684\u4e0d\u76f8\u4f3c\u6027\nmoduleEigDendro <- hclust(as.dist(moduleDiss), method = \"average\")\nmergeThreshold <- 0.25                           # \u8bbe\u7f6e\u6a21\u5757\u5408\u5e76\u9608\u503c\npdf(\"Module_Clustering.pdf\", width = 8, height = 6)\nplot(moduleEigDendro, main = \"Clustering of Module Eigengenes\", xlab = \"\", sub = \"\")\nabline(h = mergeThreshold, col = \"red\", lwd = 2)\ndev.off()\n# \u5408\u5e76\u76f8\u4f3c\u6a21\u5757\nmergeResult <- mergeCloseModules(exprMatrix, moduleColors, cutHeight = mergeThreshold, verbose = 3)\nmergedModuleColors <- mergeResult$colors\nmergedMEs <- mergeResult$newMEs\n\n# \u5408\u5e76\u524d\u540e\u6a21\u5757\u5bf9\u6bd4\npdf(\"Merged_Modules_Comparison.pdf\", width = 10, height = 6)\nplotDendroAndColors(geneDendro, cbind(moduleColors, mergedModuleColors),\n                    c(\"Original Modules\", \"Merged Modules\"), dendroLabels = FALSE, hang ",
"= 0.03,\n                    addGuide = TRUE, guideHang = 0.05, main = \"Module Comparison Pre- and Post-Merging\")\ndev.off()\n\n# \u66f4\u65b0\u6a21\u5757\u4fe1\u606f\nmoduleColors <- mergedModuleColors\nmoduleEigengenes <- mergedMEs\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n# ------------------------ \u6a21\u5757-\u6027\u72b6\u5173\u7cfb\u5206\u6790 ---------------------------\n# \u8ba1\u7b97\u6a21\u5757\u4e0e\u4e34\u5e8a\u6027\u72b6\u4e4b\u95f4\u7684\u76f8\u5173\u6027\nmoduleTraitCor <- cor(moduleEigengenes, clinicalData, use = \"p\")\nmoduleTraitPvalues <- corPvalueStudent(moduleTraitCor, nrow(exprMatrix))\n\n# \u4f7f\u7528ggplot2\u7ed8\u5236\u589e\u5f3a\u7684\u6a21\u5757-\u6027\u72b6\u70ed\u56fe\n\ncorDF <- melt(moduleTraitCor)\npvalDF <- melt(moduleTraitPvalues)\nheatmapDF <- merge(corDF, pvalDF, by = c(\"Var1\", \"Var2\"))\ncolnames(heatmapDF) <- c(\"Module\", \"Trait\", \"Correlation\", \"Pvalue\")\n\npdf(\"Module_trait_Heatmap.pdf\", width = 7, height = 6)\nggplot(heatmapDF, aes(x = Trait, y = Module, fill = Correlation)) +\n  geom_tile(color = \"white\") +                              # \u7ed8\u5236\u5e26\u767d\u8272\u8fb9\u6846\u7684\u65b9\u683c\n  scale_fill_gradient2(low = \"blue\", high = \"red\", mid = \"white\",\n                       midpoint = 0, limit = c(-1,1), space = \"Lab\",\n                       name = \"Correlation\") +\n  geom_text(aes(label = sprintf(\"%.2f\\n(%.1e)\", Correlation, Pvalue)), size = 3) +\n  theme_minimal() +                                         # \u4f7f\u7528\u7b80\u6d01\u4e3b\u9898\n  theme(axis.text.x = element_text(angle = 45, vjust = 1, hjust = 1, size = 12),\n        axis.text.y = element_text(size = 12),\n        plot.title = element_text(hjust = 0.5, size = 16)) +\n  ggtitle(\"Module-Trait Correlation Heatmap\")\ndev.off()\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n# ------------------------ \u8ba1\u7b97\u6a21\u5757\u5f52\u5c5e\u5ea6\u4e0e\u57fa\u56e0\u663e\u8457\u6027 -----------------------\n# \u8ba1\u7b97\u57fa\u56e0\u4e0e\u6a21\u5757\u76f8\u5173\u6027\uff08\u6a21\u5757\u5f52\u5c5e\u5ea6\uff0cMM\uff09\ngeneModuleMembership <- as.data.frame(cor(exprMatrix, moduleEigengenes, use = \"p\"))\ngeneMMPvalue <- as.data.frame(corPvalueStudent(as.matrix(gene",
"ModuleMembership), nrow(exprMatrix)))\n# \u8ba1\u7b97\u57fa\u56e0\u4e0e\u6027\u72b6\u76f8\u5173\u6027\uff08\u57fa\u56e0\u663e\u8457\u6027\uff0cGS\uff09\ngeneTraitSignificance <- as.data.frame(cor(exprMatrix, clinicalData, use = \"p\"))\ngeneGSPvalue <- as.data.frame(corPvalueStudent(as.matrix(geneTraitSignificance), nrow(exprMatrix)))\n\n# \u6784\u5efa\u5305\u542b\u57fa\u56e0\u540d\u79f0\u3001\u6a21\u5757\u3001MM\u3001GS\u53ca\u5bf9\u5e94P\u503c\u7684\u7efc\u5408\u6570\u636e\u6846\ngeneNames <- colnames(exprMatrix)\ngeneInfo <- data.frame(Gene = geneNames, Module = moduleColors)\n# \u5faa\u73af\u6dfb\u52a0\u6bcf\u4e2a\u6a21\u5757\u7684MM\u4fe1\u606f\nfor (mod in colnames(moduleEigengenes)) {\n  geneInfo[, paste(\"MM_\", mod, sep = \"\")] <- geneModuleMembership[, mod]\n  geneInfo[, paste(\"p.MM_\", mod, sep = \"\")] <- geneMMPvalue[, mod]\n}\n# \u5faa\u73af\u6dfb\u52a0\u6bcf\u4e2a\u4e34\u5e8a\u6027\u72b6\u7684GS\u4fe1\u606f\nfor (trait in colnames(clinicalData)) {\n  geneInfo[, paste(\"GS_\", trait, sep = \"\")] <- geneTraitSignificance[, trait]\n  geneInfo[, paste(\"p.GS_\", trait, sep = \"\")] <- geneGSPvalue[, trait]\n}\n# \u6309\u6a21\u5757\u989c\u8272\u5bf9\u57fa\u56e0\u4fe1\u606f\u8fdb\u884c\u6392\u5e8f\ngeneInfo <- geneInfo[order(geneInfo$Module), ]\nwrite.table(geneInfo, file = \"GeneInfo_Modules.txt\", sep = \"\\t\", row.names = FALSE, quote = FALSE)\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n# ------------------------ \u8f93\u51fa\u6bcf\u4e2a\u6a21\u5757\u7684\u57fa\u56e0\u5217\u8868 ------------------------\n# \u5bf9\u6bcf\u4e2a\u6a21\u5757\u8f93\u51fa\u4e00\u4e2a\u5305\u542b\u57fa\u56e0\u5217\u8868\u7684\u6587\u672c\u6587\u4ef6\nuniqueModules <- unique(moduleColors)            # \u83b7\u53d6\u552f\u4e00\u6a21\u5757\nfor (mod in uniqueModules) {                       \n  moduleGenes <- geneNames[moduleColors == mod]   # \u63d0\u53d6\u5f53\u524d\u6a21\u5757\u7684\u57fa\u56e0\n  outFileName <- paste0(\"ModuleGenes_\", mod, \".txt\")  # \u5b9a\u4e49\u8f93\u51fa\u6587\u4ef6\u540d\n  write.table(moduleGenes, file = outFileName, sep = \"\\t\", row.names = FALSE, col.names = FALSE, quote = FALSE)\n}\n\nstep <- step + 1\nsetTxtProgressBar(pb, step)                       # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n\nrm(rawData, exprData, exprDataCopy, numericData, normalizedData, filteredData)  # \u6e05\u7406\u5197\u4f59\u5bf9\u8c61\nclose(pb)                                         # \u5173\u95ed\u8fdb\u5ea6\u6761\n# \u8ba1\u7b97\u6bcf\u4e2a\u6a21\u5757\u5305\u542b\u7684\u57fa\u56e0\u6570\u91cf\nmoduleSizes <- table(moduleColors)\nmoduleSizeDF <- as.data.frame(moduleSizes)\ncolnames(moduleSizeDF) ",
"<- c(\"Module\", \"GeneCount\")\n\n# \u7ed8\u5236\u6a21\u5757\u57fa\u56e0\u6570\u91cf\u7684\u6761\u5f62\u56fe\npdf(\"Module_Gene_Counts.pdf\", width = 8, height = 6)\nggplot(moduleSizeDF, aes(x = Module, y = GeneCount, fill = Module)) +\n  geom_bar(stat = \"identity\") +\n  theme_minimal() +\n  ggtitle(\"Gene Counts per Module\") +\n  xlab(\"Module\") +\n  ylab(\"Gene Count\") +\n  theme(text = element_text(size = 12))\ndev.off()\n#\n\n\ntargetTrait <- \"Disease\"\nallModules <- unique(moduleColors)\n\nfor (mod in allModules) {\n  pdf(file = paste0(\"MM_vs_GS_\", mod, \".pdf\"), width = 6, height = 6)\n  \n  moduleGenes <- (moduleColors == mod)\n  mmColName <- paste0(\"ME\", mod)\n  gsColName <- targetTrait\n  \n  MM <- as.numeric(geneModuleMembership[moduleGenes, mmColName])\n  GS <- as.numeric(geneTraitSignificance[moduleGenes, gsColName])\n  \n  # \u68c0\u67e5 MM \u548c GS \u4e2d\u662f\u5426\u6709\u8db3\u591f\u7684\u6570\u636e\n  if (sum(!is.na(MM) & !is.na(GS)) >= 2) {  # \u81f3\u5c11\u8981\u67092\u4e2a\u975eNA\u503c\u624d\u80fd\u8ba1\u7b97\u76f8\u5173\u6027\n    # \u8ba1\u7b97\u76f8\u5173\u6027\n    corTest <- cor.test(MM, GS)\n    corVal <- corTest$estimate\n    pVal <- corTest$p.value\n    \n    # \u8bbe\u7f6e\u7ed8\u56fe\u53c2\u6570\uff0c\u589e\u52a0\u70b9\u7684\u900f\u660e\u5ea6\u548c\u5927\u5c0f\n    plot(MM, GS,\n         xlab = paste(\"Module Membership in\", mod, \"module\"),\n         ylab = paste(\"Gene Significance for\", targetTrait),\n         main = paste0(\"Module: \", mod, \n                       \"\\ncor=\", signif(corVal, 3),\n                       \", p=\", format(pVal, scientific = TRUE, digits = 2)),\n         pch = 21, bg = adjustcolor(mod, alpha.f = 0.6),\n         col = \"black\", cex = 1.5)\n    \n    # \u6dfb\u52a0\u7ebf\u6027\u62df\u5408\u7ebf\n    abline(lm(GS ~ MM), col = \"blue\", lwd = 2, lty = 2)\n    \n    # \u6dfb\u52a0\u6c34\u5e73\u548c\u5782\u76f4\u53c2\u8003\u7ebf\uff08\u53ef\u9009\uff09\n    abline(v = 0.8, h = 0.2, col = \"orange\", lty = 3, lwd = 1.5)\n  } else {\n    cat(\"Skipping module \", mod, \" due to insufficient data for correlation test.\\n\")\n  }\n  \n  dev.off()\n}\n\n\n\n\n# \u6784\u9020\u6570\u636e\u6846\uff0c\u6ce8\u610f\uff1a\u6b64\u5904\u7684 geneModuleMembership \u9700\u8c03\u6574\u4e3a\u5339\u914d\u7684\u5217\u540d\ndf <- data.frame(\n  Module = moduleColors,\n  # \u5047\u8bbe geneModuleMembership \u7684\u5217\u540d\u4e3a \"ME\" + \u6a21\u5757\u989c\u8272\uff0c\u53d6\u51b3\u4e8e\u6bcf\u4e2a\u57fa",
"\u56e0\u6240\u5c5e\u6a21\u5757\n  MM = sapply(1:length(moduleColors), function(i) geneModuleMembership[i, paste0(\"ME\", moduleColors[i])]),\n  GS = geneTraitSignificance[, \"Disease\"]\n)\n\n## \u7bb1\u7ebf\u56fe\npdf(\"Boxplot_MM.pdf\", width = 7, height = 6)\np_box <- ggplot(df, aes(x = Module, y = MM, fill = Module)) +\n  geom_boxplot(alpha = 0.7) +\n  theme_minimal() +\n  labs(title = \"Boxplot of Module Membership across Modules\", y = \"Module Membership\") +\n  theme(legend.position = \"none\")\nprint(p_box)\ndev.off()\n\n## \u5c0f\u63d0\u7434\u56fe\npdf(\"ViolinPlot_GS.pdf\", width = 7, height = 6)\np_violin <- ggplot(df, aes(x = Module, y = GS, fill = Module)) +\n  geom_violin(alpha = 0.7) +\n  theme_minimal() +\n  labs(title = \"Violin Plot of Gene Significance across Modules\", y = \"Gene Significance\") +\n  theme(legend.position = \"none\")\nprint(p_violin)\ndev.off()\n#\n# ------------------------ \u6a21\u5757\u4e4b\u95f4\u76f8\u5173\u6027\u56fe ---------------------------\n# \u8ba1\u7b97\u6a21\u5757\u7279\u5f81\u503c\uff08module eigengenes\uff09\u4e4b\u95f4\u7684\u76f8\u5173\u6027\u77e9\u9635\nmoduleCor <- cor(moduleEigengenes, use = \"p\")\n# \u8f6c\u6362\u4e3a\u957f\u683c\u5f0f\u6570\u636e\u6846\u4ee5\u4fbf\u540e\u7eed\u7ed8\u56fe\nmoduleCor_melt <- melt(moduleCor)\n\n# \u7ed8\u5236\u6a21\u5757\u76f8\u5173\u6027\u70ed\u56fe\npdf(\"Module_Module_Correlation.pdf\", width = 7, height = 6)\nggplot(moduleCor_melt, aes(x = Var1, y = Var2, fill = value)) +\n  geom_tile(color = \"white\") +\n  scale_fill_gradient2(low = \"blue\", high = \"red\", mid = \"white\", \n                       midpoint = 0, limit = c(-1, 1), space = \"Lab\", \n                       name = \"Correlation\") +\n  geom_text(aes(label = sprintf(\"%.2f\", value)), size = 3) +\n  theme_minimal() +\n  ggtitle(\"Module-to-Module Correlation Heatmap\") +\n  xlab(\"Module Eigengenes\") +\n  ylab(\"Module Eigengenes\") +\n  theme(axis.text.x = element_text(angle = 45, vjust = 1, hjust = 1))\ndev.off()\n#\n# \u9009\u62e9\u76ee\u6807\u6a21\u5757\ntargetModule <- \"red\"\ninModule <- (moduleColors == targetModule)\nmodGenes <- geneNames[inModule]\n\n# \u63d0\u53d6\u76ee\u6807\u6a21\u5757\u5185\u7684 TOM \u5b50\u77e9\u9635\nmodTOM <- TOMMatrix[inModule, inModule]\n\n# \u57fa\u4e8e\u6a21\u5757\u5185 TOM ",
"\u8ba1\u7b97\u57fa\u56e0\u95f4\u8ddd\u79bb\uff0c\u5e76\u6784\u5efa\u805a\u7c7b\u6811\ngeneDendroModule <- hclust(as.dist(1 - modTOM), method = \"average\")\n\n# \u7ed8\u5236 TOM \u70ed\u56fe\u53ca\u5bf9\u5e94\u805a\u7c7b\u6811\npdf(paste0(\"TOMplot_\", targetModule, \".pdf\"), width = 10, height = 10)\nTOMplot(modTOM, geneDendroModule, main = paste(\"TOM Plot for\", targetModule, \"Module\"))\ndev.off()\n\n\nlibrary(pheatmap)\nlibrary(grid)\nlibrary(ggplot2)\n\n# \u914d\u8272\u65b9\u6848\uff08\u53ef\u4e2a\u6027\u5316\u6269\u5c55\uff09\nmod_colors_palette <- c(\n  \"brown\"=\"#A0522D\",\"blue\"=\"#1E90FF\",\"yellow\"=\"#FFD700\",\"turquoise\"=\"#20B2AA\",\n  \"grey\"=\"#BEBEBE\",\"black\"=\"#000000\",\"magenta\"=\"#FF00FF\",\n  \"green\"=\"#228B22\",\"red\"=\"#E64B35\",\"pink\"=\"#FFB6C1\",\n  \"purple\"=\"#6A5ACD\",\"salmon\"=\"#FA8072\",\"orange\"=\"#FFA500\",\n  \"cyan\"=\"#00CED1\",\"lightyellow\"=\"#FFFACD\",\n  \"darkorange\"=\"#FF8C00\",\"royalblue\"=\"#4169E1\",\"darkgrey\"=\"#A9A9A9\"\n)\n\n# \u904d\u5386\u6240\u6709\u6a21\u5757\u8f93\u51fa\uff08\u53ef\u81ea\u5b9a\u4e49\u4f60\u8981\u8f93\u51fa\u54ea\u4e9b\u6a21\u5757\uff09\nall_modules <- unique(moduleColors)\n#all_modules <- setdiff(all_modules, c(\"grey\"))  # \u4e0d\u8f93\u51fagrey\u6a21\u5757\uff0c\u53ef\u6309\u9700\u4fee\u6539\n\nfor(targetModule in all_modules){\n  cat(\"\u6b63\u5728\u8f93\u51fa: \", targetModule, \"\\n\")\n  \n  # ==== 0. \u57fa\u56e0\u548ceigengene\u51c6\u5907 ====\n  mod_genes <- colnames(exprMatrix)[moduleColors == targetModule]\n  # \u5c0f\u6a21\u5757\u8df3\u8fc7\n  if(length(mod_genes)<2) {\n    cat(\"\u6a21\u5757\",targetModule,\"\u57fa\u56e0\u6570\u5c11\u4e8e2\uff0c\u8df3\u8fc7\u3002\\n\")\n    next\n  }\n  mod_color <- ifelse(targetModule %in% names(mod_colors_palette), mod_colors_palette[targetModule], \"#888888\")\n  sample_list <- rownames(exprMatrix)\n  me_col <- paste0(\"ME\", targetModule)\n  if(!(me_col %in% colnames(MEs))) {\n    cat(\"\u6a21\u5757eigengene\u6ca1\u627e\u5230\uff0c\u8df3\u8fc7\u3002\\n\")\n    next\n  }\n  # \u4e25\u683c\u5bf9\u9f50\u6837\u672c\u987a\u5e8f\n  mod_expr <- exprMatrix[sample_list, mod_genes, drop=FALSE]\n  eigengene <- MEs[sample_list, me_col, drop=TRUE]\n  bar_df <- data.frame(\n    Sample = factor(sample_list, levels=sample_list),\n    Eigengene = eigengene\n  )\n  \n  # ===== 1. \u70ed\u56fegrob\u5bf9\u8c61 =====\n  heatmap_grob <- grid.grabExpr({\n    pheatmap(\n      t(mod_expr),\n      cluster_cols = FALSE, \n      cluster_rows = TRUE,\n      show_rownames ",
"= FALSE,\n      show_colnames = FALSE,\n      scale = \"row\",\n      color = colorRampPalette(c(\"skyblue\", \"white\", \"orange\"))(100),\n      border_color = NA, \n      legend = FALSE, \n      fontsize = 10\n    )\n  })\n  \n  # ===== 2. \u6837\u672c\u6761\u5f62\u56fe =====\n  bar_p <- ggplot(bar_df, aes(x = Sample, y = Eigengene)) +\n    geom_bar(stat = \"identity\", width = 1, fill = mod_color) +\n    labs(y = \"Eigengene\", x = \"Sample\") + \n    theme_bw(base_size = 14) +\n    theme(\n      panel.grid = element_blank(),\n      axis.text.x = element_text(angle = 90, hjust = 1, vjust=0.5, size = 6),\n      axis.title.y = element_text(face = \"bold\"),\n      axis.title.x = element_text(face = \"bold\"),\n      plot.margin = margin(0, 5, 0, 5),\n      axis.line = element_line(linewidth = 0.6)\n    )\n  \n  # ===== 3. \u5408\u6210\u8f93\u51faPDF =====\n  pdf_file <- paste0(\"Module_\", targetModule, \"_heatmap_eigengene.pdf\")\n  pdf(pdf_file, width = 9, height = 7)\n  grid.newpage()\n  pushViewport(viewport(layout = grid.layout(2, 1,\n                                             heights = unit(c(0.58, 0.38), \"npc\"), \n                                             widths = unit(1, \"npc\"))))\n  # --- \u70ed\u56fe ---\n  pushViewport(viewport(layout.pos.row = 1, layout.pos.col = 1))\n  grid.draw(heatmap_grob)\n  # \u7f8e\u5316\u6a21\u5757\u540d\u6807\u9898\n  grid.text(targetModule, x = 0.5, y = unit(0.98, \"npc\"), \n            gp = gpar(fontface = \"bold\", fontsize = 20, col = mod_color))\n  popViewport()\n  # --- \u6761\u5f62\u56fe ---\n  pushViewport(viewport(layout.pos.row = 2, layout.pos.col = 1))\n  print(bar_p, newpage=FALSE)\n  popViewport()\n  dev.off()\n  cat(\"\u8f93\u51faPDF\uff1a\", pdf_file, \"\\n\")\n}\n\ncat(\"\u2605\u5168\u90e8\u6a21\u5757\u8f93\u51fa\u5b8c\u6210\uff01\\n\")\n\n\n#"),
"bulk/09.\u5dee\u5f02\u5206\u6790\u548cWGCNA\u6a21\u5757\u57fa\u56e0\u53d6\u4ea4\u96c6/venn\u4ea4\u96c6.R"=paste0("library(ggvenn)\nlibrary(RColorBrewer)\nlibrary(viridis)\nlibrary(ComplexUpset)\nlibrary(ggplot2)\n# 1. \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\nsetwd(\"C:\\\\Users\\\\yangbo\\\\Desktop\\\\\u539f\u59cb\u6570\u636e\u5206\u6790\\\\10.\u5dee\u5f02\u5206\u6790\u548cWGCNA\u6a21\u5757\u57fa\u56e0\u53d6\u4ea4\u96c6\")\n\n# 2. \u521b\u5efa\u8f93\u51fa\u6587\u4ef6\u5939\noutput_folder <- \"output_folder\"\nif (!dir.exists(output_folder)) dir.create(output_folder)\n\n# 3. \u83b7\u53d6\u6240\u6709TXT\u6587\u4ef6\u5e76\u5b58\u50a8\u5728\u5217\u8868\u4e2d\ntxt_files <- list.files(pattern = \"\\\\.txt$\", full.names = TRUE)\n\n# 4. \u8bfb\u53d6\u6240\u6709\u6587\u4ef6\u5e76\u5b58\u5165\u5217\u8868\ngene_list <- list()\n\nfor (file in txt_files) {\n  # \u83b7\u53d6\u6587\u4ef6\u540d\uff08\u4e0d\u5e26\u540e\u7f00\uff09\n  file_name <- tools::file_path_sans_ext(basename(file))\n  \n  # \u8bfb\u53d6\u6587\u4ef6\u5185\u5bb9\n  rt <- read.table(file, header = FALSE, sep = \"\\t\", check.names = FALSE)\n  \n  # \u5c06\u57fa\u56e0\u6570\u636e\u6dfb\u52a0\u5230gene_list\u4e2d\n  gene_list[[file_name]] <- as.vector(rt[, 1])\n  \n  # \u6253\u5370\u65e5\u5fd7\n  cat(file_name, \"\u57fa\u56e0\u6570\uff1a\", length(gene_list[[file_name]]), \"\\n\")\n}\n\n# 5. \u5229\u7528 viridis \u8c03\u8272\u677f\u751f\u6210\u989c\u8272\nnColors <- length(gene_list)\nmyColors <- viridis(nColors)\n\n# 6. \u7ed8\u5236Venn\u56fe\u5e76\u4fdd\u5b58\u4e3aPDF\npdf(file = file.path(output_folder, \"venn.pdf\"), width = 10, height = 10)  # \u589e\u5927\u56fe\u8868\u5c3a\u5bf8\n\nggvenn(gene_list, show_percentage = TRUE,\n       stroke_color = \"white\", stroke_size = 1.5,\n       fill_color = myColors,       # \u4f7f\u7528viridis\u8c03\u8272\u677f\n       set_name_color = \"black\",      # \u8bbe\u7f6e\u96c6\u5408\u540d\u79f0\u4e3a\u9ed1\u8272\n       set_name_size = 8,             # \u8c03\u6574\u96c6\u5408\u540d\u79f0\u7684\u5b57\u4f53\u5927\u5c0f\n       text_size = 6,                 # \u8c03\u6574\u6587\u672c\u5927\u5c0f\n       text_color = \"black\")          # \u8bbe\u7f6e\u6587\u672c\u989c\u8272\u4e3a\u9ed1\u8272\n\ndev.off()\n\ncat(\"Venn\u56fe\u4fdd\u5b58\u81f3\uff1a\", file.path(output_folder, \"venn.pdf\"), \"\\n\")\n\n# 7. \u83b7\u53d6\u6240\u6709\u6587\u4ef6\u7684\u5168\u5c40\u4ea4\u96c6\u57fa\u56e0\u5e76\u4fdd\u5b58\uff08CSV\u683c\u5f0f\uff09\nintersect_genes <- Reduce(intersect, gene_list)\ncat(\"\u5168\u5c40\u4ea4\u96c6\u57fa\u56e0\u6570\uff1a\", length(intersect_genes), \"\\n\")\n\n# \u5c06\u5168\u5c40\u4ea4\u96c6\u8f6c\u4e3a\u6570\u636e\u6846\u4fdd\u5b58\nglobal_intersect_df <- data.frame(Gene = intersect_genes, stringsAsFactors = FALSE)\nwrite.csv(global_intersect_df,\n          file = file.path(output_folder, \"IntersectionGenes.csv\"),\n          row.names = FALSE,\n          quote = FALSE)\n\ncat(\"\u5168\u5c40\u4ea4\u96c6\u57fa\u56e0\u5df2\u4fdd\u5b58\u81f3CSV\u6587\u4ef6\uff1a\", file.path(output_folder, \"IntersectionGenes.csv\"), \"\\",
"n\")\n\n# 8. \u751f\u6210\u6bcf\u4e24\u4e2aTXT\u6587\u4ef6\u4e4b\u95f4\u7684\u4ea4\u96c6\u57fa\u56e0\u5217\u8868\uff0c\u5e76\u4fdd\u5b58\u4e3aCSV\u8868\u683c\npairwise_intersections <- data.frame(\n  File1 = character(),\n  File2 = character(),\n  Intersection_Count = integer(),\n  Intersection_Genes = character(),\n  stringsAsFactors = FALSE\n)\n\nfiles <- names(gene_list)\nfor (i in 1:(length(files) - 1)) {\n  for (j in (i + 1):length(files)) {\n    file1 <- files[i]\n    file2 <- files[j]\n    \n    common_genes <- intersect(gene_list[[file1]], gene_list[[file2]])\n    \n    pairwise_intersections <- rbind(pairwise_intersections,\n                                    data.frame(\n                                      File1 = file1,\n                                      File2 = file2,\n                                      Intersection_Count = length(common_genes),\n                                      Intersection_Genes = paste(common_genes, collapse = \";\"),\n                                      stringsAsFactors = FALSE\n                                    ))\n  }\n}\n\nwrite.csv(pairwise_intersections,\n          file = file.path(output_folder, \"PairwiseIntersectionGenes.csv\"),\n          row.names = FALSE,\n          quote = FALSE)\n\ncat(\"\u6bcf\u4e24\u4e2aTXT\u6587\u4ef6\u95f4\u7684\u4ea4\u96c6\u57fa\u56e0\u8868\u683c\u5df2\u4fdd\u5b58\u81f3CSV\u6587\u4ef6\uff1a\", file.path(output_folder, \"PairwiseIntersectionGenes.csv\"), \"\\n\")\n\n# \u5047\u8bbe gene_list \u662f\u4e00\u4e2a\u547d\u540d\u5217\u8868\uff0c\u6bcf\u4e2a\u5143\u7d20\u5305\u542b\u4e00\u4e2a\u57fa\u56e0\u5411\u91cf\nall_genes <- unique(unlist(gene_list))\nmembership_df <- data.frame(Gene = all_genes, stringsAsFactors = FALSE)\n\n# \u5bf9\u4e8e gene_list \u4e2d\u7684\u6bcf\u4e2a\u96c6\u5408\uff0c\u589e\u52a0\u4e00\u5217\u6307\u793a\u8be5\u57fa\u56e0\u662f\u5426\u5b58\u5728\uff081 \u8868\u793a\u5b58\u5728\uff0c0 \u8868\u793a\u4e0d\u5b58\u5728\uff09\nfor (set_name in names(gene_list)) {\n  membership_df[[set_name]] <- as.integer(membership_df$Gene %in% gene_list[[set_name]])\n}\n\n# \u67e5\u770b\u524d\u51e0\u884c\u6570\u636e\u68c0\u67e5\u662f\u5426\u6b63\u786e\u6784\u5efa\nhead(membership_df)\nlibrary(ComplexUpset)\nlibrary(ggplot2)\n\nupset_plot <- ComplexUpset::upset(\n  membership_df,\n  intersect = names(gene_list),  # \u4f7f\u7528 gene_list \u7684\u5217\u4f5c\u4e3a\u96c6\u5408\n  name = \"Gene\",                 # \u4e3b\u5217\u540d\u79f0\n  sort_intersections_by = \"degree\",",
"  # \u6309\u4ea4\u96c6\u6570\u91cf\u6392\u5e8f\n  base_annotations = list(\n    \"Intersection Size\" = ComplexUpset::intersection_size(\n      text = element_text(size = 12)  # \u8bbe\u7f6e\u6587\u5b57\u5927\u5c0f\n    )\n  )\n)\n\n# \u663e\u793a\u56fe\u5f62\nprint(upset_plot)\n# \u5047\u8bbe output_folder \u5df2\u7ecf\u5b9a\u4e49\u4e3a\u4fdd\u5b58\u6587\u4ef6\u7684\u76ee\u6807\u6587\u4ef6\u5939\nggsave(\n  filename = file.path(output_folder, \"ComplexUpSetPlot.pdf\"),\n  plot = upset_plot,\n  width = 8,\n  height = 6\n)\n"),
"bulk/KEGG/KEGG\u6539.R"=paste0("# ---------------------------------------------------\n# Load necessary packages\n# ---------------------------------------------------\nlibrary(clusterProfiler)\nlibrary(org.Hs.eg.db)\nlibrary(enrichplot)\nlibrary(ggplot2)\nlibrary(RColorBrewer)\nlibrary(circlize)\n\n# ---------------------------------------------------\n# 3. Parameter settings\n# ---------------------------------------------------\npvalueFilter <- 0.05\nadjPvalFilter <- 1\n\n# \u5f3a\u5236\uff1a\u5c55\u793a\u7528 pvalue\uff08\u4e0d\u518d\u7528 p.adjust\uff09\ncolorSel <- \"pvalue\"\n\n# ---------------------------------------------------\n# 4. Set working directory (adjust the path as needed)\n# ---------------------------------------------------\nsetwd(\"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\KEGG\")\n\n# ---------------------------------------------------\n# 5. Read the input file (assume the first column contains gene symbols)\n# ---------------------------------------------------\nrt <- read.table(\"IntersectionGenes.csv\", header = TRUE, sep = \"\\t\", check.names = FALSE)\ncolnames(rt)[1] <- \"genes\"  # Rename the first column to 'genes'\n\n# ---------------------------------------------------\n# 6. Extract gene names and convert to Entrez IDs\n# ---------------------------------------------------\ngenes <- unique(as.vector(rt$genes))\nentrezIDs <- mget(genes, org.Hs.egSYMBOL2EG, ifnotfound = NA)\nentrezIDs <- as.character(entrezIDs)\nrt$entrezIDs <- entrezIDs\nrt <- rt[rt$entrezIDs != \"NA\", ]\ngene <- rt$entrezIDs  # Filtered Entrez IDs\n\n# ---------------------------------------------------\n# 7. Perform KEGG enrichment analysis\n# ---------------------------------------------------\nkk <- enrichKEGG(gene = gene, organism = \"hsa\", pvalueCutoff = 1, qvalueCutoff = 1)\n\n# ---------------------------------------------------\n# 8. Convert enrichment results to a readable format (replace Entrez IDs with gene s",
"ymbols)\n# ---------------------------------------------------\nkkx <- setReadable(kk, 'org.Hs.eg.db', 'ENTREZID')\nKEGG <- as.data.frame(kkx)\n\n# ---------------------------------------------------\n# 8.1 Filter significant enrichment results\n# ---------------------------------------------------\n# \u539f\u903b\u8f91\uff1a\u540c\u65f6\u770b pvalue \u548c p.adjust\uff08p.adjust \u8fd9\u91cc\u4f60\u8bbe\u4e3a 1 \u7b49\u4e8e\u4e0d\u7b5b\u5b83\uff09\nKEGG <- KEGG[(KEGG$pvalue < pvalueFilter & KEGG$p.adjust < adjPvalFilter), ]\n\n# \u5982\u679c\u4f60\u60f3\u201c\u5b8c\u5168\u53ea\u6309 pvalue\u201d\u7b5b\u9009\uff0c\u7528\u8fd9\u4e00\u884c\u66ff\u6362\u4e0a\u9762\u90a3\u884c\uff1a\n# KEGG <- KEGG[KEGG$pvalue < pvalueFilter, ]\n\n# ---------------------------------------------------\n# 9. Output the significant enrichment results (with gene symbols)\n# ---------------------------------------------------\nwrite.table(KEGG, file = \"KEGG.txt\", sep = \"\\t\", quote = FALSE, row.names = FALSE)\n\n# Define the number of pathways to display\nshowNum <- 30\nif (nrow(KEGG) < showNum) {\n  showNum <- nrow(KEGG)\n}\n\n# ---------------------------------------------------\n# 10. Create a bar plot (\u7528 pvalue \u5c55\u793a)\n# ---------------------------------------------------\n# Top pathways\uff1a\u6309 pvalue \u6392\u5e8f\ntopKEGG <- KEGG[order(KEGG$pvalue), ][1:showNum, ]\ntopKEGG$Description <- factor(topKEGG$Description, levels = rev(topKEGG$Description))\n\n# y\u8f74/\u586b\u5145\uff1a-log10(pvalue)\np_bar <- ggplot(topKEGG, aes(x = Description, y = -log10(pvalue), fill = -log10(pvalue))) +\n  geom_bar(stat = \"identity\", width = 0.8) +\n  coord_flip() +\n  scale_fill_gradientn(colors = brewer.pal(7, \"YlOrRd\")) +\n  theme_minimal(base_size = 14) +\n  labs(x = \"KEGG Pathway\", y = \"-log10(p-value)\", title = \"KEGG Pathway Enrichment Analysis (p-value)\") +\n  theme(plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"darkblue\"))\n\nggsave(\"barplot_custom_pvalue.pdf\", p_bar, width = 8, height = 7)\n\n# ---------------------------------------------------\n# 11. Create a dot plot (\u7528 pvalue ",
"\u5c55\u793a)\n# ---------------------------------------------------\nif (all(grepl(\"/\", topKEGG$GeneRatio))) {\n  topKEGG$GeneRatio_num <- sapply(topKEGG$GeneRatio, function(x) {\n    parts <- unlist(strsplit(x, \"/\"))\n    as.numeric(parts[1]) / as.numeric(parts[2])\n  })\n} else {\n  topKEGG$GeneRatio_num <- as.numeric(topKEGG$GeneRatio)\n}\n\n# \u989c\u8272\uff1apvalue\uff08\u800c\u4e0d\u662f p.adjust\uff09\np_dot <- ggplot(topKEGG, aes(x = GeneRatio_num, y = Description, size = Count, color = pvalue)) +\n  geom_point(alpha = 0.8) +\n  scale_color_gradientn(colors = brewer.pal(7, \"Spectral\")) +\n  theme_classic(base_size = 14) +\n  labs(x = \"Gene Ratio\", y = \"KEGG Pathway\", title = \"KEGG Dotplot (p-value)\") +\n  theme(plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"darkred\"))\n\nggsave(\"dotplot_custom_pvalue.pdf\", p_dot, width = 8, height = 7)\n\n# ---------------------------------------------------\n# 12. Create a Gene-Pathway Network plot (cnetplot)\n# ---------------------------------------------------\n# \u6ce8\u610f\uff1acnetplot \u672c\u8eab\u4e0d\u662f\u7528 ggplot aes() \u6620\u5c04 pvalue/p.adjust \u7684\u90a3\u79cd\u903b\u8f91\uff0c\n# \u5b83\u4e3b\u8981\u6309\u5bcc\u96c6\u5bf9\u8c61\u5185\u90e8\u5c5e\u6027\u7ed8\u56fe\u3002\u8fd9\u91cc\u505a\u7684\u662f\u4fdd\u6301\u4f60\u7684\u539f\u56fe\uff0c\u53ea\u628a\u6807\u9898\u8bf4\u660e\u6e05\u695a\u3002\npdf(file = \"cnetplot_custom_pvalue.pdf\", width = 9, height = 5.25)\nkkx <- setReadable(kk, 'org.Hs.eg.db', 'ENTREZID')\np_cnet <- cnetplot(kkx, circular = TRUE, showCategory = 5, colorEdge = TRUE)\nprint(p_cnet +\n        ggtitle(\"Gene-Pathway Network (KEGG enrichment)\") +\n        theme(plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"purple\")))\ndev.off()\n\n# ---------------------------------------------------\n# 13. Create an enhanced Chord Diagram with English labels\n# ---------------------------------------------------\n# \u8fd9\u91cc\u7684\u5f26\u56fe\u5e76\u4e0d\u6d89\u53ca p.adjust / pvalue \u7684\u989c\u8272\u6620\u5c04\uff08\u4f60\u73b0\u5728\u662f\u6309\u901a\u8def/\u57fa\u56e0\u4e0a\u8272\uff09\n# \u5982\u679c\u4f60\u5e0c\u671b\u201c\u901a\u8def\u989c\u8272\u6309 pvalue \u6df1\u6d45\u201d\uff0c\u6211\u4e5f\u53ef\u4ee5\u7ee7\u7eed\u5e2e\u4f60\u6539\uff08\u9700\u8981\u660e\u786e\u60f3\u8981\u7684\u89c4\u5219\uff09\n\n# Select the top pathways for chord (\u5efa\u8bae\u8fd9\u91cc\u4e5f\u6309 pvalue \u6392\u5e8f\uff0c\u4fdd\u6301\u4e00\u81f4)\nKEGG_sorted_for_chord <- KEGG[order(KEGG$pv",
"alue), ]\ntopKEGG_chord <- KEGG_sorted_for_chord[1:min(10, nrow(KEGG_sorted_for_chord)), ]\n\ngene_path_df <- data.frame(Pathway = character(), Gene = character(), stringsAsFactors = FALSE)\nfor (i in 1:nrow(topKEGG_chord)) {\n  pathway <- topKEGG_chord$Description[i]\n  genes <- unlist(strsplit(topKEGG_chord$geneID[i], \"/\"))\n  temp_df <- data.frame(Pathway = rep(pathway, length(genes)), Gene = genes, stringsAsFactors = FALSE)\n  gene_path_df <- rbind(gene_path_df, temp_df)\n}\nprint(head(gene_path_df))\n\nchord_matrix <- as.matrix(table(gene_path_df$Pathway, gene_path_df$Gene))\nrownames(chord_matrix) <- as.character(rownames(chord_matrix))\ncolnames(chord_matrix) <- as.character(colnames(chord_matrix))\nprint(dim(chord_matrix))\nprint(chord_matrix)\n\nallSectors <- union(rownames(chord_matrix), colnames(chord_matrix))\nprint(allSectors)\n\nnPathways <- length(rownames(chord_matrix))\nnGenes <- length(colnames(chord_matrix))\n\npathway_colors <- brewer.pal(n = min(nPathways, 8), name = \"Set2\")\nif (nPathways > length(pathway_colors)) {\n  pathway_colors <- rep(pathway_colors, length.out = nPathways)\n}\n\ngene_colors <- brewer.pal(n = min(nGenes, 8), name = \"Pastel1\")\nif (nGenes > length(gene_colors)) {\n  gene_colors <- rep(gene_colors, length.out = nGenes)\n}\n\ngrid.col <- c(setNames(pathway_colors, rownames(chord_matrix)),\n              setNames(gene_colors, colnames(chord_matrix)))\ngrid.col <- grid.col[allSectors]\nprint(grid.col)\n\npdf(file = \"chordDiagram_custom_pvalue.pdf\", width = 8, height = 8)\nchordDiagram(chord_matrix, grid.col = grid.col, transparency = 0.25,\n             annotationTrack = \"grid\", preAllocateTracks = list(track.height = 0.05))\ntitle(\"Gene-Pathway Chord Diagram\")\ncircos.trackPlotRegion(track.index = 1, panel.fun = function(x, y) {\n  sector.name <- get.cell.meta.data(\"sector",
".index\")\n  circos.text(CELL_META$xcenter, CELL_META$ylim[1] - mm_y(5),\n              sector.name, facing = \"clockwise\", niceFacing = TRUE, adj = c(0, 0.5), cex = 0.8)\n}, bg.border = NA)\ndev.off()\n\n# ---------------------------------------------------\n# End of analysis\n# ---------------------------------------------------\n"),
"bulk/KEGG/KEGG.R"=paste0("\n\n# ---------------------------------------------------\n# Load necessary packages\n# ---------------------------------------------------\nlibrary(clusterProfiler)\nlibrary(org.Hs.eg.db)\nlibrary(enrichplot)\nlibrary(ggplot2)\nlibrary(RColorBrewer)\nlibrary(circlize)\n\n# ---------------------------------------------------\n# 3. Parameter settings\n# ---------------------------------------------------\npvalueFilter <- 0.05\nadjPvalFilter <- 1\ncolorSel <- \"p.adjust\"\nif (adjPvalFilter > 1) {\n  colorSel <- \"pvalue\"\n}\n\n# ---------------------------------------------------\n# 4. Set working directory (adjust the path as needed)\n# ---------------------------------------------------\nsetwd(\"C:\\\\Users\\\\yb\\\\Desktop\\\\\u6e83\u75a1\u6027\u7ed3\u80a0\u708e-\u751f\u4fe1\\\\11.\u4ea4\u96c6\u57fa\u56e0\u7684KEGG\u5206\u6790\")\n\n# ---------------------------------------------------\n# 5. Read the input file (assume the first column contains gene symbols)\n# ---------------------------------------------------\nrt <- read.table(\"IntersectionGenes.csv\", header = TRUE, sep = \"\\t\", check.names = FALSE)\ncolnames(rt)[1] <- \"genes\"  # Rename the first column to 'genes'\n\n# ---------------------------------------------------\n# 6. Extract gene names and convert to Entrez IDs\n# ---------------------------------------------------\ngenes <- unique(as.vector(rt$genes))\nentrezIDs <- mget(genes, org.Hs.egSYMBOL2EG, ifnotfound = NA)\nentrezIDs <- as.character(entrezIDs)\nrt$entrezIDs <- entrezIDs\nrt <- rt[rt$entrezIDs != \"NA\", ]\ngene <- rt$entrezIDs  # Filtered Entrez IDs\n\n# ---------------------------------------------------\n# 7. Perform KEGG enrichment analysis\n# ---------------------------------------------------\nkk <- enrichKEGG(gene = gene, organism = \"hsa\", pvalueCutoff = 1, qvalueCutoff = 1)\n\n# ---------------------------------------------------\n# 8. Convert enrichment results to a readable form",
"at (replace Entrez IDs with gene symbols)\n# ---------------------------------------------------\nkkx <- setReadable(kk, 'org.Hs.eg.db', 'ENTREZID')\nKEGG <- as.data.frame(kkx)\n\n# Optionally, if manual conversion is needed, use:\n# KEGG$geneID <- sapply(KEGG$geneID, function(x) {\n#   id_vector <- unlist(strsplit(x, \"/\"))\n#   idx <- match(id_vector, rt$entrezIDs)\n#   paste(rt$genes[idx], collapse = \"/\")\n# })\n\n# Filter significant enrichment results (adjust filtering criteria as needed)\nKEGG <- KEGG[(KEGG$pvalue < pvalueFilter & KEGG$p.adjust < adjPvalFilter), ]\n\n# ---------------------------------------------------\n# 9. Output the significant enrichment results (with gene symbols)\n# ---------------------------------------------------\nwrite.table(KEGG, file = \"KEGG.txt\", sep = \"\\t\", quote = FALSE, row.names = FALSE)\n\n# Define the number of pathways to display\nshowNum <- 30\nif (nrow(KEGG) < showNum) {\n  showNum <- nrow(KEGG)\n}\n\n# ---------------------------------------------------\n# 10. Create a bar plot (enhanced version with English labels)\n# ---------------------------------------------------\ntopKEGG <- KEGG[order(KEGG$p.adjust), ][1:showNum, ]\ntopKEGG$Description <- factor(topKEGG$Description, levels = rev(topKEGG$Description))\n\np_bar <- ggplot(topKEGG, aes(x = Description, y = -log10(p.adjust), fill = -log10(p.adjust))) +\n  geom_bar(stat = \"identity\", width = 0.8) +\n  coord_flip() +\n  scale_fill_gradientn(colors = brewer.pal(7, \"YlOrRd\")) +\n  theme_minimal(base_size = 14) +\n  labs(x = \"KEGG Pathway\", y = \"-log10(Adjusted p-value)\", title = \"KEGG Pathway Enrichment Analysis\") +\n  theme(plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"darkblue\"))\nggsave(\"barplot_custom.pdf\", p_bar, width = 8, height = 7)\n\n# ---------------------------------------------------\n#",
" 11. Create a dot plot (enhanced version with English labels)\n# ---------------------------------------------------\nif(all(grepl(\"/\", topKEGG$GeneRatio))){\n  topKEGG$GeneRatio_num <- sapply(topKEGG$GeneRatio, function(x) {\n    parts <- unlist(strsplit(x, \"/\"))\n    as.numeric(parts[1]) / as.numeric(parts[2])\n  })\n} else {\n  topKEGG$GeneRatio_num <- as.numeric(topKEGG$GeneRatio)\n}\n\np_dot <- ggplot(topKEGG, aes(x = GeneRatio_num, y = Description, size = Count, color = p.adjust)) +\n  geom_point(alpha = 0.8) +\n  scale_color_gradientn(colors = brewer.pal(7, \"Spectral\")) +\n  theme_classic(base_size = 14) +\n  labs(x = \"Gene Ratio\", y = \"KEGG Pathway\", title = \"KEGG Dotplot\") +\n  theme(plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"darkred\"))\nggsave(\"dotplot_custom.pdf\", p_dot, width = 8, height = 7)\n\n# ---------------------------------------------------\n# 12. Create a Gene-Pathway Network plot (cnetplot, enhanced version with English labels)\n# ---------------------------------------------------\npdf(file = \"cnetplot_custom.pdf\", width = 9, height = 5.25)\nkkx <- setReadable(kk, 'org.Hs.eg.db', 'ENTREZID')\np_cnet <- cnetplot(kkx, circular = TRUE, showCategory = 5, colorEdge = TRUE)\nprint(p_cnet + \n        ggtitle(\"Gene-Pathway Network\") +\n        theme(plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"purple\")))\ndev.off()\n\n# ---------------------------------------------------\n# 13. Create an enhanced Chord Diagram with English labels\n# ---------------------------------------------------\n# Select the top 5 pathways (adjust as needed)\ntopKEGG_chord <- KEGG[1:min(10, nrow(KEGG)), ]\ngene_path_df <- data.frame(Pathway = character(), Gene = character(), stringsAsFactors = FALSE)\nfor (i in 1:nrow(topKEGG_chord)) {\n  pathway <- topKEGG_chord$Description[i]\n  g",
"enes <- unlist(strsplit(topKEGG_chord$geneID[i], \"/\"))\n  temp_df <- data.frame(Pathway = rep(pathway, length(genes)), Gene = genes, stringsAsFactors = FALSE)\n  gene_path_df <- rbind(gene_path_df, temp_df)\n}\nprint(head(gene_path_df))\n\nchord_matrix <- as.matrix(table(gene_path_df$Pathway, gene_path_df$Gene))\nrownames(chord_matrix) <- as.character(rownames(chord_matrix))\ncolnames(chord_matrix) <- as.character(colnames(chord_matrix))\nprint(dim(chord_matrix))\nprint(chord_matrix)\n\nallSectors <- union(rownames(chord_matrix), colnames(chord_matrix))\nprint(allSectors)\n\nnPathways <- length(rownames(chord_matrix))\nnGenes <- length(colnames(chord_matrix))\npathway_colors <- brewer.pal(n = min(nPathways, 8), name = \"Set2\")\nif(nPathways > length(pathway_colors)){\n  pathway_colors <- rep(pathway_colors, length.out = nPathways)\n}\ngene_colors <- brewer.pal(n = min(nGenes, 8), name = \"Pastel1\")\nif(nGenes > length(gene_colors)){\n  gene_colors <- rep(gene_colors, length.out = nGenes)\n}\n\ngrid.col <- c(setNames(pathway_colors, rownames(chord_matrix)),\n              setNames(gene_colors, colnames(chord_matrix)))\ngrid.col <- grid.col[allSectors]\nprint(grid.col)\n\npdf(file = \"chordDiagram_custom.pdf\", width = 8, height = 8)\nchordDiagram(chord_matrix, grid.col = grid.col, transparency = 0.25, \n             annotationTrack = \"grid\", preAllocateTracks = list(track.height = 0.05))\ntitle(\"Gene-Pathway Chord Diagram\")\ncircos.trackPlotRegion(track.index = 1, panel.fun = function(x, y) {\n  sector.name <- get.cell.meta.data(\"sector.index\")\n  circos.text(CELL_META$xcenter, CELL_META$ylim[1] - mm_y(5),\n              sector.name, facing = \"clockwise\", niceFacing = TRUE, adj = c(0, 0.5), cex = 0.8)\n}, bg.border = NA)\ndev.off()\n\n# ---------------------------------------------------\n# End of analysis\n# --------",
"-------------------------------------------\n"),
"bulk/GO/GO\u65b0.R"=paste0("#---------------------#\n# 1. \u5305\u52a0\u8f7d\u51fd\u6570 #\n# \u5206\u6790\u5305\uff08Bioconductor\uff09\nlibrary(clusterProfiler)\nlibrary(org.Hs.eg.db)\nlibrary(enrichplot)\nlibrary(ComplexHeatmap)\nlibrary(ggplot2)\nlibrary(circlize)\nlibrary(RColorBrewer)\nlibrary(dplyr)\nlibrary(ggpubr)\n#------------------------------#\n# 2. \u521d\u59cb\u5316\u53c2\u6570/\u73af\u5883\u4e0e\u8fdb\u5ea6\u6761    #\n#------------------------------#\nwdPath <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\GO\"\nif (!dir.exists(wdPath)) dir.create(wdPath, recursive = TRUE)\nsetwd(wdPath)\n\nupdateProgress <- function(pb, value, message) {\n  setTxtProgressBar(pb, value)\n  cat(message, \"\n\")\n}\ntotalSteps <- 9\npb <- txtProgressBar(min = 0, max = totalSteps, style = 3)\n\npvalThreshold <- 0.05\n# padjThreshold \u53d8\u91cf\u5728\u6b64\u7248\u672c\u4e2d\u4e0d\u518d\u7528\u4e8e\u8fc7\u6ee4\u6216 colorParameter \u903b\u8f91\uff0c\u4f46\u4fdd\u7559\u4ee5\u9632\u5176\u4ed6\u6f5c\u5728\u7528\u9014\npadjThreshold <- 0.05 \ncolorParameter <- \"pvalue\" # \u76f4\u63a5\u8bbe\u7f6e\u4e3a pvalue\uff0c\u56e0\u4e3a\u7528\u6237\u8981\u6c42\u4ee5 pvalue \u4e3a\u4e3b\nupdateProgress(pb, 1, \"\u7b2c1\u6b65\uff1a\u8bbe\u7f6e\u53c2\u6570\u548c\u5de5\u4f5c\u73af\u5883\u5b8c\u6210\")\n\n#------------------------------#\n# 3. \u8bfb\u53d6\u57fa\u56e0\u6570\u636e               #\n#------------------------------#\ngeneFile <- \"IntersectionGenes.csv\"\nif (!file.exists(geneFile)) stop(\"\u9519\u8bef\uff1a\u57fa\u56e0\u6587\u4ef6 \u4e0d\u5b58\u5728\")\ngeneData <- read.table(geneFile, header = FALSE, sep = \",\", check.names = FALSE)\nupdateProgress(pb, 2, \"\u7b2c2\u6b65\uff1a\u8bfb\u53d6\u57fa\u56e0\u6570\u636e\u5b8c\u6210\")\n\ngeneSymbols <- unique(as.vector(geneData[, 1]))\nif (length(geneSymbols) == 0) stop(\"\u9519\u8bef\uff1a\u672a\u627e\u5230\u6709\u6548\u7684\u57fa\u56e0\u7b26\u53f7\")\n\n#------------------------------#\n# 4. \u57fa\u56e0\u7b26\u53f7\u8f6cEntrez ID       #\n#------------------------------#\nentrezMapping <- mget(geneSymbols, org.Hs.egSYMBOL2EG, ifnotfound = NA)\nentrezIDs <- as.character(entrezMapping)\nvalidGenes <- entrezIDs[!is.na(entrezIDs) & entrezIDs!=\"NA\"]\nif (length(validGenes) == 0) stop(\"\u9519\u8bef\uff1a\u65e0\u6709\u6548\u7684 Entrez \u57fa\u56e0 ID\")\nupdateProgress(pb, 3, \"\u7b2c3\u6b65\uff1a\u57fa\u56e0\u7b26\u53f7\u8f6c\u6362\u4e3a EntrezID\u5b8c\u6210\")\n\n#------------------------------#\n# 5. GO\u5bcc\u96c6\u4e0e\u8fc7\u6ee4              #\n#------------------------------#\ngoAnalysis <- enrichGO(\n  gene = validGenes,\n  OrgDb = org.Hs.eg.db,\n  pvalueCutoff = 1, qvalue",
"Cutoff = 1, # \u4fdd\u6301\u9ad8\u9608\u503c\uff0c\u4ee5\u4fbf\u540e\u7eed\u624b\u52a8\u8fc7\u6ee4\n  ont = \"all\",\n  readable = TRUE\n)\ngoResult <- as.data.frame(goAnalysis)\nif (nrow(goResult)==0) stop(\"\u8b66\u544a\uff1a\u672a\u68c0\u6d4b\u5230\u4efb\u4f55\u5bcc\u96c6\u7ed3\u679c\")\n# \u4ec5\u6839\u636e pvalue \u8fdb\u884c\u8fc7\u6ee4\nfilteredGO <- goResult[goResult$pvalue < pvalThreshold, ] \nupdateProgress(pb, 4, \"\u7b2c4\u6b65\uff1aGO \u5bcc\u96c6\u5206\u6790\u53ca\u7ed3\u679c\u8fc7\u6ee4\u5b8c\u6210\")\n\n#------------------------------#\n# 6. \u7ed3\u679c\u8f93\u51fa                  #\n#------------------------------#\noutputFile <- \"GO_results.txt\"\nwrite.table(filteredGO, file = outputFile, sep = \"\t\", quote = FALSE, row.names = FALSE)\nupdateProgress(pb, 5, \"\u7b2c5\u6b65\uff1a\u5bcc\u96c6\u7ed3\u679c\u5199\u5165\u6587\u4ef6\u5b8c\u6210\")\n\n#------------------------------#\n# 7. \u67f1\u72b6\u56fe/\u6c14\u6ce1\u56fe PDF\u7ed8\u5236     #\n#------------------------------#\n# \u67f1\u72b6\u56fe\npdf(\"GO_barplot.pdf\", width=8, height=10)\nbarPlot <- barplot(\n  goAnalysis, # \u8fd9\u91cc\u4f7f\u7528\u539f\u59cb\u7684 goAnalysis \u5bf9\u8c61\uff0c\u56e0\u4e3a\u8fc7\u6ee4\u540e\u7684 filteredGO \u53ef\u80fd\u6761\u76ee\u592a\u5c11\n  drop=TRUE, showCategory=10, label_format=50,\n  split=\"ONTOLOGY\", color=colorParameter # \u4f7f\u7528 pvalue \u4f5c\u4e3a\u989c\u8272\u53c2\u6570\n) +\n  facet_grid(ONTOLOGY ~ ., scale = 'free') +\n  scale_fill_gradientn(colors = c(\"#FF6666\", \"#FFB266\", \"#FFFF99\", \"#99FF99\", \"#6666FF\", \"#7F52A0\", \"#B266FF\"))\nprint(barPlot)\ndev.off()\n\n# \u6c14\u6ce1\u56fe\npdf(\"GO_bubble.pdf\", width=8, height=10)\nbubblePlot <- dotplot(\n  goAnalysis, # \u8fd9\u91cc\u4f7f\u7528\u539f\u59cb\u7684 goAnalysis \u5bf9\u8c61\n  showCategory = 10,\n  orderBy = \"GeneRatio\",\n  label_format = 50,\n  split = \"ONTOLOGY\",\n  color=colorParameter # \u4f7f\u7528 pvalue \u4f5c\u4e3a\u989c\u8272\u53c2\u6570\n) +\n  facet_grid(ONTOLOGY ~ ., scale = 'free') +\n  scale_color_gradientn(colors = c(\"#FFB266\", \"#FFFF99\", \"#99FF99\", \"#6666FF\", \"#7F52A0\", \"#B266FF\"))\nprint(bubblePlot)\ndev.off()\nupdateProgress(pb, 6, \"\u7b2c6\u6b65\uff1a\u67f1\u72b6\u56fe\u548c\u6c14\u6ce1\u56fe\u751f\u6210\u5b8c\u6210\")\n\n#------------------------------#\n# 8. \u5206\u7ec4\u6761\u5f62\u56fe ggbarplot       #\n#------------------------------#\n# \u8fd9\u91cc\u7684 topGO \u4f9d\u7136\u57fa\u4e8e filteredGO\uff0c\u5176\u5df2\u6309 pvalue \u8fc7\u6ee4\ntopGO <- filteredGO %>% group_by(ONTOLOGY) %>% slice_head(n = 10)\npdf(\"GO_grouped_barplot.pdf\", width=11, height=8)\ngroupBarPlot <- ggbarplot(\n  topGO,\n  x=\"Descri",
"ption\", y=\"Count\", fill=\"ONTOLOGY\", color=\"white\",\n  xlab=\"\", palette=\"aaas\",\n  legend=\"right\", sort.val=\"desc\", sort.by.groups=TRUE,\n  position=position_dodge(0.9)\n) +\n  rotate_x_text(75) +\n  theme(panel.background = element_blank(),\n        axis.text.x = element_text(size=10, color=\"black\")) +\n  scale_y_continuous(expand=c(0,0)) +\n  scale_x_discrete(expand=c(0,0)) +\n  geom_text(\n    aes(label=Count),\n    position=position_dodge(0.9), vjust=-0.3, size=3\n  )\nprint(groupBarPlot)\ndev.off()\nupdateProgress(pb, 7, \"\u7b2c7\u6b65\uff1a\u5206\u7ec4\u6761\u5f62\u56fe\u751f\u6210\u5b8c\u6210\")\n\n#------------------------------#\n# 9. chord\u5f26\u56fe PDF\u7ed8\u5236         #\n#------------------------------#\npdf(\"GO_chord_diagram.pdf\", width=12, height=12)\ngo <- read.delim(\"GO_results.txt\", header=TRUE, stringsAsFactors=FALSE)\n# \u5f26\u56fe\u7684 top_terms \u4f9d\u636e pvalue \u6392\u5e8f\ntop_terms <- go %>%\n  group_by(ONTOLOGY) %>%\n  slice_min(order_by = pvalue, n = 10) %>% # \u4f9d\u636e pvalue \u6392\u5e8f\n  ungroup()\ninsert_linebreak <- function(text, line_length=35) {\n  if(nchar(text) <= line_length) return(text)\n  paste(strwrap(text, width=line_length), collapse = \"\n\")\n}\ntop_terms$Description_new <- sapply(top_terms$Description, insert_linebreak)\nmat <- table(\n  factor(top_terms$ONTOLOGY, levels=c(\"BP\",\"CC\",\"MF\")),\n  factor(top_terms$Description_new, levels=unique(top_terms$Description_new))\n)\nn_ont <- 3\nn_term <- ncol(mat)\ngap.deg <- c(rep(1, n_ont-1), 10, rep(1, n_term-1), 10)\ngrid.col <- c(BP=\"#E69F00\", CC=\"#56B4E9\", MF=\"#009E73\",\n              setNames(rep(\"#BBBBBB\", n_term), colnames(mat)))\ncircos.clear()\ncircos.par(gap.degree = gap.deg, start.degree = 90)\nchordDiagram(\n  mat,\n  grid.col = grid.col,\n  transparency = 0.4,\n  annotationTrack = c(\"\", \"grid\"),\n  preAllocateTracks = list(track.height = 0.2)\n)\ncircos.trackPlotRegion(track.index = 1, panel.fun = function(x, y) {\n  sector.name <- get.cell.met",
"a.data(\"sector.index\")\n  xlim <- get.cell.meta.data(\"xlim\")\n  ylim <- get.cell.meta.data(\"ylim\")\n  circos.text(mean(xlim), ylim[1] + 0.1, sector.name,\n              facing=\"clockwise\", niceFacing=TRUE,\n              adj=c(0,0.5), cex=0.60)\n}, bg.border=NA)\ntitle(\"GO Ontology\")\ncircos.clear()\ndev.off()\nupdateProgress(pb, 8, \"\u7b2c8\u6b65\uff1achord\u5f26\u56fe\u751f\u6210\u5b8c\u6210\")\n\n# \u8f7d\u5165\u5fc5\u8981\u7684\u5305 (\u5982\u679c\u4e4b\u524d\u672a\u52a0\u8f7d\uff0c\u8fd9\u91cc\u518d\u6b21\u786e\u4fdd)\nlibrary(dplyr)\nlibrary(ggplot2)\nlibrary(RColorBrewer)\n\n# \u8bfb\u53d6GO\u5bcc\u96c6\u5206\u6790\u7684\u7ed3\u679c\uff08\u4f60\u7684filteredGO\uff09\n# \u786e\u4fdd\u8fd9\u91cc\u8bfb\u53d6\u7684\u662f\u7ecf\u8fc7 pvalue \u8fc7\u6ee4\u540e\u7684 GO_results.txt\nfilteredGO <- read.table(\"GO_results.txt\", header=TRUE, sep=\"\t\", stringsAsFactors=FALSE, check.names=FALSE)\n\n# TRUE\u5219\u5168\u90e8\u4e09\u7c7b\uff08BP, CC, MF\uff09\uff0c\u5982\u679c\u53ea\u8981\u5176\u4e2d\u67d0\u51e0\u7c7b\uff0c\u6539\u4e3a\u53ea\u7559\u9700\u8981\u7684\u7c7b\u522b\u540d\u79f0\nfilteredGO_sub <- filteredGO %>% filter(ONTOLOGY %in% c(\"BP\", \"CC\", \"MF\"))\n\n# \u5206\u522b\u5bf9\u6bcf\u4e2a\u5927\u7c7b\u53d6Top10\u6700\u663e\u8457\u7684GO term\uff0c\u4f9d\u636e pvalue\ntopGO <- filteredGO_sub %>%\n  group_by(ONTOLOGY) %>%\n  slice_min(order_by = pvalue, n = 10) %>% # \u4f9d\u636e pvalue \u6392\u5e8f\n  ungroup() %>%\n  arrange(ONTOLOGY, pvalue) # \u4f9d\u636e pvalue \u6392\u5e8f\n\n# \u9ad8\u7ea7\uff1a\u4fdd\u8bc1\u6bcf\u4e00\u7c7b\u5185\uff0cDescription\u662f\u4ece\u6700\u663e\u8457\u5230\u6700\u4e0d\u663e\u8457\u6392\u5e8f\uff0c\u663e\u793a\u65f6\u4e0d\u4e71\ntopGO <- topGO %>% \n  group_by(ONTOLOGY) %>%\n  mutate(Description = factor(Description, levels = rev(unique(Description)))) %>%\n  ungroup()\n\n# GeneRatio\u8f6c\u6570\u503c\uff08\u4e3b\u8981\u7528\u4e8e\u6c14\u6ce1\u56fe\u6a2a\u8f74\uff09\ntopGO$GeneRatio_num <- sapply(topGO$GeneRatio, function(x) {\n  sp <- unlist(strsplit(as.character(x), \"/\"))\n  as.numeric(sp[1]) / as.numeric(sp[2])\n})\n\n# GO\u5bcc\u96c6\u6761\u5f62\u56fe\uff08\u5206\u9762\uff0c\u548cKEGG\u4e00\u6837\uff09\nbar_colors <- brewer.pal(7, \"YlOrRd\")\np_bar <- ggplot(topGO, aes(x = Description, y = -log10(pvalue), fill = -log10(pvalue))) + # Y\u8f74\u548c\u586b\u5145\u989c\u8272\u6539\u4e3a pvalue\n  geom_bar(stat = \"identity\", width = 0.8) +\n  coord_flip() +\n  facet_wrap(~ ONTOLOGY, scales = \"free_y\", ncol = 1) +\n  scale_fill_gradientn(colors = bar_colors) +\n  labs(x = \"GO Term\", y = \"-log10(p-value)\", title = \"GO Enrichment Analysis (BP/CC/MF)\") + # \u6807\u7b7e\u6539\u4e3a p-value\n  theme_minimal(base_size = 14) +\n  theme(\n    plot.title = elemen",
"t_text(hjust = 0.5, face = \"bold\", color = \"darkblue\"),\n    strip.text = element_text(size = 15, face = \"bold\", color = \"black\"),\n    axis.text.y = element_text(size = 11)\n  )\nggsave(\"GO_barplot_custom.pdf\", p_bar, width = 12, height = 12)\n\n# GO\u5bcc\u96c6\u6c14\u6ce1\u56fe\uff08\u5206\u9762\uff0c\u548cKEGG\u4e00\u6837\uff09\ndot_colors <- brewer.pal(7, \"Spectral\")\np_dot <- ggplot(topGO, aes(x = GeneRatio_num, y = Description, size = Count, color = pvalue)) + # \u989c\u8272\u6539\u4e3a pvalue\n  geom_point(alpha = 0.8) +\n  facet_wrap(~ ONTOLOGY, scales = \"free_y\", ncol = 1) +\n  scale_color_gradientn(colors = dot_colors) +\n  labs(x = \"Gene Ratio\", y = \"GO Term\", title = \"GO Dotplot (BP/CC/MF)\") +\n  theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"darkred\"),\n    strip.text = element_text(size = 15, face = \"bold\", color = \"black\"),\n    axis.text.y = element_text(size = 11)\n  )\nggsave(\"GO_dotplot_custom.pdf\", p_dot, width = 12, height = 12)\n\n# ---------------------------\n# GO\u5bcc\u96c6\u6c14\u6ce1\u56fe/\u6761\u5f62\u56fe \u5206\u9762 \u5206\u522b\u663e\u793aBP/CC/MF \u901a\u8def\u540d\u5b57\u52a0\u7c97 (\u91cd\u590d\u90e8\u5206\uff0c\u4e5f\u8fdb\u884c\u4fee\u6539)\n# ---------------------------\n\n# 2. \u8bfb\u53d6\u6570\u636e\uff08\u7528\u4f60\u81ea\u5df1\u7684GO\u5bcc\u96c6\u7ed3\u679c\u8def\u5f84\uff09\nfilteredGO <- read.table(\"GO_results.txt\", header=TRUE, sep=\"\t\", stringsAsFactors=FALSE, check.names=FALSE)\n\n# 3. \u53ea\u4fdd\u7559BP,CC,MF\u4e09\u7c7b\uff08\u5982\u60f3\u53ea\u770b\u90e8\u5206\uff0c\u6539filter\u5185\u5bb9\u5373\u53ef\uff09\nfilteredGO_sub <- filteredGO %>% filter(ONTOLOGY %in% c(\"BP\", \"CC\", \"MF\"))\n\n# 4. \u6bcf\u7c7btop10\u6700\u663e\u8457GO term\uff0c\u4f9d\u636e pvalue\ntopGO <- filteredGO_sub %>%\n  group_by(ONTOLOGY) %>%\n  slice_min(order_by = pvalue, n = 10) %>% # \u4f9d\u636e pvalue \u6392\u5e8f\n  ungroup() %>%\n  arrange(ONTOLOGY, pvalue) # \u4f9d\u636e pvalue \u6392\u5e8f\n\n# 5. \u4fdd\u8bc1\u6bcf\u4e2a\u7c7b\u522b\u5185\u90e8\u6309\u663e\u8457\u6027\u6392\u5e8f\ntopGO <- topGO %>% \n  group_by(ONTOLOGY) %>%\n  mutate(Description = factor(Description, levels = rev(unique(Description)))) %>%\n  ungroup()\n\n# 6. GeneRatio\u6570\u503c\u5316\ntopGO$GeneRatio_num <- sapply(topGO$GeneRatio, function(x) {\n  sp <- unlist(strsplit(as.character(x), \"/\"))\n  as.numeric(sp[1]) / as",
".numeric(sp[2])\n})\n\n# 7. \u6761\u5f62\u56fe (KEGG style, \u901a\u8def\u540d\u5b57\u52a0\u7c97)\nbar_colors <- brewer.pal(7, \"YlOrRd\")\np_bar <- ggplot(topGO, aes(x = Description, y = -log10(pvalue), fill = -log10(pvalue))) + # Y\u8f74\u548c\u586b\u5145\u989c\u8272\u6539\u4e3a pvalue\n  geom_bar(stat = \"identity\", width = 0.8) +\n  coord_flip() +\n  facet_wrap(~ ONTOLOGY, scales = \"free_y\", ncol = 1) +\n  scale_fill_gradientn(colors = bar_colors) +\n  labs(x = \"GO Term\", y = \"-log10(p-value)\", title = \"GO Enrichment Analysis (BP/CC/MF)\") + # \u6807\u7b7e\u6539\u4e3a p-value\n  theme_minimal(base_size = 14) +\n  theme(\n    plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"darkblue\"),\n    strip.text = element_text(size = 15, face = \"bold\", color = \"black\"),\n    axis.text.y = element_text(size = 11, face = \"bold\") # \u901a\u8def\u540d\u5b57\u52a0\u7c97\n  )\nggsave(\"GO_barplot_custom.pdf\", p_bar, width = 12, height = 12)\n\n# 8. \u6c14\u6ce1\u56fe (KEGG style, \u901a\u8def\u540d\u5b57\u52a0\u7c97)\ndot_colors <- brewer.pal(7, \"Spectral\")\np_dot <- ggplot(topGO, aes(x = GeneRatio_num, y = Description, size = Count, color = pvalue)) + # \u989c\u8272\u6539\u4e3a pvalue\n  geom_point(alpha = 0.8) +\n  facet_wrap(~ ONTOLOGY, scales = \"free_y\", ncol = 1) +\n  scale_color_gradientn(colors = dot_colors) +\n  labs(x = \"Gene Ratio\", y = \"GO Term\", title = \"GO Dotplot (BP/CC/MF)\") +\n  theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(hjust = 0.5, face = \"bold\", color = \"darkred\"),\n    strip.text = element_text(size = 15, face = \"bold\", color = \"black\"),\n    axis.text.y = element_text(size = 11, face = \"bold\") # \u901a\u8def\u540d\u5b57\u52a0\u7c97\n  )\nggsave(\"GO_dotplot_custom.pdf\", p_dot, width = 12, height = 12)\n\n#------------------------------#\n# 10. \u5173\u95ed\u8fdb\u5ea6\u6761               #\n#------------------------------#\nclose(pb)\ncat('\u5168\u90e8\u5206\u6790\u53ca\u7ed8\u56fe\u5b8c\u6210\uff01\n')\n"),
"bulk/11.marching learning/15lasso\u56de\u5f52/\u7f8e\u5316.R"=paste0("############################################################\n## LASSO \u7ed3\u679c\u53ea\u7f8e\u5316\u51fa\u56fe\u7248\n## \u4e0d\u91cd\u65b0\u8fd0\u884c glmnet\uff0c\u4e0d\u91cd\u65b0\u8fd0\u884c cv.glmnet\n## \u4e0d\u6539\u53d8 LASSO_genes_modified.txt \u7684\u57fa\u56e0\u7ed3\u679c\n##\n## \u4f7f\u7528\u5bf9\u8c61\uff1a\n## lasso_model\n## cv_model\n## gene_names\n## coef_dataframe\n## cv_results_table\n##\n## \u5982\u679c\u8fd9\u4e9b\u5bf9\u8c61\u4e0d\u5b58\u5728\uff0c\u4f1a\u81ea\u52a8\u8bfb\u53d6\u4f60\u5df2\u7ecf\u8f93\u51fa\u7684\u7ed3\u679c\u6587\u4ef6\u3002\n############################################################\n\n\n############################################################\n## 1. \u52a0\u8f7d\u7f8e\u5316\u7ed8\u56fe\u5305\n############################################################\n\nplot_packages <- c(\n  \"ggplot2\",\n  \"dplyr\",\n  \"tidyr\",\n  \"ggrepel\",\n  \"patchwork\",\n  \"scales\"\n)\n\nfor (pkg in plot_packages) {\n  if (!requireNamespace(pkg, quietly = TRUE)) {\n    install.packages(pkg, dependencies = TRUE)\n  }\n  library(pkg, character.only = TRUE)\n}\n\n\n############################################################\n## 2. \u68c0\u67e5\u5173\u952e\u5bf9\u8c61\u548c\u7ed3\u679c\u6587\u4ef6\n############################################################\n\nif (!exists(\"lasso_model\")) {\n  stop(\"\u672a\u627e\u5230 lasso_model \u5bf9\u8c61\u3002\u8bf7\u5148\u5b8c\u6574\u8fd0\u884c\u4f60\u539f\u59cb\u7684 LASSO \u4ee3\u7801\u3002\")\n}\n\nif (!exists(\"cv_model\")) {\n  stop(\"\u672a\u627e\u5230 cv_model \u5bf9\u8c61\u3002\u8bf7\u5148\u5b8c\u6574\u8fd0\u884c\u4f60\u539f\u59cb\u7684 LASSO \u4ee3\u7801\u3002\")\n}\n\nif (!exists(\"gene_names\")) {\n  if (file.exists(\"LASSO_genes_modified.txt\")) {\n    gene_names <- read.table(\n      \"LASSO_genes_modified.txt\",\n      header = FALSE,\n      stringsAsFactors = FALSE\n    )[, 1]\n  } else {\n    gene_names <- character(0)\n    warning(\"\u672a\u627e\u5230 gene_names \u5bf9\u8c61\uff0c\u4e5f\u672a\u627e\u5230 LASSO_genes_modified.txt\u3002\")\n  }\n}\n\nif (!exists(\"coef_dataframe\")) {\n  if (file.exists(\"LASSO_coefficients_modified.txt\")) {\n    coef_dataframe <- read.table(\n      \"LASSO_coefficients_modified.txt\",\n      header = TRUE,\n      sep = \"\\t\",\n      stringsAsFactors = FALSE,\n      check.names = FALSE\n    )\n  } else {\n    full_coef_matrix <- as.matrix(coef(lasso_model, s = cv_model$lambda.min))\n    coef_dataframe <- data.frame(\n      Gene = rownames(full_coef_matrix),\n      Coe",
"fficient = full_coef_matrix[, 1],\n      stringsAsFactors = FALSE\n    )\n  }\n}\n\nif (!exists(\"cv_results_table\")) {\n  if (file.exists(\"CV_results_modified.txt\")) {\n    cv_results_table <- read.table(\n      \"CV_results_modified.txt\",\n      header = TRUE,\n      sep = \"\\t\",\n      stringsAsFactors = FALSE,\n      check.names = FALSE\n    )\n  } else {\n    cv_results_table <- data.frame(\n      lambda = cv_model$lambda,\n      cvm = cv_model$cvm,\n      cvup = cv_model$cvup,\n      cvlo = cv_model$cvlo\n    )\n  }\n}\n\n\n############################################################\n## 3. \u671f\u520a\u98ce\u683c\u4e3b\u9898\n############################################################\n\ntheme_lasso_beauty <- function(base_size = 14) {\n  theme_classic(base_size = base_size) +\n    theme(\n      plot.title = element_text(\n        face = \"bold\",\n        size = base_size + 2,\n        hjust = 0.5,\n        color = \"black\"\n      ),\n      plot.subtitle = element_text(\n        size = base_size - 1,\n        hjust = 0.5,\n        color = \"grey35\"\n      ),\n      axis.title = element_text(\n        face = \"bold\",\n        size = base_size,\n        color = \"black\"\n      ),\n      axis.text = element_text(\n        color = \"black\",\n        size = base_size - 1\n      ),\n      axis.line = element_line(\n        linewidth = 0.7,\n        color = \"black\"\n      ),\n      axis.ticks = element_line(\n        linewidth = 0.6,\n        color = \"black\"\n      ),\n      panel.grid.major = element_line(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      legend.position = \"top\",\n      legend.title = element_blank(),\n      legend.text = element_text(size = base_size - 1),\n      plot.caption = element_text(\n        size = base_size - 3,\n        color = \"grey40\",\n        hjust = 0\n      ),\n      plot.margin = ",
"margin(10, 15, 10, 10)\n    )\n}\n\n\n############################################################\n## 4. \u4fdd\u5b58\u51fd\u6570\uff1a\u540c\u65f6\u4fdd\u5b58 PDF \u548c 600 dpi PNG\n############################################################\n\nsave_beauty_plot <- function(p, filename, width = 6.5, height = 5.5) {\n  \n  ggsave(\n    filename = paste0(filename, \".pdf\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = paste0(filename, \".png\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\",\n    dpi = 600\n  )\n}\n\n\n############################################################\n## 5. \u6574\u7406 LASSO \u8def\u5f84\u6570\u636e\n############################################################\n\nbeta_matrix <- as.matrix(lasso_model$beta)\n\npath_df <- as.data.frame(beta_matrix)\npath_df$Gene <- rownames(path_df)\n\npath_long <- path_df %>%\n  tidyr::pivot_longer(\n    cols = -Gene,\n    names_to = \"Step\",\n    values_to = \"Coefficient\"\n  )\n\npath_long$Step <- as.integer(gsub(\"s\", \"\", path_long$Step))\n\nlambda_df <- data.frame(\n  Step = seq_along(lasso_model$lambda),\n  lambda = lasso_model$lambda,\n  log_lambda = log(lasso_model$lambda)\n)\n\npath_long <- path_long %>%\n  dplyr::left_join(lambda_df, by = \"Step\")\n\n# \u53bb\u6389\u5168\u7a0b\u7cfb\u6570\u90fd\u4e3a0\u7684\u57fa\u56e0\uff0c\u907f\u514d\u7ebf\u6761\u592a\u591a\nactive_genes <- path_long %>%\n  dplyr::group_by(Gene) %>%\n  dplyr::summarise(max_abs_coef = max(abs(Coefficient), na.rm = TRUE)) %>%\n  dplyr::filter(max_abs_coef > 0) %>%\n  dplyr::pull(Gene)\n\npath_long_active <- path_long %>%\n  dplyr::filter(Gene %in% active_genes)\n\n# \u5728 lambda.min \u5904\u63d0\u53d6\u975e\u96f6\u57fa\u56e0\uff0c\u7528\u4e8e\u9ad8\u4eae\u6807\u6ce8\ncoef_lambda_min <- as.matrix(coef(lasso_model, s = cv_model$lambda.min))\n\ncoef_min_df <- data.frame(\n  Gene = rownames(coef_lambda_min),\n  Coefficient_lambda_min = coef_lambda_min[, 1],\n  stringsAsFactors = FALSE\n)\n\ncoef_min_df <- coef_min_df %>%\n  dplyr::filter(\n    Gene != \"(Intercept)\"",
",\n    Coefficient_lambda_min != 0\n  )\n\nselected_genes <- coef_min_df$Gene\n\n# \u5982\u679c\u539f\u59cb gene_names \u5b58\u5728\uff0c\u4ee5\u539f\u59cb\u8f93\u51fa\u6587\u4ef6\u4e3a\u51c6\nif (length(gene_names) > 0) {\n  selected_genes <- gene_names\n}\n\npath_long_active$Selected <- ifelse(\n  path_long_active$Gene %in% selected_genes,\n  \"Selected genes\",\n  \"Other genes\"\n)\n\n# \u6807\u7b7e\u4f4d\u7f6e\uff1a\u5728\u6bcf\u6761\u66f2\u7ebf\u6700\u53f3\u4fa7\u6807\u6ce8\u88ab\u9009\u62e9\u57fa\u56e0\nlabel_df <- path_long_active %>%\n  dplyr::filter(Gene %in% selected_genes) %>%\n  dplyr::group_by(Gene) %>%\n  dplyr::filter(log_lambda == min(log_lambda, na.rm = TRUE)) %>%\n  dplyr::ungroup()\n\n# \u5982\u679c\u6807\u7b7e\u592a\u591a\uff0c\u53ea\u6807\u6ce8\u7edd\u5bf9\u7cfb\u6570\u6700\u5927\u7684\u524d20\u4e2a\uff0c\u9632\u6b62\u56fe\u592a\u62e5\u6324\nif (nrow(label_df) > 20) {\n  top_label_genes <- coef_min_df %>%\n    dplyr::mutate(abs_coef = abs(Coefficient_lambda_min)) %>%\n    dplyr::arrange(desc(abs_coef)) %>%\n    dplyr::slice(1:20) %>%\n    dplyr::pull(Gene)\n  \n  label_df <- label_df %>%\n    dplyr::filter(Gene %in% top_label_genes)\n}\n\n\n############################################################\n## 6. \u7f8e\u5316 LASSO \u7cfb\u6570\u8def\u5f84\u56fe\n############################################################\n\np_lasso_path <- ggplot(\n  path_long_active,\n  aes(\n    x = log_lambda,\n    y = Coefficient,\n    group = Gene\n  )\n) +\n  geom_line(\n    data = path_long_active %>% dplyr::filter(Selected == \"Other genes\"),\n    color = \"grey75\",\n    linewidth = 0.55,\n    alpha = 0.75\n  ) +\n  geom_line(\n    data = path_long_active %>% dplyr::filter(Selected == \"Selected genes\"),\n    aes(color = Gene),\n    linewidth = 1.05,\n    alpha = 0.95\n  ) +\n  geom_vline(\n    xintercept = log(cv_model$lambda.min),\n    linetype = \"dashed\",\n    linewidth = 0.8,\n    color = \"#D62828\"\n  ) +\n  geom_vline(\n    xintercept = log(cv_model$lambda.1se),\n    linetype = \"dotted\",\n    linewidth = 0.8,\n    color = \"#2B6CB0\"\n  ) +\n  ggrepel::geom_text_repel(\n    data = label_df,\n    aes(label = Gene),\n    size = 3.6,\n    fontface = \"bold\",\n    color = \"black\",\n   ",
" box.padding = 0.35,\n    point.padding = 0.25,\n    min.segment.length = 0,\n    segment.color = \"grey50\",\n    seed = 1993,\n    max.overlaps = Inf\n  ) +\n  annotate(\n    \"text\",\n    x = log(cv_model$lambda.min),\n    y = max(path_long_active$Coefficient, na.rm = TRUE),\n    label = \"lambda.min\",\n    hjust = -0.05,\n    vjust = 1.2,\n    size = 3.6,\n    fontface = \"bold\",\n    color = \"#D62828\"\n  ) +\n  annotate(\n    \"text\",\n    x = log(cv_model$lambda.1se),\n    y = max(path_long_active$Coefficient, na.rm = TRUE),\n    label = \"lambda.1se\",\n    hjust = -0.05,\n    vjust = 2.4,\n    size = 3.6,\n    fontface = \"bold\",\n    color = \"#2B6CB0\"\n  ) +\n  labs(\n    title = \"LASSO Coefficient Profiles\",\n    subtitle = paste0(\n      \"Selected genes at lambda.min: \",\n      length(selected_genes)\n    ),\n    x = \"Log(lambda)\",\n    y = \"Coefficient\",\n    caption = \"Dashed red line: lambda.min; dotted blue line: lambda.1se.\"\n  ) +\n  theme_lasso_beauty() +\n  theme(\n    legend.position = \"none\"\n  )\n\nsave_beauty_plot(\n  p_lasso_path,\n  filename = \"LASSO_path_beauty_original_result\",\n  width = 7.2,\n  height = 5.8\n)\n\n\n############################################################\n## 7. \u6574\u7406\u4ea4\u53c9\u9a8c\u8bc1\u66f2\u7ebf\u6570\u636e\n############################################################\n\ncv_plot_df <- cv_results_table %>%\n  dplyr::mutate(\n    log_lambda = log(lambda)\n  )\n\nlambda_min_df <- cv_plot_df %>%\n  dplyr::filter(abs(lambda - cv_model$lambda.min) == min(abs(lambda - cv_model$lambda.min)))\n\nlambda_1se_df <- cv_plot_df %>%\n  dplyr::filter(abs(lambda - cv_model$lambda.1se) == min(abs(lambda - cv_model$lambda.1se)))\n\n\n############################################################\n## 8. \u7f8e\u5316 LASSO \u4ea4\u53c9\u9a8c\u8bc1\u8bef\u5dee\u56fe\n############################################################\n\np_cv <- ggplot(\n  cv_plot_df,\n  aes(x = log_lambda, y = cvm)\n) +\n  geom_er",
"rorbar(\n    aes(ymin = cvlo, ymax = cvup),\n    width = 0.03,\n    color = \"grey70\",\n    linewidth = 0.45\n  ) +\n  geom_line(\n    color = \"#2B6CB0\",\n    linewidth = 1.1\n  ) +\n  geom_point(\n    size = 2.6,\n    shape = 21,\n    fill = \"white\",\n    color = \"#2B6CB0\",\n    stroke = 0.8\n  ) +\n  geom_vline(\n    xintercept = log(cv_model$lambda.min),\n    linetype = \"dashed\",\n    linewidth = 0.8,\n    color = \"#D62828\"\n  ) +\n  geom_vline(\n    xintercept = log(cv_model$lambda.1se),\n    linetype = \"dotted\",\n    linewidth = 0.8,\n    color = \"#2B6CB0\"\n  ) +\n  geom_point(\n    data = lambda_min_df,\n    aes(x = log_lambda, y = cvm),\n    size = 4.2,\n    shape = 21,\n    fill = \"#D62828\",\n    color = \"black\",\n    stroke = 0.8\n  ) +\n  geom_point(\n    data = lambda_1se_df,\n    aes(x = log_lambda, y = cvm),\n    size = 4.2,\n    shape = 21,\n    fill = \"#2B6CB0\",\n    color = \"black\",\n    stroke = 0.8\n  ) +\n  ggrepel::geom_label_repel(\n    data = lambda_min_df,\n    aes(\n      x = log_lambda,\n      y = cvm,\n      label = paste0(\n        \"lambda.min\\n\",\n        \"log(lambda) = \",\n        sprintf(\"%.2f\", log_lambda),\n        \"\\nDeviance = \",\n        sprintf(\"%.3f\", cvm)\n      )\n    ),\n    size = 3.6,\n    fontface = \"bold\",\n    fill = \"white\",\n    label.size = 0.35,\n    box.padding = 0.45,\n    point.padding = 0.35,\n    seed = 1993\n  ) +\n  ggrepel::geom_label_repel(\n    data = lambda_1se_df,\n    aes(\n      x = log_lambda,\n      y = cvm,\n      label = paste0(\n        \"lambda.1se\\n\",\n        \"log(lambda) = \",\n        sprintf(\"%.2f\", log_lambda),\n        \"\\nDeviance = \",\n        sprintf(\"%.3f\", cvm)\n      )\n    ),\n    size = 3.6,\n    fontface = \"bold\",\n    fill = \"white\",\n    label.size = 0.35,\n    box.padding = 0.45,\n    point.padding = 0.35,\n    seed = 1993\n  ) +\n  scale_x_continuous(\n    breaks = scales::p",
"retty_breaks(n = 7)\n  ) +\n  scale_y_continuous(\n    breaks = scales::pretty_breaks(n = 6)\n  ) +\n  labs(\n    title = \"Cross-Validation Curve for LASSO Model\",\n    subtitle = \"Binomial deviance based on 10-fold cross-validation\",\n    x = \"Log(lambda)\",\n    y = \"Mean cross-validated deviance\",\n    caption = \"Error bars indicate upper and lower cross-validation estimates.\"\n  ) +\n  theme_lasso_beauty()\n\nsave_beauty_plot(\n  p_cv,\n  filename = \"LASSO_CV_curve_beauty_original_result\",\n  width = 7.2,\n  height = 5.8\n)\n\n\n############################################################\n## 9. \u7f8e\u5316\u6700\u4f18\u57fa\u56e0\u7cfb\u6570\u67f1\u72b6\u56fe\n############################################################\n\ncoef_bar_df <- coef_dataframe %>%\n  dplyr::filter(\n    Gene != \"(Intercept)\",\n    Coefficient != 0\n  )\n\n# \u5982\u679c\u539f\u59cb gene_names \u5b58\u5728\uff0c\u4e25\u683c\u6309\u539f\u59cb\u8f93\u51fa\u57fa\u56e0\u4fdd\u7559\nif (length(gene_names) > 0) {\n  coef_bar_df <- coef_bar_df %>%\n    dplyr::filter(Gene %in% gene_names)\n}\n\ncoef_bar_df <- coef_bar_df %>%\n  dplyr::mutate(\n    Direction = ifelse(Coefficient > 0, \"Positive coefficient\", \"Negative coefficient\"),\n    AbsCoefficient = abs(Coefficient)\n  ) %>%\n  dplyr::arrange(Coefficient)\n\ncoef_bar_df$Gene <- factor(\n  coef_bar_df$Gene,\n  levels = coef_bar_df$Gene\n)\n\np_coef_bar <- ggplot(\n  coef_bar_df,\n  aes(\n    x = Gene,\n    y = Coefficient,\n    fill = Direction\n  )\n) +\n  geom_col(\n    width = 0.72,\n    color = \"black\",\n    linewidth = 0.25\n  ) +\n  geom_hline(\n    yintercept = 0,\n    linewidth = 0.7,\n    color = \"black\"\n  ) +\n  coord_flip() +\n  scale_fill_manual(\n    values = c(\n      \"Positive coefficient\" = \"#D62828\",\n      \"Negative coefficient\" = \"#2B6CB0\"\n    )\n  ) +\n  labs(\n    title = \"Coefficients of Genes Selected by LASSO\",\n    subtitle = paste0(\"Number of selected genes = \", nrow(coef_bar_df)),\n    x = NULL,\n    y = \"Coefficient at lambda.min\"\n  ) +",
"\n  theme_lasso_beauty() +\n  theme(\n    axis.text.y = element_text(face = \"bold\"),\n    legend.position = \"top\"\n  )\n\nsave_beauty_plot(\n  p_coef_bar,\n  filename = \"LASSO_selected_coefficients_barplot_original_result\",\n  width = 7.2,\n  height = 5.8\n)\n\n\n############################################################\n## 10. \u5408\u5e76\u56fe\uff1a\u8def\u5f84\u56fe + \u4ea4\u53c9\u9a8c\u8bc1\u56fe\n############################################################\n\np_lasso_combined <- p_lasso_path + p_cv +\n  patchwork::plot_annotation(\n    tag_levels = \"A\",\n    theme = theme(\n      plot.tag = element_text(\n        face = \"bold\",\n        size = 18\n      )\n    )\n  )\n\nsave_beauty_plot(\n  p_lasso_combined,\n  filename = \"LASSO_combined_beauty_original_result\",\n  width = 13.5,\n  height = 5.8\n)\n\n\n############################################################\n## 11. \u4fdd\u5b58\u7ed8\u56fe\u7528\u6570\u636e\n############################################################\n\nwrite.csv(\n  path_long_active,\n  file = \"LASSO_path_plot_data_original_result.csv\",\n  row.names = FALSE\n)\n\nwrite.csv(\n  cv_plot_df,\n  file = \"LASSO_CV_plot_data_original_result.csv\",\n  row.names = FALSE\n)\n\nwrite.csv(\n  coef_bar_df,\n  file = \"LASSO_selected_coefficients_plot_data_original_result.csv\",\n  row.names = FALSE\n)\n\n\n############################################################\n## 12. \u5b8c\u6210\u63d0\u793a\n############################################################\n\ncat(\"\\n\")\ncat(\"========================================\\n\")\ncat(\"LASSO \u53ea\u7f8e\u5316\u51fa\u56fe\u5b8c\u6210\uff1a\u672a\u91cd\u65b0\u8fd0\u884c glmnet / cv.glmnet\\n\")\ncat(\"========================================\\n\")\ncat(sprintf(\"lambda.min: %.6g\\n\", cv_model$lambda.min))\ncat(sprintf(\"lambda.1se: %.6g\\n\", cv_model$lambda.1se))\ncat(sprintf(\"\u539f\u59cb\u7b5b\u9009\u57fa\u56e0\u6570: %d\\n\", length(selected_genes)))\ncat(\"========================================\\n\")\ncat(\"\u539f\u59cb\u7b5b\u9009\u57fa\u56e0\uff1a\\n\")\nprint(selected_genes)\ncat(\"========================================\\n\")\ncat(\"\u65b0\u589e\u8f93\u51fa\u6587\u4ef6\uff1a",
"\\n\")\ncat(\"  1. LASSO_path_beauty_original_result.pdf / png\\n\")\ncat(\"  2. LASSO_CV_curve_beauty_original_result.pdf / png\\n\")\ncat(\"  3. LASSO_selected_coefficients_barplot_original_result.pdf / png\\n\")\ncat(\"  4. LASSO_combined_beauty_original_result.pdf / png\\n\")\ncat(\"  5. LASSO_path_plot_data_original_result.csv\\n\")\ncat(\"  6. LASSO_CV_plot_data_original_result.csv\\n\")\ncat(\"  7. LASSO_selected_coefficients_plot_data_original_result.csv\\n\")\ncat(\"========================================\\n\")"),
"bulk/11.marching learning/15lasso\u56de\u5f52/3LASSO\u56de\u5f52\u7b5b\u9009\u7279\u5f81\u57fa\u56e0.R"=paste0("# -------------------------------\n# \u6b65\u9aa4 0\uff1a\u8bbe\u7f6e\u603b\u6b65\u9aa4\u6570\u53ca\u8fdb\u5ea6\u6761\n# -------------------------------\n# -------------------------------\n# \u5b9a\u4e49\u5de5\u4f5c\u76ee\u5f55\u8def\u5f84\uff08\u8bf7\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u4fee\u6539\uff09\nwork_dir <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\11.marching learning\\\\15lasso\u56de\u5f52\"\n# \u5982\u679c\u76ee\u5f55\u4e0d\u5b58\u5728\uff0c\u5219\u521b\u5efa\u76ee\u5f55\uff08\u5305\u62ec\u5b50\u76ee\u5f55\uff09\n\n\ntotal_steps <- 9                                     # \u5b9a\u4e49\u603b\u51719\u4e2a\u4e3b\u8981\u6b65\u9aa4\nprogress_bar <- txtProgressBar(min = 0, max = total_steps, style = 3)  # \u521b\u5efa\u8fdb\u5ea6\u6761\u5bf9\u8c61\ncurrent_step <- 0                                    # \u521d\u59cb\u5316\u5f53\u524d\u6b65\u9aa4\n\n# -------------------------------\n# \u6b65\u9aa4 1\uff1a\u8bbe\u7f6e\u968f\u673a\u79cd\u5b50\uff0c\u786e\u4fdd\u7ed3\u679c\u53ef\u91cd\u590d\n# -------------------------------\nset.seed(168)                                     # \u56fa\u5b9a\u968f\u673a\u79cd\u5b50\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 2\uff1a\u68c0\u67e5\u5e76\u52a0\u8f7d\u5fc5\u8981\u7684 R \u5305\uff08glmnet\uff09\n# -------------------------------\n# \u5224\u65ad\u662f\u5426\u5df2\u5b89\u88c5glmnet\u5305\uff0c\u5982\u679c\u672a\u5b89\u88c5\u5219\u8fdb\u884c\u5b89\u88c5\uff0c\u518d\u52a0\u8f7d\u8be5\u5305\nif (!require(\"glmnet\")) {                           # \u5982\u679c\u672a\u52a0\u8f7d\u6210\u529f\n  install.packages(\"glmnet\")                         # \u5b89\u88c5glmnet\u5305\n  library(glmnet)                                   # \u52a0\u8f7dglmnet\u5305\n} else {\n  library(glmnet)                                   # \u5982\u679c\u5df2\u5b89\u88c5\uff0c\u5219\u76f4\u63a5\u52a0\u8f7d\n}\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n\n\nif (!dir.exists(work_dir)) {                        # \u68c0\u67e5\u5de5\u4f5c\u76ee\u5f55\u662f\u5426\u5b58\u5728\n  dir.create(work_dir, recursive = TRUE)            # \u521b\u5efa\u76ee\u5f55\uff08\u9012\u5f52\u521b\u5efa\uff09\n}\nsetwd(work_dir)                                     # \u8bbe\u7f6e\u5f53\u524d\u5de5\u4f5c\u76ee\u5f55\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 4\uff1a\u52a0\u8f7d\u8f93\u5165\u6570\u636e\u6587\u4ef6\uff0c\u5e76\u8fdb\u884c\u5fc5\u8981\u7684\u5224\u65ad\n# -------------------------------\ninput_file <- \"geneexp.csv\"                         # \u5b9a\u4e49\u6570\u636e\u6587\u4ef6\u540d\n# \u5224\u65ad\u6570\u636e\u6587\u4ef6\u662f\u5426\u5b58\u5728\nif (!file.exists(i",
"nput_file)) {                    # \u5982\u679c\u6587\u4ef6\u4e0d\u5b58\u5728\u5219\u62a5\u9519\n  stop(paste(\"\u9519\u8bef\uff1a\u8f93\u5165\u6587\u4ef6\", input_file, \"\u4e0d\u5b58\u5728\uff0c\u8bf7\u68c0\u67e5\u8def\u5f84\u3002\"))\n}\ndata_raw <- read.table(input_file,                   # \u8bfb\u53d6CSV\u6587\u4ef6\n                       header = TRUE,                # \u7b2c\u4e00\u884c\u4e3a\u8868\u5934\n                       sep = \",\",                    # \u5206\u9694\u7b26\u4e3a\u9017\u53f7\n                       check.names = FALSE,          # \u4fdd\u6301\u5217\u540d\u539f\u6837\n                       row.names = 1)                # \u7b2c\u4e00\u5217\u4f5c\u4e3a\u884c\u540d\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 5\uff1a\u6570\u636e\u9884\u5904\u7406 \u2014\u2014 \u8f6c\u7f6e\u6570\u636e\u77e9\u9635\n# -------------------------------\ndata_transposed <- t(data_raw)                      # \u8f6c\u7f6e\u6570\u636e\uff0c\u4f7f\u884c\u4ee3\u8868\u6837\u672c\uff0c\u5217\u4ee3\u8868\u57fa\u56e0\n# \u5197\u4f59\uff1a\u68c0\u67e5\u8f6c\u7f6e\u540e\u7684\u524d6\u4e2a\u57fa\u56e0\u540d\u79f0\nprint(head(colnames(data_transposed)))             # \u8f93\u51fa\u57fa\u56e0\u540d\u79f0\uff0c\u4fbf\u4e8e\u8c03\u8bd5\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 6\uff1a\u51c6\u5907Lasso\u56de\u5f52\u6a21\u578b\u6240\u9700\u7684\u6570\u636e\n# -------------------------------\nX_matrix <- as.matrix(data_transposed)              # \u5c06\u8f6c\u7f6e\u6570\u636e\u8f6c\u4e3a\u77e9\u9635\u683c\u5f0f\uff08\u8f93\u5165\u53d8\u91cf\uff09\n# \u5229\u7528\u6b63\u5219\u8868\u8fbe\u5f0f\u63d0\u53d6\u6837\u672c\u6807\u7b7e\uff08\u5047\u8bbe\u6837\u672c\u540d\u683c\u5f0f\u4e3a \"XXX_\u5206\u7ec4\u4fe1\u606f\"\uff09\nY_labels <- gsub(\"(.*)\\\\_(.*)\", \"\\\\2\", row.names(data_transposed))  # \u8f93\u51fa\u5206\u7c7b\u6807\u7b7e\n# \u5197\u4f59\uff1a\u6253\u5370\u90e8\u5206\u76ee\u6807\u6807\u7b7e\u4ee5\u4f9b\u68c0\u67e5\nprint(head(Y_labels))                              # \u67e5\u770b\u524d\u51e0\u4e2a\u6837\u672c\u7684\u5206\u7ec4\u4fe1\u606f\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 7\uff1a\u6784\u5efaLasso\u56de\u5f52\u6a21\u578b\u53ca\u4ea4\u53c9\u9a8c\u8bc1\u6a21\u578b\n# -------------------------------\n# \u62df\u5408Lasso\u56de\u5f52\u6a21\u578b\uff08\u91c7\u7528\u4e8c\u5206\u7c7b\uff0calpha=1 \u8868\u793aLasso\uff09\nlasso_model <- glmnet(X_matrix, Y_labels, family = \"binomial\", alpha = 1)\n# \u624b\u52a8\u8bbe\u7f6e\u6a21\u578b\u4e2d\u7cfb\u6570\u77e9\u9635\u7684\u884c\u540d\uff0c\u786e\u4fdd\u57fa\u56e0\u540d\u79f0\u6b63\u786e\u663e\u793a\ndimnames(lasso_model$beta)[[1]] <- colnames(X_matrix)\n# \u8fdb\u884c10\u6298\u4ea4\u53c9\u9a8c\u8bc1\u4ee5\u9009\u53d6\u6700\u4f73\u60e9\u7f5a\u53c2\u6570lambda\ncv_model <- cv.glmnet(X_matrix, Y_labels, family = \"binomial\", alpha = 1,\n              ",
"        type.measure = 'deviance', nfolds = 10)\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 8\uff1a\u7ed8\u56fe\u2014\u2014\u751f\u6210Lasso\u8def\u5f84\u56fe\u5e76\u6dfb\u52a0\u57fa\u56e0\u540d\u79f0\u6807\u7b7e\n# -------------------------------\n# \u6253\u5f00PDF\u8bbe\u5907\uff0c\u51c6\u5907\u4fdd\u5b58Lasso\u8def\u5f84\u56fe\npdf(file = \"lasso_modified.pdf\", width = 6, height = 5.5)\n# \u7ed8\u5236Lasso\u56de\u5f52\u8def\u5f84\u56fe\uff0c\u6a2a\u8f74\u4e3alambda\u503c\uff08\u5bf9\u6570\u523b\u5ea6\uff09\uff0c\u81ea\u52a8\u6807\u6ce8\u90e8\u5206\u66f2\u7ebf\nplot(lasso_model, xvar = \"lambda\", label = TRUE)\n# \u5197\u4f59\uff1a\u518d\u6b21\u63d0\u53d6\u7cfb\u6570\u77e9\u9635\u4ee5\u786e\u4fdd\u51c6\u786e\u6027\ncoef_matrix <- as.matrix(lasso_model$beta)\n# \u83b7\u53d6\u6700\u540e\u4e00\u4e2alambda\u503c\uff08\u56fe\u4e2d\u53f3\u4fa7\u4f4d\u7f6e\uff09\uff0c\u5e76\u8ba1\u7b97\u5176\u5bf9\u6570\u503c\uff08\u56e0\u4e3a\u6a2a\u8f74\u4e3alog(lambda)\uff09\nlambda_last <- tail(lasso_model$lambda, 1)\nlog_lambda_last <- log(lambda_last)\n# \u904d\u5386\u6bcf\u4e2a\u57fa\u56e0\uff0c\u5982\u679c\u5728\u6700\u540e\u4e00\u4e2alambda\u5904\u7cfb\u6570\u4e0d\u4e3a0\uff0c\u5219\u624b\u52a8\u6dfb\u52a0\u6807\u7b7e\nfor (i in 1:nrow(coef_matrix)) {                   # \u5faa\u73af\u6bcf\u4e2a\u57fa\u56e0\n  # \u5224\u65ad\u5f53\u524d\u57fa\u56e0\u5728\u6700\u540e\u4e00\u4e2alambda\u5904\u7684\u7cfb\u6570\u662f\u5426\u975e\u96f6\n  if (coef_matrix[i, length(lasso_model$lambda)] != 0) {  \n    text(x = log_lambda_last,                     # \u8bbe\u7f6e\u6807\u7b7e\u7684x\u5750\u6807\uff08\u56fe\u53f3\u4fa7\uff09\n         y = coef_matrix[i, length(lasso_model$lambda)],  # \u5bf9\u5e94\u7684\u7cfb\u6570\u503c\u4f5c\u4e3ay\u5750\u6807\n         labels = rownames(coef_matrix)[i],       # \u4f7f\u7528\u57fa\u56e0\u540d\u79f0\u4f5c\u4e3a\u6807\u7b7e\n         pos = 4,                                 # \u6807\u7b7e\u663e\u793a\u5728\u70b9\u7684\u53f3\u4fa7\n         cex = 0.7,                               # \u8bbe\u7f6e\u6807\u7b7e\u5b57\u4f53\u5927\u5c0f\n         col = \"red\")                             # \u8bbe\u7f6e\u6807\u7b7e\u989c\u8272\n  }\n}\ndev.off()                                          # \u5173\u95edPDF\u8bbe\u5907\uff0c\u4fdd\u5b58\u6587\u4ef6\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 9\uff1a\u7ed8\u56fe\u2014\u2014\u751f\u6210\u4ea4\u53c9\u9a8c\u8bc1\u8bef\u5dee\u56fe\u53ca\u8f93\u51fa\u7ed3\u679c\u8868\u683c\n# -------------------------------\n# \u7ed8\u5236\u4ea4\u53c9\u9a8c\u8bc1\u8bef\u5dee\u56fe\uff0c\u4fdd\u5b58\u4e3aPDF\npdf(file = \"cvfit_modified.pdf\", width = 6, height = 5.5)\nplot(cv_model)                                     # \u7ed8\u5236\u4ea4\u53c9\u9a8c\u8bc1\u66f2\u7ebf\ndev.off()                                          # \u5173\u95edPDF\u8bbe\u5907\n\n# \u63d0\u53d6\u6700\u4f18lambda\u4e0b\u7684\u6240\u6709\u57fa\u56e0\u7cfb\u6570\noptimal_coefs <- coef(lasso_model, s = cv_model$lambda.min)\n# \u5224\u65ad\u662f\u5426\u5b58\u5728\u9664\u622a\u8ddd\u5916\u7684\u975e\u96f6\u7cfb\u6570\ni",
"f (sum(optimal_coefs != 0) <= 1) {                 # \u5982\u679c\u53ea\u6709\u622a\u8ddd\u9879\u4e3a\u975e\u96f6\n  warning(\"\u8b66\u544a\uff1a\u672a\u68c0\u6d4b\u5230\u4efb\u4f55\u975e\u96f6\u7684\u57fa\u56e0\u7cfb\u6570\uff0c\u53ef\u80fd\u9700\u8981\u68c0\u67e5\u6570\u636e\u6216\u6a21\u578b\u53c2\u6570\u3002\")\n} else {\n  # \u83b7\u53d6\u6240\u6709\u975e\u96f6\u7cfb\u6570\u5bf9\u5e94\u7684\u57fa\u56e0\u540d\u79f0\uff08\u6392\u9664\u622a\u8ddd\u9879\uff09\n  nonzero_indices <- which(optimal_coefs != 0)      # \u83b7\u53d6\u975e\u96f6\u7cfb\u6570\u7684\u7d22\u5f15\n  gene_names <- rownames(optimal_coefs)[nonzero_indices]  # \u63d0\u53d6\u57fa\u56e0\u540d\u79f0\n  gene_names <- gene_names[gene_names != \"(Intercept)\"]      # \u6392\u9664\u622a\u8ddd\u9879\n  # \u8f93\u51fa\u5173\u952e\u57fa\u56e0\u5217\u8868\u5230\u6587\u672c\u6587\u4ef6\n  write.table(gene_names,\n              file = \"LASSO_genes_modified.txt\",\n              sep = \"\\t\",\n              quote = FALSE,\n              row.names = FALSE,\n              col.names = FALSE)\n}\n\n# \u8f93\u51fa\u6700\u4f18lambda\u4e0b\u7684\u5b8c\u6574\u57fa\u56e0\u56de\u5f52\u7cfb\u6570\u8868\nfull_coef_matrix <- as.matrix(coef(lasso_model, s = cv_model$lambda.min))\ncoef_dataframe <- data.frame(Gene = rownames(full_coef_matrix), \n                             Coefficient = full_coef_matrix[,1])\nwrite.table(coef_dataframe,\n            file = \"LASSO_coefficients_modified.txt\",\n            sep = \"\\t\",\n            quote = FALSE,\n            row.names = FALSE,\n            col.names = TRUE)\n\n# \u8f93\u51fa\u4ea4\u53c9\u9a8c\u8bc1\u8be6\u7ec6\u7ed3\u679c\uff0c\u5305\u542blambda\u503c\u53ca\u5bf9\u5e94\u7684\u5747\u65b9\u8bef\u5dee\u7b49\u4fe1\u606f\ncv_results_table <- data.frame(lambda = cv_model$lambda,\n                               cvm = cv_model$cvm,\n                               cvup = cv_model$cvup,\n                               cvlo = cv_model$cvlo)\nwrite.table(cv_results_table,\n            file = \"CV_results_modified.txt\",\n            sep = \"\\t\",\n            quote = FALSE,\n            row.names = FALSE,\n            col.names = TRUE)\ncurrent_step <- current_step + 1                     # \u66f4\u65b0\u8fdb\u5ea6\u6761\u6b65\u9aa4\nsetTxtProgressBar(progress_bar, current_step)       # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n\n# -------------------------------\n# \u6b65\u9aa4 10\uff1a\u6e05\u7406\u5de5\u4f5c\u4e0e\u7ed3\u675f\n# -------------------------------\nclose(progress_bar)                                # \u5173\u95ed\u8fdb\u5ea6\u6761\ncat(\"\u6240\u6709\u6b65\u9aa4\u5df2\u5b8c\u6210\uff0c\u7ed3\u679c\u6587\u4ef6\u5df2\u4fdd\u5b58\u3002\\n\")         # \u8f93\u51fa\u5b8c\u6210\u63d0\u793a\u4fe1\u606f\n"),
"bulk/11.marching learning/23.SVM\u5206\u6790/\u7f8e\u5316\u56fe.R"=paste0("############################################################\n## \u53ea\u7f8e\u5316\u51fa\u56fe\u7248\uff1a\u4e0d\u91cd\u65b0\u8fd0\u884c SVM-RFE\uff0c\u4e0d\u6539\u53d8\u539f\u59cb\u57fa\u56e0\u7ed3\u679c\n## \u4f7f\u7528\u5bf9\u8c61\uff1a\n## errors\n## optimalFeatureCount\n## optimalError\n## optimalAccuracy\n## no.info\n## topFeatures\n## featureGenes\n##\n## \u6ce8\u610f\uff1a\n## \u8fd9\u6bb5\u4ee3\u7801\u5fc5\u987b\u653e\u5728\u4f60\u7684\u539f\u59cb SVM-RFE \u4ee3\u7801\u8fd0\u884c\u5b8c\u6210\u4e4b\u540e\u3002\n############################################################\n\n\n############################################################\n## 1. \u52a0\u8f7d\u7f8e\u5316\u7ed8\u56fe\u5305\n############################################################\n\nplot_packages <- c(\n  \"ggplot2\",\n  \"dplyr\",\n  \"patchwork\",\n  \"ggrepel\",\n  \"scales\"\n)\n\nfor (pkg in plot_packages) {\n  if (!requireNamespace(pkg, quietly = TRUE)) {\n    install.packages(pkg, dependencies = TRUE)\n  }\n  library(pkg, character.only = TRUE)\n}\n\n\n############################################################\n## 2. \u68c0\u67e5\u539f\u59cb\u7ed3\u679c\u662f\u5426\u5b58\u5728\n############################################################\n\nif (!exists(\"errors\")) {\n  stop(\"\u672a\u627e\u5230 errors \u5bf9\u8c61\u3002\u8bf7\u5148\u5b8c\u6574\u8fd0\u884c\u4f60\u7684\u539f\u59cb SVM-RFE \u4ee3\u7801\u3002\")\n}\n\nif (!exists(\"optimalFeatureCount\")) {\n  optimalFeatureCount <- which.min(errors)\n}\n\nif (!exists(\"optimalError\")) {\n  optimalError <- min(errors, na.rm = TRUE)\n}\n\nif (!exists(\"optimalAccuracy\")) {\n  optimalAccuracy <- 1 - optimalError\n}\n\nif (!exists(\"no.info\")) {\n  if (exists(\"data\")) {\n    no.info <- min(prop.table(table(data[, 1])))\n  } else {\n    no.info <- 0.5\n    warning(\"\u672a\u627e\u5230 data \u5bf9\u8c61\uff0cno.info \u6682\u65f6\u8bbe\u4e3a 0.5\u3002\")\n  }\n}\n\nif (!exists(\"featureGenes\")) {\n  if (file.exists(\"SVM-RFE.gene.txt\")) {\n    featureGenes <- read.table(\n      \"SVM-RFE.gene.txt\",\n      header = FALSE,\n      stringsAsFactors = FALSE\n    )\n    colnames(featureGenes) <- \"FeatureName\"\n  } else {\n    stop(\"\u672a\u627e\u5230 featureGenes \u5bf9\u8c61\uff0c\u4e5f\u672a\u627e\u5230 SVM-RFE.gene.txt \u6587\u4ef6\u3002\")\n  }\n}\n\nif (!exists(\"topFeatures\")) {\n  if (file.exists(\"feature_svm.txt\")) {\n    topFeatures <- read.delim(\n      \"feature_svm.txt\",\n      header = TRU",
"E,\n      check.names = FALSE,\n      stringsAsFactors = FALSE\n    )\n  } else {\n    warning(\"\u672a\u627e\u5230 topFeatures \u5bf9\u8c61\uff0c\u4e5f\u672a\u627e\u5230 feature_svm.txt \u6587\u4ef6\u3002\u540e\u7eed\u53ea\u7ed8\u5236\u6700\u4f18\u57fa\u56e0\u6392\u5e8f\u56fe\u3002\")\n    topFeatures <- NULL\n  }\n}\n\n\n############################################################\n## 3. \u4fdd\u5b58\u539f\u59cb\u8bef\u5dee\u548c\u51c6\u786e\u7387\u6570\u636e\uff0c\u65b9\u4fbf\u4ee5\u540e\u4e0d\u91cd\u65b0\u8dd1\u6a21\u578b\u76f4\u63a5\u753b\u56fe\n############################################################\n\ncurve_data_original <- data.frame(\n  Feature_Number = seq_along(errors),\n  CV_Error = as.numeric(errors),\n  CV_Accuracy = 1 - as.numeric(errors)\n)\n\nwrite.csv(\n  curve_data_original,\n  file = \"SVM_RFE_curve_data_original.csv\",\n  row.names = FALSE\n)\n\n\n############################################################\n## 4. \u671f\u520a\u98ce\u683c\u4e3b\u9898\n############################################################\n\ntheme_svm_beauty <- function(base_size = 14) {\n  theme_classic(base_size = base_size) +\n    theme(\n      plot.title = element_text(\n        face = \"bold\",\n        size = base_size + 2,\n        hjust = 0.5,\n        color = \"black\"\n      ),\n      plot.subtitle = element_text(\n        size = base_size - 1,\n        hjust = 0.5,\n        color = \"grey35\"\n      ),\n      axis.title = element_text(\n        face = \"bold\",\n        size = base_size,\n        color = \"black\"\n      ),\n      axis.text = element_text(\n        color = \"black\",\n        size = base_size - 1\n      ),\n      axis.line = element_line(\n        linewidth = 0.7,\n        color = \"black\"\n      ),\n      axis.ticks = element_line(\n        linewidth = 0.6,\n        color = \"black\"\n      ),\n      panel.grid.major = element_line(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      legend.position = \"top\",\n      legend.title = element_blank(),\n      legend.text = element_text(size = base_size - 1),\n      plot.caption = element_text(\n        size = base_siz",
"e - 3,\n        color = \"grey40\",\n        hjust = 0\n      ),\n      plot.margin = margin(10, 15, 10, 10)\n    )\n}\n\n\n############################################################\n## 5. \u4fdd\u5b58\u51fd\u6570\uff1a\u540c\u65f6\u4fdd\u5b58 PDF \u548c 600 dpi PNG\n############################################################\n\nsave_beauty_plot <- function(p, filename, width = 6, height = 5) {\n  \n  ggsave(\n    filename = paste0(filename, \".pdf\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = paste0(filename, \".png\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\",\n    dpi = 600\n  )\n}\n\n\n############################################################\n## 6. \u7f8e\u5316\u66f2\u7ebf\u7ed8\u56fe\u51fd\u6570\n############################################################\n\nPlotSVMRFECurve <- function(values,\n                            optimal_n,\n                            baseline,\n                            metric = c(\"error\", \"accuracy\")) {\n  \n  metric <- match.arg(metric)\n  \n  df <- data.frame(\n    Feature_Number = seq_along(values),\n    Value = as.numeric(values)\n  )\n  \n  df <- df[is.finite(df$Value), , drop = FALSE]\n  \n  if (nrow(df) == 0) {\n    stop(\"\u7ed8\u56fe\u6570\u636e\u4e3a\u7a7a\uff0c\u8bf7\u68c0\u67e5 errors \u662f\u5426\u6b63\u5e38\u3002\")\n  }\n  \n  opt_df <- df[df$Feature_Number == optimal_n, , drop = FALSE]\n  \n  if (nrow(opt_df) == 0) {\n    if (metric == \"error\") {\n      opt_df <- df[which.min(df$Value), , drop = FALSE]\n    } else {\n      opt_df <- df[which.max(df$Value), , drop = FALSE]\n    }\n  }\n  \n  if (metric == \"error\") {\n    \n    main_title <- \"SVM-RFE Cross-Validation Error\"\n    sub_title <- \"Lower error indicates better feature subset\"\n    y_lab <- \"10-fold CV error\"\n    line_col <- \"#2B6CB0\"\n    point_col <- \"#2B6CB0\"\n    opt_col <- \"#D62828\"\n    \n    opt_label <- sprintf(\n      \"Optimal features = %d\\nCV error = %.1f%%\",\n      opt_df$Feature_Num",
"ber,\n      100 * opt_df$Value\n    )\n    \n  } else {\n    \n    main_title <- \"SVM-RFE Cross-Validation Accuracy\"\n    sub_title <- \"Higher accuracy indicates better feature subset\"\n    y_lab <- \"10-fold CV accuracy\"\n    line_col <- \"#2F855A\"\n    point_col <- \"#2F855A\"\n    opt_col <- \"#D62828\"\n    \n    opt_label <- sprintf(\n      \"Optimal features = %d\\nCV accuracy = %.1f%%\",\n      opt_df$Feature_Number,\n      100 * opt_df$Value\n    )\n  }\n  \n  y_min <- max(\n    0,\n    min(c(df$Value, baseline), na.rm = TRUE) - 0.05\n  )\n  \n  y_max <- min(\n    1,\n    max(c(df$Value, baseline), na.rm = TRUE) + 0.05\n  )\n  \n  p <- ggplot(df, aes(x = Feature_Number, y = Value)) +\n    geom_hline(\n      yintercept = baseline,\n      linetype = \"dashed\",\n      linewidth = 0.7,\n      color = \"grey45\"\n    ) +\n    geom_line(\n      linewidth = 1.2,\n      color = line_col\n    ) +\n    geom_point(\n      size = 2.8,\n      shape = 21,\n      stroke = 0.8,\n      fill = \"white\",\n      color = point_col\n    ) +\n    geom_vline(\n      xintercept = opt_df$Feature_Number,\n      linetype = \"dotted\",\n      linewidth = 0.8,\n      color = opt_col\n    ) +\n    geom_point(\n      data = opt_df,\n      aes(x = Feature_Number, y = Value),\n      size = 4.2,\n      shape = 21,\n      stroke = 1,\n      fill = opt_col,\n      color = \"black\"\n    ) +\n    ggrepel::geom_label_repel(\n      data = opt_df,\n      aes(label = opt_label),\n      size = 4,\n      fontface = \"bold\",\n      color = \"black\",\n      fill = \"white\",\n      label.size = 0.35,\n      box.padding = 0.5,\n      point.padding = 0.4,\n      min.segment.length = 0,\n      segment.color = \"grey40\",\n      seed = 1993\n    ) +\n    scale_x_continuous(\n      breaks = scales::pretty_breaks(n = 8),\n      expand = expansion(mult = c(0.03, 0.08))\n    ) +\n    scale_y_continuous(\n      labels ",
"= scales::percent_format(accuracy = 1),\n      limits = c(y_min, y_max),\n      expand = expansion(mult = c(0.02, 0.06))\n    ) +\n    labs(\n      title = main_title,\n      subtitle = sub_title,\n      x = \"Number of selected features\",\n      y = y_lab,\n      caption = \"Dashed horizontal line indicates the no-information baseline.\"\n    ) +\n    theme_svm_beauty()\n  \n  return(p)\n}\n\n\n############################################################\n## 7. \u7ed8\u5236\u539f\u59cb\u7ed3\u679c\u5bf9\u5e94\u7684\u9519\u8bef\u7387\u66f2\u7ebf\n############################################################\n\np_error <- PlotSVMRFECurve(\n  values = errors,\n  optimal_n = optimalFeatureCount,\n  baseline = no.info,\n  metric = \"error\"\n)\n\nsave_beauty_plot(\n  p_error,\n  filename = \"SVM_RFE_error_curve_beauty_original_result\",\n  width = 6.2,\n  height = 5.2\n)\n\n\n############################################################\n## 8. \u7ed8\u5236\u539f\u59cb\u7ed3\u679c\u5bf9\u5e94\u7684\u51c6\u786e\u7387\u66f2\u7ebf\n############################################################\n\n# \u6ce8\u610f\uff1a\n# \u4f60\u7684\u539f\u59cb\u4ee3\u7801\u4e2d accuracy \u56fe\u7684 no.info \u4ecd\u7136\u4f7f\u7528\u4e86 no.info\u3002\n# \u4e3a\u4e86\u4e0d\u6539\u53d8\u539f\u56fe\u903b\u8f91\uff0c\u8fd9\u91cc\u4e5f\u4fdd\u7559\u540c\u6837\u7684 baseline\u3002\n# \u5982\u679c\u4f60\u60f3\u66f4\u4e25\u8c28\uff0caccuracy \u7684 baseline \u5e94\u8be5\u4f7f\u7528 1 - no.info\u3002\n\np_accuracy <- PlotSVMRFECurve(\n  values = 1 - errors,\n  optimal_n = optimalFeatureCount,\n  baseline = no.info,\n  metric = \"accuracy\"\n)\n\nsave_beauty_plot(\n  p_accuracy,\n  filename = \"SVM_RFE_accuracy_curve_beauty_original_result\",\n  width = 6.2,\n  height = 5.2\n)\n\n\n############################################################\n## 9. \u5408\u5e76\u9519\u8bef\u7387\u548c\u51c6\u786e\u7387\u66f2\u7ebf\n############################################################\n\np_combined <- p_error + p_accuracy +\n  patchwork::plot_annotation(\n    tag_levels = \"A\",\n    theme = theme(\n      plot.tag = element_text(\n        face = \"bold\",\n        size = 18\n      )\n    )\n  )\n\nsave_beauty_plot(\n  p_combined,\n  filename = \"SVM_RFE_combined_plots_beauty_original_result\",\n  width = 12,\n  height = 5.4\n)\n\n\n#######################",
"#####################################\n## 10. \u7ed8\u5236\u6700\u4f18\u57fa\u56e0\u6392\u5e8f\u56fe\n## \u5b8c\u5168\u4f7f\u7528\u4f60\u539f\u59cb SVM-RFE.gene.txt \u4e2d\u7684\u57fa\u56e0\uff0c\u4e0d\u91cd\u65b0\u7b5b\u9009\n############################################################\n\nselected_genes <- featureGenes[, 1]\nselected_genes <- as.character(selected_genes)\nselected_genes <- selected_genes[selected_genes != \"\"]\n\nselected_gene_df <- data.frame(\n  Gene = selected_genes,\n  Rank = seq_along(selected_genes),\n  stringsAsFactors = FALSE\n)\n\nselected_gene_df$DisplayScore <- rev(seq_len(nrow(selected_gene_df)))\nselected_gene_df$Gene <- factor(\n  selected_gene_df$Gene,\n  levels = rev(selected_gene_df$Gene)\n)\n\np_selected_genes <- ggplot(\n  selected_gene_df,\n  aes(x = Gene, y = DisplayScore)\n) +\n  geom_col(\n    width = 0.72,\n    fill = \"#D62828\",\n    color = \"black\",\n    linewidth = 0.25\n  ) +\n  geom_text(\n    aes(label = paste0(\"#\", Rank)),\n    hjust = -0.15,\n    size = 3.8,\n    fontface = \"bold\"\n  ) +\n  coord_flip(clip = \"off\") +\n  scale_y_continuous(\n    expand = expansion(mult = c(0.02, 0.18))\n  ) +\n  labs(\n    title = \"Optimal Genes Selected by SVM-RFE\",\n    subtitle = paste0(\n      \"Original result: \",\n      optimalFeatureCount,\n      \" genes, CV accuracy = \",\n      sprintf(\"%.1f%%\", 100 * optimalAccuracy)\n    ),\n    x = NULL,\n    y = \"Relative ranking score\"\n  ) +\n  theme_svm_beauty() +\n  theme(\n    axis.text.y = element_text(\n      face = \"bold\",\n      size = 12\n    ),\n    legend.position = \"none\"\n  )\n\nsave_beauty_plot(\n  p_selected_genes,\n  filename = \"SVM_RFE_selected_genes_barplot_original_result\",\n  width = 7,\n  height = 5.8\n)\n\n\n############################################################\n## 11. \u8f93\u51fa\u539f\u59cb\u6700\u4f18\u57fa\u56e0\u548c\u7ed8\u56fe\u5b8c\u6210\u4fe1\u606f\n############################################################\n\ncat(\"\\n\")\ncat(\"========================================\\n\")\ncat(\"\u53ea\u7f8e\u5316\u51fa\u56fe\u5b8c\u6210\uff1a\u672a\u91cd\u65b0\u8fd0\u884c SVM-RFE\\n\")\ncat(\"=======================",
"=================\\n\")\ncat(sprintf(\"\u539f\u59cb\u6700\u4f18\u7279\u5f81\u6570\uff1a%d\\n\", optimalFeatureCount))\ncat(sprintf(\"\u539f\u59cb\u6700\u5c0f\u9519\u8bef\u7387\uff1a%.4f\\n\", optimalError))\ncat(sprintf(\"\u539f\u59cb\u6700\u9ad8\u51c6\u786e\u7387\uff1a%.4f\\n\", optimalAccuracy))\ncat(\"========================================\\n\")\ncat(\"\u539f\u59cb\u6700\u4f18\u57fa\u56e0\uff1a\\n\")\nprint(selected_genes)\ncat(\"========================================\\n\")\ncat(\"\u65b0\u589e\u8f93\u51fa\u6587\u4ef6\uff1a\\n\")\ncat(\"  1. SVM_RFE_curve_data_original.csv\\n\")\ncat(\"  2. SVM_RFE_error_curve_beauty_original_result.pdf / png\\n\")\ncat(\"  3. SVM_RFE_accuracy_curve_beauty_original_result.pdf / png\\n\")\ncat(\"  4. SVM_RFE_combined_plots_beauty_original_result.pdf / png\\n\")\ncat(\"  5. SVM_RFE_selected_genes_barplot_original_result.pdf / png\\n\")\ncat(\"========================================\\n\")"),
"bulk/11.marching learning/23.SVM\u5206\u6790/SVM-RFE.gene.R"=paste0("\n  library(e1071)                                     # \u5982\u679c\u5df2\u5b89\u88c5\uff0c\u76f4\u63a5\u52a0\u8f7de1071\u5305\n\n\n# \u8bbe\u7f6e\u968f\u673a\u79cd\u5b50\uff0c\u786e\u4fdd\u7ed3\u679c\u53ef\u91cd\u590d\nset.seed(1993)                                      # \u56fa\u5b9a\u968f\u673a\u79cd\u5b50\n\n# \u5b9a\u4e49\u8f93\u5165\u6570\u636e\u6587\u4ef6\u7684\u8def\u5f84\nworkDir <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\11.marching learning\\\\23.SVM\u5206\u6790\"  # \u5de5\u4f5c\u76ee\u5f55\ninputFile <- file.path(workDir, \"batch_corrected_data.csv\")  # \u57fa\u56e0\u8868\u8fbe\u6570\u636e\u6587\u4ef6\n\n# \u81ea\u52a8\u8bc6\u522b Intersection_ \u524d\u7f00\u7684txt\u6587\u4ef6\u4f5c\u4e3a\u57fa\u56e0\u5217\u8868\ngene_list_files <- list.files(workDir, pattern = \"^Intersection_.*\\\\.txt$\", full.names = TRUE)\nif (length(gene_list_files) == 0) {\n  stop(\"\u672a\u5728\u5de5\u4f5c\u76ee\u5f55\u4e0b\u627e\u5230 Intersection_ \u524d\u7f00\u7684txt\u6587\u4ef6\uff01\")\n}\ngeneListFile <- gene_list_files[1]  # \u4f7f\u7528\u7b2c\u4e00\u4e2a\u5339\u914d\u7684\u6587\u4ef6\nmessage(sprintf(\"\u81ea\u52a8\u8bc6\u522b\u57fa\u56e0\u5217\u8868\u6587\u4ef6: %s\", basename(geneListFile)))\n\n# \u8bbe\u7f6e\u5f53\u524d\u5de5\u4f5c\u76ee\u5f55\nsetwd(workDir)                                       # \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\n\n# \u5224\u65ad\u8f93\u5165\u6587\u4ef6\u662f\u5426\u5b58\u5728\uff0c\u4e0d\u5b58\u5728\u5219\u505c\u6b62\u6267\u884c\nif (!file.exists(inputFile)) {                      # \u68c0\u67e5\u8868\u8fbe\u6570\u636e\u6587\u4ef6\u662f\u5426\u5b58\u5728\n  stop(\"\u8868\u8fbe\u6570\u636e\u6587\u4ef6\u4e0d\u5b58\u5728\uff0c\u8bf7\u68c0\u67e5\u6587\u4ef6\u8def\u5f84\uff01\")         # \u82e5\u4e0d\u5b58\u5728\u5219\u62a5\u9519\u505c\u6b62\u6267\u884c\n}\n\nif (!file.exists(geneListFile)) {                   # \u68c0\u67e5\u57fa\u56e0\u5217\u8868\u6587\u4ef6\u662f\u5426\u5b58\u5728\n  stop(\"\u57fa\u56e0\u5217\u8868\u6587\u4ef6\u4e0d\u5b58\u5728\uff0c\u8bf7\u68c0\u67e5\u6587\u4ef6\u8def\u5f84\uff01\")         # \u82e5\u4e0d\u5b58\u5728\u5219\u62a5\u9519\u505c\u6b62\u6267\u884c\n}\n\n# \u8bfb\u53d6\u8981\u5206\u6790\u7684\u57fa\u56e0\u5217\u8868\uff08\u81ea\u52a8\u5224\u65ad\u662f\u5426\u6709\u8868\u5934\uff09\nmessage(\"\u8bfb\u53d6\u57fa\u56e0\u5217\u8868\u6587\u4ef6...\")\ngeneListRaw <- readLines(geneListFile)\ngeneListRaw <- trimws(geneListRaw)\ngeneListRaw <- geneListRaw[geneListRaw != \"\"]\n# \u5982\u679c\u7b2c\u4e00\u884c\u662f \"Gene\" \u6216 \"Genes\" \u7b49\u8868\u5934\uff0c\u5219\u8df3\u8fc7\nif (tolower(geneListRaw[1]) %in% c(\"gene\", \"genes\", \"genename\", \"gene_name\")) {\n  geneList <- geneListRaw[-1]\n} else {\n  geneList <- geneListRaw\n}\ngeneList <- unique(geneList)\nmessage(sprintf(\"\u5171\u8bfb\u53d6 %d \u4e2a\u57fa\u56e0\", length(geneList)))\n\n# ---------------------- \u5b9a\u4e49\u8f85\u52a9\u51fd\u6570 ----------------------\n\n# \u5b9a\u4e49\u83b7\u53d6SVM\u6743\u91cd\u7684\u51fd\u6570\uff08\u7528\u4e8e\u8ba1\u7b97\u7279\u5f81\u91cd\u8981\u6027\uff09\ngetWeights <- function(test.fold, X) {\n  # \u6839\u636e\u662f\u5426\u6307\u5b9a\u6d4b\u8bd5\u6298\uff0c\u9009\u62e9\u8bad\u7ec3\u6570\u636e\n  train.data <- X\n  if (!is.null(test.fold)) {                         # \u5982\u679c\u63d0\u4f9b\u6d4b\u8bd5\u6298\u7f16\u53f7\n    train.data <- X[-test.fold, ]                    # \u6392\u9664\u6d4b\u8bd5\u6298\u6570\u636e\u4f5c\u4e3a\u8bad\u7ec3\u6570\u636e\n  }\n  # \u4f7f\u7528\u7ebf\u6027\u6838\u8bad\u7ec3SVM\u6a21\u578b\uff0ccost\u8bbe\u4e3a10\uff0c\u5173\u95ed\u5185\u90e8\u6570\u636e\u7f29\u653e\n  svmModel <- svm(train.data[, -1], train.data[, 1],\n",
"                  cost = 10, cachesize = 500,\n                  scale = FALSE, type = \"C-classification\",\n                  kernel = \"linear\")                # \u8bad\u7ec3\u7ebf\u6027SVM\u5206\u7c7b\u5668\n  # \u8ba1\u7b97\u5e76\u8fd4\u56de\u6743\u91cd\u5411\u91cf\uff08\u6a21\u578b\u7cfb\u6570\u4e58\u652f\u6301\u5411\u91cf\uff09\n  return(t(svmModel$coefs) %*% svmModel$SV)          # \u8fd4\u56deSVM\u6743\u91cd\u5411\u91cf\n}\n\n# \u5b9a\u4e49SVM-RFE\u7b97\u6cd5\u51fd\u6570\uff0c\u7528\u4e8e\u7279\u5f81\u9009\u62e9\nsvmRFE <- function(X, k = 1, halve.above = 5000) {\n  totalFeatures <- ncol(X) - 1                       # \u8ba1\u7b97\u9664\u5206\u7ec4\u5217\u5916\u7684\u7279\u5f81\u603b\u6570\n  cat(\"\u603b\u7279\u5f81\u6570\u91cf\uff1a\", totalFeatures, \"\\n\")           # \u8f93\u51fa\u603b\u7279\u5f81\u6570\u91cf\n  cat(\"\u5f00\u59cb\u6570\u636e\u6807\u51c6\u5316...\\n\")                         # \u8f93\u51fa\u6b65\u9aa4\u63d0\u793a\n  \n  # \u5bf9\u6570\u636e\u8fdb\u884c\u6807\u51c6\u5316\u5904\u7406\uff08\u4e0d\u5bf9\u5206\u7ec4\u4fe1\u606f\u5904\u7406\uff09\n  X[, -1] <- scale(X[, -1])                          # \u6807\u51c6\u5316\u7279\u5f81\u6570\u636e\n  cat(\"\u6570\u636e\u6807\u51c6\u5316\u5b8c\u6210\uff01\\n\")                           # \u8f93\u51fa\u6807\u51c6\u5316\u5b8c\u6210\u4fe1\u606f\n  \n  # \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\uff0c\u663e\u793a\u7279\u5f81\u9012\u5f52\u8fc7\u7a0b\n  pb <- txtProgressBar(min = 1, max = totalFeatures, style = 3)  # \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\n  \n  survivingIndices <- 1:totalFeatures                # \u521d\u59cb\u5316\u5b58\u6d3b\u7279\u5f81\u7d22\u5f15\n  rankingPosition  <- totalFeatures                  # \u521d\u59cb\u5316\u6392\u540d\u4f4d\u7f6e\n  rankedFeatures <- vector(length = totalFeatures)   # \u521d\u59cb\u5316\u6700\u7ec8\u7279\u5f81\u6392\u540d\u5217\u8868\n  \n  # \u5faa\u73af\u9012\u5f52\u6d88\u9664\u7279\u5f81\uff0c\u76f4\u81f3\u6240\u6709\u7279\u5f81\u5747\u88ab\u6392\u5e8f\n  while (length(survivingIndices) > 0) {\n    # \u5224\u65ad\u662f\u5426\u8fdb\u884c\u591a\u91cdSVM-RFE\n    if (k > 1) {                                     # \u5982\u679ck\u5927\u4e8e1\u5219\u4f7f\u7528\u591a\u91cd\u9a8c\u8bc1\u65b9\u5f0f\n      # \u751f\u6210\u968f\u673a\u6298\uff0c\u4fdd\u8bc1\u6bcf\u4e2a\u6298\u5747\u5300\u5206\u5e03\n      folds <- rep(1:k, length.out = nrow(X))\n      folds <- sample(folds)                         # \u6253\u4e71\u6298\u5e8f\n      foldsList <- lapply(1:k, function(x) which(folds == x))  # \u5c06\u6298\u7f16\u53f7\u5206\u7ec4\n      \n      # \u5bf9\u6bcf\u4e2a\u6298\u8fdb\u884c\u8bad\u7ec3\uff0c\u83b7\u53d6\u6743\u91cd\u5411\u91cf\n      weightList <- lapply(foldsList, getWeights, X[, c(1, 1 + survivingIndices)])\n      weightMatrix <- do.call(rbind, weightList)      # \u5408\u5e76\u5404\u6298\u7684\u6743\u91cd\u5411\u91cf\n      \n      # \u6807\u51c6\u5316\u6bcf\u4e2a\u6743\u91cd\u5411\u91cf\n      weightMatrix <- t(apply(weightMatrix, 1, function(w) w / sqrt(sum(w^2) + 1e-6)))\n      \n      # \u8ba1\u7b97\u6bcf\u4e2a\u7279\u5f81\u7684\u8bc4\u5206\uff0c\u5229\u7528\u5747\u503c\u548c\u6807\u51c6\u5dee\n      v <- weightMatrix^2                           # \u8ba1\u7b97\u5e73\u65b9\u503c\n      vBar <- apply(v, 2, mean)                       # \u8ba1\u7b97\u5747\u503c\n      vSD <- apply(v, 2, sd)",
" + 1e-6                   # \u8ba1\u7b97\u6807\u51c6\u5dee\uff0c\u9632\u6b62\u9664\u96f6\n      scores <- vBar / vSD                            # \u5f97\u5230\u6bcf\u4e2a\u7279\u5f81\u7684\u8bc4\u5206\n    } else {                                         # \u82e5\u53ea\u8fdb\u884c\u5355\u6b21SVM-RFE\n      weights <- getWeights(NULL, X[, c(1, 1 + survivingIndices)])  # \u8ba1\u7b97\u6743\u91cd\u5411\u91cf\n      scores <- weights^2                           # \u5f97\u5230\u8bc4\u5206\uff08\u5e73\u65b9\uff09\n    }\n    \n    # \u5bf9\u5f53\u524d\u5b58\u6d3b\u7279\u5f81\u6309\u8bc4\u5206\u8fdb\u884c\u6392\u5e8f\uff08\u4ece\u5c0f\u5230\u5927\uff09\n    ranking <- sort(scores, index.return = TRUE)$ix   # \u83b7\u53d6\u6392\u5e8f\u7d22\u5f15\n    if (length(survivingIndices) == 1) {             # \u7279\u5f81\u4ec5\u5269\u4e00\u65f6\n      ranking <- 1                                 # \u8bbe\u7f6e\u7d22\u5f15\u4e3a1\n    }\n    \n    # \u5224\u65ad\u662f\u5426\u9700\u8981\u4e00\u6b21\u6027\u5254\u9664\u591a\u4e2a\u7279\u5f81\uff08\u7279\u5f81\u6570\u5927\u4e8e\u9608\u503c\u65f6\uff09\n    if (length(survivingIndices) > halve.above) {   # \u5982\u679c\u5b58\u6d3b\u7279\u5f81\u6570\u91cf\u5927\u4e8e\u9608\u503c\n      numFeatures <- length(survivingIndices)        # \u5f53\u524d\u5b58\u6d3b\u7279\u5f81\u6570\n      numToCut <- round(numFeatures / 2)             # \u4e00\u6b21\u5254\u9664\u4e00\u534a\u7279\u5f81\n      cat(\"\u5f53\u524d\u7279\u5f81\u6570:\", numFeatures, \"\uff0c\u5254\u9664\", numToCut, \"\u4e2a\u7279\u5f81...\\n\")  # \u63d0\u793a\u5254\u9664\u4fe1\u606f\n      # \u91cd\u8bbe\u8fdb\u5ea6\u6761\u8303\u56f4\n      pb <- txtProgressBar(min = 1, max = numFeatures - numToCut, style = 3)\n    } else {\n      numToCut <- 1                                # \u5426\u5219\u6bcf\u6b21\u5254\u9664\u4e00\u4e2a\u7279\u5f81\n    }\n    \n    # \u5c06\u5254\u9664\u7684\u7279\u5f81\u4fdd\u5b58\u81f3\u6392\u540d\u5217\u8868\u4e2d\n    rankedFeatures[rankingPosition:(rankingPosition - numToCut + 1)] <- \n      survivingIndices[ranking[1:numToCut]]\n    rankingPosition <- rankingPosition - numToCut   # \u66f4\u65b0\u6392\u540d\u4f4d\u7f6e\n    survivingIndices <- survivingIndices[-ranking[1:numToCut]]  # \u79fb\u9664\u5df2\u5254\u9664\u7279\u5f81\n    \n    # \u66f4\u65b0\u5e76\u663e\u793a\u8fdb\u5ea6\u6761\n    setTxtProgressBar(pb, length(survivingIndices))  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u663e\u793a\n    flush.console()                                # \u5237\u65b0\u63a7\u5236\u53f0\n  }\n  \n  # \u5173\u95ed\u8fdb\u5ea6\u6761\n  close(pb)                                          # \u7ed3\u675f\u8fdb\u5ea6\u6761\u663e\u793a\n  \n  # \u8fd4\u56de\u7279\u5f81\u7684\u6392\u540d\u7ed3\u679c\n  return(rankedFeatures)                             # \u8fd4\u56de\u6700\u7ec8\u7279\u5f81\u6392\u540d\u5411\u91cf\n}\n\n# \u5305\u88c5SVM-RFE\u7b97\u6cd5\u7684\u51fd\u6570\uff0c\u7528\u4e8e\u4ea4\u53c9\u9a8c\u8bc1\u6298\u5185\u7684\u7279\u5f81\u9009\u62e9\nsvmRFE_wrap <- function(test.fold, X, ...) {\n  # \u5206\u79bb\u8bad\u7ec3\u96c6\u4e0e\u6d4b\u8bd5\u96c6\n  trainingData <- X[-test.fold, ]                   # \u8bad\u7ec3\u6570\u636e\n  testingData  <- X[test.fold, ]           ",
"         # \u6d4b\u8bd5\u6570\u636e\n  \n  # \u8c03\u7528svmRFE\u51fd\u6570\u5bf9\u8bad\u7ec3\u96c6\u8fdb\u884c\u7279\u5f81\u6392\u5e8f\n  featuresRanked <- svmRFE(trainingData, ...)\n  \n  # \u8fd4\u56de\u5305\u542b\u7279\u5f81\u6392\u540d\u4ee5\u53ca\u8bad\u7ec3\u96c6\u3001\u6d4b\u8bd5\u96c6\u7684\u884c\u53f7\u4fe1\u606f\u7684\u5217\u8868\n  return(list(feature_ids = featuresRanked,\n              train_ids = row.names(trainingData),\n              test_ids = row.names(testingData)))\n}\n\n# \u5b9a\u4e49\u7279\u5f81\u6392\u5e8f\u7ed3\u679c\u5199\u5165\u51fd\u6570\nWriteFeatures <- function(results, input, save = TRUE, file = 'features_ranked.txt') {\n  # \u5bf9\u5404\u6298\u7684\u7279\u5f81\u6392\u5e8f\u7ed3\u679c\u6c42\u5e73\u5747\u6392\u540d\n  featureID <- sort(apply(sapply(results, function(x) {\n    # \u6b64\u5904\u589e\u52a0\u5197\u4f59\u5224\u65ad\uff0c\u9632\u6b62\u51fa\u73b0\u7a7a\u6570\u636e\n    if(is.null(x$feature)) return(rep(NA, ncol(input) - 1))\n    sort(x$feature, index.return = TRUE)$ix\n  }), 1, mean, na.rm = TRUE), index.return = TRUE)$ix\n  avgRank <- sort(apply(sapply(results, function(x) {\n    if(is.null(x$feature)) return(rep(NA, ncol(input) - 1))\n    sort(x$feature, index.return = TRUE)$ix\n  }), 1, mean, na.rm = TRUE), index.return = TRUE)$x\n  \n  # \u83b7\u53d6\u7279\u5f81\u540d\u79f0\uff08\u6392\u9664\u7b2c\u4e00\u5217\u5206\u7ec4\u4fe1\u606f\uff09\n  featureNames <- colnames(input[, -1])[featureID]\n  # \u6784\u5efa\u6570\u636e\u6846\u5b58\u50a8\u6392\u5e8f\u7ed3\u679c\n  featuresRanked <- data.frame(FeatureName = featureNames,\n                               FeatureID = featureID,\n                               AvgRank = avgRank)\n  # \u6839\u636esave\u53c2\u6570\u51b3\u5b9a\u662f\u5426\u5199\u5165\u6587\u4ef6\n  if (save) {\n    write.table(featuresRanked, file = file, quote = FALSE, row.names = FALSE)\n  } else {\n    return(featuresRanked)\n  }\n}\n\n# \u5b9a\u4e49\u6cdb\u5316\u8bef\u5dee\u9a8c\u8bc1\u51fd\u6570\uff0c\u5bf9\u7ed9\u5b9a\u7279\u5f81\u6570\u91cf\u8fdb\u884c\u8bc4\u4f30\nFeatSweep_wrap <- function(i, results, input) {\n  # \u5bf9\u6bcf\u4e2a\u4ea4\u53c9\u9a8c\u8bc1\u6298\u8fdb\u884cSVM\u8c03\u4f18\uff0c\u5e76\u83b7\u53d6\u6a21\u578b\u6027\u80fd\n  svmList <- lapply(results, function(x) {\n    # \u4f7f\u7528tune\u51fd\u6570\u5bfb\u627e\u6700\u4f18\u8d85\u53c2\u6570\uff0c\u5305\u542bgamma\u4e0ecost\u7684\u641c\u7d22\n    tuned <- tune(svm,\n                  train.x = input[x$train_ids, 1 + x$feature_ids[1:i]],\n                  train.y = input[x$train_ids, 1],\n                  ranges = list(gamma = 2^(-12:0), cost = 2^(-6:6)),\n                  tunecontrol = tune.control(sampling = \"fix\"))\n    # \u91cd\u65b0\u7528\u6700\u4f18\u53c2\u6570\u8fdb\u884c\u6a21\u578b\u9a8c\u8bc1\n    model_perf <- tune(svm,\n                       train.x = inp",
"ut[x$train_ids, 1 + x$feature_ids[1:i]],\n                       train.y = input[x$train_ids, 1],\n                       validation.x = input[x$test_ids, 1 + x$feature_ids[1:i]],\n                       validation.y = input[x$test_ids, 1],\n                       ranges = tuned$best.parameters,\n                       tunecontrol = tune.control(sampling = \"fix\"))$perf\n    return(model_perf)\n  })\n  # \u8ba1\u7b97\u6240\u6709\u6298\u7684\u5e73\u5747\u9519\u8bef\u7387\n  errorMean <- mean(sapply(svmList, function(perf) perf$error))\n  return(list(svm_list = svmList, error = errorMean))\n}\n\n# \u5305\u88c5\u6cdb\u5316\u8bef\u5dee\u9a8c\u8bc1\u51fd\u6570\uff0c\u589e\u52a0\u8fdb\u5ea6\u6761\u548c\u5269\u4f59\u65f6\u95f4\u4f30\u7b97\nFeatSweep_wrap_progress <- function(i, results, input) {\n  startTime <- Sys.time()                           # \u8bb0\u5f55\u5f00\u59cb\u65f6\u95f4\n  # \u6267\u884c\u6cdb\u5316\u8bef\u5dee\u8bc4\u4f30\n  result <- FeatSweep_wrap(i, results, input)\n  elapsedTime <- as.numeric(Sys.time() - startTime, units = \"secs\")  # \u8ba1\u7b97\u5df2\u7528\u65f6\u95f4\n  \n  # \u4f30\u7b97\u5269\u4f59\u65f6\u95f4\uff08\u5047\u8bbe\u8bc4\u4f30\u603b\u517125\u4e2a\u7279\u5f81\uff09\n  remainingTime <- if (i > 0) elapsedTime * (25 - i) / i else NA\n  # \u8f93\u51fa\u5f53\u524d\u8fdb\u5ea6\u4fe1\u606f\n  cat(sprintf(\"\u5df2\u5b8c\u6210\u7279\u5f81\u6570\uff1a%d/25, \u8017\u65f6\uff1a%.2f\u79d2, \u9884\u8ba1\u5269\u4f59\u65f6\u95f4\uff1a%.2f\u79d2\\n\",\n              i, elapsedTime, remainingTime))\n  return(result)\n}\n\n# \u5b9a\u4e49\u7ed8\u56fe\u51fd\u6570\uff0c\u7ed8\u5236\u6cdb\u5316\u8bef\u5dee\u66f2\u7ebf\n# \u53c2\u6570 optimal_n: \u53ef\u9009\uff0c\u6307\u5b9a\u6700\u4f18\u7279\u5f81\u6570\u91cf\uff0c\u786e\u4fdd\u4e0e\u51c6\u786e\u7387\u56fe\u4e00\u81f4\nPlotErrors <- function(errors, errors2 = NULL, no.info = 0.5,\n                       ylim = range(c(errors, errors2), na.rm = TRUE),\n                       xlab = 'Number of Features', ylab = '10 x CV Error',\n                       optimal_n = NULL) {\n  oldPar <- par(mar = c(5, 5, 4, 5), xpd = TRUE)    # \u4fdd\u5b58\u539f\u59cb\u56fe\u5f62\u53c2\u6570\n\n  # \u5185\u90e8\u51fd\u6570\uff0c\u6dfb\u52a0\u6570\u636e\u66f2\u7ebf\u4e0e\u6807\u8bb0\n  AddLine <- function(x, col = '#4B4453', opt_n = NULL) {\n    lines(which(!is.na(x)), na.omit(x), col = col, lwd = 3)  # \u7ed8\u5236\u66f2\u7ebf\n    # \u5982\u679c\u63d0\u4f9b\u4e86\u6700\u4f18\u7279\u5f81\u6570\uff0c\u4f7f\u7528\u5b83\uff1b\u5426\u5219\u81ea\u52a8\u8ba1\u7b97\n    x_min <- if (!is.null(opt_n)) opt_n else which.min(x)\n    y_min <- x[x_min]                               # \u83b7\u53d6\u5bf9\u5e94\u7684\u9519\u8bef\u7387\n    points(x_min, y_min, col = '#C34A36', pch = 19, cex = 1.5)  # \u6807\u8bb0\u6700\u5c0f\u503c\n    text(x_min, y_min,",
" labels = paste0(\"n=\", x_min, \"\\n(\", sprintf(\"%.4f\", y_min), \")\"),\n         pos = 2, col = 'darkred', cex = 1.2, font = 2)  # \u6dfb\u52a0\u6587\u5b57\u8bf4\u660e\n  }\n\n  # \u7ed8\u5236\u7a7a\u56fe\u6846\n  plot(errors, type = 'n', ylim = ylim, xlab = xlab, ylab = ylab,\n       main = \"Generalization Error vs Number of Features\",\n       col.main = \"darkblue\", col.lab = \"darkblue\", cex.lab = 1.2, cex.axis = 1.1)\n  grid(col = \"lightgray\", lty = \"dotted\")          # \u6dfb\u52a0\u7f51\u683c\u7ebf\n  AddLine(errors, opt_n = optimal_n)               # \u7ed8\u5236\u9519\u8bef\u7387\u66f2\u7ebf\n  if (!is.null(errors2)) {                         # \u5982\u679c\u6709\u7b2c\u4e8c\u7ec4\u9519\u8bef\u7387\u6570\u636e\n    AddLine(errors2, col = 'forestgreen')           # \u7ed8\u5236\u7b2c\u4e8c\u6761\u66f2\u7ebf\n  }\n  abline(h = no.info, lty = 2, col = 'darkgray')     # \u6dfb\u52a0\u65e0\u4fe1\u606f\u5224\u522b\u7ebf\n  on.exit(par(oldPar))                              # \u6062\u590d\u539f\u59cb\u56fe\u5f62\u53c2\u6570\n}\n\n# \u5b9a\u4e49\u7ed8\u56fe\u51fd\u6570\uff0c\u7ed8\u5236\u51c6\u786e\u7387\u66f2\u7ebf\uff08\u51c6\u786e\u7387 = 1 - \u9519\u8bef\u7387\uff09\n# \u53c2\u6570 optimal_n: \u53ef\u9009\uff0c\u6307\u5b9a\u6700\u4f18\u7279\u5f81\u6570\u91cf\uff0c\u786e\u4fdd\u4e0e\u9519\u8bef\u7387\u56fe\u4e00\u81f4\nPlotAccuracy <- function(accuracy, accuracy2 = NULL, no.info = 0.5,\n                         ylim = range(c(accuracy, accuracy2), na.rm = TRUE),\n                         xlab = 'Number of Features', ylab = '10 x CV Accuracy',\n                         optimal_n = NULL) {\n  oldPar <- par(mar = c(5, 5, 4, 5), xpd = TRUE)    # \u4fdd\u5b58\u539f\u59cb\u56fe\u5f62\u53c2\u6570\n\n  # \u5185\u90e8\u51fd\u6570\uff0c\u6dfb\u52a0\u6570\u636e\u66f2\u7ebf\u4e0e\u6807\u8bb0\n  AddLine <- function(x, col = '#4B4453', opt_n = NULL) {\n    lines(which(!is.na(x)), na.omit(x), col = col, lwd = 3)  # \u7ed8\u5236\u66f2\u7ebf\n    # \u5982\u679c\u63d0\u4f9b\u4e86\u6700\u4f18\u7279\u5f81\u6570\uff0c\u4f7f\u7528\u5b83\uff1b\u5426\u5219\u81ea\u52a8\u8ba1\u7b97\n    x_max <- if (!is.null(opt_n)) opt_n else which.max(x)\n    y_max <- x[x_max]                               # \u83b7\u53d6\u5bf9\u5e94\u7684\u51c6\u786e\u7387\u503c\n    points(x_max, y_max, col = 'gold', pch = 19, cex = 1.5)  # \u6807\u8bb0\u6700\u9ad8\u503c\n    text(x_max, y_max, labels = paste0(\"n=\", x_max, \"\\n(\", sprintf(\"%.4f\", y_max), \")\"),\n         pos = 4, offset = 1, col = 'darkred', cex = 1.2, font = 2)  # \u6dfb\u52a0\u6587\u5b57\u8bf4\u660e\n  }\n\n  # \u7ed8\u5236\u7a7a\u56fe\u6846\n  plot(accuracy, type = 'n', ylim = ylim, xlab = xlab, ylab = ylab,\n       main = \"CV Accuracy vs Number of Fea",
"tures\",\n       col.main = \"darkblue\", col.lab = \"darkblue\", cex.lab = 1.2, cex.axis = 1.1)\n  grid(col = \"lightgray\", lty = \"dotted\")          # \u6dfb\u52a0\u7f51\u683c\u7ebf\n  AddLine(accuracy, opt_n = optimal_n)             # \u7ed8\u5236\u51c6\u786e\u7387\u66f2\u7ebf\n  if (!is.null(accuracy2)) {                       # \u5982\u679c\u6709\u7b2c\u4e8c\u7ec4\u6570\u636e\n    AddLine(accuracy2, col = 'forestgreen')         # \u7ed8\u5236\u7b2c\u4e8c\u6761\u66f2\u7ebf\n  }\n  abline(h = no.info, lty = 2, col = 'darkgray')     # \u6dfb\u52a0\u65e0\u4fe1\u606f\u5224\u522b\u7ebf\n  on.exit(par(oldPar))                              # \u6062\u590d\u539f\u59cb\u56fe\u5f62\u53c2\u6570\n}\n\n# ---------------------- \u6570\u636e\u8bfb\u53d6\u4e0e\u9884\u5904\u7406 ----------------------\n\n# \u8bfb\u53d6\u8f93\u5165\u6570\u636e\u6587\u4ef6\uff0c\u6ce8\u610f\u68c0\u67e5\u5206\u9694\u7b26\u548c\u6587\u4ef6\u683c\u5f0f\nmessage(\"\u8bfb\u53d6\u57fa\u56e0\u8868\u8fbe\u6570\u636e...\")\ndata <- read.csv(inputFile, header = TRUE, check.names = FALSE, row.names = 1)  # \u8bfb\u53d6CSV\u6587\u4ef6\n\n# \u5224\u65ad\u6570\u636e\u662f\u5426\u4e3a\u7a7a\uff0c\u82e5\u4e3a\u7a7a\u5219\u62a5\u9519\nif (nrow(data) == 0) {\n  stop(\"\u6570\u636e\u4e3a\u7a7a\uff0c\u8bf7\u68c0\u67e5\u8f93\u5165\u6587\u4ef6\u5185\u5bb9\uff01\")\n}\n\nmessage(sprintf(\"\u539f\u59cb\u6570\u636e\uff1a%d \u4e2a\u57fa\u56e0\uff0c%d \u4e2a\u6837\u672c\", nrow(data), ncol(data)))\n\n# \u7b5b\u9009\u6307\u5b9a\u7684\u57fa\u56e0\nmessage(\"\u7b5b\u9009\u6307\u5b9a\u7684\u57fa\u56e0...\")\n# \u83b7\u53d6\u6570\u636e\u4e2d\u5b58\u5728\u7684\u57fa\u56e0\uff08\u884c\u540d\u4e2d\u5b58\u5728\u7684\u57fa\u56e0\uff09\navailableGenes <- intersect(geneList, rownames(data))\nmessage(sprintf(\"\u5728\u8868\u8fbe\u6570\u636e\u4e2d\u627e\u5230 %d \u4e2a\u57fa\u56e0\", length(availableGenes)))\n\nif (length(availableGenes) == 0) {\n  stop(\"\u6307\u5b9a\u7684\u57fa\u56e0\u5217\u8868\u4e2d\u6ca1\u6709\u5728\u8868\u8fbe\u6570\u636e\u4e2d\u627e\u5230\u7684\u57fa\u56e0\uff01\u8bf7\u68c0\u67e5\u57fa\u56e0\u540d\u79f0\u662f\u5426\u5339\u914d\u3002\")\n}\n\n# \u53ea\u4fdd\u7559\u6307\u5b9a\u7684\u57fa\u56e0\ndata <- data[availableGenes, , drop = FALSE]\nmessage(sprintf(\"\u7b5b\u9009\u540e\u6570\u636e\uff1a%d \u4e2a\u57fa\u56e0\uff0c%d \u4e2a\u6837\u672c\", nrow(data), ncol(data)))\n\n# \u8f6c\u7f6e\u6570\u636e\uff0c\u4f7f\u6837\u672c\u4e3a\u884c\uff0c\u57fa\u56e0\u4e3a\u5217\ndata <- as.data.frame(t(data))                      # \u8f6c\u7f6e\u6570\u636e\n\n# \u63d0\u53d6\u6837\u672c\u5206\u7ec4\u4fe1\u606f\uff08\u4ece\u884c\u540d\u4e2d\u63d0\u53d6\uff0c\u683c\u5f0f\u4e3a\"\u6837\u672c_\u7ec4\u522b\"\uff09\nmessage(\"\u63d0\u53d6\u6837\u672c\u5206\u7ec4\u4fe1\u606f...\")\ngroup <- rownames(data)\n# \u5c1d\u8bd5\u4ece\u884c\u540d\u4e2d\u63d0\u53d6\u7ec4\u522b\u4fe1\u606f\uff08\u5047\u8bbe\u683c\u5f0f\u4e3a\"\u6837\u672c_\u7ec4\u522b\"\uff09\ngroup <- gsub(\"(.*)\\\\_(.*)\", \"\\\\2\", group)\n\n# \u68c0\u67e5\u662f\u5426\u6210\u529f\u63d0\u53d6\u7ec4\u522b\u4fe1\u606f\nuniqueGroups <- unique(group)\nmessage(sprintf(\"\u68c0\u6d4b\u5230 %d \u4e2a\u5206\u7ec4\uff1a%s\", length(uniqueGroups), paste(uniqueGroups, collapse = \", \")))\n\n# \u5c06\u5206\u7ec4\u4fe1\u606f\u6dfb\u52a0\u5230\u6570\u636e\u4e2d\uff0c\u5e76\u8f6c\u6362\u4e3a\u56e0\u5b50\u7c7b\u578b\ndata <- cbind(group, data)                          # \u5408\u5e76\u5206\u7ec4\u4fe1\u606f\ncolnames(data)[1] <- \"group\"                        # \u8bbe\u7f6e\u7b2c\u4e00\u5217\u5217\u540d\n\n# \u5c1d\u8bd5\u81ea\u52a8\u8bc6\u522b\u5206\u7ec4\u6807\u7b7e\uff0c\u5982\u679c\u65e0\u6cd5\u8bc6\u522b\u5219\u4f7f\u7528\u539f\u59cb\u6807\u7b7e\nif (length(uniqueGroups) == 2) {\n  # \u5982\u679c\u6709\u4e24\u4e2a\u5206\u7ec4\uff0c\u5c1d\u8bd5\u8bc6\u522b\u5bf9\u7167\u7ec4\u548c\u5904\u7406\u7ec4\n  if (\"con\" %in% uniqueGroup",
"s && \"tre\" %in% uniqueGroups) {\n    data$group <- factor(data$group, levels = c(\"con\", \"tre\"))\n    message(\"\u5206\u7ec4\u6807\u7b7e\uff1a\u5bf9\u7167\u7ec4(con) vs \u5904\u7406\u7ec4(tre)\")\n  } else if (\"control\" %in% tolower(uniqueGroups) || \"normal\" %in% tolower(uniqueGroups)) {\n    # \u5982\u679c\u5305\u542bcontrol\u6216normal\uff0c\u5c06\u5176\u4f5c\u4e3a\u7b2c\u4e00\u4e2a\u6c34\u5e73\n    controlLabel <- uniqueGroups[grep(\"control|normal\", tolower(uniqueGroups))][1]\n    treatmentLabel <- setdiff(uniqueGroups, controlLabel)\n    data$group <- factor(data$group, levels = c(controlLabel, treatmentLabel))\n    message(sprintf(\"\u5206\u7ec4\u6807\u7b7e\uff1a%s vs %s\", controlLabel, treatmentLabel))\n  } else {\n    # \u5426\u5219\u6309\u5b57\u6bcd\u987a\u5e8f\u6392\u5217\n    data$group <- factor(data$group, levels = sort(uniqueGroups))\n    message(sprintf(\"\u5206\u7ec4\u6807\u7b7e\uff1a%s\", paste(sort(uniqueGroups), collapse = \" vs \")))\n  }\n} else {\n  data$group <- factor(data$group)\n  message(sprintf(\"\u8b66\u544a\uff1a\u68c0\u6d4b\u5230 %d \u4e2a\u5206\u7ec4\uff0cSVM-RFE \u6700\u9002\u5408\u4e8c\u5206\u7c7b\u95ee\u9898\", length(uniqueGroups)))\n}\n\n# ---------------------- \u8fd0\u884c SVM-RFE \u5e76\u83b7\u53d6\u7ed3\u679c ----------------------\n\n# \u6267\u884cSVM-RFE\u7b97\u6cd5\u8fdb\u884c\u7279\u5f81\u9009\u62e9\uff0c\u53c2\u6570\uff1a\u591a\u91cd\u6298\u6570k=10\uff0c\u7279\u5f81\u6570\u9608\u503c\u8bbe\u4e3a50\nmessage(\"\u6267\u884cSVM-RFE\u7279\u5f81\u9009\u62e9...\")\nsvmRFE(data, k = 10, halve.above = 50)              # \u8c03\u7528SVM-RFE\u51fd\u6570\n\n# \u8bbe\u7f6e10\u6298\u4ea4\u53c9\u9a8c\u8bc1\u53c2\u6570\nnfold <- 10                                         # \u5b9a\u4e49\u4ea4\u53c9\u9a8c\u8bc1\u6298\u6570\u4e3a10\nnumSamples <- nrow(data)                            # \u6837\u672c\u603b\u6570\n\n# \u968f\u673a\u751f\u6210\u4ea4\u53c9\u9a8c\u8bc1\u6298\u7d22\u5f15\uff0c\u5e76\u5206\u7ec4\nfolds <- rep(1:nfold, length.out = numSamples)      # \u751f\u6210\u6298\u53f7\u5411\u91cf\nfolds <- sample(folds)                              # \u6253\u4e71\u6298\u53f7\u987a\u5e8f\nfoldsList <- lapply(1:nfold, function(x) which(folds == x))  # \u5206\u7ec4\u5b58\u50a8\n\n# \u5728\u6bcf\u4e2a\u4ea4\u53c9\u9a8c\u8bc1\u6298\u4e0a\u8fd0\u884cSVM-RFE\uff0c\u5e76\u4fdd\u5b58\u7ed3\u679c\u5230\u5217\u8868\u4e2d\nmessage(\"\u5728\u4ea4\u53c9\u9a8c\u8bc1\u6298\u4e0a\u8fd0\u884cSVM-RFE...\")\nresults <- lapply(foldsList, svmRFE_wrap, data, k = 10, halve.above = 50)  # \u8ba1\u7b97\u6bcf\u4e2a\u6298\u7684\u7279\u5f81\u6392\u5e8f\n\n# \u4fdd\u5b58\u91cd\u8981\u7279\u5f81\u7684\u6392\u5e8f\u7ed3\u679c\u5230\u53d8\u91cf\nmessage(\"\u6574\u7406\u7279\u5f81\u6392\u5e8f\u7ed3\u679c...\")\ntopFeatures <- WriteFeatures(results, data, save = FALSE)  # \u83b7\u53d6\u7279\u5f81\u6392\u5e8f\u6570\u636e\nwrite.table(topFeatures, file = \"feature_svm.txt\", sep = \"\\t\", quote = FALSE, row.names = FALSE)  # \u5199\u5165\u6587\u4ef6\nmessage(\"\u7279\u5f81\u6392\u5e8f\u7ed3\u679c\u5df2\u4fdd\u5b58\u5230 feature_svm.tx",
"t\")\n\n# ---------------------- \u6cdb\u5316\u8bef\u5dee\u9a8c\u8bc1\u4e0e\u8fdb\u5ea6\u6761\u663e\u793a ----------------------\n\n# \u786e\u5b9a\u8981\u8bc4\u4f30\u7684\u6700\u5927\u7279\u5f81\u6570\uff08\u4e0d\u8d85\u8fc7\u603b\u7279\u5f81\u6570\uff09\nmaxFeatures <- min(25, ncol(data) - 1)              # \u6700\u591a\u8bc4\u4f3025\u4e2a\u7279\u5f81\u6216\u6240\u6709\u7279\u5f81\nmessage(sprintf(\"\u5c06\u8bc4\u4f30\u524d %d \u4e2a\u7279\u5f81\u7684\u6027\u80fd...\", maxFeatures))\n\n# \u5bf9\u524dN\u4e2a\u7279\u5f81\u8fdb\u884c\u6cdb\u5316\u8bef\u5dee\u9a8c\u8bc1\uff0c\u4f7f\u7528\u8fdb\u5ea6\u6761\u5c55\u793a\u8fdb\u5ea6\u548c\u5269\u4f59\u65f6\u95f4\u4f30\u8ba1\nprogressBar <- txtProgressBar(min = 1, max = maxFeatures, style = 3)  # \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\nfeatSweep <- lapply(1:maxFeatures, function(i) {\n  res <- FeatSweep_wrap_progress(i, results, data)  # \u8c03\u7528\u6cdb\u5316\u8bef\u5dee\u9a8c\u8bc1\u51fd\u6570\n  setTxtProgressBar(progressBar, i)                 # \u66f4\u65b0\u8fdb\u5ea6\u6761\n  return(res)                                       # \u8fd4\u56de\u5f53\u524d\u7ed3\u679c\n})\nclose(progressBar)                                  # \u5173\u95ed\u8fdb\u5ea6\u6761\n\n# \u8ba1\u7b97\u6570\u636e\u4e2d\u6700\u5c0f\u7684\u5206\u5e03\u6bd4\u4f8b\uff0c\u4f5c\u4e3a\u65e0\u4fe1\u606f\u5224\u522b\u7ebf\nno.info <- min(prop.table(table(data[, 1])))         # \u8ba1\u7b97\u65e0\u4fe1\u606f\u9519\u8bef\u7387\n\n# \u8ba1\u7b97\u6bcf\u4e2a\u7279\u5f81\u6570\u91cf\u5bf9\u5e94\u7684\u5e73\u5747\u6cdb\u5316\u9519\u8bef\u7387\nerrors <- sapply(featSweep, function(x) ifelse(is.null(x), NA, x$error))  # \u8ba1\u7b97\u5e73\u5747\u9519\u8bef\u7387\n\n# ---------------------- \u6700\u4f18\u7279\u5f81\u9009\u62e9 ----------------------\n\n# \u6839\u636e\u9519\u8bef\u7387\u6700\u5c0f\u7684\u7279\u5f81\u6570\u91cf\u9009\u62e9\u6700\u4f18\u7279\u5f81\uff08\u5728\u7ed8\u56fe\u524d\u8ba1\u7b97\uff0c\u786e\u4fdd\u4e24\u56fe\u4e00\u81f4\uff09\nmessage(\"\u786e\u5b9a\u6700\u4f18\u7279\u5f81...\")\noptimalFeatureCount <- which.min(errors)            # \u83b7\u53d6\u9519\u8bef\u7387\u6700\u5c0f\u65f6\u5bf9\u5e94\u7684\u7279\u5f81\u6570\noptimalError <- min(errors, na.rm = TRUE)          # \u83b7\u53d6\u6700\u5c0f\u9519\u8bef\u7387\noptimalAccuracy <- 1 - optimalError                # \u8ba1\u7b97\u6700\u4f18\u51c6\u786e\u7387\n\n# ---------------------- \u7ed8\u56fe\u8f93\u51fa ----------------------\n\n# \u7ed8\u5236\u6cdb\u5316\u9519\u8bef\u7387\u66f2\u7ebf\u56fe\uff0c\u5e76\u4fdd\u5b58\u4e3aPDF\u6587\u4ef6\nmessage(\"\u751f\u6210\u6cdb\u5316\u9519\u8bef\u7387\u66f2\u7ebf\u56fe...\")\npdf(file = \"errors.pdf\", width = 5, height = 5)      # \u6253\u5f00PDF\u8bbe\u5907\nPlotErrors(errors, no.info = no.info, optimal_n = optimalFeatureCount)  # \u8c03\u7528\u7ed8\u56fe\u51fd\u6570\u7ed8\u5236\u9519\u8bef\u7387\u56fe\ndev.off()                                           # \u5173\u95edPDF\u8bbe\u5907\nmessage(\"\u9519\u8bef\u7387\u56fe\u5df2\u4fdd\u5b58\u5230 errors.pdf\")\n\n# \u7ed8\u5236\u4ea4\u53c9\u9a8c\u8bc1\u51c6\u786e\u7387\u66f2\u7ebf\u56fe\uff08\u51c6\u786e\u7387 = 1 - \u9519\u8bef\u7387\uff09\uff0c\u4fdd\u5b58\u4e3aPDF\u6587\u4ef6\nmessage(\"\u751f\u6210\u4ea4\u53c9\u9a8c\u8bc1\u51c6\u786e\u7387\u66f2\u7ebf\u56fe...\")\npdf(file = \"accuracy.pdf\", width = 5, height = 5)      # \u6253\u5f00PDF\u8bbe\u5907\nPlotAccuracy(1 - errors, no.info = no.info, optimal_n = optimalFeatureCount)  # \u8c03\u7528\u7ed8\u56fe\u51fd\u6570\u7ed8\u5236\u51c6\u786e\u7387\u56fe\ndev.off()                                           # \u5173\u95edPDF\u8bbe\u5907\nmessage(\"\u51c6\u786e\u7387\u56fe\u5df2\u4fdd\u5b58\u5230 accuracy.pdf\")\n\n# \u5c06\u9519\u8bef\u7387\u548c\u51c6\u786e\u7387\u56fe",
"\u5408\u5e76\u663e\u793a\uff0c\u5e76\u4fdd\u5b58\u4e3aPDF\u6587\u4ef6\nmessage(\"\u751f\u6210\u5408\u5e76\u56fe\u8868...\")\npdf(file = \"combined_plots.pdf\", width = 10, height = 5)  # \u6253\u5f00PDF\u8bbe\u5907\uff0c\u8bbe\u7f6e\u591a\u56fe\u5e03\u5c40\npar(mfrow = c(1, 2))                                # \u8bbe\u7f6e\u4e24\u56fe\u5e76\u6392\u663e\u793a\nPlotErrors(errors, no.info = no.info, optimal_n = optimalFeatureCount)  # \u7ed8\u5236\u9519\u8bef\u7387\u56fe\uff0c\u4f7f\u7528\u7edf\u4e00\u7684\u6700\u4f18\u7279\u5f81\u6570\nPlotAccuracy(1 - errors, no.info = no.info, optimal_n = optimalFeatureCount)  # \u7ed8\u5236\u51c6\u786e\u7387\u56fe\uff0c\u4f7f\u7528\u7edf\u4e00\u7684\u6700\u4f18\u7279\u5f81\u6570\ndev.off()                                           # \u5173\u95edPDF\u8bbe\u5907\nmessage(\"\u5408\u5e76\u56fe\u8868\u5df2\u4fdd\u5b58\u5230 combined_plots.pdf\")\n\nmessage(sprintf(\"\u6700\u4f18\u7279\u5f81\u6570\u91cf\uff1a%d\", optimalFeatureCount))\nmessage(sprintf(\"\u6700\u5c0f\u9519\u8bef\u7387\uff1a%.4f\", optimalError))\nmessage(sprintf(\"\u6700\u9ad8\u51c6\u786e\u7387\uff1a%.4f\", optimalAccuracy))\n\nfeatureGenes <- topFeatures[1:optimalFeatureCount, 1, drop = FALSE]  # \u9009\u62e9\u6700\u4f18\u7279\u5f81\n\n# \u5c06\u6700\u4f18\u7279\u5f81\u5199\u5165\u6587\u672c\u6587\u4ef6\uff0c\u4e0d\u542b\u5217\u540d\u548c\u884c\u53f7\nwrite.table(featureGenes, file = \"SVM-RFE.gene.txt\", sep = \"\\t\",\n            quote = FALSE, row.names = FALSE, col.names = FALSE)  # \u5199\u5165\u6700\u4f18\u7279\u5f81\u6587\u4ef6\nmessage(\"\u6700\u4f18\u7279\u5f81\u57fa\u56e0\u5df2\u4fdd\u5b58\u5230 SVM-RFE.gene.txt\")\n\n# \u8f93\u51fa\u5168\u90e8\u6b65\u9aa4\u5b8c\u6210\u63d0\u793a\ncat(\"========================================\\n\")\ncat(\"\u6240\u6709\u6b65\u9aa4\u6267\u884c\u5b8c\u6bd5\uff0c\u7ed3\u679c\u6587\u4ef6\u5df2\u4fdd\u5b58\uff01\\n\")\ncat(\"========================================\\n\")\ncat(sprintf(\"\u8f93\u5165\u57fa\u56e0\u6570\uff1a%d\\n\", length(geneList)))\ncat(sprintf(\"\u6700\u7ec8\u5206\u6790\u57fa\u56e0\u6570\uff1a%d\\n\", ncol(data) - 1))\ncat(sprintf(\"\u6837\u672c\u603b\u6570\uff1a%d\\n\", nrow(data)))\ncat(sprintf(\"\u6700\u4f18\u7279\u5f81\u6570\uff1a%d\\n\", optimalFeatureCount))\ncat(sprintf(\"\u6700\u5c0f\u9519\u8bef\u7387\uff1a%.4f\\n\", optimalError))\ncat(sprintf(\"\u6700\u9ad8\u51c6\u786e\u7387\uff1a%.4f\\n\", optimalAccuracy))\ncat(\"========================================\\n\")\ncat(\"\u8f93\u51fa\u6587\u4ef6\uff1a\\n\")\ncat(\"  - feature_svm.txt\uff1a\u6240\u6709\u7279\u5f81\u7684\u6392\u540d\u7ed3\u679c\\n\")\ncat(\"  - SVM-RFE.gene.txt\uff1a\u6700\u4f18\u7279\u5f81\u57fa\u56e0\u5217\u8868\\n\")\ncat(\"  - errors.pdf\uff1a\u6cdb\u5316\u9519\u8bef\u7387\u66f2\u7ebf\\n\")\ncat(\"  - accuracy.pdf\uff1a\u4ea4\u53c9\u9a8c\u8bc1\u51c6\u786e\u7387\u66f2\u7ebf\\n\")\ncat(\"  - combined_plots.pdf\uff1a\u9519\u8bef\u7387\u548c\u51c6\u786e\u7387\u5408\u5e76\u56fe\\n\")\ncat(\"========================================\\n\")\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n"),
"bulk/11.marching learning/16.\u968f\u673a\u751f\u6210\u6811/\u7f8e\u5316.R"=paste0("############################################################\n## \u968f\u673a\u68ee\u6797 RF \u7ed3\u679c\u53ea\u7f8e\u5316\u51fa\u56fe\u7248\n## \u4e0d\u91cd\u65b0\u8fd0\u884c randomForest\n## \u4e0d\u6539\u53d8 Top_RF_Genes.txt \u548c All_Gene_Scores.txt \u7684\u7ed3\u679c\n##\n## \u4f7f\u7528\u5bf9\u8c61\u6216\u6587\u4ef6\uff1a\n## 1. geneScores \u6216 All_Gene_Scores.txt\n## 2. topGenes \u6216 Top_RF_Genes.txt\n##\n## \u8f93\u51fa\uff1a\n## 1. RF_Gene_Importance_Bubble_beauty_original_result.pdf / png\n## 2. RF_Gene_Importance_Lollipop_beauty_original_result.pdf / png\n## 3. RF_Top10_Gene_Importance_Barplot_beauty_original_result.pdf / png\n############################################################\n\n\n############################################################\n## 1. \u52a0\u8f7d\u7ed8\u56fe\u5305\n############################################################\n\nplot_packages <- c(\n  \"ggplot2\",\n  \"dplyr\",\n  \"ggrepel\",\n  \"scales\"\n)\n\nfor (pkg in plot_packages) {\n  if (!requireNamespace(pkg, quietly = TRUE)) {\n    install.packages(pkg, dependencies = TRUE)\n  }\n  library(pkg, character.only = TRUE)\n}\n\n\n############################################################\n## 2. \u8bfb\u53d6\u539f\u59cb\u968f\u673a\u68ee\u6797\u7ed3\u679c\n## \u4e0d\u91cd\u65b0\u8bad\u7ec3\u6a21\u578b\uff0c\u4e0d\u91cd\u65b0\u8ba1\u7b97\u91cd\u8981\u6027\n############################################################\n\nif (!exists(\"geneScores\")) {\n  if (file.exists(\"All_Gene_Scores.txt\")) {\n    geneScores <- read.table(\n      \"All_Gene_Scores.txt\",\n      header = TRUE,\n      sep = \"\\t\",\n      stringsAsFactors = FALSE,\n      check.names = FALSE\n    )\n  } else {\n    stop(\"\u672a\u627e\u5230 geneScores \u5bf9\u8c61\uff0c\u4e5f\u672a\u627e\u5230 All_Gene_Scores.txt\u3002\u8bf7\u5148\u8fd0\u884c\u539f\u59cb\u968f\u673a\u68ee\u6797\u4ee3\u7801\u3002\")\n  }\n}\n\nif (!exists(\"topGenes\")) {\n  if (file.exists(\"Top_RF_Genes.txt\")) {\n    topGenes <- read.table(\n      \"Top_RF_Genes.txt\",\n      header = FALSE,\n      sep = \"\\t\",\n      stringsAsFactors = FALSE,\n      check.names = FALSE\n    )[, 1]\n  } else {\n    warning(\"\u672a\u627e\u5230 topGenes \u5bf9\u8c61\uff0c\u4e5f\u672a\u627e\u5230 Top_RF_Genes.txt\u3002\u5c06\u4ec5\u6839\u636e All_Gene_Scores.txt \u6392\u5e8f\u7ed8\u56fe\u3002\")\n    topGenes <- geneScores$Gene[1:min(10, nrow(geneScores))]\n  }\n}\n\ngeneScores <- geneScores %>%\n ",
" dplyr::filter(\n    !is.na(Gene),\n    !is.na(Importance)\n  ) %>%\n  dplyr::arrange(desc(Importance))\n\ntopGenes <- as.character(topGenes)\ntopGenes <- topGenes[topGenes != \"\"]\n\n# \u4fdd\u5b58\u4e00\u4efd\u7ed8\u56fe\u7528\u6570\u636e\uff0c\u65b9\u4fbf\u4ee5\u540e\u4e0d\u91cd\u65b0\u8dd1\u6a21\u578b\u76f4\u63a5\u753b\u56fe\nwrite.csv(\n  geneScores,\n  file = \"RF_Gene_Importance_plot_data_original_result.csv\",\n  row.names = FALSE\n)\n\n\n############################################################\n## 3. \u8bbe\u7f6e\u7ed8\u56fe\u4e3b\u9898\n############################################################\n\ntheme_rf_beauty <- function(base_size = 14) {\n  theme_classic(base_size = base_size) +\n    theme(\n      plot.title = element_text(\n        face = \"bold\",\n        size = base_size + 2,\n        hjust = 0.5,\n        color = \"black\"\n      ),\n      plot.subtitle = element_text(\n        size = base_size - 1,\n        hjust = 0.5,\n        color = \"grey35\"\n      ),\n      axis.title = element_text(\n        face = \"bold\",\n        size = base_size,\n        color = \"black\"\n      ),\n      axis.text = element_text(\n        color = \"black\",\n        size = base_size - 1\n      ),\n      axis.text.y = element_text(\n        face = \"bold\",\n        color = \"black\"\n      ),\n      axis.line = element_line(\n        linewidth = 0.7,\n        color = \"black\"\n      ),\n      axis.ticks = element_line(\n        linewidth = 0.6,\n        color = \"black\"\n      ),\n      panel.grid.major.x = element_line(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.major.y = element_blank(),\n      panel.grid.minor = element_blank(),\n      legend.position = \"top\",\n      legend.title = element_blank(),\n      legend.text = element_text(size = base_size - 1),\n      plot.caption = element_text(\n        size = base_size - 3,\n        color = \"grey40\",\n        hjust = 0\n      ),\n      plot.margin = margin(10, 20, 10, 10)\n    )\n}\n\n\n##############################",
"##############################\n## 4. \u4fdd\u5b58\u51fd\u6570\uff1a\u540c\u65f6\u4fdd\u5b58 PDF \u548c 600 dpi PNG\n############################################################\n\nsave_rf_plot <- function(p, filename, width = 7, height = 5.5) {\n  \n  ggsave(\n    filename = paste0(filename, \".pdf\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = paste0(filename, \".png\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\",\n    dpi = 600\n  )\n}\n\n\n############################################################\n## 5. \u51c6\u5907\u524d15\u4e2a\u57fa\u56e0\u7528\u4e8e\u5c55\u793a\n############################################################\n\nnTop_show <- min(15, nrow(geneScores))\n\nplot_df <- geneScores[1:nTop_show, , drop = FALSE]\n\nplot_df <- plot_df %>%\n  dplyr::mutate(\n    Rank = dplyr::row_number(),\n    RF_Selected = ifelse(\n      Gene %in% topGenes,\n      \"Top RF genes\",\n      \"Other displayed genes\"\n    )\n  )\n\nplot_df$Gene <- factor(\n  plot_df$Gene,\n  levels = rev(plot_df$Gene)\n)\n\nmax_importance <- max(plot_df$Importance, na.rm = TRUE)\n\n\n############################################################\n## 6. \u7f8e\u5316\u7248\u6c14\u6ce1\u56fe\n############################################################\n\np_bubble <- ggplot(\n  plot_df,\n  aes(\n    x = Importance,\n    y = Gene\n  )\n) +\n  geom_segment(\n    aes(\n      x = 0,\n      xend = Importance,\n      y = Gene,\n      yend = Gene\n    ),\n    linewidth = 1.0,\n    color = \"grey82\"\n  ) +\n  geom_point(\n    aes(\n      size = Importance,\n      fill = RF_Selected\n    ),\n    shape = 21,\n    color = \"black\",\n    stroke = 0.7,\n    alpha = 0.95\n  ) +\n  geom_text(\n    aes(\n      label = paste0(\"#\", Rank)\n    ),\n    x = 0,\n    hjust = 1.1,\n    size = 3.6,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  ggrepel::geom_text_repel(\n    aes(\n      label = sprintf(\"%.3f\", Importance)\n    ),\n    nudge_x = m",
"ax_importance * 0.08,\n    direction = \"y\",\n    hjust = 0,\n    size = 3.5,\n    color = \"black\",\n    segment.color = \"grey60\",\n    min.segment.length = 0,\n    seed = 1993,\n    max.overlaps = Inf\n  ) +\n  scale_fill_manual(\n    values = c(\n      \"Top RF genes\" = \"#D62828\",\n      \"Other displayed genes\" = \"#8D99AE\"\n    )\n  ) +\n  scale_size_continuous(\n    range = c(3.5, 8.5)\n  ) +\n  scale_x_continuous(\n    expand = expansion(mult = c(0.12, 0.22)),\n    breaks = scales::pretty_breaks(n = 6)\n  ) +\n  labs(\n    title = \"Random Forest Gene Importance\",\n    subtitle = paste0(\n      \"Top \",\n      nTop_show,\n      \" genes ranked by MeanDecreaseGini\"\n    ),\n    x = \"MeanDecreaseGini\",\n    y = NULL,\n    caption = \"Gene ranking and importance values are directly derived from the original RF output.\"\n  ) +\n  theme_rf_beauty()\n\nsave_rf_plot(\n  p_bubble,\n  filename = \"RF_Gene_Importance_Bubble_beauty_original_result\",\n  width = 7.3,\n  height = 5.8\n)\n\n\n############################################################\n## 7. \u7f8e\u5316\u7248\u68d2\u68d2\u7cd6\u56fe\n## \u8fd9\u4e2a\u66f4\u9002\u5408SCI\u6b63\u6587\u5c55\u793a\n############################################################\n\np_lollipop <- ggplot(\n  plot_df,\n  aes(\n    x = Importance,\n    y = Gene\n  )\n) +\n  geom_segment(\n    aes(\n      x = 0,\n      xend = Importance,\n      y = Gene,\n      yend = Gene\n    ),\n    linewidth = 1.15,\n    color = \"grey78\"\n  ) +\n  geom_point(\n    aes(\n      fill = RF_Selected\n    ),\n    size = 5.0,\n    shape = 21,\n    color = \"black\",\n    stroke = 0.7\n  ) +\n  geom_text(\n    aes(\n      x = Importance,\n      label = sprintf(\"%.3f\", Importance)\n    ),\n    hjust = -0.18,\n    size = 3.6,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  geom_text(\n    aes(\n      x = 0,\n      label = paste0(\"#\", Rank)\n    ),\n    hjust = 1.1,\n    size = 3.6,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  s",
"cale_fill_manual(\n    values = c(\n      \"Top RF genes\" = \"#D62828\",\n      \"Other displayed genes\" = \"#8D99AE\"\n    )\n  ) +\n  scale_x_continuous(\n    expand = expansion(mult = c(0.12, 0.22)),\n    breaks = scales::pretty_breaks(n = 6)\n  ) +\n  labs(\n    title = \"Top Genes Identified by Random Forest\",\n    subtitle = \"Feature importance ranked by MeanDecreaseGini\",\n    x = \"MeanDecreaseGini\",\n    y = NULL\n  ) +\n  theme_rf_beauty()\n\nsave_rf_plot(\n  p_lollipop,\n  filename = \"RF_Gene_Importance_Lollipop_beauty_original_result\",\n  width = 7.3,\n  height = 5.8\n)\n\n\n############################################################\n## 8. \u7f8e\u5316\u7248Top 10\u67f1\u72b6\u56fe\n## \u4e25\u683c\u4f7f\u7528\u539f\u59cb Top_RF_Genes.txt \u4e2d\u7684\u57fa\u56e0\n############################################################\n\ntop10_df <- geneScores %>%\n  dplyr::filter(Gene %in% topGenes) %>%\n  dplyr::arrange(Importance)\n\n# \u4e3a\u4e86\u4e25\u683c\u6309\u539f\u59cbTop_RF_Genes.txt\u6392\u5e8f\uff0c\u4e5f\u4fdd\u5b58\u539f\u59cb\u6392\u540d\ntop_rank_df <- data.frame(\n  Gene = topGenes,\n  Original_Rank = seq_along(topGenes),\n  stringsAsFactors = FALSE\n)\n\ntop10_df <- top10_df %>%\n  dplyr::left_join(top_rank_df, by = \"Gene\") %>%\n  dplyr::arrange(desc(Importance))\n\ntop10_df$Gene <- factor(\n  top10_df$Gene,\n  levels = rev(top10_df$Gene)\n)\n\np_top10_bar <- ggplot(\n  top10_df,\n  aes(\n    x = Gene,\n    y = Importance\n  )\n) +\n  geom_col(\n    width = 0.72,\n    fill = \"#D62828\",\n    color = \"black\",\n    linewidth = 0.25\n  ) +\n  geom_text(\n    aes(\n      label = sprintf(\"%.3f\", Importance)\n    ),\n    hjust = -0.15,\n    size = 3.6,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  coord_flip(clip = \"off\") +\n  scale_y_continuous(\n    expand = expansion(mult = c(0.02, 0.22)),\n    breaks = scales::pretty_breaks(n = 6)\n  ) +\n  labs(\n    title = \"Top 10 Genes Selected by Random Forest\",\n    subtitle = \"Original RF-selected genes without recalculation\",\n    x = NULL,\n    y =",
" \"MeanDecreaseGini\"\n  ) +\n  theme_rf_beauty() +\n  theme(\n    legend.position = \"none\"\n  )\n\nsave_rf_plot(\n  p_top10_bar,\n  filename = \"RF_Top10_Gene_Importance_Barplot_beauty_original_result\",\n  width = 7.0,\n  height = 5.5\n)\n\n\n############################################################\n## 9. \u5b8c\u6210\u63d0\u793a\n############################################################\n\ncat(\"\\n\")\ncat(\"========================================\\n\")\ncat(\"\u968f\u673a\u68ee\u6797\u56fe\u5f62\u7f8e\u5316\u5b8c\u6210\uff1a\u672a\u91cd\u65b0\u8fd0\u884c randomForest\\n\")\ncat(\"========================================\\n\")\ncat(\"\u539f\u59cbTop RF genes\uff1a\\n\")\nprint(topGenes)\ncat(\"========================================\\n\")\ncat(\"\u65b0\u589e\u8f93\u51fa\u6587\u4ef6\uff1a\\n\")\ncat(\"  1. RF_Gene_Importance_Bubble_beauty_original_result.pdf / png\\n\")\ncat(\"  2. RF_Gene_Importance_Lollipop_beauty_original_result.pdf / png\\n\")\ncat(\"  3. RF_Top10_Gene_Importance_Barplot_beauty_original_result.pdf / png\\n\")\ncat(\"  4. RF_Gene_Importance_plot_data_original_result.csv\\n\")\ncat(\"========================================\\n\")\n\n\n\n\n\n\n\n\n\n############################################################\n## \u968f\u673a\u68ee\u6797 OOB Error \u66f2\u7ebf\u7f8e\u5316\u7248\n## \u4e0d\u91cd\u65b0\u8fd0\u884c randomForest\n## \u4e0d\u6539\u53d8 rfModel / rfOptimized / topGenes \u7684\u7ed3\u679c\n##\n## \u4f7f\u7528\u5bf9\u8c61\uff1a\n## rfModel\n##\n## \u8f93\u51fa\uff1a\n## RF_error_curve_beauty_original_result.pdf\n## RF_error_curve_beauty_original_result.png\n## RF_error_curve_plot_data_original_result.csv\n############################################################\n\n\n############################################################\n## 1. \u52a0\u8f7d\u7ed8\u56fe\u5305\n############################################################\n\nplot_packages <- c(\n  \"ggplot2\",\n  \"dplyr\",\n  \"tidyr\",\n  \"ggrepel\",\n  \"scales\"\n)\n\nfor (pkg in plot_packages) {\n  if (!requireNamespace(pkg, quietly = TRUE)) {\n    install.packages(pkg, dependencies = TRUE)\n  }\n  library(pkg, character.only = TRUE)\n}\n\n\n############################################################\n",
"## 2. \u68c0\u67e5 rfModel \u662f\u5426\u5b58\u5728\n############################################################\n\nif (!exists(\"rfModel\")) {\n  stop(\"\u672a\u627e\u5230 rfModel \u5bf9\u8c61\u3002\u8bf7\u5148\u5b8c\u6574\u8fd0\u884c\u4f60\u7684\u539f\u59cb\u968f\u673a\u68ee\u6797\u4ee3\u7801\u3002\")\n}\n\nif (is.null(rfModel$err.rate)) {\n  stop(\"rfModel \u4e2d\u6ca1\u6709 err.rate \u4fe1\u606f\uff0c\u65e0\u6cd5\u7ed8\u5236 OOB error \u66f2\u7ebf\u3002\")\n}\n\n\n############################################################\n## 3. \u63d0\u53d6\u539f\u59cb OOB error \u6570\u636e\n############################################################\n\nrf_error_df <- as.data.frame(rfModel$err.rate)\n\nrf_error_df$Trees <- seq_len(nrow(rf_error_df))\n\n# \u539f\u59cb randomForest \u7684\u7b2c\u4e00\u5217\u901a\u5e38\u662f OOB\ncolnames(rf_error_df)[1] <- \"Overall OOB error\"\n\n# \u5176\u4ed6\u5217\u4e3a\u5404\u7c7b\u522b OOB error\nif (ncol(rf_error_df) > 2) {\n  old_class_names <- colnames(rf_error_df)[2:(ncol(rf_error_df) - 1)]\n  colnames(rf_error_df)[2:(ncol(rf_error_df) - 1)] <- paste0(old_class_names, \" OOB error\")\n}\n\n# \u4fdd\u5b58\u7ed8\u56fe\u6570\u636e\nwrite.csv(\n  rf_error_df,\n  file = \"RF_error_curve_plot_data_original_result.csv\",\n  row.names = FALSE\n)\n\n# \u8f6c\u6210\u957f\u6570\u636e\u7528\u4e8e ggplot\nrf_error_long <- rf_error_df %>%\n  tidyr::pivot_longer(\n    cols = -Trees,\n    names_to = \"Error_Type\",\n    values_to = \"Error\"\n  )\n\nrf_error_long$Error_Type <- factor(\n  rf_error_long$Error_Type,\n  levels = unique(rf_error_long$Error_Type)\n)\n\n\n############################################################\n## 4. \u786e\u5b9a\u6700\u4f73\u6811\u6570\u91cf\n############################################################\n\n# \u4f18\u5148\u4f7f\u7528\u4f60\u539f\u59cb\u4ee3\u7801\u91cc\u8ba1\u7b97\u51fa\u6765\u7684 bestTreeCount\nif (exists(\"bestTreeCount\")) {\n  best_tree <- bestTreeCount\n} else {\n  best_tree <- which.min(rfModel$err.rate[, 1])\n}\n\nbest_error <- rf_error_df[best_tree, \"Overall OOB error\"]\n\n\n############################################################\n## 5. \u671f\u520a\u98ce\u683c\u4e3b\u9898\n############################################################\n\ntheme_rf_error_beauty <- function(base_size = 14) {\n  theme_classic(base_size = base_size) +\n    theme(\n      plot.title = element_text(\n        face = \"bo",
"ld\",\n        size = base_size + 2,\n        hjust = 0.5,\n        color = \"black\"\n      ),\n      plot.subtitle = element_text(\n        size = base_size - 1,\n        hjust = 0.5,\n        color = \"grey35\"\n      ),\n      axis.title = element_text(\n        face = \"bold\",\n        size = base_size,\n        color = \"black\"\n      ),\n      axis.text = element_text(\n        color = \"black\",\n        size = base_size - 1\n      ),\n      axis.line = element_line(\n        linewidth = 0.7,\n        color = \"black\"\n      ),\n      axis.ticks = element_line(\n        linewidth = 0.6,\n        color = \"black\"\n      ),\n      panel.grid.major = element_line(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      legend.position = \"top\",\n      legend.title = element_blank(),\n      legend.text = element_text(size = base_size - 1),\n      plot.caption = element_text(\n        size = base_size - 3,\n        color = \"grey40\",\n        hjust = 0\n      ),\n      plot.margin = margin(10, 15, 10, 10)\n    )\n}\n\n\n############################################################\n## 6. \u7f8e\u5316\u7ed8\u5236 OOB error \u66f2\u7ebf\n############################################################\n\n# \u6839\u636e\u66f2\u7ebf\u6570\u91cf\u81ea\u52a8\u8bbe\u7f6e\u989c\u8272\nerror_types <- levels(rf_error_long$Error_Type)\n\nmy_cols <- c(\n  \"Overall OOB error\" = \"#111111\",\n  \"con OOB error\" = \"#D62828\",\n  \"tra OOB error\" = \"#2B6CB0\",\n  \"tre OOB error\" = \"#2B6CB0\",\n  \"Control OOB error\" = \"#D62828\",\n  \"Treat OOB error\" = \"#2B6CB0\",\n  \"Normal OOB error\" = \"#D62828\",\n  \"UC OOB error\" = \"#2B6CB0\"\n)\n\n# \u5982\u679c\u7c7b\u522b\u540d\u79f0\u4e0d\u5728\u4e0a\u9762\uff0c\u81ea\u52a8\u8865\u5145\u989c\u8272\nmissing_types <- setdiff(error_types, names(my_cols))\nif (length(missing_types) > 0) {\n  extra_cols <- scales::hue_pal()(length(missing_types))\n  names(extra_cols) <- missing_types\n  my_cols <- c(my_cols, extra_cols)\n}\n\nmy_cols <- my_cols[error_types]\n\np_",
"rf_error <- ggplot(\n  rf_error_long,\n  aes(\n    x = Trees,\n    y = Error,\n    color = Error_Type,\n    linetype = Error_Type\n  )\n) +\n  geom_line(\n    linewidth = 1.05,\n    alpha = 0.95\n  ) +\n  geom_vline(\n    xintercept = best_tree,\n    linetype = \"dashed\",\n    linewidth = 0.8,\n    color = \"#D62828\"\n  ) +\n  geom_point(\n    data = data.frame(\n      Trees = best_tree,\n      Error = best_error,\n      Error_Type = \"Overall OOB error\"\n    ),\n    aes(x = Trees, y = Error),\n    inherit.aes = FALSE,\n    size = 4.0,\n    shape = 21,\n    fill = \"#D62828\",\n    color = \"black\",\n    stroke = 0.8\n  ) +\n  ggrepel::geom_label_repel(\n    data = data.frame(\n      Trees = best_tree,\n      Error = best_error,\n      Label = paste0(\n        \"Selected trees = \",\n        best_tree,\n        \"\\nOOB error = \",\n        sprintf(\"%.2f%%\", 100 * best_error)\n      )\n    ),\n    aes(\n      x = Trees,\n      y = Error,\n      label = Label\n    ),\n    inherit.aes = FALSE,\n    size = 3.8,\n    fontface = \"bold\",\n    fill = \"white\",\n    label.size = 0.35,\n    box.padding = 0.5,\n    point.padding = 0.4,\n    segment.color = \"grey45\",\n    seed = 1993\n  ) +\n  scale_color_manual(values = my_cols) +\n  scale_linetype_manual(\n    values = rep(\n      c(\"solid\", \"dashed\", \"dotted\", \"dotdash\", \"longdash\"),\n      length.out = length(error_types)\n    )\n  ) +\n  scale_x_continuous(\n    breaks = scales::pretty_breaks(n = 8),\n    expand = expansion(mult = c(0.02, 0.05))\n  ) +\n  scale_y_continuous(\n    labels = scales::percent_format(accuracy = 1),\n    breaks = scales::pretty_breaks(n = 6),\n    expand = expansion(mult = c(0.03, 0.08))\n  ) +\n  labs(\n    title = \"Random Forest OOB Error Curve\",\n    subtitle = \"Out-of-bag error changes with the number of trees\",\n    x = \"Number of trees\",\n    y = \"OOB error rate\",\n    caption = \"The",
" vertical dashed line indicates the selected tree number from the original RF analysis.\"\n  ) +\n  theme_rf_error_beauty()\n\nprint(p_rf_error)\n\n\n############################################################\n## 7. \u4fdd\u5b58 PDF \u548c 600 dpi PNG\n############################################################\n\nggsave(\n  filename = \"RF_error_curve_beauty_original_result.pdf\",\n  plot = p_rf_error,\n  width = 7.2,\n  height = 5.6,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"RF_error_curve_beauty_original_result.png\",\n  plot = p_rf_error,\n  width = 7.2,\n  height = 5.6,\n  units = \"in\",\n  dpi = 600\n)\n\n\n############################################################\n## 8. \u5b8c\u6210\u63d0\u793a\n############################################################\n\ncat(\"\\n\")\ncat(\"========================================\\n\")\ncat(\"\u968f\u673a\u68ee\u6797 OOB error \u66f2\u7ebf\u7f8e\u5316\u5b8c\u6210\\n\")\ncat(\"\u672a\u91cd\u65b0\u8fd0\u884c randomForest\uff0c\u672a\u6539\u53d8\u539f\u59cb\u7ed3\u679c\\n\")\ncat(\"========================================\\n\")\ncat(sprintf(\"\u539f\u59cb\u9009\u62e9\u6811\u6570\u91cf\uff1a%d\\n\", best_tree))\ncat(sprintf(\"\u5bf9\u5e94 Overall OOB error\uff1a%.4f\\n\", best_error))\ncat(\"========================================\\n\")\ncat(\"\u65b0\u589e\u8f93\u51fa\u6587\u4ef6\uff1a\\n\")\ncat(\"  1. RF_error_curve_beauty_original_result.pdf\\n\")\ncat(\"  2. RF_error_curve_beauty_original_result.png\\n\")\ncat(\"  3. RF_error_curve_plot_data_original_result.csv\\n\")\ncat(\"========================================\\n\")\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n"),
"bulk/11.marching learning/16.\u968f\u673a\u751f\u6210\u6811/\u968f\u673a\u68ee\u6797\u6a21\u578b\u8bc6\u522b\u57fa\u56e0.R"=paste0("#############################################\n# \u6b64\u4ee3\u7801\u7528\u4e8e\u57fa\u4e8e\u968f\u673a\u68ee\u6797\u5bf9\u57fa\u56e0\u8868\u8fbe\u6570\u636e\u8fdb\u884c\u5206\u6790\n# \u5305\u542b\u6570\u636e\u8bfb\u53d6\u3001\u9884\u5904\u7406\u3001\u6a21\u578b\u6784\u5efa\u3001\u7279\u5f81\u9009\u62e9\u548c\u7ed8\u56fe\u7b49\u6b65\u9aa4\n#############################################\n\n#----------------------------\n# \u7b2c1\u6b65\uff1a\u5b89\u88c5\u548c\u52a0\u8f7d\u5fc5\u8981\u7684R\u5305\n#----------------------------\n\n# \u5224\u65ad\u5305\u662f\u5426\u5df2\u5b89\u88c5\uff0c\u5426\u5219\u5b89\u88c5\u5b83\u4eec\nif (!require(\"randomForest\")) {            # \u68c0\u67e5randomForest\u5305\u662f\u5426\u5b58\u5728\n  install.packages(\"randomForest\")           # \u5982\u679c\u672a\u5b89\u88c5\uff0c\u5219\u5b89\u88c5\u968f\u673a\u68ee\u6797\u5305\n  library(randomForest)                      # \u52a0\u8f7d\u968f\u673a\u68ee\u6797\u5305\n} else {\n  library(randomForest)                      # \u5982\u679c\u5df2\u5b89\u88c5\uff0c\u5219\u76f4\u63a5\u52a0\u8f7d\n}\nif (!require(\"ggplot2\")) {                   # \u68c0\u67e5ggplot2\u5305\u662f\u5426\u5b58\u5728\n  install.packages(\"ggplot2\")                # \u5982\u679c\u672a\u5b89\u88c5\uff0c\u5219\u5b89\u88c5ggplot2\u5305\n  library(ggplot2)                           # \u52a0\u8f7dggplot2\u5305\n} else {\n  library(ggplot2)                           # \u5982\u679c\u5df2\u5b89\u88c5\uff0c\u5219\u76f4\u63a5\u52a0\u8f7d\n}\nif (!require(\"viridis\")) {                   # \u68c0\u67e5viridis\u5305\u662f\u5426\u5b58\u5728\n  install.packages(\"viridis\")                # \u5982\u679c\u672a\u5b89\u88c5\uff0c\u5219\u5b89\u88c5viridis\u5305\n  library(viridis)                           # \u52a0\u8f7dviridis\u5305\n} else {\n  library(viridis)                           # \u5982\u679c\u5df2\u5b89\u88c5\uff0c\u5219\u76f4\u63a5\u52a0\u8f7d\n}\n\n# \u8bbe\u7f6e\u968f\u673a\u79cd\u5b50\u4ee5\u786e\u4fdd\u7ed3\u679c\u7684\u53ef\u91cd\u590d\u6027\nset.seed(2025)  # \u4fee\u6539\u4e86\u79cd\u5b50\u503c\n\n# \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\ntotalSteps <- 10   # \u603b\u517110\u4e2a\u6b65\u9aa4\npb <- txtProgressBar(min = 0, max = totalSteps, style = 3)\nstep <- 0  # \u5f53\u524d\u8fdb\u5ea6\u8ba1\u6570\u5668\n\n#----------------------------\n# \u7b2c2\u6b65\uff1a\u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\u548c\u8bfb\u53d6\u6570\u636e\u6587\u4ef6\n#----------------------------\n\nstep <- step + 1  # \u8fdb\u5ea6\u66f4\u65b0\nsetTxtProgressBar(pb, step)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\n\n# \u6307\u5b9a\u6570\u636e\u6587\u4ef6\u540d\u79f0\uff08\u8bf7\u786e\u8ba4\u6587\u4ef6\u5728\u6307\u5b9a\u8def\u5f84\u4e0b\u5b58\u5728\uff09\ndataFileName <- \"geneexp.csv\"  # \u66f4\u6362\u4e86\u6587\u4ef6\u540d\n# \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\uff08\u8bf7\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u4fee\u6539\u8def\u5f84\uff09\nworkDir <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\11.marching learning\\\\16.\u968f\u673a\u751f\u6210\u6811\"  \nif (dir.exists(workDir)) {               # \u5224\u65ad\u5de5\u4f5c\u76ee\u5f55\u662f\u5426\u5b58\u5728\n  setwd(workDir)                         # \u5982\u679c\u5b58\u5728\uff0c\u5219\u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\n} else {\n  dir.create(workDir, recursive = TRUE)   # \u5982\u679c\u4e0d\u5b58\u5728\uff0c\u5219\u521b\u5efa\u76ee\u5f55\n  setwd(workDir)\n}\n\n# \u5224\u65ad\u6570\u636e\u6587\u4ef6\u662f\u5426\u5b58\u5728\uff0c\u82e5\u4e0d\u5b58\u5728\u5219\u7ec8\u6b62\u6267\u884c\nif (!file.exists(dataFileName)) {\n  stop(\"\u6570\u636e\u6587\u4ef6\u4e0d\u5b58\u5728\uff0c\u8bf7\u68c0\u67e5\u6587\u4ef6\u540d\u6216\u8def\u5f84\uff01\")  # \u8f93\u51fa\u9519\u8bef\u63d0\u793a\u5e76\u505c\u6b62\u7a0b\u5e8f\n}\n\n# \u8bfb\u53d6\u6570\u636e\u6587\u4ef6\uff08\u5047\u8bbeCSV\u6587\u4ef6\uff0c\u5e26\u6807",
"\u9898\uff0c\u7b2c\u4e00\u5217\u4e3a\u884c\u540d\uff09\nrawData <- read.table(dataFileName, header = TRUE, sep = \",\", \n                      check.names = FALSE, row.names = 1)\n# \u590d\u5236\u4e00\u4efd\u6570\u636e\u7528\u4e8e\u5197\u4f59\u5907\u4efd\uff08\u5197\u4f59\u4ee3\u7801\uff0c\u4fbf\u4e8e\u540e\u7eed\u6bd4\u8f83\uff09\nbackupData <- rawData\n\n#----------------------------\n# \u7b2c3\u6b65\uff1a\u6570\u636e\u9884\u5904\u7406\n#----------------------------\n\nstep <- step + 1  # \u66f4\u65b0\u8fdb\u5ea6\u6761\nsetTxtProgressBar(pb, step)\n\n# \u8f6c\u7f6e\u6570\u636e\uff0c\u4f7f\u6bcf\u884c\u4ee3\u8868\u4e00\u4e2a\u6837\u672c\uff0c\u6bcf\u5217\u4ee3\u8868\u4e00\u4e2a\u57fa\u56e0\nexprData <- t(rawData)\n\n# \u5224\u65ad\u8f6c\u7f6e\u540e\u6570\u636e\u662f\u5426\u4e3a\u7a7a\nif (nrow(exprData) == 0) {\n  stop(\"\u8f6c\u7f6e\u540e\u7684\u6570\u636e\u4e3a\u7a7a\uff0c\u8bf7\u68c0\u67e5\u8f93\u5165\u6570\u636e\uff01\")\n}\n\n# \u4ece\u6837\u672c\u540d\u79f0\u4e2d\u63d0\u53d6\u7ec4\u522b\u4fe1\u606f\uff0c\u5047\u8bbe\u6837\u672c\u540d\u5f62\u5982 \"sample01_Control\" \u6216 \"sample02_Treat\"\nsampleLabels <- row.names(exprData)\n# \u4f7f\u7528\u6b63\u5219\u8868\u8fbe\u5f0f\u63d0\u53d6\u4e0b\u5212\u7ebf\u540e\u7684\u90e8\u5206\u4f5c\u4e3a\u7ec4\u522b\ngroupInfo <- gsub(\".*_(.*)$\", \"\\\\1\", sampleLabels)\n# \u5982\u679c\u63d0\u53d6\u7ed3\u679c\u4e2d\u5b58\u5728NA\u6216\u7a7a\u5b57\u7b26\uff0c\u5219\u7528\u9ed8\u8ba4\u503c\u66ff\u4ee3\ngroupInfo[groupInfo == \"\"] <- \"Unknown\"\n# \u5728 Step3 \u6570\u636e\u9884\u5904\u7406\u540e\uff0c\u52a0\u4e0a\u8fd9\u4e00\u884c\ncolnames(exprData) <- make.names(colnames(exprData))\n\n#----------------------------\n# \u7b2c4\u6b65\uff1a\u6784\u5efa\u521d\u59cb\u968f\u673a\u68ee\u6797\u6a21\u578b\n#----------------------------\n\nstep <- step + 1  # \u66f4\u65b0\u8fdb\u5ea6\u6761\nsetTxtProgressBar(pb, step)\n\n# \u6784\u5efa\u521d\u59cb\u968f\u673a\u68ee\u6797\u6a21\u578b\uff1a\u4f7f\u7528\u6240\u6709\u57fa\u56e0\u4f5c\u4e3a\u9884\u6d4b\u53d8\u91cf\uff0cgroupInfo\u4f5c\u4e3a\u54cd\u5e94\u53d8\u91cf\n# \u4f7f\u7528500\u68f5\u6811\u6765\u6784\u5efa\u6a21\u578b\nrfModel <- randomForest(as.factor(groupInfo) ~ ., data = as.data.frame(exprData), ntree = 500)\n\n# \u68c0\u67e5\u6a21\u578b\u8f93\u51fa\u662f\u5426\u6b63\u5e38\nif (is.null(rfModel)) {\n  stop(\"\u968f\u673a\u68ee\u6797\u6a21\u578b\u6784\u5efa\u5931\u8d25\uff0c\u8bf7\u68c0\u67e5\u6570\u636e\u683c\u5f0f\uff01\")\n}\n\n#----------------------------\n# \u7b2c5\u6b65\uff1a\u4fdd\u5b58\u968f\u673a\u68ee\u6797\u6a21\u578b\u9519\u8bef\u7387\u56fe\n#----------------------------\n\nstep <- step + 1  # \u66f4\u65b0\u8fdb\u5ea6\u6761\nsetTxtProgressBar(pb, step)\n\n# \u7ed8\u5236\u5e76\u4fdd\u5b58\u6a21\u578b\u9519\u8bef\u7387\u56fe\u81f3PDF\u6587\u4ef6\npdf(file = \"RF_error_plot.pdf\", width = 6, height = 6)  # \u5f00\u542fPDF\u8bbe\u5907\nplot(rfModel, main = \"Random Forest Error Rate\", lwd = 2, \n     col = c(\"black\", \"red\", \"blue\"), type = \"l\", lty = c(1,2,3))  # \u7ed8\u5236\u9519\u8bef\u7387\u66f2\u7ebf\n# \u6dfb\u52a0\u56fe\u4f8b\u8bf4\u660e\nlegend(\"topright\", legend = c(\"Overall OOB Error\", \"Class 1 OOB Error\", \"Class 2 OOB Error\"),\n       col = c(\"black\", \"red\", \"blue\"), lwd = 2, lty = c(1,2,3), cex = 0.8, box.lwd = 0.5)\ndev.off()  # \u5173\u95edPDF\u8bbe\u5907\uff0c\u4fdd\u5b58\u56fe\u50cf\n\n#----------------------------\n# \u7b2c6\u6b65\uff1a\u786e\u5b9a\u6700\u4f73\u51b3\u7b56\u6811\u6570\u91cf\n#----------------------------\n\nstep <- step + 1  # \u66f4\u65b0\u8fdb\u5ea6\u6761\nsetTxtProgressBar",
"(pb, step)\n\n# \u4ece\u6a21\u578b\u4e2d\u627e\u51fa\u9519\u8bef\u7387\u6700\u4f4e\u65f6\u7684\u6811\u6570\u91cf\nbestTreeCount <- which.min(rfModel$err.rate[, 1])\n# \u5982\u679c\u6700\u4f73\u6811\u6570\u91cf\u5c0f\u4e8e\u67d0\u4e2a\u9608\u503c\uff0c\u5219\u63d0\u793a\u5e76\u8c03\u6574\nif (bestTreeCount < 50) {\n  bestTreeCount <- 50  # \u5f3a\u5236\u6700\u5c11\u4f7f\u752850\u68f5\u6811\n}\n\n# \u8f93\u51fa\u6700\u4f73\u6811\u6570\u91cf\uff08\u6253\u5370\u5230\u63a7\u5236\u53f0\uff09\nprint(paste(\"\u6700\u4f73\u51b3\u7b56\u6811\u6570\u91cf\u4e3a:\", bestTreeCount))\n\n#----------------------------\n# \u7b2c7\u6b65\uff1a\u91cd\u65b0\u8bad\u7ec3\u968f\u673a\u68ee\u6797\u6a21\u578b\n#----------------------------\n\nstep <- step + 1  # \u66f4\u65b0\u8fdb\u5ea6\u6761\nsetTxtProgressBar(pb, step)\n\n# \u4f7f\u7528\u6700\u4f73\u6811\u6570\u91cf\u91cd\u65b0\u8bad\u7ec3\u968f\u673a\u68ee\u6797\u6a21\u578b\nrfOptimized <- randomForest(as.factor(groupInfo) ~ ., data = as.data.frame(exprData), ntree = bestTreeCount)\n\n# \u5224\u65ad\u91cd\u65b0\u8bad\u7ec3\u6a21\u578b\u662f\u5426\u6210\u529f\nif (is.null(rfOptimized)) {\n  stop(\"\u91cd\u65b0\u8bad\u7ec3\u7684\u968f\u673a\u68ee\u6797\u6a21\u578b\u6784\u5efa\u5931\u8d25\uff01\")\n}\n\n##----------------------------\n# \u7b2c8\u6b65\uff1a\u63d0\u53d6\u548c\u7b5b\u9009\u57fa\u56e0\u91cd\u8981\u6027\n#----------------------------\n\nstep <- step + 1  # \u66f4\u65b0\u8fdb\u5ea6\u6761\nsetTxtProgressBar(pb, step)\n\n# \u83b7\u53d6\u6a21\u578b\u4e2d\u6bcf\u4e2a\u53d8\u91cf\u7684\u91cd\u8981\u6027\u8bc4\u5206\nrawImportance <- importance(rfOptimized)\n\n# \u6309\u7167Gini\u6307\u6570\u964d\u5e8f\u6392\u5217\u57fa\u56e0\nif (!is.null(dim(rawImportance))) {\n  # \u5982\u679c\u8fd4\u56de\u7684\u662f\u77e9\u9635\uff0c\u5219\u63d0\u53d6 \"MeanDecreaseGini\" \u5217\n  giniValues <- rawImportance[,\"MeanDecreaseGini\"]\n} else {\n  # \u5982\u679c\u8fd4\u56de\u7684\u662f\u5411\u91cf\uff0c\u5219\u76f4\u63a5\u4f7f\u7528\n  giniValues <- rawImportance\n}\n# \u5bf9\u57fa\u56e0\u6309\u7167\u91cd\u8981\u6027\u8fdb\u884c\u6392\u5e8f\nsortedGini <- sort(giniValues, decreasing = TRUE)\n\n# \u9009\u62e9\u524d10\u4e2a\u6700\u91cd\u8981\u7684\u57fa\u56e0\ntopGenes <- names(sortedGini)[1:10]\n\n# \u5c06\u7b5b\u9009\u51fa\u7684\u7279\u5f81\u57fa\u56e0\u4fdd\u5b58\u5230\u6587\u672c\u6587\u4ef6\u4e2d\nwrite.table(topGenes, file = \"Top_RF_Genes.txt\", sep = \"\\t\", quote = FALSE, col.names = FALSE, row.names = FALSE)\n\n#----------------------------\n# \u7b2c9\u6b65\uff1a\u7ed8\u5236\u57fa\u56e0\u91cd\u8981\u6027\u6c14\u6ce1\u56fe\uff08\u4f7f\u7528ggplot2\u548cviridis\uff09\n#----------------------------\n\nstep <- step + 1  # \u66f4\u65b0\u8fdb\u5ea6\u6761\nsetTxtProgressBar(pb, step)\n\n# \u6784\u9020\u6570\u636e\u6846\u7528\u4e8e\u7ed8\u56fe\uff1a\u8fd9\u91cc\u63d0\u53d6\u6240\u6709\u57fa\u56e0\u53ca\u5176\u91cd\u8981\u6027\nimpDF <- data.frame(Gene = names(sortedGini), \n                    Importance = as.numeric(sortedGini),\n                    stringsAsFactors = FALSE)\n\n# \u4fdd\u7559\u524d15\u4e2a\u57fa\u56e0\u8fdb\u884c\u5c55\u793a\uff08\u5982\u679c\u57fa\u56e0\u6570\u91cf\u4e0d\u8db315\uff0c\u4fdd\u7559\u5168\u90e8\uff09\nnTop <- min(15, nrow(impDF))\nimpDF <- impDF[1:nTop,]\n\n# \u5c06\u57fa\u56e0\u540d\u8f6c\u6362\u4e3a\u56e0\u5b50\uff0c\u5e76\u6309\u91cd\u8981\u6027\u9006\u5e8f\u6392\u5217\nimpDF$Gene <- factor(impDF$Gene, levels = rev(impDF$Gene))\n\n# \u4f7f\u7528ggplot2\u548cviridis\u7ed8\u5236\u6c14\u6ce1\u56fe\np1 <- ggplot(impDF, aes(x = Importance, y = Gene)) +\n  geom_segm",
"ent(aes(x = 0, xend = Importance, y = Gene, yend = Gene), color = \"grey80\", size = 1.2) +\n  geom_point(aes(color = Importance, size = Importance), shape = 21, fill = \"white\", stroke = 1.2) +\n  scale_color_viridis(option = \"plasma\", direction = -1) +\n  scale_size_continuous(range = c(3,7)) +\n  labs(x = \"Importance\", y = \"\", title = \"Gene Importance\") +\n  theme_classic() +\n  theme(axis.text = element_text(size = 12, color = \"black\"),\n        axis.title = element_text(size = 14),\n        plot.title = element_text(hjust = 0.5, size = 16, face = \"bold\"),\n        legend.position = \"right\",\n        legend.title = element_text(size = 12),\n        legend.text = element_text(size = 10))\n\n# \u4fdd\u5b58\u6c14\u6ce1\u56fe\u5230PDF\u6587\u4ef6\npdf(file = \"Gene_Importance_Bubble.pdf\", width = 7, height = 5)\nprint(p1)\ndev.off()\n# \u6784\u5efa\u6240\u6709\u57fa\u56e0\u8bc4\u5206\u7684\u6570\u636e\u6846\ngeneScores <- data.frame(Gene = names(sortedGini), Importance = as.numeric(sortedGini),\n                         stringsAsFactors = FALSE)\n\n# \u5c06\u6240\u6709\u57fa\u56e0\u8bc4\u5206\u8f93\u51fa\u5230\u6587\u672c\u6587\u4ef6\uff08\u4f8b\u5982CSV\u6216\u5236\u8868\u7b26\u5206\u9694\u6587\u4ef6\uff09\nwrite.table(geneScores, file = \"All_Gene_Scores.txt\", sep = \"\\t\", quote = FALSE, row.names = FALSE)\n"),
"bulk/11.marching learning/KNN/\u7f8e\u5316.R"=paste0("############################################################\n## KNN-RFE \u7ed3\u679c\u53ea\u7f8e\u5316\u51fa\u56fe\u7248\n## \u4e0d\u91cd\u65b0\u8fd0\u884c rfe()\n## \u4e0d\u91cd\u65b0\u8fd0\u884c train()\n## \u4e0d\u6539\u53d8 imp_genes_best / KNN_BestModel_Gene_Names.csv\n##\n## \u9700\u8981\u4f60\u539f\u59cb\u4ee3\u7801\u5df2\u7ecf\u751f\u6210\uff1a\n## knnProfile\n## acc_df\n## best_vars\n## imp_genes_best\n## fit_knn_best\n## cm_best\n## X_scaled\n## y\n############################################################\n\n\n############################################################\n## 1. \u52a0\u8f7d\u7f8e\u5316\u7ed8\u56fe\u5305\n############################################################\n\nplot_packages <- c(\n  \"ggplot2\",\n  \"dplyr\",\n  \"tidyr\",\n  \"ggrepel\",\n  \"patchwork\",\n  \"scales\"\n)\n\nfor (pkg in plot_packages) {\n  if (!requireNamespace(pkg, quietly = TRUE)) {\n    install.packages(pkg, dependencies = TRUE)\n  }\n  library(pkg, character.only = TRUE)\n}\n\n\n############################################################\n## 2. \u68c0\u67e5\u539f\u59cb\u7ed3\u679c\u662f\u5426\u5b58\u5728\n############################################################\n\nif (!exists(\"knnProfile\")) {\n  stop(\"\u672a\u627e\u5230 knnProfile \u5bf9\u8c61\u3002\u8bf7\u5148\u5b8c\u6574\u8fd0\u884c\u4f60\u7684\u539f\u59cb KNN-RFE \u4ee3\u7801\u3002\")\n}\n\nif (!exists(\"X_scaled\")) {\n  stop(\"\u672a\u627e\u5230 X_scaled \u5bf9\u8c61\u3002\u8bf7\u5148\u5b8c\u6574\u8fd0\u884c\u4f60\u7684\u539f\u59cb KNN-RFE \u4ee3\u7801\u3002\")\n}\n\nif (!exists(\"y\")) {\n  stop(\"\u672a\u627e\u5230 y \u5bf9\u8c61\u3002\u8bf7\u5148\u5b8c\u6574\u8fd0\u884c\u4f60\u7684\u539f\u59cb KNN-RFE \u4ee3\u7801\u3002\")\n}\n\nif (!exists(\"best_vars\")) {\n  if (!is.null(knnProfile$optsize)) {\n    best_vars <- knnProfile$optsize\n  } else if (file.exists(\"KNN_BestModel_Gene_Names.csv\")) {\n    best_vars <- nrow(read.csv(\"KNN_BestModel_Gene_Names.csv\"))\n  } else {\n    best_vars <- length(predictors(knnProfile))\n  }\n}\n\nif (!exists(\"imp_genes_best\")) {\n  if (file.exists(\"KNN_BestModel_Gene_Names.csv\")) {\n    imp_genes_best <- read.csv(\n      \"KNN_BestModel_Gene_Names.csv\",\n      stringsAsFactors = FALSE,\n      check.names = FALSE\n    )$Gene\n  } else {\n    imp_genes_best <- predictors(knnProfile)[1:best_vars]\n  }\n}\n\nimp_genes_best <- as.character(imp_genes_best)\nimp_genes_best <- imp_genes_best[imp_genes",
"_best != \"\"]\n\nif (!exists(\"acc_df\")) {\n  acc_df <- data.frame(\n    Variables = knnProfile$results$Variables,\n    Accuracy = knnProfile$results$Accuracy\n  )\n  \n  if (\"AccuracySD\" %in% colnames(knnProfile$results)) {\n    acc_df$sd <- knnProfile$results$AccuracySD\n  } else {\n    acc_df$sd <- 0\n  }\n}\n\nif (!\"sd\" %in% colnames(acc_df)) {\n  if (\"AccuracySD\" %in% colnames(knnProfile$results)) {\n    acc_df$sd <- knnProfile$results$AccuracySD\n  } else {\n    acc_df$sd <- 0\n  }\n}\n\nbest_point <- acc_df[acc_df$Variables == best_vars, , drop = FALSE]\n\nif (nrow(best_point) == 0) {\n  best_point <- acc_df[which.max(acc_df$Accuracy), , drop = FALSE]\n}\n\nbest_point <- best_point[1, , drop = FALSE]\n\n\n############################################################\n## 3. \u7edf\u4e00\u5206\u7ec4\u6807\u7b7e\n############################################################\n\ngroup_df <- data.frame(\n  Sample = rownames(X_scaled),\n  Group = as.character(y),\n  stringsAsFactors = FALSE\n)\n\ngroup_df$Group_Label <- ifelse(\n  group_df$Group %in% c(\"0\", 0),\n  \"Control\",\n  \"UC\"\n)\n\ngroup_df$Group_Label <- factor(\n  group_df$Group_Label,\n  levels = c(\"Control\", \"UC\")\n)\n\n\n############################################################\n## 4. \u671f\u520a\u98ce\u683c\u4e3b\u9898\n############################################################\n\ntheme_knn_beauty <- function(base_size = 14) {\n  theme_classic(base_size = base_size) +\n    theme(\n      plot.title = element_text(\n        face = \"bold\",\n        size = base_size + 2,\n        hjust = 0.5,\n        color = \"black\"\n      ),\n      plot.subtitle = element_text(\n        size = base_size - 1,\n        hjust = 0.5,\n        color = \"grey35\"\n      ),\n      axis.title = element_text(\n        face = \"bold\",\n        size = base_size,\n        color = \"black\"\n      ),\n      axis.text = element_text(\n        color = \"black\",\n        size = bas",
"e_size - 1\n      ),\n      axis.line = element_line(\n        linewidth = 0.7,\n        color = \"black\"\n      ),\n      axis.ticks = element_line(\n        linewidth = 0.6,\n        color = \"black\"\n      ),\n      panel.grid.major = element_line(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      legend.position = \"top\",\n      legend.title = element_blank(),\n      legend.text = element_text(size = base_size - 1),\n      strip.background = element_rect(\n        fill = \"grey95\",\n        color = \"black\",\n        linewidth = 0.5\n      ),\n      strip.text = element_text(\n        face = \"bold\",\n        size = base_size - 1,\n        color = \"black\"\n      ),\n      plot.caption = element_text(\n        size = base_size - 3,\n        color = \"grey40\",\n        hjust = 0\n      ),\n      plot.margin = margin(10, 15, 10, 10)\n    )\n}\n\n\n############################################################\n## 5. \u4fdd\u5b58\u51fd\u6570\uff1aPDF + 600 dpi PNG\n############################################################\n\nsave_knn_plot <- function(p, filename, width = 7, height = 5.5) {\n  \n  ggsave(\n    filename = paste0(filename, \".pdf\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = paste0(filename, \".png\"),\n    plot = p,\n    width = width,\n    height = height,\n    units = \"in\",\n    dpi = 600\n  )\n}\n\n\n############################################################\n## 6. \u7f8e\u5316 KNN-RFE \u53d8\u91cf\u6570-\u51c6\u786e\u7387\u66f2\u7ebf\n############################################################\n\nacc_df_plot <- acc_df %>%\n  dplyr::mutate(\n    ymin = pmax(0, Accuracy - sd),\n    ymax = pmin(1, Accuracy + sd)\n  )\n\nbest_label <- paste0(\n  \"Best subset\\n\",\n  best_point$Variables,\n  \" genes\\nAccuracy = \",\n  sprintf(\"%.3f\", best_point$Accuracy)\n)\n\np_acc <- ggplot(\n  acc_df_p",
"lot,\n  aes(x = Variables, y = Accuracy)\n) +\n  geom_ribbon(\n    aes(ymin = ymin, ymax = ymax),\n    fill = \"#BDD7E7\",\n    alpha = 0.35\n  ) +\n  geom_line(\n    linewidth = 1.25,\n    color = \"#2B6CB0\"\n  ) +\n  geom_point(\n    size = 3.2,\n    shape = 21,\n    fill = \"white\",\n    color = \"#2B6CB0\",\n    stroke = 0.9\n  ) +\n  geom_point(\n    data = best_point,\n    aes(x = Variables, y = Accuracy),\n    size = 5,\n    shape = 21,\n    fill = \"#D62828\",\n    color = \"black\",\n    stroke = 0.9\n  ) +\n  geom_vline(\n    xintercept = best_point$Variables,\n    linetype = \"dashed\",\n    linewidth = 0.75,\n    color = \"#D62828\"\n  ) +\n  geom_text(\n    aes(label = sprintf(\"%.3f\", Accuracy)),\n    vjust = -1.1,\n    size = 3.8,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  ggrepel::geom_label_repel(\n    data = best_point,\n    aes(\n      x = Variables,\n      y = Accuracy,\n      label = best_label\n    ),\n    size = 4,\n    fontface = \"bold\",\n    fill = \"white\",\n    label.size = 0.35,\n    box.padding = 0.5,\n    point.padding = 0.4,\n    segment.color = \"grey45\",\n    seed = 1993\n  ) +\n  scale_x_continuous(\n    breaks = acc_df_plot$Variables,\n    expand = expansion(mult = c(0.05, 0.08))\n  ) +\n  scale_y_continuous(\n    labels = scales::percent_format(accuracy = 1),\n    limits = c(\n      max(0.5, min(acc_df_plot$ymin, na.rm = TRUE) - 0.03),\n      min(1, max(acc_df_plot$ymax, na.rm = TRUE) + 0.04)\n    ),\n    breaks = scales::pretty_breaks(n = 6)\n  ) +\n  labs(\n    title = \"KNN-RFE Model Performance\",\n    subtitle = \"Cross-validated accuracy across different feature subset sizes\",\n    x = \"Number of selected features\",\n    y = \"Cross-validated accuracy\",\n    caption = \"The red point indicates the original best feature subset.\"\n  ) +\n  theme_knn_beauty()\n\nsave_knn_plot(\n  p_acc,\n  filename = \"KNN_RFE_Accuracy_C",
"urve_Beauty_original_result\",\n  width = 7.2,\n  height = 5.6\n)\n\n\n############################################################\n## 7. \u589e\u52a0 Kappa + Accuracy \u53cc\u6307\u6807\u56fe\n############################################################\n\nperf_df <- knnProfile$results %>%\n  dplyr::select(\n    Variables,\n    Accuracy,\n    Kappa\n  ) %>%\n  tidyr::pivot_longer(\n    cols = c(\"Accuracy\", \"Kappa\"),\n    names_to = \"Metric\",\n    values_to = \"Value\"\n  )\n\np_perf <- ggplot(\n  perf_df,\n  aes(\n    x = Variables,\n    y = Value,\n    color = Metric,\n    shape = Metric\n  )\n) +\n  geom_line(\n    linewidth = 1.15\n  ) +\n  geom_point(\n    size = 3.2,\n    stroke = 0.9\n  ) +\n  geom_vline(\n    xintercept = best_vars,\n    linetype = \"dashed\",\n    linewidth = 0.75,\n    color = \"#D62828\"\n  ) +\n  scale_color_manual(\n    values = c(\n      \"Accuracy\" = \"#2B6CB0\",\n      \"Kappa\" = \"#D62828\"\n    )\n  ) +\n  scale_x_continuous(\n    breaks = sort(unique(perf_df$Variables))\n  ) +\n  scale_y_continuous(\n    limits = c(0, 1),\n    labels = scales::percent_format(accuracy = 1),\n    breaks = scales::pretty_breaks(n = 6)\n  ) +\n  labs(\n    title = \"KNN-RFE Accuracy and Kappa\",\n    subtitle = \"Performance comparison across feature subset sizes\",\n    x = \"Number of selected features\",\n    y = \"Performance metric\"\n  ) +\n  theme_knn_beauty()\n\nsave_knn_plot(\n  p_perf,\n  filename = \"KNN_RFE_Accuracy_Kappa_Curve_Beauty_original_result\",\n  width = 7.2,\n  height = 5.6\n)\n\n\n############################################################\n## 8. \u65b0\u589e\uff1a\u6700\u4f73\u57fa\u56e0\u6392\u5e8f\u56fe\n## \u4e25\u683c\u4f7f\u7528\u539f\u59cb imp_genes_best\uff0c\u4e0d\u91cd\u65b0\u7b5b\u9009\n############################################################\n\ngene_rank_df <- data.frame(\n  Gene = imp_genes_best,\n  Rank = seq_along(imp_genes_best),\n  stringsAsFactors = FALSE\n)\n\n# \u5982\u679c knnProfile$variables \u4e2d\u6709\u53d8\u91cf\u91cd\u8981\u6027\uff0c\u5219\u5c3d\u91cf\u63d0\u53d6\u5e73\u5747\u5f97\u5206\nrank_score_df <- NULL\n\nif (\"variables\" %in% nam",
"es(knnProfile)) {\n  \n  var_tbl <- knnProfile$variables\n  \n  if (!is.null(var_tbl) && nrow(var_tbl) > 0) {\n    \n    gene_col <- intersect(c(\"var\", \"Variable\", \"variables\", \"Gene\"), colnames(var_tbl))[1]\n    score_col <- intersect(c(\"Overall\", \"Accuracy\", \"ROC\", \"importance\"), colnames(var_tbl))[1]\n    \n    if (!is.na(gene_col) && !is.na(score_col)) {\n      \n      var_tbl_sub <- var_tbl\n      \n      if (\"Variables\" %in% colnames(var_tbl_sub)) {\n        var_tbl_sub <- var_tbl_sub[var_tbl_sub$Variables == best_vars, , drop = FALSE]\n      }\n      \n      rank_score_df <- var_tbl_sub %>%\n        dplyr::group_by(.data[[gene_col]]) %>%\n        dplyr::summarise(\n          RFE_Score = mean(.data[[score_col]], na.rm = TRUE),\n          .groups = \"drop\"\n        )\n      \n      colnames(rank_score_df)[1] <- \"Gene\"\n    }\n  }\n}\n\nif (!is.null(rank_score_df)) {\n  gene_rank_df <- gene_rank_df %>%\n    dplyr::left_join(rank_score_df, by = \"Gene\")\n}\n\nif (!\"RFE_Score\" %in% colnames(gene_rank_df) || all(is.na(gene_rank_df$RFE_Score))) {\n  gene_rank_df$RFE_Score <- rev(seq_len(nrow(gene_rank_df)))\n}\n\ngene_rank_df$Gene <- factor(\n  gene_rank_df$Gene,\n  levels = rev(gene_rank_df$Gene)\n)\n\np_gene_rank <- ggplot(\n  gene_rank_df,\n  aes(\n    x = Gene,\n    y = RFE_Score\n  )\n) +\n  geom_col(\n    width = 0.72,\n    fill = \"#D62828\",\n    color = \"black\",\n    linewidth = 0.25\n  ) +\n  geom_text(\n    aes(label = paste0(\"#\", Rank)),\n    hjust = -0.15,\n    size = 3.8,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  coord_flip(clip = \"off\") +\n  scale_y_continuous(\n    expand = expansion(mult = c(0.02, 0.20)),\n    breaks = scales::pretty_breaks(n = 6)\n  ) +\n  labs(\n    title = \"Top Genes Selected by KNN-RFE\",\n    subtitle = paste0(\n      \"Original selected feature subset: \",\n      length(imp_genes_best),\n      \" ",
"genes\"\n    ),\n    x = NULL,\n    y = \"Relative RFE ranking score\"\n  ) +\n  theme_knn_beauty() +\n  theme(\n    legend.position = \"none\",\n    axis.text.y = element_text(face = \"bold\")\n  )\n\nsave_knn_plot(\n  p_gene_rank,\n  filename = \"KNN_Selected_Gene_Ranking_Beauty_original_result\",\n  width = 7.0,\n  height = 5.8\n)\n\nwrite.csv(\n  gene_rank_df,\n  file = \"KNN_Selected_Gene_Ranking_Data_original_result.csv\",\n  row.names = FALSE\n)\n\n\n############################################################\n## 9. \u7f8e\u5316\u6700\u4f73\u57fa\u56e0\u8868\u8fbe\u7bb1\u7ebf\u56fe + \u5c0f\u63d0\u7434\u56fe\n############################################################\n\nexpr_sub_best <- as.data.frame(\n  X_scaled[, imp_genes_best, drop = FALSE]\n)\n\nexpr_sub_best$Group <- group_df$Group_Label\n\nexpr_long_best <- expr_sub_best %>%\n  tidyr::pivot_longer(\n    cols = -Group,\n    names_to = \"Gene\",\n    values_to = \"Expression\"\n  )\n\nexpr_long_best$Gene <- factor(\n  expr_long_best$Gene,\n  levels = imp_genes_best\n)\n\np_box_violin <- ggplot(\n  expr_long_best,\n  aes(\n    x = Group,\n    y = Expression,\n    fill = Group\n  )\n) +\n  geom_violin(\n    trim = FALSE,\n    alpha = 0.65,\n    color = NA\n  ) +\n  geom_boxplot(\n    width = 0.18,\n    outlier.shape = NA,\n    alpha = 0.95,\n    color = \"black\",\n    linewidth = 0.4\n  ) +\n  geom_jitter(\n    aes(color = Group),\n    width = 0.13,\n    size = 0.8,\n    alpha = 0.45\n  ) +\n  facet_wrap(\n    ~ Gene,\n    scales = \"free_y\",\n    ncol = 2\n  ) +\n  scale_fill_manual(\n    values = c(\n      \"Control\" = \"#2B6CB0\",\n      \"UC\" = \"#D62828\"\n    )\n  ) +\n  scale_color_manual(\n    values = c(\n      \"Control\" = \"#2B6CB0\",\n      \"UC\" = \"#D62828\"\n    )\n  ) +\n  labs(\n    title = \"Expression Patterns of KNN-RFE Selected Genes\",\n    subtitle = \"Scaled expression values of the original selected genes\",\n    x = NULL,\n    y = \"Scaled expression\"\n  ) +\n  theme_knn_beauty() +\n",
"  theme(\n    legend.position = \"top\",\n    strip.text = element_text(face = \"bold\")\n  )\n\nsave_knn_plot(\n  p_box_violin,\n  filename = \"KNN_Selected_Gene_BoxViolin_Beauty_original_result\",\n  width = 8.5,\n  height = max(6, ceiling(length(imp_genes_best) / 2) * 2.2)\n)\n\n\n############################################################\n## 10. \u7f8e\u5316 PCA \u56fe\n############################################################\n\npca_res <- prcomp(\n  X_scaled[, imp_genes_best, drop = FALSE],\n  scale. = TRUE\n)\n\npca_var <- (pca_res$sdev^2) / sum(pca_res$sdev^2)\n\npca_df <- data.frame(\n  PC1 = pca_res$x[, 1],\n  PC2 = pca_res$x[, 2],\n  Group = group_df$Group_Label,\n  Sample = rownames(X_scaled),\n  stringsAsFactors = FALSE\n)\n\np_pca <- ggplot(\n  pca_df,\n  aes(\n    x = PC1,\n    y = PC2,\n    color = Group,\n    fill = Group\n  )\n) +\n  stat_ellipse(\n    geom = \"polygon\",\n    alpha = 0.15,\n    color = NA,\n    level = 0.95\n  ) +\n  stat_ellipse(\n    linewidth = 0.8,\n    level = 0.95\n  ) +\n  geom_point(\n    size = 3.0,\n    alpha = 0.88,\n    shape = 21,\n    color = \"black\",\n    stroke = 0.35\n  ) +\n  scale_fill_manual(\n    values = c(\n      \"Control\" = \"#2B6CB0\",\n      \"UC\" = \"#D62828\"\n    )\n  ) +\n  scale_color_manual(\n    values = c(\n      \"Control\" = \"#2B6CB0\",\n      \"UC\" = \"#D62828\"\n    )\n  ) +\n  labs(\n    title = \"PCA Based on KNN-RFE Selected Genes\",\n    subtitle = paste0(\n      \"Feature number = \",\n      length(imp_genes_best)\n    ),\n    x = paste0(\n      \"PC1 (\",\n      sprintf(\"%.1f\", 100 * pca_var[1]),\n      \"%)\"\n    ),\n    y = paste0(\n      \"PC2 (\",\n      sprintf(\"%.1f\", 100 * pca_var[2]),\n      \"%)\"\n    )\n  ) +\n  theme_knn_beauty()\n\nsave_knn_plot(\n  p_pca,\n  filename = \"KNN_Selected_Gene_PCA_Beauty_original_result\",\n  width = 6.5,\n  height = 5.6\n)\n\n\n#########################################################",
"###\n## 11. \u7f8e\u5316\u6df7\u6dc6\u77e9\u9635\u70ed\u56fe\n############################################################\n\nif (!exists(\"cm_best\")) {\n  if (!exists(\"pred_best\")) {\n    stop(\"\u672a\u627e\u5230 cm_best \u6216 pred_best\uff0c\u65e0\u6cd5\u7ed8\u5236\u6df7\u6dc6\u77e9\u9635\u56fe\u3002\")\n  }\n  cm_best <- caret::confusionMatrix(pred_best, y)\n}\n\ncm_df_best <- as.data.frame(cm_best$table)\n\ncm_df_best$Reference_Label <- ifelse(\n  as.character(cm_df_best$Reference) %in% c(\"0\", 0),\n  \"Control\",\n  \"UC\"\n)\n\ncm_df_best$Prediction_Label <- ifelse(\n  as.character(cm_df_best$Prediction) %in% c(\"0\", 0),\n  \"Control\",\n  \"UC\"\n)\n\ncm_df_best$Reference_Label <- factor(\n  cm_df_best$Reference_Label,\n  levels = c(\"Control\", \"UC\")\n)\n\ncm_df_best$Prediction_Label <- factor(\n  cm_df_best$Prediction_Label,\n  levels = c(\"Control\", \"UC\")\n)\n\np_cm <- ggplot(\n  cm_df_best,\n  aes(\n    x = Reference_Label,\n    y = Prediction_Label,\n    fill = Freq\n  )\n) +\n  geom_tile(\n    color = \"white\",\n    linewidth = 1.2\n  ) +\n  geom_text(\n    aes(label = Freq),\n    size = 7,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  scale_fill_gradient(\n    low = \"#F1F5F9\",\n    high = \"#D62828\"\n  ) +\n  labs(\n    title = \"Confusion Matrix of the KNN Model\",\n    subtitle = paste0(\n      \"Accuracy = \",\n      sprintf(\"%.1f%%\", 100 * cm_best$overall[\"Accuracy\"]),\n      \"; Kappa = \",\n      sprintf(\"%.3f\", cm_best$overall[\"Kappa\"])\n    ),\n    x = \"Reference\",\n    y = \"Prediction\",\n    fill = \"Count\"\n  ) +\n  theme_knn_beauty() +\n  theme(\n    panel.grid = element_blank(),\n    legend.position = \"right\"\n  )\n\nsave_knn_plot(\n  p_cm,\n  filename = \"KNN_ConfusionMatrix_Heatmap_Beauty_original_result\",\n  width = 5.8,\n  height = 5.4\n)\n\n\n############################################################\n## 12. \u65b0\u589e\uff1a\u6a21\u578b\u6027\u80fd\u6307\u6807\u67f1\u72b6\u56fe\n############################################################\n\nmetric_df <- data.frame(\n  Metric = c(\n    \"Accuracy\",\n    \"Kappa\"",
",\n    \"Sensitivity\",\n    \"Specificity\",\n    \"Balanced Accuracy\"\n  ),\n  Value = c(\n    as.numeric(cm_best$overall[\"Accuracy\"]),\n    as.numeric(cm_best$overall[\"Kappa\"]),\n    as.numeric(cm_best$byClass[\"Sensitivity\"]),\n    as.numeric(cm_best$byClass[\"Specificity\"]),\n    as.numeric(cm_best$byClass[\"Balanced Accuracy\"])\n  )\n)\n\nmetric_df$Metric <- factor(\n  metric_df$Metric,\n  levels = metric_df$Metric\n)\n\np_metric <- ggplot(\n  metric_df,\n  aes(\n    x = Metric,\n    y = Value\n  )\n) +\n  geom_col(\n    width = 0.68,\n    fill = \"#2B6CB0\",\n    color = \"black\",\n    linewidth = 0.25\n  ) +\n  geom_text(\n    aes(label = sprintf(\"%.3f\", Value)),\n    vjust = -0.45,\n    size = 4.0,\n    fontface = \"bold\"\n  ) +\n  scale_y_continuous(\n    limits = c(0, 1.08),\n    labels = scales::percent_format(accuracy = 1),\n    breaks = seq(0, 1, 0.2)\n  ) +\n  labs(\n    title = \"Performance Metrics of the KNN Model\",\n    subtitle = \"Calculated from the original best KNN model\",\n    x = NULL,\n    y = \"Metric value\"\n  ) +\n  theme_knn_beauty() +\n  theme(\n    axis.text.x = element_text(\n      angle = 30,\n      hjust = 1,\n      face = \"bold\"\n    )\n  )\n\nsave_knn_plot(\n  p_metric,\n  filename = \"KNN_Performance_Metrics_Barplot_Beauty_original_result\",\n  width = 6.8,\n  height = 5.4\n)\n\n\n############################################################\n## 13. \u5408\u5e76\u4e3b\u56fe\uff1a\u51c6\u786e\u7387\u66f2\u7ebf + \u57fa\u56e0\u6392\u5e8f + \u6df7\u6dc6\u77e9\u9635\n############################################################\n\np_main_combined <- (p_acc | p_gene_rank) / p_cm +\n  patchwork::plot_annotation(\n    tag_levels = \"A\",\n    theme = theme(\n      plot.tag = element_text(\n        face = \"bold\",\n        size = 18\n      )\n    )\n  )\n\nsave_knn_plot(\n  p_main_combined,\n  filename = \"KNN_RFE_Main_Figure_Beauty_original_result\",\n  width = 13,\n  height = 10.5\n)\n\n\n################################################",
"############\n## 14. \u4fdd\u5b58\u7ed8\u56fe\u6570\u636e\n############################################################\n\nwrite.csv(\n  acc_df_plot,\n  file = \"KNN_RFE_Accuracy_Curve_Data_original_result.csv\",\n  row.names = FALSE\n)\n\nwrite.csv(\n  expr_long_best,\n  file = \"KNN_Selected_Gene_BoxViolin_Data_original_result.csv\",\n  row.names = FALSE\n)\n\nwrite.csv(\n  pca_df,\n  file = \"KNN_Selected_Gene_PCA_Data_original_result.csv\",\n  row.names = FALSE\n)\n\nwrite.csv(\n  cm_df_best,\n  file = \"KNN_ConfusionMatrix_Data_original_result.csv\",\n  row.names = FALSE\n)\n\nwrite.csv(\n  metric_df,\n  file = \"KNN_Performance_Metrics_Data_original_result.csv\",\n  row.names = FALSE\n)\n\n\n############################################################\n## 15. \u5b8c\u6210\u63d0\u793a\n############################################################\n\ncat(\"\\n\")\ncat(\"========================================\\n\")\ncat(\"KNN-RFE \u56fe\u5f62\u7f8e\u5316\u5b8c\u6210\uff1a\u672a\u91cd\u65b0\u8fd0\u884c rfe() \u6216 train()\\n\")\ncat(\"========================================\\n\")\ncat(sprintf(\"\u539f\u59cb\u6700\u4f73\u7279\u5f81\u6570\uff1a%d\\n\", best_vars))\ncat(\"\u539f\u59cb KNN-RFE \u9009\u62e9\u57fa\u56e0\uff1a\\n\")\nprint(imp_genes_best)\ncat(\"========================================\\n\")\ncat(\"\u65b0\u589e\u8f93\u51fa\u6587\u4ef6\uff1a\\n\")\ncat(\"  1. KNN_RFE_Accuracy_Curve_Beauty_original_result.pdf / png\\n\")\ncat(\"  2. KNN_RFE_Accuracy_Kappa_Curve_Beauty_original_result.pdf / png\\n\")\ncat(\"  3. KNN_Selected_Gene_Ranking_Beauty_original_result.pdf / png\\n\")\ncat(\"  4. KNN_Selected_Gene_BoxViolin_Beauty_original_result.pdf / png\\n\")\ncat(\"  5. KNN_Selected_Gene_PCA_Beauty_original_result.pdf / png\\n\")\ncat(\"  6. KNN_ConfusionMatrix_Heatmap_Beauty_original_result.pdf / png\\n\")\ncat(\"  7. KNN_Performance_Metrics_Barplot_Beauty_original_result.pdf / png\\n\")\ncat(\"  8. KNN_RFE_Main_Figure_Beauty_original_result.pdf / png\\n\")\ncat(\"========================================\\n\")"),
"bulk/11.marching learning/KNN/KNN (K-Nearest Neighbors).R"=paste0("# ======================================\n# \u8bbe\u7f6e\u5de5\u4f5c\u8def\u5f84\nworkDir <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\11.marching learning\\\\KNN\"\nsetwd(workDir)\n\n# ========== \u5fc5\u9700\u5305\u52a0\u8f7d ==========\nlibrary(viridis)\nlibrary(caret)\nlibrary(ggplot2)\nlibrary(reshape2)\n\n# ========== 1. \u8bfb\u5165\u8868\u8fbe\u77e9\u9635\u4e0e\u6807\u51c6\u5316 ==========\ndat <- read.csv(\"geneexp.csv\", header=TRUE, check.names=FALSE, row.names=1)\ndat_t <- t(dat)\nsample_names <- rownames(dat_t)\nY <- ifelse(grepl(\"_con$\", sample_names), 0, ifelse(grepl(\"_tra$\", sample_names), 1, NA))\nstopifnot(sum(is.na(Y)) == 0)\nX <- as.data.frame(dat_t)\ny <- as.factor(Y)\nX_scaled <- as.data.frame(scale(X))\ncolnames(X_scaled) <- make.names(colnames(X_scaled)) # \u7279\u5f81\u540d\u5408\u6cd5\u5316\nstopifnot(all(sapply(X_scaled, is.numeric)))\nstopifnot(nrow(X_scaled) == length(y))\n\n# ========== 2. RFE\u9012\u5f52\u7279\u5f81\u6d88\u9664\uff0cKNN ==========\nset.seed(12345)\nctrl <- rfeControl(functions = lrFuncs, method = \"cv\", number = 5)\nsizes <- c(5, 10, 20, 30, 40)\n\nknnProfile <- rfe(\n  X_scaled, y,\n  sizes = sizes,\n  rfeControl = ctrl,\n  method = \"knn\",\n  tuneGrid = expand.grid(k = 5)\n)\nprint(knnProfile)\n\n\n\n# ========== 4. KNN\u5efa\u6a21\uff08\u91c7\u7528\u6700\u4f73\u7279\u5f81\u6570\u91cf\uff09 ==========\n# \u53d6\u6700\u4f73\u70b9\u7684\u7279\u5f81\u6570\nacc_df <- data.frame(\n  Variables = knnProfile$results$Variables,\n  Accuracy  = knnProfile$results$Accuracy\n)\nif (\"AccuracySD\" %in% colnames(knnProfile$results)) {\n  acc_df$sd <- knnProfile$results$AccuracySD\n} else {\n  acc_df$sd <- 0\n}\n\nbest_idx <- which.max(acc_df$Accuracy)\nbest_point <- acc_df[best_idx, ]\nbest_vars <- best_point$Variables # \u6700\u4f73\u70b9\u7279\u5f81\u6570\n\n# \u63d0\u53d6\u6700\u4f73\u7279\u5f81\u5b50\u96c6\nimp_genes_best <- predictors(knnProfile)[1:best_vars]\n\n# \u6a21\u578b\u8bad\u7ec3\u4e0e\u9884\u6d4b\nset.seed(123)\nfit_knn_best <- train(\n  x = X_scaled[, imp_genes_best, drop=FALSE],\n  y = y,\n  method = \"knn\",\n  tuneGrid = expand.grid(k = 5),\n  trControl = trainControl(method = \"cv\", number = 5)\n)\npred_best <- predict(fit_knn_best, X_scaled[, imp_genes_best, drop=FALS",
"E])\ncm_best <- confusionMatrix(pred_best, y)\nprint(cm_best)\nwrite.csv(data.frame(Sample=rownames(X_scaled),\n                     TrueLabel=y,\n                     PredLabel=pred_best),\n          \"KNN_Sample_Prediction_bestmodel.csv\", row.names=FALSE)\n\n# ========== 5. \u7ed8\u5236 \u53d8\u91cf\u6570-\u51c6\u786e\u7387\u66f2\u7ebf\uff0c\u5e76\u53ea\u6807\u6ce8\u6700\u4f73\u70b9 ==========\nbest_idx <- which.max(acc_df$Accuracy)\nbest_point <- acc_df[best_idx, ]\nbest_label <- paste0(\"Best\\n(\", best_point$Variables, \", \", sprintf(\"%.3f\", best_point$Accuracy), \")\")\n\npdf(\"KNN_NumFeature_Accuracy_BestOnly.pdf\", width=7, height=5)\np <- ggplot(acc_df, aes(x=Variables, y=Accuracy)) +\n  # \u533a\u95f4\u5e26\n  geom_ribbon(aes(ymin=Accuracy-sd, ymax=Accuracy+sd), fill=\"#bdd7e7\", alpha=0.3) +\n  geom_line(size=1.3, color=\"#2171b5\") +\n  geom_point(size=2.5, color=\"#e41a1c\") +\n  # \u7ed9\u6bcf\u4e00\u70b9\u52a0\u6570\u503c\u6807\u7b7e\uff08y\u503c\u5411\u4e0a\u504f\u79fb\u9632\u6b62\u91cd\u53e0\uff09\n  geom_text(aes(label=sprintf(\"%.3f\", Accuracy)),\n            vjust=-1, color=\"#222222\", size=3.8, fontface=\"bold\") +\n  # \u4ec5\u9ad8\u4eae\u548c\u6807\u6ce8\u6700\u4f73\u70b9\n  geom_point(data=best_point,\n             aes(x=Variables, y=Accuracy),\n             shape=8, size=4, color=\"#41ab5d\") +\n  geom_text(data=best_point,\n            aes(x=Variables, y=Accuracy, label=best_label),\n            vjust=-2.2, hjust=0.5, size=4.5, color=\"#228B22\", fontface=\"bold\") +\n  scale_y_continuous(limits=c(0.5,1), expand=expansion(add=0.02)) +\n  scale_x_continuous(breaks=acc_df$Variables) +\n  theme_bw(base_size=16) +\n  theme(\n    panel.grid.major = element_line(color=\"grey85\", size=0.4, linetype=2),\n    panel.grid.minor = element_blank(),\n    axis.text  = element_text(color=\"black\"),\n    plot.title = element_text(face=\"bold\", hjust=0.5, size=19),\n    plot.subtitle = element_text(face=\"italic\", hjust=0.5, size=13)\n  ) +\n  labs(\n    title=\"Model performance versus number of genes\",\n    subtitle=\"Cross-validated accuracy curve from KNN-RFE\",\n    x=\"Numb",
"er of features\",\n    y=\"Cross-validated accuracy\"\n  )\nprint(p)\ndev.off()\n\n# ========== 6. \u53ef\u9009\uff1a\u6700\u4f18\u7279\u5f81\u5b50\u96c6\u7bb1\u7ebf\u56fe ==========\nexpr_sub_best <- as.data.frame(X_scaled[, imp_genes_best, drop=FALSE])\nexpr_sub_best$Group <- y\nexpr_melt_best <- melt(expr_sub_best, id.vars=\"Group\")\n\npdf(\"KNN_BestGene_Boxplot.pdf\", width=9, height=10)\nggplot(expr_melt_best, aes(x=Group, y=value, fill=Group)) +\n  geom_boxplot() +\n  facet_wrap(~variable, scales = \"free_y\") +\n  theme_bw() +\n  labs(title = paste0(\"Best KNN Genes Expression by Group (n=\",best_vars,\")\"),\n       x = \"Group\", y = \"Normalized Expression\")\ndev.off()\n\n# ========== 7. \u53ef\u9009\uff1aPCA\u56fe ==========\npca_res <- prcomp(X_scaled[, imp_genes_best], scale. = TRUE)\npca_df <- data.frame(PC1 = pca_res$x[,1], PC2 = pca_res$x[,2], Group = y)\npdf(\"KNN_BestGene_PCA.pdf\", width=6, height=5)\nggplot(pca_df, aes(x=PC1, y=PC2, color=Group)) +\n  geom_point(size=3, alpha=0.85) +\n  theme_bw(base_size=14) +\n  labs(title=paste0(\"PCA of Best KNN genes (n=\",best_vars,\")\"), x=\"PC1\", y=\"PC2\")\ndev.off()\n\n# ========== 8. \u6df7\u6dc6\u77e9\u9635\u53ef\u89c6\u5316 ==========\ncm_df_best <- as.data.frame(cm_best$table)\npdf(\"KNN_ConfusionMatrix_Bar_Best.pdf\", width=6, height=5)\nggplot(cm_df_best, aes(Prediction, Freq, fill=Reference)) +\n  geom_bar(stat=\"identity\", position=\"dodge\") +\n  theme_bw(base_size=14) +\n  labs(title=\"Confusion matrix of KNN best model\", x=\"Predicted\", y=\"Count\")\ndev.off()\n# ========== \uff1a\u4fdd\u5b58\u6700\u4f73\u6a21\u578b\u7528\u6240\u6709\u57fa\u56e0\u540d ==========\nimp_genes_best <- predictors(knnProfile)[1:best_vars]\nwrite.csv(\n  data.frame(Gene = imp_genes_best),\n  \"KNN_BestModel_Gene_Names.csv\",\n  row.names = FALSE\n)\n"),
"bulk/11.marching learning/Analysis_Result/.Rhistory"=paste0(")\np_all <- ggplot(\ndf_boxplot_long,\naes(x = Group, y = Expression, fill = Group)\n) +\ngeom_boxplot(\nwidth = 0.55,\nalpha = 0.85,\noutlier.shape = NA,\nlinewidth = 0.65,\ncolor = \"black\"\n) +\ngeom_jitter(\naes(color = Group),\nwidth = 0.15,\nsize = 1.5,\nalpha = 0.65\n) +\ngeom_text(\ndata = label_df,\naes(x = 1.5, y = y_pos, label = Label),\ninherit.aes = FALSE,\nsize = 3.6,\nfontface = \"bold\"\n) +\nscale_fill_manual(values = my_colors) +\nscale_color_manual(values = my_colors) +\nfacet_wrap(\n~ Gene,\nscales = \"free_y\",\nncol = 3\n) +\nlabs(\nx = NULL,\ny = \"Expression level\",\ntitle = \"Expression of diagnostic genes\"\n) +\ntheme_classic(base_size = 13) +\ntheme(\nplot.title = element_text(\nface = \"bold\",\nhjust = 0.5,\nsize = 17\n),\nstrip.background = element_rect(\nfill = \"grey95\",\ncolor = \"black\",\nlinewidth = 0.6\n),\nstrip.text = element_text(\nface = \"bold\",\nsize = 12\n),\naxis.text.x = element_text(\ncolor = \"black\",\nface = \"bold\",\nangle = 30,\nhjust = 1,\nsize = 10\n),\naxis.text.y = element_text(\ncolor = \"black\",\nsize = 10\n),\naxis.title.y = element_text(\nface = \"bold\",\nsize = 13\n),\nlegend.position = \"top\",\nlegend.title = element_blank(),\nlegend.text = element_text(size = 12),\naxis.line = element_line(\nlinewidth = 0.7,\ncolor = \"black\"\n)\n)\nggsave(\nfilename = \"All_Diagnostic_Genes_Boxplot.pdf\",\nplot = p_all,\nwidth = 10,\nheight = max(6, ceiling(length(model_vars) / 3) * 3.2)\n)\nggsave(\nfilename = \"All_Diagnostic_Genes_Boxplot.tiff\",\nplot = p_all,\nwidth = 10,\nheight = max(6, ceiling(length(model_vars) / 3) * 3.2),\ndpi = 600,\ncompression = \"lzw\"\n)\ncat(\">> \u6240\u6709\u57fa\u56e0\u6574\u5408\u7248\u7bb1\u7ebf\u56fe\u5df2\u8f93\u51fa\uff1aAll_Diagnostic_Genes_Boxplot.pdf / .tiff\\n\")\n# ==== \u65b0\u589e\uff1a\u6bcf\u4e2a\u8bca\u65ad\u57fa\u56e0\u5355\u72ec\u7ed8\u5236\u9ad8\u8d28\u91cf\u7bb1\u7ebf\u56fe ====\ncat(\">> \u6b63\u5728\u751f\u6210\u6bcf\u4e2a\u8bca\u65ad\u57fa\u56e0\u7684\u5355\u72ec\u7bb1\u7ebf\u56fe...\\n\")\n# ===============================\n# 1. \u52a0\u8f7d\u7ed8\u56fe\u76f8\u5173R\u5305\n# ===============================\nplot_packages <- c(\"ggplot2\", \"ggpubr\", \"dplyr\", \"tidyr\")\n",
"for (pkg in plot_packages) {\nif (!requireNamespace(pkg, quietly = TRUE)) {\ninstall.packages(pkg, dependencies = TRUE)\n}\nlibrary(pkg, character.only = TRUE)\n}\n# ===============================\n# 2. \u521b\u5efa\u7bb1\u7ebf\u56fe\u8f93\u51fa\u6587\u4ef6\u5939\n# ===============================\nboxplot_dir <- \"Individual_Gene_Boxplots\"\nif (!dir.exists(boxplot_dir)) {\ndir.create(boxplot_dir)\n}\n# ===============================\n# 3. \u91cd\u65b0\u4ece\u6837\u672c\u540d\u63d0\u53d6\u5206\u7ec4\n# ===============================\n# \u6ce8\u610f\uff1a\n# \u8fd9\u91cc\u4e0d\u7528 df_expr$GroupType\uff0c\u56e0\u4e3a\u524d\u9762DCA\u6b65\u9aa4\u53ef\u80fd\u5df2\u7ecf\u628aGroupType\u8f6c\u62100/1\n# \u8fd9\u91cc\u91cd\u65b0\u4ece\u6837\u672c\u540d\u6700\u540e\u4e00\u4e2a\u4e0b\u5212\u7ebf\u540e\u7684\u5185\u5bb9\u63d0\u53d6\u5206\u7ec4\nplot_group <- gsub(\"(.*)_([A-Za-z0-9]+)$\", \"\\\\2\", rownames(df_expr))\nplot_group <- trimws(plot_group)\n# ===============================\n# 4. \u624b\u52a8\u89c4\u8303\u5206\u7ec4\u540d\u79f0\n# ===============================\n# \u628a tra \u6539\u6210 UC\nplot_group[tolower(plot_group) %in% c(\"tra\", \"treat\", \"treated\", \"treatment\")] <- \"UC\"\n# \u5176\u4ed6\u53ef\u80fd\u4ee3\u8868UC/\u75be\u75c5\u7ec4\u7684\u540d\u79f0\u4e5f\u7edf\u4e00\u6210UC\nplot_group[tolower(plot_group) %in% c(\"uc\", \"disease\", \"case\", \"patient\")] <- \"UC\"\n# \u628a\u6b63\u5e38\u7ec4\u7edf\u4e00\u6210Control\nplot_group[tolower(plot_group) %in% c(\"normal\", \"control\", \"ctrl\", \"con\", \"healthy\")] <- \"Control\"\n# \u5982\u679c\u4f60\u7684\u5206\u7ec4\u662f0/1\uff0c\u4e5f\u53ef\u4ee5\u81ea\u52a8\u8f6c\u6362\nplot_group[plot_group == \"0\"] <- \"Control\"\nplot_group[plot_group == \"1\"] <- \"UC\"\n# \u56fa\u5b9a\u663e\u793a\u987a\u5e8f\uff1aControl\u5728\u5de6\uff0cUC\u5728\u53f3\nif (all(c(\"Control\", \"UC\") %in% unique(plot_group))) {\nplot_group <- factor(plot_group, levels = c(\"Control\", \"UC\"))\n} else {\nplot_group <- factor(plot_group)\n}\n# \u68c0\u67e5\u662f\u5426\u4e3a\u4e8c\u5206\u7c7b\nif (nlevels(plot_group) != 2) {\ncat(\"\u5f53\u524d\u8bc6\u522b\u5230\u7684\u5206\u7ec4\u5982\u4e0b\uff1a\\n\")\nprint(table(plot_group))\nstop(\"\u9519\u8bef\uff1a\u7bb1\u7ebf\u56fe\u7ed8\u5236\u8981\u6c42\u53ea\u6709\u4e24\u4e2a\u5206\u7ec4\uff0c\u8bf7\u68c0\u67e5\u6837\u672c\u540d\u4e2d\u7684\u5206\u7ec4\u4fe1\u606f\u3002\")\n}\ngroup_levels <- levels(plot_group)\ncat(\"\u7bb1\u7ebf\u56fe\u5206\u7ec4\u4e3a\uff1a\", group_levels[1], \" vs \", group_levels[2], \"\\n\")\nprint(table(plot_group))\n# ===============================\n# 5. \u6574\u7406\u957f\u6570\u636e\n# ===============================\ndf_boxplot <- data.frame(\nSample = rownames(df_expr),\nGroup = plot_group,\ndf_expr[, model_vars, drop = FALSE],\ncheck.names = FALSE\n)\ndf_boxplot_long <- tidyr::pi",
"vot_longer(\ndf_boxplot,\ncols = dplyr::all_of(model_vars),\nnames_to = \"Gene\",\nvalues_to = \"Expression\"\n)\ndf_boxplot_long$Group <- factor(\ndf_boxplot_long$Group,\nlevels = group_levels\n)\n# ===============================\n# 6. \u8ba1\u7b97\u6bcf\u4e2a\u57fa\u56e0\u7684P\u503c\n# ===============================\np_value_df <- data.frame()\nfor (gene in model_vars) {\ntemp_data <- df_boxplot_long[df_boxplot_long$Gene == gene, ]\ngroup1 <- temp_data$Expression[temp_data$Group == group_levels[1]]\ngroup2 <- temp_data$Expression[temp_data$Group == group_levels[2]]\n# \u4f7f\u7528Wilcoxon\u68c0\u9a8c\uff0c\u9002\u5408\u8868\u8fbe\u91cf\u6570\u636e\uff0c\u66f4\u7a33\u5065\np_val <- tryCatch(\nwilcox.test(group1, group2, exact = FALSE)$p.value,\nerror = function(e) NA\n)\np_value_df <- rbind(\np_value_df,\ndata.frame(\nGene = gene,\nGroup1 = group_levels[1],\nGroup2 = group_levels[2],\nMean_Group1 = mean(group1, na.rm = TRUE),\nMean_Group2 = mean(group2, na.rm = TRUE),\nMedian_Group1 = median(group1, na.rm = TRUE),\nMedian_Group2 = median(group2, na.rm = TRUE),\nP_Value = p_val,\nstringsAsFactors = FALSE\n)\n)\n}\n# FDR\u6821\u6b63\np_value_df$FDR <- p.adjust(p_value_df$P_Value, method = \"BH\")\n# \u6dfb\u52a0\u663e\u8457\u6027\u6807\u7b7e\np_value_df$Significance <- ifelse(\nis.na(p_value_df$P_Value), \"NA\",\nifelse(\np_value_df$P_Value < 0.001, \"***\",\nifelse(\np_value_df$P_Value < 0.01, \"**\",\nifelse(p_value_df$P_Value < 0.05, \"*\", \"ns\")\n)\n)\n)\n# \u6dfb\u52a0\u8868\u8fbe\u65b9\u5411\np_value_df$Expression_Trend <- ifelse(\np_value_df$Mean_Group2 > p_value_df$Mean_Group1,\npaste0(group_levels[2], \" higher\"),\npaste0(group_levels[1], \" higher\")\n)\n# \u8f93\u51faP\u503c\u8868\u683c\nwrite.csv(\np_value_df,\nfile = \"Individual_Gene_Boxplot_Pvalues.csv\",\nrow.names = FALSE\n)\ncat(\">> \u6bcf\u4e2a\u57fa\u56e0\u7684P\u503c\u5df2\u8f93\u51fa\u81f3 Individual_Gene_Boxplot_Pvalues.csv\\n\")\n# ===============================\n# 7. \u8bbe\u7f6e\u989c\u8272\n# ===============================\nmy_colors <- c(\"#4DBBD5\", \"#E64B35\")\nnames(my_colors) <- group_levels\n# ===============================\n# 8. \u4fdd\u5b58\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7bb1\u7ebf\u56fe\n# ===============",
"================\nfor (gene in model_vars) {\ntemp_data <- df_boxplot_long[df_boxplot_long$Gene == gene, ]\ntemp_p <- p_value_df[p_value_df$Gene == gene, ]\ny_max <- max(temp_data$Expression, na.rm = TRUE)\ny_min <- min(temp_data$Expression, na.rm = TRUE)\ny_range <- y_max - y_min\nif (y_range == 0) {\ny_range <- abs(y_max) * 0.1 + 1\n}\n# ===============================\n# \u5173\u952e\u4fee\u6539\uff1a\n# \u628aP\u503c\u62ec\u53f7\u7ebf\u3001\u661f\u53f7\u3001P\u503c\u6587\u5b57\u5206\u5f00\uff0c\u907f\u514d\u91cd\u53e0\n# ===============================\ny_bracket <- y_max + 0.20 * y_range\ny_tick_bottom <- y_bracket - 0.04 * y_range\ny_p_text <- y_bracket + 0.07 * y_range\ny_star <- y_bracket + 0.14 * y_range\ny_upper <- y_bracket + 0.24 * y_range\np_text <- ifelse(\nis.na(temp_p$P_Value),\n\"P = NA\",\nifelse(\ntemp_p$P_Value < 0.001,\n\"P < 0.001\",\npaste0(\"P = \", signif(temp_p$P_Value, 3))\n)\n)\np_single <- ggplot(\ntemp_data,\naes(x = Group, y = Expression, fill = Group)\n) +\ngeom_boxplot(\nwidth = 0.55,\nalpha = 0.88,\noutlier.shape = NA,\nlinewidth = 0.8,\ncolor = \"black\"\n) +\ngeom_jitter(\naes(color = Group),\nwidth = 0.15,\nsize = 2.3,\nalpha = 0.78\n) +\nstat_summary(\nfun = median,\ngeom = \"crossbar\",\nwidth = 0.42,\nlinewidth = 0.35,\ncolor = \"black\"\n) +\nannotate(\n\"segment\",\nx = 1,\nxend = 2,\ny = y_bracket,\nyend = y_bracket,\nlinewidth = 0.75,\ncolor = \"black\"\n) +\nannotate(\n\"segment\",\nx = 1,\nxend = 1,\ny = y_bracket,\nyend = y_tick_bottom,\nlinewidth = 0.75,\ncolor = \"black\"\n) +\nannotate(\n\"segment\",\nx = 2,\nxend = 2,\ny = y_bracket,\nyend = y_tick_bottom,\nlinewidth = 0.75,\ncolor = \"black\"\n) +\nannotate(\n\"text\",\nx = 1.5,\ny = y_star,\nlabel = temp_p$Significance,\nsize = 5.2,\nfontface = \"bold\"\n) +\nannotate(\n\"text\",\nx = 1.5,\ny = y_p_text,\nlabel = p_text,\nsize = 4.1,\nfontface = \"bold\"\n) +\nscale_fill_manual(values = my_colors) +\nscale_color_manual(values = my_colors) +\nlabs(\ntitle = gene,\nx = NULL,\ny = \"Expression level\"\n) +\ntheme_classic(",
"base_size = 14) +\ntheme(\nplot.title = element_text(\nface = \"bold\",\nhjust = 0.5,\nsize = 18\n),\naxis.title.y = element_text(\nface = \"bold\",\nsize = 14\n),\naxis.text.x = element_text(\ncolor = \"black\",\nface = \"bold\",\nsize = 13\n),\naxis.text.y = element_text(\ncolor = \"black\",\nsize = 12\n),\nlegend.position = \"none\",\naxis.line = element_line(\nlinewidth = 0.8,\ncolor = \"black\"\n),\nplot.margin = margin(18, 18, 18, 18)\n) +\ncoord_cartesian(\nylim = c(y_min - 0.05 * y_range, y_upper),\nclip = \"off\"\n)\n# \u6587\u4ef6\u540d\u5b89\u5168\u5904\u7406\nsafe_gene <- gsub(\"[^A-Za-z0-9_\\\\-]\", \"_\", gene)\n# \u8f93\u51faPDF\nggsave(\nfilename = file.path(boxplot_dir, paste0(safe_gene, \"_Boxplot.pdf\")),\nplot = p_single,\nwidth = 4.2,\nheight = 5.4\n)\n# \u8f93\u51fa600 dpi TIFF\uff0c\u9002\u5408SCI\u6295\u7a3f\nggsave(\nfilename = file.path(boxplot_dir, paste0(safe_gene, \"_Boxplot.tiff\")),\nplot = p_single,\nwidth = 4.2,\nheight = 5.4,\ndpi = 600,\ncompression = \"lzw\"\n)\n}\ncat(\">> \u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7bb1\u7ebf\u56fe\u5df2\u8f93\u51fa\u81f3\u6587\u4ef6\u5939\uff1aIndividual_Gene_Boxplots\\n\")\n# ===============================\n# 9. \u989d\u5916\u8f93\u51fa\uff1a\u6240\u6709\u57fa\u56e0\u6574\u5408\u7248\u7bb1\u7ebf\u56fe\n# ===============================\ncat(\">> \u6b63\u5728\u751f\u6210\u6240\u6709\u57fa\u56e0\u6574\u5408\u7248\u7bb1\u7ebf\u56fe...\\n\")\n# \u7ed9\u6bcf\u4e2a\u57fa\u56e0\u8ba1\u7b97\u5355\u72ec\u7684y\u8f74\u6807\u6ce8\u4f4d\u7f6e\nlabel_df <- df_boxplot_long %>%\ndplyr::group_by(Gene) %>%\ndplyr::summarise(\ny_max = max(Expression, na.rm = TRUE),\ny_min = min(Expression, na.rm = TRUE),\n.groups = \"drop\"\n) %>%\ndplyr::mutate(\ny_range = y_max - y_min,\ny_range = ifelse(y_range == 0, abs(y_max) * 0.1 + 1, y_range),\ny_star = y_max + 0.27 * y_range,\ny_p = y_max + 0.17 * y_range\n) %>%\ndplyr::left_join(\np_value_df[, c(\"Gene\", \"P_Value\", \"Significance\")],\nby = \"Gene\"\n) %>%\ndplyr::mutate(\nP_label = ifelse(\nis.na(P_Value),\n\"P = NA\",\nifelse(\nP_Value < 0.001,\n\"P < 0.001\",\npaste0(\"P = \", signif(P_Value, 3))\n)\n)\n)\np_all <- ggplot(\ndf_boxplot_long,\naes(x = Group, y = Expression, fill = Group)\n) +\ngeom_boxplot(\nwidth = 0.55,\nalpha = 0.88,\noutlier.shape = NA,\nlinewidth = 0.65,\ncolor = \"blac",
"k\"\n) +\ngeom_jitter(\naes(color = Group),\nwidth = 0.15,\nsize = 1.5,\nalpha = 0.68\n) +\ngeom_text(\ndata = label_df,\naes(x = 1.5, y = y_star, label = Significance),\ninherit.aes = FALSE,\nsize = 4.0,\nfontface = \"bold\"\n) +\ngeom_text(\ndata = label_df,\naes(x = 1.5, y = y_p, label = P_label),\ninherit.aes = FALSE,\nsize = 3.1,\nfontface = \"bold\"\n) +\nscale_fill_manual(values = my_colors) +\nscale_color_manual(values = my_colors) +\nfacet_wrap(\n~ Gene,\nscales = \"free_y\",\nncol = 3\n) +\nscale_y_continuous(\nexpand = expansion(mult = c(0.06, 0.34))\n) +\nlabs(\nx = NULL,\ny = \"Expression level\",\ntitle = \"Expression of diagnostic genes\"\n) +\ntheme_classic(base_size = 13) +\ntheme(\nplot.title = element_text(\nface = \"bold\",\nhjust = 0.5,\nsize = 17\n),\nstrip.background = element_rect(\nfill = \"grey95\",\ncolor = \"black\",\nlinewidth = 0.6\n),\nstrip.text = element_text(\nface = \"bold\",\nsize = 12\n),\naxis.text.x = element_text(\ncolor = \"black\",\nface = \"bold\",\nangle = 30,\nhjust = 1,\nsize = 10\n),\naxis.text.y = element_text(\ncolor = \"black\",\nsize = 10\n),\naxis.title.y = element_text(\nface = \"bold\",\nsize = 13\n),\nlegend.position = \"top\",\nlegend.title = element_blank(),\nlegend.text = element_text(size = 12),\naxis.line = element_line(\nlinewidth = 0.7,\ncolor = \"black\"\n),\nplot.margin = margin(15, 15, 15, 15)\n)\nggsave(\nfilename = \"All_Diagnostic_Genes_Boxplot.pdf\",\nplot = p_all,\nwidth = 10,\nheight = max(6, ceiling(length(model_vars) / 3) * 3.2)\n)\nggsave(\nfilename = \"All_Diagnostic_Genes_Boxplot.tiff\",\nplot = p_all,\nwidth = 10,\nheight = max(6, ceiling(length(model_vars) / 3) * 3.2),\ndpi = 600,\ncompression = \"lzw\"\n)\ncat(\">> \u6240\u6709\u57fa\u56e0\u6574\u5408\u7248\u7bb1\u7ebf\u56fe\u5df2\u8f93\u51fa\uff1aAll_Diagnostic_Genes_Boxplot.pdf / .tiff\\n\")\n"),
"immune/fig05_cibersort.R"=paste0("# ============================================================\n# \u7b2c\u4e09\u90e8\u5206\uff1a\u5173\u952e\u57fa\u56e0\u4e0e\u514d\u75ab\u6d78\u6da6\u7ec6\u80de\u7684\u76f8\u5173\u6027\u5206\u6790\n# \u7f8e\u5316\u7248\uff1a\u76f8\u5173\u6027\u70ed\u56fe + \u5706\u5f62\u6c14\u6ce1\u56fe + \u5355\u57fa\u56e0\u76f8\u5173\u6027\u6563\u70b9\u56fe\n# ============================================================\n\ncat(\"\\n==== \u7b2c\u4e09\u90e8\u5206\uff1a\u57fa\u56e0-\u514d\u75ab\u6d78\u6da6\u7ec6\u80de\u76f8\u5173\u6027\u5206\u6790\uff1a\u7f8e\u5316\u7248 ====\\n\")\n\nlibrary(ggplot2)\nlibrary(dplyr)\nlibrary(tidyr)\nlibrary(reshape2)\nlibrary(limma)\nlibrary(pheatmap)\nlibrary(RColorBrewer)\nlibrary(ggpubr)\nlibrary(scales)\nlibrary(stringr)\n\n# ----------------------------\n# 1. \u8bfb\u53d6\u57fa\u56e0\u8868\u8fbe\u6570\u636e\n# ----------------------------\nexprRaw <- read.table(\n  input_file,\n  header = TRUE,\n  sep = \",\",\n  check.names = FALSE\n)\n\nexprMat <- as.matrix(exprRaw)\nrownames(exprMat) <- exprMat[, 1]\n\nexprVals <- exprMat[, -1, drop = FALSE]\nrowNamesTmp <- rownames(exprVals)\ncolNamesTmp <- colnames(exprVals)\n\nnumExpr <- matrix(\n  as.numeric(as.matrix(exprVals)),\n  nrow = nrow(exprVals),\n  dimnames = list(rowNamesTmp, colNamesTmp)\n)\n\nnumExpr <- avereps(numExpr)\n\n# ----------------------------\n# 2. \u8bfb\u53d6\u76ee\u6807\u57fa\u56e0\u5217\u8868\n# ----------------------------\ngene_list <- read.csv(\n  gene_list_file,\n  header = TRUE,\n  stringsAsFactors = FALSE,\n  check.names = FALSE\n)\n\ntargetGene <- unique(trimws(as.character(gene_list[, 1])))\ntargetGene <- targetGene[targetGene != \"\" & !is.na(targetGene)]\n\nmatched_genes <- targetGene[targetGene %in% rownames(numExpr)]\n\ncat(\"\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(targetGene), \"\\n\")\ncat(\"\u8868\u8fbe\u77e9\u9635\u4e2d\u5339\u914d\u5230\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(matched_genes), \"\\n\")\n\nif (length(matched_genes) == 0) {\n  stop(\"\u76ee\u6807\u57fa\u56e0\u5728\u8868\u8fbe\u77e9\u9635\u4e2d\u5747\u672a\u5339\u914d\u5230\uff0c\u8bf7\u68c0\u67e5\u57fa\u56e0\u540d\u3002\")\n}\n\nexprSelected <- t(numExpr[matched_genes, , drop = FALSE])\n\n# ----------------------------\n# 3. \u63d0\u53d6\u514d\u75ab\u6d78\u6da6\u77e9\u9635\n# ----------------------------\nimmune_cols <- setdiff(colnames(rt), c(\"Sample\", \"Group\"))\n\nimmuneMat <- as.matrix(rt[, immune_cols, drop = FALSE])\nimmuneMat <- apply(immuneMat, 2, as.numeric)\nrownames(immuneMat) <- rownames(rt)\n\n# ----------------------------\n#",
" 4. \u6837\u672c\u53d6\u4ea4\u96c6\n# ----------------------------\ncommonSamples <- intersect(rownames(exprSelected), rownames(immuneMat))\n\ncat(\"\u5171\u540c\u6837\u672c\u6570\uff1a\", length(commonSamples), \"\\n\")\n\nif (length(commonSamples) < 3) {\n  stop(\"\u5171\u540c\u6837\u672c\u6570\u8fc7\u5c11\uff0c\u65e0\u6cd5\u8fdb\u884c\u76f8\u5173\u6027\u5206\u6790\u3002\")\n}\n\nexprSelected <- exprSelected[commonSamples, , drop = FALSE]\nimmuneMat    <- immuneMat[commonSamples, , drop = FALSE]\n\n# \u53bb\u9664\u6807\u51c6\u5dee\u4e3a0\u7684\u514d\u75ab\u7ec6\u80de\nvalidImmune <- immuneMat[, apply(immuneMat, 2, sd, na.rm = TRUE) > 0, drop = FALSE]\n\ncat(\"\u6709\u6548\u514d\u75ab\u7ec6\u80de\u7c7b\u578b\u6570\uff1a\", ncol(validImmune), \"\\n\")\n\nif (ncol(validImmune) == 0) {\n  stop(\"\u6240\u6709\u514d\u75ab\u7ec6\u80de\u5217\u6807\u51c6\u5dee\u5747\u4e3a0\uff0c\u65e0\u6cd5\u8ba1\u7b97\u76f8\u5173\u6027\u3002\")\n}\n\n# ----------------------------\n# 5. \u8ba1\u7b97 Spearman \u76f8\u5173\u6027\n# ----------------------------\ncor_mat <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\np_val_matrix <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\nfor (i in seq_len(ncol(exprSelected))) {\n  for (j in seq_len(ncol(validImmune))) {\n    \n    x <- as.numeric(exprSelected[, i])\n    y <- as.numeric(validImmune[, j])\n    \n    test_result <- tryCatch(\n      cor.test(\n        x,\n        y,\n        method = \"spearman\",\n        use = \"pairwise.complete.obs\",\n        exact = FALSE\n      ),\n      error = function(e) NULL\n    )\n    \n    if (!is.null(test_result)) {\n      cor_mat[i, j] <- as.numeric(test_result$estimate)\n      p_val_matrix[i, j] <- test_result$p.value\n    }\n  }\n}\n\n# ----------------------------\n# 6. \u5bfc\u51fa\u76f8\u5173\u6027\u7ed3\u679c\u957f\u8868\n# ----------------------------\ncorrDF <- data.frame()\n\nfor (i in 1:nrow(cor_mat)) {\n  for (j in 1:ncol(cor_mat)) {\n    \n    p_now <- p_val_matrix[i, j]\n    cor_now <- cor_mat[i, j]\n    \n    sig_now <- ifelse(\n      is.na(p_now), \"\",\n      ifelse(p_now < 0.001, \"***\",\n             ifelse",
"(p_now < 0.01, \"**\",\n                    ifelse(p_now < 0.05, \"*\", \"\")))\n    )\n    \n    corrDF <- rbind(\n      corrDF,\n      data.frame(\n        Gene = rownames(cor_mat)[i],\n        ImmuneCell = colnames(cor_mat)[j],\n        Correlation = cor_now,\n        P.Value = p_now,\n        Significance = sig_now,\n        stringsAsFactors = FALSE\n      )\n    )\n  }\n}\n\ncorrDF$AbsCorrelation <- abs(corrDF$Correlation)\n\nwrite.csv(\n  corrDF,\n  file = \"Gene_Immune_Correlation_Results_beautified.csv\",\n  row.names = FALSE\n)\n\ncat(\">> \u76f8\u5173\u6027\u7ed3\u679c\u8868\u5df2\u4fdd\u5b58\uff1aGene_Immune_Correlation_Results_beautified.csv\\n\")\n\n# ============================================================\n# \u56fe1\uff1a\u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe...\\n\")\n\n# \u6807\u7b7e\u77e9\u9635\uff1a\u53ea\u663e\u793a\u663e\u8457\u6027\u661f\u53f7\uff0c\u56fe\u66f4\u5e72\u51c0\nlabels_star <- matrix(\n  \"\",\n  nrow = nrow(cor_mat),\n  ncol = ncol(cor_mat),\n  dimnames = dimnames(cor_mat)\n)\n\nfor (i in 1:nrow(p_val_matrix)) {\n  for (j in 1:ncol(p_val_matrix)) {\n    p_now <- p_val_matrix[i, j]\n    if (!is.na(p_now)) {\n      if (p_now < 0.001) labels_star[i, j] <- \"***\"\n      else if (p_now < 0.01) labels_star[i, j] <- \"**\"\n      else if (p_now < 0.05) labels_star[i, j] <- \"*\"\n    }\n  }\n}\n\n# \u989c\u8272\uff1a\u84dd\u8272\u8d1f\u76f8\u5173\uff0c\u767d\u8272\u65e0\u76f8\u5173\uff0c\u7ea2\u8272\u6b63\u76f8\u5173\nheat_cols <- colorRampPalette(c(\"#2166AC\", \"white\", \"#B2182B\"))(100)\n\ngene_num <- nrow(cor_mat)\nimmune_num <- ncol(cor_mat)\n\npdf_width  <- max(9, 4 + 0.45 * immune_num)\npdf_height <- max(5, 2.5 + 0.55 * gene_num)\n\npdf(\n  file = \"Gene_Immune_Correlation_Heatmap_beautified.pdf\",\n  width = pdf_width,\n  height = pdf_height\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1, length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color ",
"= \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and Immune Cells\",\n  legend = TRUE\n)\n\ndev.off()\n\npng(\n  file = \"Gene_Immune_Correlation_Heatmap_beautified.png\",\n  width = pdf_width,\n  height = pdf_height,\n  units = \"in\",\n  res = 300\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1, length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color = \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and Immune Cells\",\n  legend = TRUE\n)\n\ndev.off()\n\ncat(\">> \u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe2\uff1aNature\u98ce\u683c\u5706\u5f62\u6c14\u6ce1\u56fe\n# \u989c\u8272\u4ee3\u8868\u76f8\u5173\u7cfb\u6570\u65b9\u5411\u548c\u5927\u5c0f\uff1b\u5706\u70b9\u5927\u5c0f\u4ee3\u8868\u76f8\u5173\u6027\u7edd\u5bf9\u503c\uff1b\u661f\u53f7\u4ee3\u8868P\u503c\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248\u5706\u5f62\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_df <- corrDF %>%\n  filter(!is.na(Correlation), !is.na(P.Value))\n\n# \u6392\u5e8f\uff1a\u57fa\u56e0\u6309\u8f93\u5165\u987a\u5e8f\uff0c\u514d\u75ab\u7ec6\u80de\u6309\u805a\u7c7b\u6216\u5b57\u6bcd\u987a\u5e8f\nbubble_df$Gene <- factor(\n  bubble_df$Gene,\n  levels = matched_genes[matched_genes %in% unique(bubble_df$Gene)]\n)\n\n# \u514d\u75ab\u7ec6\u80de\u6309\u5e73\u5747\u76f8\u5173\u6027\u6392\u5e8f\uff0c\u8ba9\u56fe\u66f4\u6709\u89c4\u5f8b\nimmune_order <- bubble_df %>%\n  group_by(ImmuneCell) %>%\n  summarise(mean_cor = mean(Correlation, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(mean_cor) %>%\n  pull(ImmuneCell)\n\nbubble_df$ImmuneCell <- factor(\n  bubble_df$ImmuneCell,\n  levels = immune_order\n)\n\nbubble_df$SigLabel <- ifelse(\n  bubble_df$P.Value < 0.001, \"***\",\n  ifelse(bubble_df$P.Value < 0.01, \"**\",\n         ifelse(bubble_df$P.Value < 0.05, \"*\", \"\"))\n)\n\nmax_abs_cor <- max(abs(bubble_df$Correlation), na.rm = TRUE)\n\nfig_width  <- max(8, 3.5 + length(unique(bubble_df$Gene)) * 0.8)\nfig_height <- max(7, 2.5 + length(unique(bubble_df$ImmuneCell)) * 0.35)\n\np_bubble <- ggplot(\n  bubble_df,\n  aes(x = G",
"ene, y = ImmuneCell)\n) +\n  geom_point(\n    aes(size = AbsCorrelation, fill = Correlation),\n    shape = 21,\n    color = \"grey25\",\n    stroke = 0.25,\n    alpha = 0.95\n  ) +\n  geom_text(\n    aes(label = SigLabel),\n    size = 3.2,\n    color = \"black\",\n    fontface = \"bold\"\n  ) +\n  scale_fill_gradient2(\n    low = \"#2166AC\",\n    mid = \"white\",\n    high = \"#B2182B\",\n    midpoint = 0,\n    limits = c(-max_abs_cor, max_abs_cor),\n    name = \"Spearman\\ncorrelation\"\n  ) +\n  scale_size_continuous(\n    range = c(2.5, 9),\n    name = \"|Correlation|\"\n  ) +\n  labs(\n    x = NULL,\n    y = NULL,\n    title = \"Gene\u2013Immune Cell Correlation\"\n  ) +\n  theme_bw(base_size = 13) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 17\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      face = \"bold.italic\",\n      color = \"black\",\n      size = 11\n    ),\n    axis.text.y = element_text(\n      color = \"black\",\n      size = 10\n    ),\n    panel.grid.major = element_line(\n      color = \"grey88\",\n      linewidth = 0.35\n    ),\n    panel.grid.minor = element_blank(),\n    panel.border = element_rect(\n      color = \"black\",\n      fill = NA,\n      linewidth = 0.8\n    ),\n    legend.position = \"right\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 11\n    ),\n    legend.text = element_text(size = 10),\n    plot.margin = margin(10, 15, 10, 10)\n  )\n\nggsave(\n  filename = \"Gene_Immune_Correlation_Bubble_beautified.pdf\",\n  plot = p_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"Gene_Immune_Correlation_Bubble_beautified.png\",\n  plot = p_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> \u7f8e\u5316\u7248\u5706\u5f62\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================",
"================================\n# \u56fe3\uff1a\u53ea\u663e\u793a\u663e\u8457\u76f8\u5173\u7684\u6c14\u6ce1\u56fe\n# \u9002\u5408\u653e\u4e3b\u56fe\uff0c\u51cf\u5c11\u4fe1\u606f\u566a\u97f3\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_sig <- bubble_df %>%\n  filter(P.Value < 0.05)\n\nif (nrow(bubble_sig) > 0) {\n  \n  bubble_sig$Gene <- factor(\n    bubble_sig$Gene,\n    levels = levels(bubble_df$Gene)\n  )\n  \n  bubble_sig$ImmuneCell <- factor(\n    bubble_sig$ImmuneCell,\n    levels = levels(bubble_df$ImmuneCell)\n  )\n  \n  fig_width_sig  <- max(6, 3.5 + length(unique(bubble_sig$Gene)) * 0.85)\n  fig_height_sig <- max(5, 2.5 + length(unique(bubble_sig$ImmuneCell)) * 0.4)\n  \n  p_bubble_sig <- ggplot(\n    bubble_sig,\n    aes(x = Gene, y = ImmuneCell)\n  ) +\n    geom_point(\n      aes(size = AbsCorrelation, fill = Correlation),\n      shape = 21,\n      color = \"grey20\",\n      stroke = 0.25,\n      alpha = 0.95\n    ) +\n    geom_text(\n      aes(label = SigLabel),\n      size = 3.4,\n      color = \"black\",\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(3, 10),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      x = NULL,\n      y = NULL,\n      title = \"Significant Gene\u2013Immune Cell Correlations\"\n    ) +\n    theme_bw(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 16\n      ),\n      axis.text.x = element_text(\n        angle = 45,\n        hjust = 1,\n        vjust = 1,\n        face = \"bold.italic\",\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 10\n      ),\n      panel.grid.major = element_line",
"(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      panel.border = element_rect(\n        color = \"black\",\n        fill = NA,\n        linewidth = 0.8\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 11\n      ),\n      legend.text = element_text(size = 10),\n      plot.margin = margin(10, 15, 10, 10)\n    )\n  \n  ggsave(\n    filename = \"Gene_Immune_Correlation_Bubble_significant_only.pdf\",\n    plot = p_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = \"Gene_Immune_Correlation_Bubble_significant_only.png\",\n    plot = p_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\",\n    dpi = 300\n  )\n  \n  cat(\">> \u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n  \n} else {\n  cat(\">> \u6ca1\u6709 P < 0.05 \u7684\u663e\u8457\u76f8\u5173\u5173\u7cfb\uff0c\u8df3\u8fc7\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u3002\\n\")\n}\n\n\n# ============================================================\n# \u56fe4\uff1a\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe\n# \u5c55\u793a\u8be5\u57fa\u56e0\u4e0e\u5168\u90e8\u514d\u75ab\u7ec6\u80de\u7684\u76f8\u5173\u6027\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684\u514d\u75ab\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe...\\n\")\n\nlollipop_dir <- \"Gene_Immune_Lollipop_Plots\"\n\nif (!dir.exists(lollipop_dir)) {\n  dir.create(lollipop_dir)\n}\n\nfor (g in unique(as.character(bubble_df$Gene))) {\n  \n  plot_g <- bubble_df %>%\n    filter(Gene == g) %>%\n    arrange(Correlation)\n  \n  plot_g$ImmuneCell <- factor(plot_g$ImmuneCell, levels = plot_g$ImmuneCell)\n  plot_g$SigColor <- ifelse(plot_g$P.Value < 0.05, \"P < 0.05\", \"NS\")\n  \n  p_lollipop <- ggplot(plot_g, aes(x = Correlation, y = ImmuneCell)) +\n    geom_vline(\n      xintercept = 0,\n      linetype = \"dashed\",\n      color = \"grey50\",\n      linewidth = 0.7\n    ) +\n    geom_segment(\n      aes(x = 0, xend = Correlation, y = ImmuneCell, yend = ImmuneCell),\n      color = \"grey60\",\n",
"      linewidth = 0.8\n    ) +\n    geom_point(\n      aes(fill = Correlation, size = AbsCorrelation),\n      shape = 21,\n      color = \"black\",\n      stroke = 0.25\n    ) +\n    geom_text(\n      aes(\n        label = ifelse(P.Value < 0.05, SigLabel, \"\")\n      ),\n      nudge_x = 0.05,\n      size = 4,\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(2.8, 8),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      title = paste0(g, \" - Immune Cell Correlation\"),\n      x = \"Spearman correlation\",\n      y = NULL\n    ) +\n    theme_classic(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 16\n      ),\n      axis.title.x = element_text(\n        face = \"bold\",\n        size = 13\n      ),\n      axis.text.x = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 10\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 10\n      ),\n      legend.text = element_text(size = 9)\n    )\n  \n  safe_g <- gsub(\"[^A-Za-z0-9_]\", \"_\", g)\n  \n  ggsave(\n    filename = file.path(lollipop_dir, paste0(safe_g, \"_Immune_Correlation_Lollipop.pdf\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(5, 2.5 + nrow(plot_g) * 0.25),\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = file.path(lollipop_dir, paste0(safe_g, \"_Immune_Correlation_Lollipop.png\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(5, 2.5 + nrow(plot_g) * 0.25),\n    units = \"in\",\n    dpi = 300\n  )",
"\n}\n\ncat(\">> \u5355\u57fa\u56e0\u68d2\u68d2\u7cd6\u56fe\u5df2\u4fdd\u5b58\u81f3\u6587\u4ef6\u5939\uff1aGene_Immune_Lollipop_Plots\\n\")\n\ncat(\"\\n==== \u57fa\u56e0-\u514d\u75ab\u6d78\u6da6\u76f8\u5173\u6027\u7f8e\u5316\u5206\u6790\u5b8c\u6210\uff01====\\n\")\n\n\n\n\n\n# ============================================================\n# \u7f8e\u5316\u7248\u514d\u75ab\u7ec6\u80de\u6d78\u6da6\u7bb1\u7ebf\u56fe\n# Control vs UC\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248\u514d\u75ab\u7ec6\u80de\u7bb1\u7ebf\u56fe...\\n\")\n\nlibrary(ggplot2)\nlibrary(ggpubr)\nlibrary(dplyr)\nlibrary(reshape2)\nlibrary(RColorBrewer)\n\n# ----------------------------\n# 1. \u91cd\u65b0\u6574\u7406 CIBERSORT \u7ed3\u679c\n# ----------------------------\n\nrt <- read.table(\n  \"CIBERSORT-Results.csv\",\n  header = TRUE,\n  sep = \",\",\n  check.names = FALSE,\n  row.names = 1\n)\n\n# \u6839\u636e\u6837\u672c\u540e\u7f00\u5224\u65ad\u5206\u7ec4\n# \u628a tra / traat \u7edf\u4e00\u6539\u6210 UC\nrt$Group <- ifelse(\n  grepl(\"_con$\", rownames(rt), ignore.case = TRUE),\n  \"Control\",\n  ifelse(\n    grepl(\"_tra$|_traat$|_UC$\", rownames(rt), ignore.case = TRUE),\n    \"UC\",\n    NA\n  )\n)\n\nrt$Sample <- rownames(rt)\n\n# \u53bb\u9664\u65e0\u6cd5\u8bc6\u522b\u5206\u7ec4\u7684\u6837\u672c\nrt <- rt[!is.na(rt$Group), ]\n\n# \u8bbe\u7f6e\u5206\u7ec4\u987a\u5e8f\nrt$Group <- factor(rt$Group, levels = c(\"Control\", \"UC\"))\n\ncat(\"\u5206\u7ec4\u60c5\u51b5\uff1a\\n\")\nprint(table(rt$Group))\n\n# ----------------------------\n# 2. \u8f6c\u6210\u957f\u683c\u5f0f\n# ----------------------------\n\ndata_long <- melt(\n  rt,\n  id.vars = c(\"Sample\", \"Group\"),\n  variable.name = \"Immune\",\n  value.name = \"Fraction\"\n)\n\ndata_long$Fraction <- as.numeric(data_long$Fraction)\n\n# \u53bb\u9664\u975e\u514d\u75ab\u7ec6\u80de\u5217\uff0c\u9632\u6b62 P-value / Correlation / RMSE \u6df7\u5165\ndata_long <- data_long %>%\n  filter(\n    !Immune %in% c(\"P-value\", \"Correlation\", \"RMSE\"),\n    !is.na(Fraction)\n  )\n\n# ----------------------------\n# 3. \u514d\u75ab\u7ec6\u80de\u6392\u5e8f\n# \u6309 UC \u7ec4\u4e2d\u4f4d\u6570\u4ece\u9ad8\u5230\u4f4e\u6392\u5e8f\uff0c\u56fe\u66f4\u6709\u903b\u8f91\n# ----------------------------\n\nimmune_order <- data_long %>%\n  filter(Group == \"UC\") %>%\n  group_by(Immune) %>%\n  summarise(median_fraction = median(Fraction, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(desc(median_fraction)) %>%\n  pull(Immune)\n\ndata_long$Immune <- factor(data_long$Immune, levels = immune_order)\n\ncountControl <- length(un",
"ique(data_long$Sample[data_long$Group == \"Control\"]))\ncountUC      <- length(unique(data_long$Sample[data_long$Group == \"UC\"]))\n\n# ----------------------------\n# 4. \u8ba1\u7b97\u6bcf\u79cd\u514d\u75ab\u7ec6\u80de\u7684 Wilcoxon P \u503c\n# ----------------------------\n\npvalue_table <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    p.value = tryCatch(\n      wilcox.test(Fraction ~ Group)$p.value,\n      error = function(e) NA\n    ),\n    .groups = \"drop\"\n  ) %>%\n  mutate(\n    p.adj = p.adjust(p.value, method = \"BH\"),\n    Significance = case_when(\n      is.na(p.value) ~ \"ns\",\n      p.value < 0.001 ~ \"***\",\n      p.value < 0.01  ~ \"**\",\n      p.value < 0.05  ~ \"*\",\n      TRUE ~ \"ns\"\n    )\n  )\n\nwrite.csv(\n  pvalue_table,\n  file = \"Immune_Cell_Comparison_Pvalues_beautified.csv\",\n  row.names = FALSE\n)\n\n# ----------------------------\n# 5. \u4e3a\u663e\u8457\u6027\u6807\u6ce8\u51c6\u5907\u4f4d\u7f6e\n# ----------------------------\n\nlabel_df <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    y.position = max(Fraction, na.rm = TRUE) * 1.08 + 0.01,\n    .groups = \"drop\"\n  ) %>%\n  left_join(pvalue_table, by = \"Immune\")\n\n# ----------------------------\n# 6. \u7ed8\u5236\u7f8e\u5316\u7248\u7bb1\u7ebf\u56fe\n# ----------------------------\n\np_immune_box <- ggplot(\n  data_long,\n  aes(x = Immune, y = Fraction, fill = Group)\n) +\n  geom_boxplot(\n    aes(color = Group),\n    position = position_dodge(width = 0.75),\n    width = 0.58,\n    outlier.shape = NA,\n    alpha = 0.70,\n    linewidth = 0.65\n  ) +\n  geom_jitter(\n    aes(color = Group),\n    position = position_jitterdodge(\n      jitter.width = 0.12,\n      dodge.width = 0.75\n    ),\n    size = 0.65,\n    alpha = 0.35\n  ) +\n  geom_text(\n    data = label_df,\n    aes(\n      x = Immune,\n      y = y.position,\n      label = Significance\n    ),\n    inherit.aes = FALSE,\n    size = 4.2,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  scale_fill_manual(\n    values = c(\"Control\" = ",
"\"#4DBBD5\", \"UC\" = \"#E64B35\"),\n    name = \"Group\"\n  ) +\n  scale_color_manual(\n    values = c(\"Control\" = \"#0073C2\", \"UC\" = \"#CD201F\"),\n    name = \"Group\"\n  ) +\n  scale_y_continuous(\n    expand = expansion(mult = c(0.02, 0.15))\n  ) +\n  labs(\n    title = \"Immune Cell Infiltration Comparison\",\n    subtitle = paste0(\"Control n = \", countControl, \", UC n = \", countUC),\n    x = NULL,\n    y = \"Estimated fraction\"\n  ) +\n  theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 18,\n      color = \"black\"\n    ),\n    plot.subtitle = element_text(\n      hjust = 0.5,\n      size = 13,\n      color = \"black\"\n    ),\n    axis.title.y = element_text(\n      face = \"bold\",\n      size = 15,\n      color = \"black\"\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      size = 10.5,\n      color = \"black\"\n    ),\n    axis.text.y = element_text(\n      size = 12,\n      color = \"black\"\n    ),\n    axis.line = element_line(\n      linewidth = 0.8,\n      color = \"black\"\n    ),\n    axis.ticks = element_line(\n      linewidth = 0.7,\n      color = \"black\"\n    ),\n    legend.position = \"top\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 12\n    ),\n    legend.text = element_text(size = 12),\n    panel.grid = element_blank(),\n    plot.margin = margin(15, 20, 20, 20)\n  ) +\n  coord_cartesian(clip = \"off\")\n\nggsave(\n  filename = \"Immune_Cell_Boxplot_beautified.pdf\",\n  plot = p_immune_box,\n  width = 13,\n  height = 7,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"Immune_Cell_Boxplot_beautified.png\",\n  plot = p_immune_box,\n  width = 13,\n  height = 7,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> \u7f8e\u5316\u7248\u514d\u75ab\u7ec6\u80de\u7bb1\u7ebf\u56fe\u5df2\u4fdd\u5b58\uff1aImmune_Cell_Boxplot_beautified.pdf/png\\n\")\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n"),
"immune/fig05_mcpcounter.R"=paste0("# ============================================================\n# \u7b2c\u4e8c\u90e8\u5206\uff1aMCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u53ef\u89c6\u5316\uff1a\u7f8e\u5316\u7248\n# ============================================================\n\ncat(\"\\n==== \u7b2c\u4e8c\u90e8\u5206\uff1aMCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u53ef\u89c6\u5316\uff1a\u7f8e\u5316\u7248 ====\\n\")\n\nlibrary(reshape2)\nlibrary(ggplot2)\nlibrary(ggpubr)\nlibrary(dplyr)\nlibrary(broom)\nlibrary(limma)\nlibrary(pheatmap)\nlibrary(RColorBrewer)\nlibrary(scales)\nlibrary(stringr)\n\n# ----------------------------\n# 1. \u6574\u7406MCP-counter\u7ed3\u679c\n# ----------------------------\nrt <- immune_df\n\n# \u6839\u636e\u6837\u672c\u540e\u7f00\u5224\u65ad\u5206\u7ec4\n# con -> Control\uff1btra / treat / UC -> UC\nrt$Group <- ifelse(\n  grepl(\"_con$\", rownames(rt), ignore.case = TRUE),\n  \"Control\",\n  ifelse(\n    grepl(\"_tra$|_treat$|_treatment$|_UC$\", rownames(rt), ignore.case = TRUE),\n    \"UC\",\n    NA\n  )\n)\n\nrt$Sample <- rownames(rt)\n\n# \u53bb\u9664\u5206\u7ec4\u65e0\u6cd5\u8bc6\u522b\u7684\u6837\u672c\nrt <- rt[!is.na(rt$Group), ]\n\nrt$Group <- factor(rt$Group, levels = c(\"Control\", \"UC\"))\n\ncat(\"\u5206\u7ec4\u60c5\u51b5\uff1a\\n\")\nprint(table(rt$Group))\n\n# ----------------------------\n# 2. \u8f6c\u6210\u957f\u683c\u5f0f\n# ----------------------------\ndata_long <- melt(\n  rt,\n  id.vars = c(\"Sample\", \"Group\"),\n  variable.name = \"Immune\",\n  value.name = \"Abundance\"\n)\n\ndata_long$Abundance <- as.numeric(data_long$Abundance)\n\ndata_long <- data_long %>%\n  filter(!is.na(Abundance), !is.na(Group))\n\ncountControl <- length(unique(data_long$Sample[data_long$Group == \"Control\"]))\ncountUC      <- length(unique(data_long$Sample[data_long$Group == \"UC\"]))\n\n# ----------------------------\n# 3. \u514d\u75ab\u7ec6\u80de\u6309UC\u7ec4\u4e2d\u4f4d\u6570\u6392\u5e8f\n# ----------------------------\nimmune_order <- data_long %>%\n  filter(Group == \"UC\") %>%\n  group_by(Immune) %>%\n  summarise(median_abundance = median(Abundance, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(desc(median_abundance)) %>%\n  pull(Immune)\n\ndata_long$Immune <- factor(data_long$Immune, levels = immune_order)\n\n# ----------------------------\n# 4. \u7edf\u8ba1\u68c0\u9a8c\n# --------------",
"--------------\npvalue_table <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    p.value = tryCatch(\n      wilcox.test(Abundance ~ Group)$p.value,\n      error = function(e) NA\n    ),\n    .groups = \"drop\"\n  ) %>%\n  mutate(\n    p.adj = p.adjust(p.value, method = \"BH\"),\n    Significance = case_when(\n      is.na(p.value) ~ \"ns\",\n      p.value < 0.001 ~ \"***\",\n      p.value < 0.01  ~ \"**\",\n      p.value < 0.05  ~ \"*\",\n      TRUE ~ \"ns\"\n    )\n  )\n\nwrite.csv(\n  pvalue_table,\n  file = \"MCPcounter_Immune_Cell_Pvalues_beautified.csv\",\n  row.names = FALSE\n)\n\nsummary_table <- data_long %>%\n  group_by(Immune, Group) %>%\n  summarise(\n    MeanAbundance = mean(Abundance, na.rm = TRUE),\n    MedianAbundance = median(Abundance, na.rm = TRUE),\n    SD = sd(Abundance, na.rm = TRUE),\n    Count = n(),\n    .groups = \"drop\"\n  )\n\nwrite.csv(\n  summary_table,\n  file = \"MCPcounter_Immune_Cell_Summary_beautified.csv\",\n  row.names = FALSE\n)\n\n# ----------------------------\n# 5. \u663e\u8457\u6027\u6807\u6ce8\u4f4d\u7f6e\n# ----------------------------\nlabel_df <- data_long %>%\n  group_by(Immune) %>%\n  summarise(\n    y.position = max(Abundance, na.rm = TRUE) * 1.08,\n    .groups = \"drop\"\n  ) %>%\n  left_join(pvalue_table, by = \"Immune\")\n\n# ============================================================\n# \u56fe1\uff1a\u7f8e\u5316\u7248MCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u7bb1\u7ebf\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248MCP-counter\u514d\u75ab\u7ec6\u80de\u7bb1\u7ebf\u56fe...\\n\")\n\np_mcp_box <- ggplot(\n  data_long,\n  aes(x = Immune, y = Abundance, fill = Group)\n) +\n  geom_boxplot(\n    aes(color = Group),\n    position = position_dodge(width = 0.75),\n    width = 0.58,\n    outlier.shape = NA,\n    alpha = 0.72,\n    linewidth = 0.65\n  ) +\n  geom_jitter(\n    aes(color = Group),\n    position = position_jitterdodge(\n      jitter.width = 0.10,\n      dodge.width = 0.75\n    ),\n    size = 0.45,\n    a",
"lpha = 0.22\n  ) +\n  geom_text(\n    data = label_df,\n    aes(x = Immune, y = y.position, label = Significance),\n    inherit.aes = FALSE,\n    size = 4.3,\n    fontface = \"bold\",\n    color = \"black\"\n  ) +\n  scale_fill_manual(\n    values = c(\"Control\" = \"#4DBBD5\", \"UC\" = \"#E64B35\"),\n    name = \"Group\"\n  ) +\n  scale_color_manual(\n    values = c(\"Control\" = \"#0073C2\", \"UC\" = \"#CD201F\"),\n    name = \"Group\"\n  ) +\n  scale_y_continuous(\n    expand = expansion(mult = c(0.02, 0.16))\n  ) +\n  labs(\n    title = \"MCP-counter Immune Cell Abundance\",\n    subtitle = paste0(\"Control n = \", countControl, \", UC n = \", countUC),\n    x = NULL,\n    y = \"Abundance score\"\n  ) +\n  theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 18,\n      color = \"black\"\n    ),\n    plot.subtitle = element_text(\n      hjust = 0.5,\n      size = 13,\n      color = \"black\"\n    ),\n    axis.title.y = element_text(\n      face = \"bold\",\n      size = 15,\n      color = \"black\"\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      size = 11,\n      color = \"black\"\n    ),\n    axis.text.y = element_text(\n      size = 12,\n      color = \"black\"\n    ),\n    axis.line = element_line(\n      linewidth = 0.8,\n      color = \"black\"\n    ),\n    axis.ticks = element_line(\n      linewidth = 0.7,\n      color = \"black\"\n    ),\n    legend.position = \"top\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 12\n    ),\n    legend.text = element_text(size = 12),\n    panel.grid = element_blank(),\n    plot.margin = margin(15, 20, 20, 20)\n  ) +\n  coord_cartesian(clip = \"off\")\n\nggsave(\n  filename = \"MCPcounter_Immune_Boxplot_beautified.pdf\",\n  plot = p_mcp_box,\n  width = 11,\n  height = 6.8,\n  units = \"in\"\n)\n\nggsave(\n  fil",
"ename = \"MCPcounter_Immune_Boxplot_beautified.png\",\n  plot = p_mcp_box,\n  width = 11,\n  height = 6.8,\n  units = \"in\",\n  dpi = 300\n)\n\n# \u6a2a\u5411\u7248\u672c\uff0c\u9002\u5408\u8865\u5145\u56fe\np_mcp_box_flip <- p_mcp_box +\n  coord_flip(clip = \"off\") +\n  theme(\n    axis.text.x = element_text(angle = 0, size = 11),\n    axis.text.y = element_text(size = 11, color = \"black\")\n  )\n\nggsave(\n  filename = \"MCPcounter_Immune_Boxplot_beautified_horizontal.pdf\",\n  plot = p_mcp_box_flip,\n  width = 8,\n  height = 7,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"MCPcounter_Immune_Boxplot_beautified_horizontal.png\",\n  plot = p_mcp_box_flip,\n  width = 8,\n  height = 7,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> MCP-counter\u514d\u75ab\u7bb1\u7ebf\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe2\uff1a\u7f8e\u5316\u7248MCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u5806\u53e0\u6761\u5f62\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u7f8e\u5316\u7248MCP-counter\u5806\u53e0\u6761\u5f62\u56fe...\\n\")\n\n# \u6309\u5206\u7ec4\u548c\u6837\u672c\u603b\u4e30\u5ea6\u6392\u5e8f\nsample_order <- data_long %>%\n  group_by(Sample, Group) %>%\n  summarise(total_abundance = sum(Abundance, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(Group, total_abundance) %>%\n  pull(Sample)\n\ndata_long$Sample <- factor(data_long$Sample, levels = sample_order)\n\nimmune_types <- levels(data_long$Immune)\nnColors <- length(immune_types)\nmyColors <- colorRampPalette(brewer.pal(12, \"Set3\"))(nColors)\n\np_mcp_bar <- ggplot(\n  data_long,\n  aes(x = Sample, y = Abundance, fill = Immune)\n) +\n  geom_bar(\n    stat = \"identity\",\n    width = 0.95,\n    color = NA\n  ) +\n  scale_fill_manual(\n    values = myColors,\n    name = \"Immune cell type\"\n  ) +\n  labs(\n    title = \"MCP-counter Immune Cell Abundance Distribution\",\n    subtitle = \"Control vs UC\",\n    x = NULL,\n    y = \"Relative abundance score\"\n  ) +\n  theme_minimal(base_size = 14) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      ",
"size = 17\n    ),\n    plot.subtitle = element_text(\n      hjust = 0.5,\n      size = 12\n    ),\n    axis.text.x = element_blank(),\n    axis.ticks.x = element_blank(),\n    axis.text.y = element_text(\n      color = \"black\",\n      size = 11\n    ),\n    axis.title.y = element_text(\n      face = \"bold\",\n      size = 13\n    ),\n    panel.grid.major.x = element_blank(),\n    panel.grid.minor = element_blank(),\n    legend.position = \"right\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 11\n    ),\n    legend.text = element_text(size = 9),\n    plot.margin = margin(10, 20, 10, 10)\n  )\n\nggsave(\n  filename = \"MCPcounter_Immune_StackedBar_beautified.pdf\",\n  plot = p_mcp_bar,\n  width = 13,\n  height = 7,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"MCPcounter_Immune_StackedBar_beautified.png\",\n  plot = p_mcp_bar,\n  width = 13,\n  height = 7,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> MCP-counter\u5806\u53e0\u6761\u5f62\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u7b2c\u4e09\u90e8\u5206\uff1a\u5173\u952e\u57fa\u56e0\u4e0eMCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u76f8\u5173\u6027\u5206\u6790\uff1a\u7f8e\u5316\u7248\n# ============================================================\n\ncat(\"\\n==== \u7b2c\u4e09\u90e8\u5206\uff1a\u57fa\u56e0-MCPcounter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u76f8\u5173\u6027\u5206\u6790\uff1a\u7f8e\u5316\u7248 ====\\n\")\n\n# ----------------------------\n# 1. \u8bfb\u53d6\u76ee\u6807\u57fa\u56e0\u5217\u8868\n# ----------------------------\ngene_list <- read.csv(\n  gene_list_file,\n  header = TRUE,\n  stringsAsFactors = FALSE,\n  check.names = FALSE\n)\n\ntargetGene <- unique(trimws(as.character(gene_list[, 1])))\ntargetGene <- targetGene[targetGene != \"\" & !is.na(targetGene)]\n\nmatched_genes <- targetGene[targetGene %in% rownames(numExpr)]\n\ncat(\"\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(targetGene), \"\\n\")\ncat(\"\u8868\u8fbe\u77e9\u9635\u4e2d\u5339\u914d\u5230\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(matched_genes), \"\\n\")\n\nif (length(matched_genes) == 0) {\n  stop(\"\u76ee\u6807\u57fa\u56e0\u5728\u8868\u8fbe\u77e9\u9635\u4e2d\u5747\u672a\u5339\u914d\u5230\uff0c\u8bf7\u68c0\u67e5\u57fa\u56e0\u540d\u3002\")\n}\n\nexprSelected <- t(numExpr[matched_genes, , drop = FALSE])\n\n# ----------------------------\n# 2. \u63d0\u53d6\u514d\u75ab\u4e30\u5ea6\u77e9\u9635\n# ---------------------",
"-------\nimmune_cols <- setdiff(colnames(rt), c(\"Sample\", \"Group\"))\n\nimmuneMat <- as.matrix(rt[, immune_cols, drop = FALSE])\nimmuneMat <- apply(immuneMat, 2, as.numeric)\nrownames(immuneMat) <- rownames(rt)\n\n# ----------------------------\n# 3. \u5171\u540c\u6837\u672c\n# ----------------------------\ncommonSamples <- intersect(rownames(exprSelected), rownames(immuneMat))\n\ncat(\"\u5171\u540c\u6837\u672c\u6570\uff1a\", length(commonSamples), \"\\n\")\n\nif (length(commonSamples) < 3) {\n  stop(\"\u5171\u540c\u6837\u672c\u6570\u8fc7\u5c11\uff0c\u65e0\u6cd5\u8fdb\u884c\u76f8\u5173\u6027\u5206\u6790\u3002\")\n}\n\nexprSelected <- exprSelected[commonSamples, , drop = FALSE]\nimmuneMat    <- immuneMat[commonSamples, , drop = FALSE]\n\n# \u53bb\u9664\u6807\u51c6\u5dee\u4e3a0\u7684\u514d\u75ab\u7ec6\u80de\nvalidImmune <- immuneMat[, apply(immuneMat, 2, sd, na.rm = TRUE) > 0, drop = FALSE]\n\ncat(\"\u6709\u6548\u514d\u75ab\u7ec6\u80de\u7c7b\u578b\u6570\uff1a\", ncol(validImmune), \"\\n\")\n\nif (ncol(validImmune) == 0) {\n  stop(\"\u6240\u6709\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u5217\u6807\u51c6\u5dee\u5747\u4e3a0\uff0c\u65e0\u6cd5\u8ba1\u7b97\u76f8\u5173\u6027\u3002\")\n}\n\n# ----------------------------\n# 4. Spearman\u76f8\u5173\u6027\n# ----------------------------\ncor_mat <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\np_val_matrix <- matrix(\n  NA,\n  nrow = ncol(exprSelected),\n  ncol = ncol(validImmune),\n  dimnames = list(colnames(exprSelected), colnames(validImmune))\n)\n\nfor (i in seq_len(ncol(exprSelected))) {\n  for (j in seq_len(ncol(validImmune))) {\n    \n    x <- as.numeric(exprSelected[, i])\n    y <- as.numeric(validImmune[, j])\n    \n    test_result <- tryCatch(\n      cor.test(\n        x,\n        y,\n        method = \"spearman\",\n        use = \"pairwise.complete.obs\",\n        exact = FALSE\n      ),\n      error = function(e) NULL\n    )\n    \n    if (!is.null(test_result)) {\n      cor_mat[i, j] <- as.numeric(test_result$estimate)\n      p_val_matrix[i, j] <- test_result$p.value\n    }\n  }\n}\n\n# ----------------------------\n# 5. \u5bfc\u51fa\u76f8\u5173\u6027\u7ed3\u679c\u957f\u8868\n# ----------------------------\ncorrDF <- data.frame(",
")\n\nfor (i in 1:nrow(cor_mat)) {\n  for (j in 1:ncol(cor_mat)) {\n    \n    p_now <- p_val_matrix[i, j]\n    cor_now <- cor_mat[i, j]\n    \n    sig_now <- ifelse(\n      is.na(p_now), \"\",\n      ifelse(\n        p_now < 0.001, \"***\",\n        ifelse(\n          p_now < 0.01, \"**\",\n          ifelse(p_now < 0.05, \"*\", \"\")\n        )\n      )\n    )\n    \n    corrDF <- rbind(\n      corrDF,\n      data.frame(\n        Gene = rownames(cor_mat)[i],\n        ImmuneCell = colnames(cor_mat)[j],\n        Correlation = cor_now,\n        P.Value = p_now,\n        Significance = sig_now,\n        stringsAsFactors = FALSE\n      )\n    )\n  }\n}\n\ncorrDF$AbsCorrelation <- abs(corrDF$Correlation)\n\nwrite.csv(\n  corrDF,\n  file = \"MCPcounter_Gene_Immune_Correlation_Results_beautified.csv\",\n  row.names = FALSE\n)\n\ncat(\">> MCP-counter\u76f8\u5173\u6027\u7ed3\u679c\u8868\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe3\uff1a\u7f8e\u5316\u7248\u76f8\u5173\u6027\u70ed\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236MCP-counter\u76f8\u5173\u6027\u70ed\u56fe...\\n\")\n\nlabels_star <- matrix(\n  \"\",\n  nrow = nrow(cor_mat),\n  ncol = ncol(cor_mat),\n  dimnames = dimnames(cor_mat)\n)\n\nfor (i in 1:nrow(p_val_matrix)) {\n  for (j in 1:ncol(p_val_matrix)) {\n    p_now <- p_val_matrix[i, j]\n    if (!is.na(p_now)) {\n      if (p_now < 0.001) labels_star[i, j] <- \"***\"\n      else if (p_now < 0.01) labels_star[i, j] <- \"**\"\n      else if (p_now < 0.05) labels_star[i, j] <- \"*\"\n    }\n  }\n}\n\nheat_cols <- colorRampPalette(c(\"#2166AC\", \"white\", \"#B2182B\"))(100)\n\ngene_num <- nrow(cor_mat)\nimmune_num <- ncol(cor_mat)\n\npdf_width  <- max(8, 4 + 0.55 * immune_num)\npdf_height <- max(5, 2.5 + 0.55 * gene_num)\n\npdf(\n  file = \"MCPcounter_Gene_Immune_Correlation_Heatmap_beautified.pdf\",\n  width = pdf_width,\n  height = pdf_height\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1",
", length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color = \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and MCP-counter Immune Cells\"\n)\n\ndev.off()\n\npng(\n  file = \"MCPcounter_Gene_Immune_Correlation_Heatmap_beautified.png\",\n  width = pdf_width,\n  height = pdf_height,\n  units = \"in\",\n  res = 300\n)\n\npheatmap(\n  cor_mat,\n  color = heat_cols,\n  breaks = seq(-1, 1, length.out = 101),\n  display_numbers = labels_star,\n  number_color = \"black\",\n  fontsize_number = 11,\n  fontsize_row = 12,\n  fontsize_col = 10,\n  cluster_rows = FALSE,\n  cluster_cols = TRUE,\n  border_color = \"grey85\",\n  angle_col = 45,\n  main = \"Correlation between Diagnostic Genes and MCP-counter Immune Cells\"\n)\n\ndev.off()\n\ncat(\">> MCP-counter\u76f8\u5173\u6027\u70ed\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe4\uff1a\u7f8e\u5316\u7248\u5706\u5f62\u6c14\u6ce1\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236MCP-counter\u76f8\u5173\u6027\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_df <- corrDF %>%\n  filter(!is.na(Correlation), !is.na(P.Value))\n\nbubble_df$Gene <- factor(\n  bubble_df$Gene,\n  levels = matched_genes[matched_genes %in% unique(bubble_df$Gene)]\n)\n\nimmune_order_cor <- bubble_df %>%\n  group_by(ImmuneCell) %>%\n  summarise(mean_cor = mean(Correlation, na.rm = TRUE), .groups = \"drop\") %>%\n  arrange(mean_cor) %>%\n  pull(ImmuneCell)\n\nbubble_df$ImmuneCell <- factor(\n  bubble_df$ImmuneCell,\n  levels = immune_order_cor\n)\n\nbubble_df$SigLabel <- ifelse(\n  bubble_df$P.Value < 0.001, \"***\",\n  ifelse(\n    bubble_df$P.Value < 0.01, \"**\",\n    ifelse(bubble_df$P.Value < 0.05, \"*\", \"\")\n  )\n)\n\nmax_abs_cor <- max(abs(bubble_df$Correlation), na.rm = TRUE)\n\nfig_width  <- max(7, 3.5 + length(",
"unique(bubble_df$Gene)) * 0.8)\nfig_height <- max(5.5, 2.5 + length(unique(bubble_df$ImmuneCell)) * 0.45)\n\np_mcp_bubble <- ggplot(\n  bubble_df,\n  aes(x = Gene, y = ImmuneCell)\n) +\n  geom_point(\n    aes(size = AbsCorrelation, fill = Correlation),\n    shape = 21,\n    color = \"grey25\",\n    stroke = 0.25,\n    alpha = 0.95\n  ) +\n  geom_text(\n    aes(label = SigLabel),\n    size = 3.4,\n    color = \"black\",\n    fontface = \"bold\"\n  ) +\n  scale_fill_gradient2(\n    low = \"#2166AC\",\n    mid = \"white\",\n    high = \"#B2182B\",\n    midpoint = 0,\n    limits = c(-max_abs_cor, max_abs_cor),\n    name = \"Spearman\\ncorrelation\"\n  ) +\n  scale_size_continuous(\n    range = c(3, 10),\n    name = \"|Correlation|\"\n  ) +\n  labs(\n    title = \"Gene\u2013MCP-counter Immune Cell Correlation\",\n    x = NULL,\n    y = NULL\n  ) +\n  theme_bw(base_size = 13) +\n  theme(\n    plot.title = element_text(\n      hjust = 0.5,\n      face = \"bold\",\n      size = 17\n    ),\n    axis.text.x = element_text(\n      angle = 45,\n      hjust = 1,\n      vjust = 1,\n      face = \"bold.italic\",\n      color = \"black\",\n      size = 11\n    ),\n    axis.text.y = element_text(\n      color = \"black\",\n      size = 11\n    ),\n    panel.grid.major = element_line(\n      color = \"grey88\",\n      linewidth = 0.35\n    ),\n    panel.grid.minor = element_blank(),\n    panel.border = element_rect(\n      color = \"black\",\n      fill = NA,\n      linewidth = 0.8\n    ),\n    legend.position = \"right\",\n    legend.title = element_text(\n      face = \"bold\",\n      size = 11\n    ),\n    legend.text = element_text(size = 10),\n    plot.margin = margin(10, 15, 10, 10)\n  )\n\nggsave(\n  filename = \"MCPcounter_Gene_Immune_Correlation_Bubble_beautified.pdf\",\n  plot = p_mcp_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\"\n)\n\nggsave(\n  filename = \"MCPcounter_Gene_Imm",
"une_Correlation_Bubble_beautified.png\",\n  plot = p_mcp_bubble,\n  width = fig_width,\n  height = fig_height,\n  units = \"in\",\n  dpi = 300\n)\n\ncat(\">> MCP-counter\u76f8\u5173\u6027\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n\n\n# ============================================================\n# \u56fe5\uff1a\u53ea\u663e\u793a\u663e\u8457\u76f8\u5173\u7684\u6c14\u6ce1\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236MCP-counter\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe...\\n\")\n\nbubble_sig <- bubble_df %>%\n  filter(P.Value < 0.05)\n\nif (nrow(bubble_sig) > 0) {\n  \n  bubble_sig$Gene <- factor(\n    bubble_sig$Gene,\n    levels = levels(bubble_df$Gene)\n  )\n  \n  bubble_sig$ImmuneCell <- factor(\n    bubble_sig$ImmuneCell,\n    levels = levels(bubble_df$ImmuneCell)\n  )\n  \n  fig_width_sig  <- max(6.5, 3.5 + length(unique(bubble_sig$Gene)) * 0.85)\n  fig_height_sig <- max(4.8, 2.5 + length(unique(bubble_sig$ImmuneCell)) * 0.45)\n  \n  p_mcp_bubble_sig <- ggplot(\n    bubble_sig,\n    aes(x = Gene, y = ImmuneCell)\n  ) +\n    geom_point(\n      aes(size = AbsCorrelation, fill = Correlation),\n      shape = 21,\n      color = \"grey20\",\n      stroke = 0.25,\n      alpha = 0.95\n    ) +\n    geom_text(\n      aes(label = SigLabel),\n      size = 3.5,\n      color = \"black\",\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(3.2, 10),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      title = \"Significant Gene\u2013MCP-counter Immune Cell Correlations\",\n      x = NULL,\n      y = NULL\n    ) +\n    theme_bw(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 16\n      ),\n      axis.text.x = element_text(\n        angle = 45,\n        hjust = 1,\n ",
"       vjust = 1,\n        face = \"bold.italic\",\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      panel.grid.major = element_line(\n        color = \"grey88\",\n        linewidth = 0.35\n      ),\n      panel.grid.minor = element_blank(),\n      panel.border = element_rect(\n        color = \"black\",\n        fill = NA,\n        linewidth = 0.8\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 11\n      ),\n      legend.text = element_text(size = 10),\n      plot.margin = margin(10, 15, 10, 10)\n    )\n  \n  ggsave(\n    filename = \"MCPcounter_Gene_Immune_Correlation_Bubble_significant_only.pdf\",\n    plot = p_mcp_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\"\n  )\n  \n  ggsave(\n    filename = \"MCPcounter_Gene_Immune_Correlation_Bubble_significant_only.png\",\n    plot = p_mcp_bubble_sig,\n    width = fig_width_sig,\n    height = fig_height_sig,\n    units = \"in\",\n    dpi = 300\n  )\n  \n  cat(\">> MCP-counter\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u3002\\n\")\n  \n} else {\n  cat(\">> \u6ca1\u6709P < 0.05\u7684\u663e\u8457\u76f8\u5173\u5173\u7cfb\uff0c\u8df3\u8fc7\u663e\u8457\u76f8\u5173\u6c14\u6ce1\u56fe\u3002\\n\")\n}\n\n\n# ============================================================\n# \u56fe6\uff1a\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684MCP-counter\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe\n# ============================================================\n\ncat(\">> \u7ed8\u5236\u6bcf\u4e2a\u57fa\u56e0\u5355\u72ec\u7684MCP-counter\u76f8\u5173\u6027\u68d2\u68d2\u7cd6\u56fe...\\n\")\n\nlollipop_dir <- \"MCPcounter_Gene_Immune_Lollipop_Plots\"\n\nif (!dir.exists(lollipop_dir)) {\n  dir.create(lollipop_dir)\n}\n\nfor (g in unique(as.character(bubble_df$Gene))) {\n  \n  plot_g <- bubble_df %>%\n    filter(Gene == g) %>%\n    arrange(Correlation)\n  \n  plot_g$ImmuneCell <- factor(plot_g$ImmuneCell, levels = plot_g$ImmuneCell)\n  \n  p_lollipop <- ggplot(plot_g, aes(x = Correlation, y = ImmuneCell)) +\n    geom_vline(\n      xinterc",
"ept = 0,\n      linetype = \"dashed\",\n      color = \"grey50\",\n      linewidth = 0.7\n    ) +\n    geom_segment(\n      aes(x = 0, xend = Correlation, y = ImmuneCell, yend = ImmuneCell),\n      color = \"grey60\",\n      linewidth = 0.8\n    ) +\n    geom_point(\n      aes(fill = Correlation, size = AbsCorrelation),\n      shape = 21,\n      color = \"black\",\n      stroke = 0.25\n    ) +\n    geom_text(\n      aes(label = ifelse(P.Value < 0.05, SigLabel, \"\")),\n      nudge_x = 0.05,\n      size = 4,\n      fontface = \"bold\"\n    ) +\n    scale_fill_gradient2(\n      low = \"#2166AC\",\n      mid = \"white\",\n      high = \"#B2182B\",\n      midpoint = 0,\n      limits = c(-max_abs_cor, max_abs_cor),\n      name = \"Spearman\\ncorrelation\"\n    ) +\n    scale_size_continuous(\n      range = c(3, 8),\n      name = \"|Correlation|\"\n    ) +\n    labs(\n      title = paste0(g, \" - MCP-counter Immune Cell Correlation\"),\n      x = \"Spearman correlation\",\n      y = NULL\n    ) +\n    theme_classic(base_size = 13) +\n    theme(\n      plot.title = element_text(\n        hjust = 0.5,\n        face = \"bold\",\n        size = 15\n      ),\n      axis.title.x = element_text(\n        face = \"bold\",\n        size = 13\n      ),\n      axis.text.x = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      axis.text.y = element_text(\n        color = \"black\",\n        size = 11\n      ),\n      legend.position = \"right\",\n      legend.title = element_text(\n        face = \"bold\",\n        size = 10\n      ),\n      legend.text = element_text(size = 9)\n    )\n  \n  safe_g <- gsub(\"[^A-Za-z0-9_]\", \"_\", g)\n  \n  ggsave(\n    filename = file.path(lollipop_dir, paste0(safe_g, \"_MCPcounter_Immune_Correlation_Lollipop.pdf\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(4.8, 2.2 + nrow(plot_g) * 0.35),\n    units = \"in\"\n  )\n  \n  ggsave(\n ",
"   filename = file.path(lollipop_dir, paste0(safe_g, \"_MCPcounter_Immune_Correlation_Lollipop.png\")),\n    plot = p_lollipop,\n    width = 7,\n    height = max(4.8, 2.2 + nrow(plot_g) * 0.35),\n    units = \"in\",\n    dpi = 300\n  )\n}\n\ncat(\">> \u5355\u57fa\u56e0MCP-counter\u68d2\u68d2\u7cd6\u56fe\u5df2\u4fdd\u5b58\u81f3\u6587\u4ef6\u5939\uff1aMCPcounter_Gene_Immune_Lollipop_Plots\\n\")\n\ncat(\"\\n==== MCP-counter\u514d\u75ab\u4e30\u5ea6\u5206\u6790\u4e0e\u7f8e\u5316\u7ed8\u56fe\u5168\u90e8\u5b8c\u6210\uff01====\\n\")"),
"immune/fig07_cohort_sensitivity.R"=paste0("# Cohort-wise box plots adapted from the two original Figure 5 R scripts.\n# Run from the directory containing this script and its data folder.\n\nsuppressPackageStartupMessages({\n  library(ggplot2)\n  library(dplyr)\n  library(reshape2)\n  library(patchwork)\n})\n\nargs <- commandArgs(trailingOnly = TRUE)\noutput_dir <- if (length(args)) args[[1]] else \".\"\ndir.create(output_dir, recursive = TRUE, showWarnings = FALSE)\n\ncohorts <- c(\"GSE87466\", \"GSE206285\")\nall_samples <- \"all\"\nfit_subset <- \"permutation_P_lt_0.05\"\nsubtypes <- paste(\"Macrophages\", c(\"M0\", \"M1\", \"M2\"))\nlineage <- \"Monocytic lineage\"\ngroup_levels <- c(\"Control\", \"UC\")\nfill_colors <- c(Control = \"#4DBBD5\", UC = \"#E64B35\")\noutline_colors <- c(Control = \"#0073C2\", UC = \"#CD201F\")\njitter_seed <- 20261121L\n\nread_scores <- function(cohort, method) {\n  file <- file.path(\"data\", paste0(cohort, \"_\", method, \".csv\"))\n  scores <- read.csv(file, check.names = FALSE, fileEncoding = \"UTF-8-BOM\")\n  stopifnot(all(scores$Group %in% group_levels), !anyDuplicated(scores$Sample))\n  scores$Cohort <- cohort\n  scores$Group <- factor(scores$Group, levels = group_levels)\n  scores\n}\n\nciber_scores <- bind_rows(lapply(cohorts, read_scores, method = \"cibersort\"))\nmcp_scores <- bind_rows(lapply(cohorts, read_scores, method = \"mcpcounter\"))\ncomparisons <- read.csv(file.path(\"data\", \"group_comparisons.csv\"),\n                       check.names = FALSE, fileEncoding = \"UTF-8-BOM\")\nnames(comparisons)[names(comparisons) == \"cell\"] <- \"Immune\"\n\nciber_data <- bind_rows(\n  mutate(ciber_scores, selection = all_samples),\n  mutate(filter(ciber_scores, .data[[\"P-value\"]] < 0.05), selection = fit_subset)\n) %>%\n  melt(id.vars = c(\"Sample\", \"Cohort\", \"Group\", \"selection\"),\n       measure.vars = subtypes,\n       variable.name = \"Immune\", value.name = \"Fraction\"",
")\nciber_data$Immune <- factor(ciber_data$Immune, levels = subtypes)\n\nmcp_data <- mcp_scores %>%\n  mutate(selection = all_samples) %>%\n  melt(id.vars = c(\"Sample\", \"Cohort\", \"Group\", \"selection\"),\n       measure.vars = lineage, variable.name = \"Immune\", value.name = \"Abundance\")\n\ngroup_labels <- function(data, score_name, method, extra_height) {\n  tests <- filter(comparisons, .data$method == .env$method)\n  labels <- data %>%\n    group_by(Cohort, selection, Immune) %>%\n    summarise(\n      count_UC = sum(Group == \"UC\"),\n      count_control = sum(Group == \"Control\"),\n      median_UC_plot = median(.data[[score_name]][Group == \"UC\"]),\n      median_control_plot = median(.data[[score_name]][Group == \"Control\"]),\n      y.position = max(.data[[score_name]]) * 1.08 + extra_height,\n      .groups = \"drop\"\n    ) %>%\n    left_join(tests, by = c(\"Cohort\", \"selection\", \"Immune\")) %>%\n    mutate(Significance = case_when(\n      BH_P < 0.001 ~ \"***\",\n      BH_P < 0.01 ~ \"**\",\n      BH_P < 0.05 ~ \"*\",\n      TRUE ~ \"ns\"\n    ))\n  stopifnot(all(is.finite(labels$BH_P)),\n            all(labels$n_UC == labels$count_UC),\n            all(labels$n_Control == labels$count_control),\n            all(abs(labels$median_UC - labels$median_UC_plot) < 1e-12),\n            all(abs(labels$median_Control - labels$median_control_plot) < 1e-12))\n  labels\n}\n\nciber_labels <- group_labels(ciber_data, \"Fraction\", \"CIBERSORT\", 0.01)\nmcp_labels <- group_labels(mcp_data, \"Abundance\", \"MCP-counter\", 0)\n\nciber_panels <- ciber_labels %>%\n  distinct(Cohort, selection, n_Control, n_UC) %>%\n  arrange(match(selection, c(all_samples, fit_subset)), match(Cohort, cohorts)) %>%\n  mutate(Panel = paste0(\n    Cohort, \"  |  \", if_else(selection == all_samples, \"All included samples\", \"Fit P < 0.05\"),\n    \"\\nControl n = \", n_Control, ",
"\", UC n = \", n_UC\n  ))\nmcp_panels <- mcp_labels %>%\n  distinct(Cohort, selection, n_Control, n_UC) %>%\n  arrange(match(Cohort, cohorts)) %>%\n  mutate(Panel = paste0(Cohort, \"\\nControl n = \", n_Control, \", UC n = \", n_UC))\n\nset_panels <- function(data, panels) {\n  data %>%\n    left_join(select(panels, Cohort, selection, Panel), by = c(\"Cohort\", \"selection\")) %>%\n    mutate(Panel = factor(Panel, levels = panels$Panel))\n}\nciber_data <- set_panels(ciber_data, ciber_panels)\nciber_labels <- set_panels(ciber_labels, ciber_panels)\nmcp_data <- set_panels(mcp_data, mcp_panels)\nmcp_labels <- set_panels(mcp_labels, mcp_panels)\n\n# Keep the original figures' boxplot and jitter layers, colors, and black axes.\n# In the sensitivity figure the original significance symbols use BH-adjusted P.\nbox_layers <- function(box_alpha, jitter_width, point_size, point_alpha) {\n  list(\n    geom_boxplot(\n      aes(color = Group),\n      position = position_dodge(width = 0.75),\n      width = 0.58, outlier.shape = NA, alpha = box_alpha, linewidth = 0.65\n    ),\n    geom_jitter(\n      aes(color = Group),\n      position = position_jitterdodge(\n        jitter.width = jitter_width, dodge.width = 0.75, seed = jitter_seed\n      ),\n      size = point_size, alpha = point_alpha\n    ),\n    scale_fill_manual(values = fill_colors, name = \"Group\"),\n    scale_color_manual(values = outline_colors, name = \"Group\")\n  )\n}\n\nfigure_theme <- theme_classic(base_size = 14) +\n  theme(\n    plot.title = element_text(hjust = 0.5, face = \"bold\", size = 16, color = \"black\"),\n    plot.title.position = \"plot\",\n    plot.tag = element_text(family = \"serif\", size = 23, hjust = 0, vjust = 1, color = \"black\"),\n    plot.tag.position = c(0.016, 0.985),\n    strip.background = element_blank(),\n    strip.text = element_text(size = 11, color = \"b",
"lack\", lineheight = 0.95),\n    axis.title = element_text(face = \"bold\", size = 13, color = \"black\"),\n    axis.text = element_text(size = 11, color = \"black\"),\n    axis.line = element_line(linewidth = 0.8, color = \"black\"),\n    axis.ticks = element_line(linewidth = 0.7, color = \"black\"),\n    legend.position = \"top\",\n    legend.title = element_text(face = \"bold\", size = 12),\n    legend.text = element_text(size = 12),\n    panel.grid = element_blank(),\n    panel.spacing.x = grid::unit(1.3, \"lines\"),\n    panel.spacing.y = grid::unit(0.9, \"lines\"),\n    plot.margin = margin(9, 13, 5, 9)\n  )\n\np_cibersort <- ggplot(ciber_data, aes(x = Immune, y = Fraction, fill = Group)) +\n  box_layers(0.70, 0.12, 0.65, 0.35) +\n  geom_text(\n    data = ciber_labels,\n    aes(x = Immune, y = y.position, label = Significance),\n    inherit.aes = FALSE, size = 4.2, fontface = \"bold\", color = \"black\"\n  ) +\n  scale_x_discrete(labels = c(\"M0\", \"M1\", \"M2\")) +\n  scale_y_continuous(expand = expansion(mult = c(0.02, 0.11))) +\n  facet_wrap(vars(Panel), ncol = 2, axes = \"all_x\") +\n  labs(tag = \"A\", title = \"CIBERSORT macrophage fractions\", x = NULL,\n       y = \"Estimated fraction\") +\n  figure_theme +\n  coord_cartesian(clip = \"off\")\n\np_mcpcounter <- ggplot(mcp_data, aes(x = Immune, y = Abundance, fill = Group)) +\n  box_layers(0.72, 0.10, 0.45, 0.22) +\n  geom_text(\n    data = mcp_labels,\n    aes(x = Immune, y = y.position, label = Significance),\n    inherit.aes = FALSE, size = 4.3, fontface = \"bold\", color = \"black\"\n  ) +\n  scale_y_continuous(expand = expansion(mult = c(0.02, 0.14))) +\n  facet_wrap(vars(Panel), ncol = 2) +\n  labs(tag = \"B\", title = \"MCP-counter immune cell abundance\", x = NULL,\n       y = \"Abundance score\") +\n  figure_theme +\n  theme(legend.position = \"none\", plot.margin = margin(11, 13, 8, 9)) ",
"+\n  coord_flip(clip = \"off\")\n\nfigure <- wrap_plots(free(p_cibersort, side = \"l\"), p_mcpcounter,\n                     ncol = 1, heights = c(3.15, 1))\npdf_path <- file.path(output_dir, \"Supplementary_Figure_6.pdf\")\npng_path <- file.path(output_dir, \"Supplementary_Figure_6.png\")\nggsave(pdf_path, figure, device = grDevices::cairo_pdf, width = 8.5,\n       height = 7.15, units = \"in\", bg = \"white\")\nggsave(png_path, figure, device = ragg::agg_png, width = 8.5,\n       height = 7.15, units = \"in\", dpi = 600, bg = \"white\")\n\nbind_rows(select(ciber_labels, Cohort, selection, Immune, n_Control, n_UC, BH_P, Significance),\n          select(mcp_labels, Cohort, selection, Immune, n_Control, n_UC, BH_P, Significance)) %>%\n  arrange(match(selection, c(all_samples, fit_subset)), match(Cohort, cohorts), Immune) %>%\n  print(n = Inf)\n"),
"legacy_analysis/02.GEO\u6570\u636e\u4e0b\u8f7d -\u7b2c1\u4e2a/GSE206285/01GEO\u6570\u636e\u5904\u7406.\u6709gene symbol\u60c5\u51b5.R"=paste0("# 1. \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\nsetwd(\"C:\\\\Users\\\\yb\\\\Desktop\\\\GSE206285\")  # \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\n\n# 2. \u8bbe\u7f6e\u53c2\u6570\uff1a\u7528\u6237\u6307\u5b9a\u57fa\u56e0\u4fe1\u606f\u6240\u5728\u884c\u6570\uff08\u4f8b\u5982\u7b2c11\u884c\uff09\u5e76\u8f6c\u6362\u4e3a0\u8d77\u59cb\u7d22\u5f15\ninputRow <- 11                              # \u7528\u6237\u6307\u5b9a\u4f7f\u7528\u7b2c?\u884c\u6570\u636e\uff081\u8d77\u59cb\uff09\ntargetColIdx <- inputRow - 1                  # \u8f6c\u6362\u4e3a0\u8d77\u59cb\u7d22\u5f15\uff0c\u7528\u4e8e\u5e73\u53f0\u6587\u4ef6\u4e2d\u76ee\u6807\u5217\u5b9a\u4f4d\n\n# 3. \u5b9a\u4e49\u6570\u636e\u6587\u4ef6\u53ca\u8f93\u51fa\u6587\u4ef6\u7684\u8def\u5f84\nexprFilePath <- \"GSE.txt\"                     # \u8868\u8fbe\u6570\u636e\u6587\u4ef6\u8def\u5f84\nplatformFilePath <- \"GPL.txt\"                 # \u5e73\u53f0\u6587\u4ef6\u8def\u5f84\uff08\u542b\u63a2\u9488\u4e0e\u57fa\u56e0\u4fe1\u606f\uff09\noutputFilePath <- \"geneMatrix.txt\"            # \u6700\u7ec8\u8f93\u51fa\u6587\u4ef6\u8def\u5f84\n\n# 4. \u8bfb\u53d6\u8868\u8fbe\u6570\u636e\u6587\u4ef6\uff08GSE.txt\uff09\ncat(\"\u6b63\u5728\u52a0\u8f7d\u8868\u8fbe\u6570\u636e\u6587\u4ef6\uff1a\", exprFilePath, \"...\\n\")  # \u8f93\u51fa\u63d0\u793a\u4fe1\u606f\nexprData <- read.delim(exprFilePath,          # \u8bfb\u53d6\u6587\u4ef6\n                       header = TRUE,          # \u7b2c\u4e00\u884c\u4e3a\u8868\u5934\n                       sep = \"\\t\",             # \u4f7f\u7528\u5236\u8868\u7b26\u5206\u9694\n                       quote = \"\\\"\",           # \u4f7f\u7528\u53cc\u5f15\u53f7\u5305\u88f9\u5b57\u7b26\u578b\u6570\u636e\n                       comment.char = \"!\")     # \u5ffd\u7565\u4ee5\"!\"\u5f00\u5934\u7684\u6ce8\u91ca\u884c\ncolnames(exprData)[1] <- \"ProbeID\"            # \u5c06\u7b2c\u4e00\u5217\u91cd\u547d\u540d\u4e3a \"ProbeID\"\ncat(\"\u8868\u8fbe\u6570\u636e\u52a0\u8f7d\u5b8c\u6210\uff0c\u5171\", ncol(exprData)-1, \"\u4e2a\u6837\u672c\u3002\\n\")  # \u8f93\u51fa\u6837\u672c\u6570\uff08\u51cf\u53bb\u63a2\u9488ID\u5217\uff09\n\n# 5. \u8bfb\u53d6\u5e73\u53f0\u6587\u4ef6\uff08GPL.txt\uff09\ncat(\"\u6b63\u5728\u52a0\u8f7d\u5e73\u53f0\u6587\u4ef6\uff1a\", platformFilePath, \"...\\n\")  # \u8f93\u51fa\u63d0\u793a\u4fe1\u606f\nplatformData <- read.delim(platformFilePath,    # \u8bfb\u53d6\u5e73\u53f0\u6587\u4ef6\n                           header = FALSE,        # \u65e0\u8868\u5934\n                           sep = \"\\t\",            # \u4ee5\u5236\u8868\u7b26\u5206\u9694\n                           quote = \"\\\"\",          # \u4f7f\u7528\u53cc\u5f15\u53f7\u5305\u88f9\u5b57\u7b26\u578b\u6570\u636e\n                           comment.char = \"#\",    # \u5ffd\u7565\u4ee5\"#\"\u5f00\u5934\u7684\u6ce8\u91ca\u884c\n                           stringsAsFactors = FALSE)  # \u4e0d\u5c06\u5b57\u7b26\u8f6c\u6362\u4e3a\u56e0\u5b50\n\n# 6. \u6784\u5efa\u63a2\u9488\u4e0e\u57fa\u56e0\u7b26\u53f7\u6620\u5c04\uff08\u9010\u884c\u5904\u7406\u5e76\u663e\u793a\u8fdb\u5ea6\uff09\ncat(\"\u5f00\u59cb\u5904\u7406\u5e73\u53f0\u6587\u4ef6\u6570\u636e...\\n\")         # \u8f93\u51fa\u63d0\u793a\u4fe1\u606f\ntotalRows <- nrow(platformData)               # \u83b7\u53d6\u5e73\u53f0\u6587\u4ef6\u603b\u884c\u6570\ngeneMapping <- list()                         # \u521d\u59cb\u5316\u7a7a\u5217\u8868\u7528\u4e8e\u5b58\u50a8\u6620\u5c04\uff1a\u63a2\u9488ID -> \u57fa\u56e0\u7b26\u53f7\npbPlat <- txtProgressBar(min = 0, max = totalRows, style = 3)  # \u521b\u5efa\u8fdb\u5ea6\u6761\uff0c\u8303\u56f4\u4ece0\u5230\u603b\u884c\u6570\n\nfor (row in 1:totalRows) {                     # \u904d\u5386\u5e73\u53f0\u6587\u4ef6\u7684\u6bcf\u4e00\u884c\n  # \u82e5\u6574\u884c\u5168\u4e3a\u7a7a\uff0c\u6216\u7b2c\u4e00\u5217\u4ee5 \"ID\" \u6216 \"!\" \u5f00\u5934\uff0c\u5219\u8df3\u8fc7\u8be5\u884c\n  if (all(platformData[row, ] == \"\") || g",
"repl(\"^(ID|\\\\!)\", platformData[row, 1])) {\n    setTxtProgressBar(pbPlat, row)             # \u66f4\u65b0\u8fdb\u5ea6\u6761\n    next\n  }\n  \n  # \u68c0\u67e5\u5f53\u524d\u884c\u662f\u5426\u5305\u542b\u76ee\u6807\u5217\uff08targetColIdx + 1\uff09\n  if (ncol(platformData) >= (targetColIdx + 1)) {\n    rawGene <- platformData[row, targetColIdx + 1]  # \u63d0\u53d6\u76ee\u6807\u5217\u7684\u539f\u59cb\u57fa\u56e0\u4fe1\u606f\n    # \u5982\u679c\u539f\u59cb\u4fe1\u606f\u975e\u7a7a\u4e14\u4e0d\u5305\u542b\u7a7a\u683c\uff08\u53ea\u5305\u542b\u4e00\u4e2a\u5355\u8bcd\uff09\n    if (rawGene != \"\" && !grepl(\".+\\\\s+.+\", rawGene)) {\n      # \u82e5\u5305\u542b\"///\"\uff0c\u53ea\u53d6\u5de6\u4fa7\u90e8\u5206\uff1b\u540c\u65f6\u53bb\u9664\u5f15\u53f7\n      cleanGene <- sub(\"(.+?)///(.+)\", \"\\\\1\", rawGene)\n      cleanGene <- gsub('\"', '', cleanGene)\n      # \u5efa\u7acb\u6620\u5c04\uff1a\u5c06\u5f53\u524d\u884c\u7b2c\u4e00\u5217\uff08\u63a2\u9488ID\uff09\u6620\u5c04\u5230\u5904\u7406\u540e\u7684\u57fa\u56e0\u7b26\u53f7\n      geneMapping[[ as.character(platformData[row, 1]) ]] <- cleanGene\n    }\n  }\n  setTxtProgressBar(pbPlat, row)             # \u66f4\u65b0\u8fdb\u5ea6\u6761\n}\nclose(pbPlat)                                 # \u5173\u95ed\u8fdb\u5ea6\u6761\ncat(\"\\n\u5e73\u53f0\u6587\u4ef6\u5904\u7406\u5b8c\u6210\uff0c\u6210\u529f\u5efa\u7acb\u6620\u5c04\u6570\uff1a\", length(geneMapping), \"\\n\")  # \u8f93\u51fa\u6620\u5c04\u5efa\u7acb\u5b8c\u6210\u4fe1\u606f\n\n# 7. \u5408\u5e76\u8868\u8fbe\u6570\u636e\u4e0e\u5e73\u53f0\u6620\u5c04\u6570\u636e\ncat(\"\u6b63\u5728\u5408\u5e76\u8868\u8fbe\u6570\u636e\u4e0e\u5e73\u53f0\u6620\u5c04\u6570\u636e...\\n\")  # \u8f93\u51fa\u63d0\u793a\u4fe1\u606f\n# \u4ece\u8868\u8fbe\u6570\u636e\u4e2d\u63d0\u53d6\u63a2\u9488ID\u5217\u5e76\u4fdd\u5b58\nprobeIDs <- exprData[[\"ProbeID\"]]\n# \u53d6\u51fa\u9664\u63a2\u9488ID\u4ee5\u5916\u7684\u8868\u8fbe\u6570\u636e\u90e8\u5206\nexprDataCore <- exprData[, -1, drop = FALSE]\n# \u6784\u9020\u6570\u636e\u6846\uff0c\u7528\u4e8e\u540e\u7eed\u5408\u5e76\uff1a\u5c06ProbeID\u4e0e\u8868\u8fbe\u6570\u636e\u4e00\u8d77\u4f7f\u7528\nexprDataWithID <- exprData\n# \u5c06\u5e73\u53f0\u6620\u5c04\u8f6c\u6362\u4e3a\u6570\u636e\u6846\uff0c\u5305\u542b\u63a2\u9488ID\u548c\u5bf9\u5e94\u7684\u57fa\u56e0\u7b26\u53f7\nmappingDF <- data.frame(ProbeID = names(geneMapping),\n                        geneSymbol = unlist(geneMapping),\n                        stringsAsFactors = FALSE)\n# \u5229\u7528 merge \u51fd\u6570\u6309\"ProbeID\"\u5339\u914d\uff0c\u5408\u5e76\u8868\u8fbe\u6570\u636e\u4e0e\u57fa\u56e0\u6620\u5c04\u4fe1\u606f\nmergedData <- merge(exprDataWithID, mappingDF, by = \"ProbeID\")\ncat(\"\u5408\u5e76\u5b8c\u6210\uff0c\u5171\u83b7\u5f97\", nrow(mergedData), \"\u884c\u6709\u6548\u6570\u636e\u3002\\n\")  # \u8f93\u51fa\u5408\u5e76\u540e\u6570\u636e\u884c\u6570\n\n# 8. \u6309\u57fa\u56e0\u5206\u7ec4\uff0c\u8ba1\u7b97\u5404\u6837\u672c\u7684\u5e73\u5747\u8868\u8fbe\u503c\uff08\u9010\u57fa\u56e0\u5904\u7406\u663e\u793a\u8fdb\u5ea6\uff09\ncat(\"\u6b63\u5728\u6309\u57fa\u56e0\u5206\u7ec4\u5e76\u8ba1\u7b97\u5404\u6837\u672c\u5e73\u5747\u8868\u8fbe\u503c...\\n\")  # \u8f93\u51fa\u63d0\u793a\u4fe1\u606f\n# \u83b7\u53d6\u6240\u6709\u6837\u672c\u5217\u540d\u79f0\uff08\u6392\u9664ProbeID\u548c\u65b0\u5408\u5e76\u7684geneSymbol\u5217\uff09\nsampleCols <- setdiff(colnames(mergedData), c(\"ProbeID\", \"geneSymbol\"))\n# \u6839\u636e\u57fa\u56e0\u7b26\u53f7\u5bf9\u6570\u636e\u8fdb\u884c\u5206\u7ec4\ngeneGroups <- split(mergedData, mergedData$geneSymbol)\n# \u83b7\u53d6\u6240\u6709\u4e0d\u540c\u57fa\u56e0\u540d\u79f0\ngeneNamesUnique <- names(geneGroups)\ntotalGenes <- length(geneNamesUnique)         # \u603b\u57fa\u56e0\u6570\nresultList <- vector(\"list\", totalGenes)        # \u521d\u59cb\u5316\u5217\u8868\u4fdd\u5b58\u8ba1\u7b97\u7ed3\u679c\npbAgg <- tx",
"tProgressBar(min = 0, max = totalGenes, style = 3)  # \u521b\u5efa\u805a\u5408\u8fdb\u5ea6\u6761\n\nfor (i in seq_along(geneNamesUnique)) {         # \u904d\u5386\u6bcf\u4e2a\u57fa\u56e0\u7ec4\n  geneName <- geneNamesUnique[i]                # \u5f53\u524d\u57fa\u56e0\u540d\u79f0\n  groupData <- geneGroups[[i]]                  # \u53d6\u51fa\u8be5\u57fa\u56e0\u5bf9\u5e94\u7684\u6240\u6709\u63a2\u9488\u6570\u636e\n  # \u5bf9\u6837\u672c\u5217\uff08\u9664ProbeID\u548cgeneSymbol\uff09\u8ba1\u7b97\u5747\u503c\uff0c\u5ffd\u7565\u7f3a\u5931\u503c\n  means <- colMeans(groupData[, sampleCols, drop = FALSE], na.rm = TRUE)\n  # \u5c06\u5f53\u524d\u57fa\u56e0\u540d\u79f0\u4e0e\u8ba1\u7b97\u7684\u5747\u503c\u5408\u5e76\u4e3a\u4e00\u884c\n  resultList[[i]] <- c(geneSymbol = geneName, means)\n  setTxtProgressBar(pbAgg, i)                   # \u66f4\u65b0\u8fdb\u5ea6\u6761\n}\nclose(pbAgg)                                   # \u5173\u95ed\u805a\u5408\u8fdb\u5ea6\u6761\n# \u5c06\u7ed3\u679c\u5217\u8868\u5408\u5e76\u4e3a\u6570\u636e\u6846\naggData <- do.call(rbind, resultList)\n# \u8f6c\u6362\u4e3a\u6570\u636e\u6846\uff0c\u5e76\u4fdd\u6301\u5b57\u7b26\u578b\u57fa\u56e0\u540d\u79f0\naggData <- as.data.frame(aggData, stringsAsFactors = FALSE)\n# \u5bf9\u9664geneSymbol\u5916\u7684\u6570\u503c\u578b\u5217\u8f6c\u6362\u4e3a\u6570\u503c\u578b\uff08\u56e0do.call\u8fd4\u56de\u5b57\u7b26\u578b\uff09\nfor (col in colnames(aggData)[-1]) {\n  aggData[[col]] <- as.numeric(aggData[[col]])\n}\n# \u5bf9\u7ed3\u679c\u6309\u7167\u57fa\u56e0\u540d\u79f0\u6392\u5e8f\naggData <- aggData[order(aggData$geneSymbol), ]\ncat(\"\u6570\u636e\u805a\u5408\u5b8c\u6210\uff0c\u5171\u8ba1\u7b97\u51fa\", nrow(aggData), \"\u4e2a\u57fa\u56e0\u7684\u5e73\u5747\u8868\u8fbe\u503c\u3002\\n\")  # \u8f93\u51fa\u805a\u5408\u7ed3\u679c\n\n# 9. \u5199\u5165\u8f93\u51fa\u6587\u4ef6\uff08geneMatrix.txt\uff09\ncat(\"\u6b63\u5728\u5199\u5165\u8f93\u51fa\u6587\u4ef6\uff1a\", outputFilePath, \"...\\n\")  # \u8f93\u51fa\u5199\u5165\u63d0\u793a\u4fe1\u606f\n# \u5229\u7528 write.table \u5199\u51fa\u6570\u636e\uff0c\u4f7f\u7528\u5236\u8868\u7b26\u5206\u9694\u3001\u4e0d\u5199\u884c\u53f7\u3001\u4e0d\u52a0\u5f15\u53f7\nwrite.table(aggData, file = outputFilePath, sep = \"\\t\", row.names = FALSE, quote = FALSE)\ncat(\"\u8f93\u51fa\u6587\u4ef6\u751f\u6210\u6210\u529f\uff1a\", outputFilePath, \"\\n\")  # \u8f93\u51fa\u5b8c\u6210\u63d0\u793a\n"),
"legacy_analysis/05.\u6dfb\u52a0\u6837\u672c\u4fe1\u606f\uff0c\u8bad\u7ec3\u96c6\u6570\u636e/\u6dfb\u52a0\u6837\u672c\u7c7b\u578b\u5e76\u77eb\u6b63.R"=paste0("# ===========================\n# \u53c2\u6570\u8bbe\u7f6e\u90e8\u5206\n# ===========================\n\n# \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\uff0c\u786e\u4fdd\u8def\u5f84\u6b63\u786e\nsetwd(\"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\05.\u6dfb\u52a0\u6837\u672c\u4fe1\u606f\uff0c\u8bad\u7ec3\u96c6\u6570\u636e\")  \n\n# \u5b9a\u4e49\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u6837\u672c\u4fe1\u606f\u6587\u4ef6\u8def\u5f84\ncontrolFile = \"control.txt\"       # \u5bf9\u7167\u7ec4\u6837\u672c\u4fe1\u606f\ntreatFile = \"train.txt\"           # \u5b9e\u9a8c\u7ec4\u6837\u672c\u4fe1\u606f\n\n# \u83b7\u53d6\u76ee\u5f55\u4e0b\u6240\u6709\u4ee5 \"GSE\" \u5f00\u5934\u4e14\u4ee5 \".txt\" \u7ed3\u5c3e\u7684\u6587\u4ef6\ngseFiles = dir(pattern = \"^GSE.*\\\\.txt$\")  \nif (length(gseFiles) == 0) stop(\"\u672a\u627e\u5230\u4efb\u4f55\u7b26\u5408\u6761\u4ef6\u7684 GSE \u6587\u4ef6\uff01\")  # \u68c0\u67e5\u662f\u5426\u6709\u7b26\u5408\u6761\u4ef6\u7684\u6587\u4ef6\n\ncat(\"\u8bfb\u53d6\u5230\u4ee5\u4e0b\u6587\u4ef6:\\n\")\nprint(gseFiles)  # \u8f93\u51fa\u627e\u5230\u7684\u6240\u6709 GSE \u6587\u4ef6\n\n# ===========================\n# \u52a0\u8f7d\u5fc5\u9700\u7684 R \u5305\n# ===========================\n\n# \u52a0\u8f7d `limma` \u5305\u7528\u4e8e\u6570\u636e\u6807\u51c6\u5316\u548c\u5206\u6790\nlibrary(limma)      \n# \u52a0\u8f7d `ggpubr` \u5305\u7528\u4e8e\u7ed8\u56fe\nlibrary(ggpubr)     \n# \u52a0\u8f7d `pROC` \u5305\u7528\u4e8e\u7ed8\u5236 ROC \u66f2\u7ebf\nlibrary(pROC)       \n\n# ===========================\n# \u904d\u5386\u6bcf\u4e2a GSE \u6587\u4ef6\u8fdb\u884c\u5904\u7406\n# ===========================\n\n# \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\ntotalFiles = length(gseFiles)\nprogressBar = txtProgressBar(min = 0, max = totalFiles, style = 3)\n\n# \u904d\u5386\u6bcf\u4e2a GSE \u6587\u4ef6\nfor (i in 1:totalFiles) {\n  # \u83b7\u53d6\u5f53\u524d\u5904\u7406\u7684 GSE \u6587\u4ef6\u540d\n  currentFile = gseFiles[i]\n  cat(\"\\n\u6b63\u5728\u5904\u7406\u6587\u4ef6:\", currentFile, \"\\n\")\n  \n  # \u8bfb\u53d6\u8868\u8fbe\u77e9\u9635\u6587\u4ef6\uff0c\u5e76\u8f6c\u6362\u4e3a\u6570\u503c\u77e9\u9635\n  expressionData = tryCatch({\n    read.table(currentFile, header = TRUE, sep = \"\\t\", check.names = FALSE)\n  }, error = function(e) {\n    cat(\"\u8bfb\u53d6\u6587\u4ef6\u9519\u8bef:\", currentFile, \"\\n\")\n    return(NULL)\n  })\n  \n  # \u5982\u679c\u8bfb\u53d6\u7684\u6587\u4ef6\u4e3a\u7a7a\uff0c\u5219\u8df3\u8fc7\n  if (is.null(expressionData) || nrow(expressionData) == 0) {\n    cat(\"\u8b66\u544a: \u6587\u4ef6\", currentFile, \"\u8bfb\u53d6\u5931\u8d25\u6216\u6570\u636e\u4e3a\u7a7a\uff0c\u8df3\u8fc7\u5904\u7406\\n\")\n    next\n  }\n  \n  # \u5c06\u6570\u636e\u8f6c\u6362\u4e3a\u77e9\u9635\u683c\u5f0f\n  expressionDataMatrix = as.matrix(expressionData)\n  rownames(expressionDataMatrix) = expressionDataMatrix[, 1]  # \u8bbe\u7f6e\u57fa\u56e0\u540d\u4e3a\u884c\u540d\n  expressionDataMatrix = expressionDataMatrix[, -1]  # \u5220\u9664\u7b2c\u4e00\u5217\u57fa\u56e0\u540d\n  \n  # \u8f6c\u6362\u4e3a\u6570\u503c\u77e9\u9635\u5e76\u8fdb\u884c\u5e73\u5747\u91cd\u590d\u5904\u7406\n  numericData = matrix(as.numeric(expressionDataMatrix), nrow = nrow(expressionDataMatrix), \n                       dimnames = list(rownames(expressionDataMatrix), colnames(expressionDataMatrix)))\n  processedData = avereps(num",
"ericData)\n  \n  # \u5224\u65ad\u662f\u5426\u9700\u8981 log2 \u8f6c\u6362\n  quantiles = quantile(processedData, c(0, 0.25, 0.5, 0.75, 0.99, 1.0), na.rm = TRUE)\n  needLog = (quantiles[5] > 100) || ((quantiles[6] - quantiles[1]) > 50 && quantiles[2] > 0)\n  \n  if (needLog) {\n    processedData[processedData < 0] = 0  # \u5c0f\u4e8e0\u7684\u503c\u8bbe\u4e3a0\n    processedData = log2(processedData + 1)  # \u8fdb\u884c log2 \u8f6c\u6362\n  }\n  \n  # \u5bf9\u6570\u636e\u8fdb\u884c\u6807\u51c6\u5316\u5904\u7406\n  normalizedData = normalizeBetweenArrays(processedData)\n  \n  # ===========================\n  # \u8bfb\u53d6\u6837\u672c\u4fe1\u606f\u6587\u4ef6\n  # ===========================\n  \n  controlSamples = tryCatch({\n    read.table(controlFile, header = FALSE, sep = \"\\t\", check.names = FALSE)\n  }, error = function(e) {\n    stop(\"\u8bfb\u53d6\u5bf9\u7167\u7ec4\u6837\u672c\u4fe1\u606f\u6587\u4ef6\u51fa\u9519!\")\n  })\n  \n  treatSamples = tryCatch({\n    read.table(treatFile, header = FALSE, sep = \"\\t\", check.names = FALSE)\n  }, error = function(e) {\n    stop(\"\u8bfb\u53d6\u5b9e\u9a8c\u7ec4\u6837\u672c\u4fe1\u606f\u6587\u4ef6\u51fa\u9519!\")\n  })\n  \n  # \u63d0\u53d6\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u6837\u672c\u7684\u6570\u636e\uff0c\u8fdb\u884c\u5339\u914d\n  controlSamplesNames = as.vector(controlSamples[, 1])\n  treatSamplesNames = as.vector(treatSamples[, 1])\n  \n  # \u786e\u4fdd\u6240\u6709\u6837\u672c\u5728\u6570\u636e\u4e2d\u5b58\u5728\n  missingControl = setdiff(controlSamplesNames, colnames(normalizedData))\n  missingTreat = setdiff(treatSamplesNames, colnames(normalizedData))\n  \n  if (length(missingControl) > 0) {\n    cat(\"\u8b66\u544a: \u5bf9\u7167\u7ec4\u6837\u672c\", missingControl, \"\u5728\u6570\u636e\u4e2d\u672a\u627e\u5230\uff01\\n\")\n  }\n  \n  if (length(missingTreat) > 0) {\n    cat(\"\u8b66\u544a: \u5b9e\u9a8c\u7ec4\u6837\u672c\", missingTreat, \"\u5728\u6570\u636e\u4e2d\u672a\u627e\u5230\uff01\\n\")\n  }\n  \n  # \u63d0\u53d6\u5339\u914d\u7684\u6837\u672c\u6570\u636e\n  controlData = normalizedData[, controlSamplesNames[controlSamplesNames %in% colnames(normalizedData)]]\n  treatData = normalizedData[, treatSamplesNames[treatSamplesNames %in% colnames(normalizedData)]]\n  \n  # \u5408\u5e76\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u6570\u636e\n  combinedData = cbind(controlData, treatData)\n  \n  # \u751f\u6210\u6837\u672c\u7c7b\u578b\u6807\u7b7e\n  sampleType = c(rep(\"con\", ncol(controlData)), rep(\"tra\", ncol(treatData)))\n  finalData = rbind(id = paste0(colnames(combinedData), \"_\", sampleType), combinedData)\n  \n  # \u8f93\u51fa\u6587\u4ef6\u540d\n  o",
"utputFile = paste0(gsub(\".txt$\", \"\", currentFile), \".csv\")\n  \n  # \u4fdd\u5b58\u7ed3\u679c\u5230\u6587\u4ef6\n  write.table(finalData, file = outputFile, sep = \",\", quote = FALSE, col.names = FALSE)\n  cat(\"\u6587\u4ef6\u5df2\u4fdd\u5b58:\", outputFile, \"\\n\")\n  \n  # \u66f4\u65b0\u8fdb\u5ea6\u6761\n  setTxtProgressBar(progressBar, i)\n}\n\n# \u5173\u95ed\u8fdb\u5ea6\u6761\nclose(progressBar)\ncat(\"\\n\u6240\u6709\u6587\u4ef6\u5904\u7406\u5b8c\u6210\uff01\\n\")\n"),
"legacy_analysis/07.\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u7684\u5dee\u5f02\u5206\u6790-\u591a\u6570\u636e/\u5dee\u5f02\u5206\u6790.R"=paste0("# ========================== 0. \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\uff08\u53ef\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u4fee\u6539\uff09 ==========================\nsetwd(\"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\07.\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u7684\u5dee\u5f02\u5206\u6790-\u591a\u6570\u636e\")  # \u5efa\u8bae\u4f7f\u7528\u6b63\u659c\u6760\uff0c\u907f\u514d Windows \u53cd\u659c\u6760\u5bfc\u81f4\u7684\u9519\u8bef\n\nthreshold_logFC <-1 # log2\u6298\u53e0\u53d8\u5316\u9608\u503c   \u5dee\u5f02\u57fa\u56e0\u6bd4\u8f83\u591a\u53ef\u4ee5\u628a\u503c\u6539\u4e3a1\nthreshold_adjP  <- 0.05    # \u8c03\u6574\u540eP\u503c\u9608\u503c\nmax_display_genes <- 30    # \u70ed\u56fe\u4e2d\u6bcf\u4fa7\uff08\u4e0a\u8c03\u548c\u4e0b\u8c03\uff09\u5c55\u793a\u7684\u57fa\u56e0\u6700\u5927\u6570\u91cf\nresult_dir <- \"result_csv\"\nif(!dir.exists(result_dir)) dir.create(result_dir)\n\n# \u8bb0\u5f55 Step 1 \u5f00\u59cb\u65f6\u95f4\nstep1_start <- Sys.time()\ncat(\"[Step 1] \u5f00\u59cb\u8fd0\u884c...\\n\")\n\n# \u8f7d\u5165\u5fc5\u8981\u7684 R \u5305 -----------------------------------------------------\nlibrary(limma)    # \u7528\u4e8e\u7ebf\u6027\u6a21\u578b\u548c\u5dee\u5f02\u8868\u8fbe\u5206\u6790\n\n# \u68c0\u67e5\u5e76\u5b89\u88c5 pheatmap \u5305 -----------------------------------------------------\nif (!requireNamespace(\"pheatmap\", quietly = TRUE)) {\n  install.packages(\"pheatmap\")\n}\nif (!requireNamespace(\"ggplot2\", quietly = TRUE)) {\n  install.packages(\"ggplot2\")\n}\nlibrary(ggplot2)\nlibrary(ggrepel)\nlibrary(pheatmap) # \u7528\u4e8e\u7ed8\u5236\u70ed\u56fe\n\n# \u68c0\u67e5\u5e76\u5b89\u88c5 RColorBrewer \u5305\uff08\u7528\u4e8e\u66f4\u4e30\u5bcc\u7684\u989c\u8272\u65b9\u6848\uff09---------------------------\nif (!requireNamespace(\"RColorBrewer\", quietly = TRUE)) {\n  install.packages(\"RColorBrewer\")\n}\nlibrary(RColorBrewer)\n\n# \u8bb0\u5f55 Step 1 \u7ed3\u675f\u65f6\u95f4\nstep1_end <- Sys.time()\ncat(\"[Step 1] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", \n    round(difftime(step1_end, step1_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n\n# ========================== 2. \u53c2\u6570\u8bbe\u5b9a\u53ca\u6587\u4ef6\u8def\u5f84\u914d\u7f6e ==========================\nstep2_start <- Sys.time()\ncat(\"[Step 2] \u5f00\u59cb\u53c2\u6570\u8bbe\u5b9a\u548c\u6587\u4ef6\u8def\u5f84\u914d\u7f6e...\\n\")\n\n\n\n# \u5b9a\u4e49\u8f93\u5165\u6587\u4ef6\u8def\u5f84\uff08\u8bf7\u6839\u636e\u5b9e\u9645\u60c5\u51b5\u4fee\u6539\uff09---------------------------------------\nfile_expr  <- \"batch_corrected_data.csv\"  # \u57fa\u56e0\u8868\u8fbe\u77e9\u9635\u6587\u4ef6\n \n\nstep2_end <- Sys.time()\ncat(\"[Step 2] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", \n    round(difftime(step2_end, step2_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n# ========================== \u8bfb\u53d6\u8868\u8fbe\u77e9\u9635\u5e76\u4fdd\u8bc1\u6570\u503c\u578b ==========================\nfile_expr <- \"batch_corrected_data.csv\" # \u4fee\u6539\u6210\u4f60\u7684\u5b9e\u9645\u6570\u636e\u6587\u4ef6\u540d\n\n# \u5efa\u8bae\u81ea\u52a8\u68c0\u6d4b\u5206\u9694\u7b26\ntmp_head <- readLines(file_expr, 1)\nsep <- ifelse(grepl(\",\", tmp_head), \",\", \"\\t\")\n\n# \u8bfb\u53d6\u539f\u59cb\u8868\u8fbe\u6587\u4ef6\uff0c\u884c\u4e3a\u57fa\u56e0\u540d\uff0c\u5217\u4e3a\u6837\u672c",
"\nexpr_raw <- read.table(file_expr, header=TRUE, sep=sep, check.names=FALSE, stringsAsFactors=FALSE)\nrownames(expr_raw) <- expr_raw[,1]\nexpr_mat <- expr_raw[,-1, drop=FALSE]\n\n# \u5f3a\u5236\u8f6c\u4e3amatrix\u5e76\u786e\u4fdd\u662f\u6570\u503c\u578b\nexpr_mat <- as.matrix(expr_mat)\nexpr_mat <- apply(expr_mat, 2, as.numeric) # \u9010\u5217\u5f3a\u5236\u7c7b\u578b\nrownames(expr_mat) <- rownames(expr_raw)\ncolnames(expr_mat) <- colnames(expr_raw)[-1] # \u4fdd\u6301\u5217\u540d\ncombined_expr <- expr_mat\n\n# \u68c0\u67e5\u6240\u6709\u5143\u7d20\u7686\u4e3a\u6570\u503c\nif(!is.numeric(expr_mat)) stop(\"\u8868\u8fbe\u77e9\u9635\u4ecd\u5b58\u5728\u975e\u6570\u503c\u5217\uff01\")\ncat(\"\u8868\u8fbe\u77e9\u9635\u7ef4\u5ea6:\", dim(expr_mat)[1], \"\u57fa\u56e0 x\", dim(expr_mat)[2], \"\u6837\u672c\\n\")\n\n# ========================== \u81ea\u52a8\u5224\u65ad\u5206\u7ec4\u4fe1\u606f ==========================\nsample_names <- colnames(expr_mat)\ngroup_info <- ifelse(grepl(\"_con$\", sample_names, ignore.case = TRUE), \"Control\",\n                     ifelse(grepl(\"_tra$\", sample_names, ignore.case = TRUE), \"Treatment\", \"Unknown\"))\nif(any(group_info == \"Unknown\")) stop(\"\u5206\u7ec4\u672a\u77e5\u7684\u6837\u672c\u5b58\u5728\uff0c\u8bf7\u68c0\u67e5\u6837\u672c\u540d\u540e\u7f00\uff01\")\nnum_ctrl <- sum(group_info == \"Control\")\nnum_treat <- sum(group_info == \"Treatment\")\ncat(\"\u5206\u7ec4\u60c5\u51b5\uff1aControl =\", num_ctrl, \", Treatment =\", num_treat, \"\\n\")\n\n# ========================== \u5dee\u5f02\u8868\u8fbe\u5206\u6790\uff08LIMMA\uff09 ==========================\nlibrary(limma)\ngroup_labels <- factor(group_info, levels = c(\"Control\", \"Treatment\"))\ndesign_mat <- model.matrix(~0 + group_labels)\ncolnames(design_mat) <- c(\"Control\", \"Treatment\")\nfit <- lmFit(expr_mat, design_mat)\ncontrast_mat <- makeContrasts(Treatment - Control, levels = design_mat)\nfit2 <- contrasts.fit(fit, contrast_mat)\nfit2 <- eBayes(fit2)\nall_diff_results <- topTable(fit2, adjust.method = \"fdr\", number = Inf)\ncat(\"\u5dee\u5f02\u5206\u6790\u5b8c\u6210\uff01\u53d1\u73b0FDR<0.05\u57fa\u56e0\u6570\uff1a\", sum(all_diff_results$adj.P.Val < 0.05), \"\\n\")\n\n# \u53ef\u9009\uff1a\u8f93\u51fa\u5168\u90e8\u57fa\u56e0\u7684\u5dee\u5f02\u5206\u6790\u8868\nwrite.table(cbind(Gene=rownames(all_diff_results), all_diff_results),\n            file=\"DE_results.csv\", sep=\",\", quote=FALSE, row.names=FALSE)\n\n\n# \u53ef\u9009\uff1a\u5199\u51fa\u5230\u6587\u4ef6\n# write.csv(all_diff_results, fi",
"le=\"DEG_results.csv\")\n\nstep5_end <- Sys.time()\n#cat(\"[Step 5] \u7528\u65f6\uff1a\", round(as.numeric(difftime(step5_end, step5_start, units = \"secs\")), 2), \"\u79d2\\n\")\n\n\n# ------------------------- Step 6: \u7b5b\u9009\u663e\u8457\u5dee\u5f02\u8868\u8fbe\u57fa\u56e0\u5e76\u8f93\u51fa\u5305\u542b\u5fc5\u8981\u4fe1\u606f\u7684\u8868\u683c -------------------------\nstep6_start <- Sys.time()\ncat(\"[Step 6] \u5f00\u59cb\u7b5b\u9009\u663e\u8457\u5dee\u5f02\u8868\u8fbe\u57fa\u56e0\u5e76\u8f93\u51fa\u5305\u542b\u5fc5\u8981\u4fe1\u606f\u7684\u8868\u683c...\\n\")\n\n# \u6839\u636e\u8bbe\u5b9a\u7684\u9608\u503c\u7b5b\u9009\u663e\u8457\u4e0a\u8c03\u6216\u4e0b\u8c03\u7684\u57fa\u56e0\nsignificant_DEGs <- all_diff_results[with(all_diff_results,\n                                          (abs(logFC) > threshold_logFC & adj.P.Val < threshold_adjP)), ]\n\n# \u6574\u7406\u8f93\u51fa\u683c\u5f0f\uff0c\u6dfb\u52a0 \"Gene\" \u5217\u663e\u793a\u57fa\u56e0\u540d\u79f0\uff0c\n# \u6b64\u5916\u9ed8\u8ba4\u7684 topTable \u8f93\u51fa\u5df2\u7ecf\u5305\u542b\u4ee5\u4e0b\u4fe1\u606f\uff1a\n#   - logFC: \u57fa\u56e0\u7684\u5bf9\u6570\u6298\u53e0\u53d8\u5316\n#   - AveExpr: \u5404\u6837\u672c\u7684\u5e73\u5747\u8868\u8fbe\u503c\n#   - t: \u7ecf\u8fc7\u7ecf\u9a8c\u8d1d\u53f6\u65af\u8c03\u6574\u540e\u7684 t \u7edf\u8ba1\u91cf\n#   - P.Value: \u539f\u59cb p \u503c\n#   - adj.P.Val: \u8c03\u6574\u540e p \u503c\uff08FDR\u6821\u6b63\uff09\n#   - B: \u5dee\u5f02\u8868\u8fbe\u7684\u5bf9\u6570 odds\noutput_DEGs <- cbind(Gene = rownames(significant_DEGs), significant_DEGs)\n\n# \u8ba1\u7b97\u6807\u51c6\u8bef\u5dee (SE)\n# \u6839\u636e t \u7edf\u8ba1\u91cf\u516c\u5f0f\uff1a t = logFC / SE  =>  SE = |logFC/t|\n# \u5f53 t \u4e0d\u4e3a 0 \u65f6\u8ba1\u7b97\uff0c\u5426\u5219\u8fd4\u56de NA\nSE <- ifelse(as.numeric(output_DEGs[, \"t\"]) != 0,\n             abs(as.numeric(output_DEGs[, \"logFC\"]) / as.numeric(output_DEGs[, \"t\"])),\n             NA)\noutput_DEGs <- cbind(output_DEGs, SE = SE)\n\n# \u5982\u679c\u6709\u989d\u5916\u7684\u6ce8\u91ca\u4fe1\u606f\uff08\u5982 EntrezID\u3001GeneDescription\u3001Chromosome \u7b49\uff09\uff0c\n# \u53ef\u901a\u8fc7 merge() \u5c06\u5916\u90e8\u6ce8\u91ca\u8868\u4e0e\u7ed3\u679c\u5408\u5e76\uff0c\u793a\u4f8b\u5982\u4e0b\uff1a\n# annotation_table <- read.table(\"gene_annotation.txt\", sep=\"\\t\", header=TRUE, stringsAsFactors = FALSE)\n# output_DEGs <- merge(output_DEGs, annotation_table, by.x=\"Gene\", by.y=\"GeneSymbol\", all.x=TRUE)\n\n# \u53ef\u9009\uff1a\u8c03\u6574\u5217\u987a\u5e8f\uff0c\u4f7f\u7ed3\u679c\u66f4\u76f4\u89c2\uff08\u4f8b\u5982\u628a Gene, logFC, SE, AveExpr, t, P.Value, adj.P.Val, B \u653e\u5728\u524d\u9762\uff09\noutput_DEGs <- as.data.frame(output_DEGs, stringsAsFactors = FALSE)\ndesired_order <- c(\"Gene\", \"logFC\", \"SE\", \"AveExpr\", \"t\", \"P.Value\", \"adj.P.Val\", \"B\")\nexisting_cols <- intersect(desired_order, colnames(output_DEGs))\noutput_DEGs <- output_DEGs[, c(existing_cols, setdiff(colnames(output_DEGs), existing_cols))]\n\n# \u5c06\u8f93\u51fa\u8868\u683c\u5199\u5165\u6587\u4ef6\uff0c\u786e\u4fdd\u6240\u6709\u4fe1\u606f\u90fd\u5c55\u793a\nwrite.table(output_DEGs, file ",
"= \"DE_significant_genes.csv\", sep = \",\", quote = FALSE, row.names = FALSE)\n\nstep6_end <- Sys.time()\ncat(\"[Step 6] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step6_end, step6_start, units = \"secs\"), 2), \"\u79d2\\n\\n\")\n\n\n\n# ========================== 7. \u7ed8\u5236\u70ed\u56fe\uff0c\u5728\u4e0b\u65b9\u663e\u793a\u5206\u7ec4\u6837\u672c\u6570\u91cf ==========================\nstep7_start <- Sys.time()\ncat(\"[Step 7] \u5f00\u59cb\u7ed8\u5236\u70ed\u56fe\\n\")\n\n# 1. \u51c6\u5907\u7ed8\u56fe\u6570\u636e ------------------------------------------------------------\nordered_DEGs <- significant_DEGs[order(as.numeric(as.vector(significant_DEGs$logFC))), ]\nordered_gene_names <- rownames(ordered_DEGs)\ntotal_DEG_count <- length(ordered_gene_names)\n\nif (total_DEG_count > (max_display_genes * 2)) {\n  selected_gene_set <- ordered_gene_names[c(1:max_display_genes, \n                                            (total_DEG_count - max_display_genes + 1):total_DEG_count)]\n} else {\n  selected_gene_set <- ordered_gene_names\n}\nheatmap_expr <- combined_expr[selected_gene_set, ]\n\n# 2. \u6784\u5efa\u6837\u672c\u6ce8\u91ca\u4fe1\u606f\uff0c\u5e76\u8bbe\u7f6e\u5206\u7ec4\u989c\u8272 ------------------------------------------\n# \u4fee\u6539\u5b9e\u9a8c\u7ec4\u540d\u79f0\u4e3a \"Treat\"\nsample_annotation <- data.frame(Group = factor(c(rep(\"Control\", num_ctrl), \n                                                 rep(\"Treat\", num_treat))))\nrownames(sample_annotation) <- colnames(combined_expr)\n\nannotation_colors <- list(\n  Group = c(\"Control\" = \"#66C2A5\",    # \u6d45\u7eff\n            \"Treat\"   = \"#FC8D62\")     # \u6d45\u6a59\n)\n\n# 3. \u5b9a\u4e49\u66f4\u4e30\u5bcc\u7684\u8c03\u8272\u677f\uff0c\u4f7f\u7528 RColorBrewer \u7684 \"RdYlBu\" \u53cd\u8f6c\u8c03\u8272\u677f ------------------\ncolor_palette <- colorRampPalette(rev(brewer.pal(11, \"RdYlBu\")))(255)\n\n# 4. \u51c6\u5907\u70ed\u56fe\u5bf9\u8c61\uff08\u6dfb\u52a0\u4e3b\u6807\u9898\uff09\uff0csilent=TRUE \u4e0d\u76f4\u63a5\u7ed8\u5236 --------\nheatmap_result <- pheatmap(\n  mat               = heatmap_expr,\n  annotation_col    = sample_annotation,\n  annotation_colors = annotation_colors,\n  color             = color_palette,\n  cluster_cols      = FALSE,\n  show_colnames     = FALSE,\n  scale             = \"row\",\n  fontsize          = 12,\n  fontsi",
"ze_row      = 7,\n  fontsize_col      = 10,\n  border_color      = NA,\n  main              = \"Differential Expression Heatmap\",\n  silent            = TRUE\n)\n\n# 5. \u8ba1\u7b97\u5bf9\u7167\u7ec4\u548c\u5b9e\u9a8c\u7ec4\u7684\u6837\u672c\u6570\u91cf\uff0c\u5e76\u62fc\u63a5\u6587\u672c ------------------------------------\ncontrol_count <- num_ctrl\ntreatment_count <- num_treat\nsample_text <- paste(\"Control:\", control_count, \"| Treat:\", treatment_count)\n\n# 6. \u7ed8\u5236\u5230 PDF\uff0c\u91c7\u7528 grid \u5206\u533a\uff0c\u5c06\u70ed\u56fe\u548c\u6587\u672c\u5206\u4e0a\u4e0b\u4e24\u90e8\u5206 -----------------------\nlibrary(grid)\npdf(file = \"DE_heatmap.pdf\", height = 8, width = 10)\ngrid.newpage()\npushViewport(viewport(layout = grid.layout(nrow = 2, \n                                           heights = unit(c(0.93, 0.07), \"npc\"))))\n# \u7b2c1\u884c\uff1a\u7ed8\u5236\u70ed\u56fe\npushViewport(viewport(layout.pos.row = 1))\ngrid.draw(heatmap_result$gtable)\npopViewport()\n# \u7b2c2\u884c\uff1a\u7ed8\u5236\u6587\u672c\uff08\u5206\u7ec4\u6837\u672c\u6570\u91cf\uff09\npushViewport(viewport(layout.pos.row = 2))\ngrid.text(label = sample_text,\n          x = 0.5, \n          y = 0.5,\n          gp = gpar(fontsize = 13, fontface = \"bold\", col = \"#333333\"))\npopViewport()\npopViewport()\ndev.off()\n\nstep7_end <- Sys.time()\ncat(\"[Step 7] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", \n    round(difftime(step7_end, step7_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n# ========================== 8. \u7ed8\u5236\u706b\u5c71\u56fe ==========================\nstep8_start <- Sys.time()\ncat(\"[Step 8] \u5f00\u59cb\u7ed8\u5236\u706b\u5c71\u56fe...\\n\")\n\n# \u4e3a\u6bcf\u4e2a\u57fa\u56e0\u6dfb\u52a0\u663e\u8457\u6027\u6807\u8bb0\uff0c\u8f93\u51fa\u5e26\u7a7a\u683c\u7684\u7c7b\u522b\u540d\u79f0\nsignificance_status <- ifelse(\n  (all_diff_results$adj.P.Val < threshold_adjP & abs(all_diff_results$logFC) > threshold_logFC),\n  ifelse(all_diff_results$logFC > threshold_logFC, \"Up regulated\", \"Down regulated\"),\n  \"Not Significant\"\n)\nall_diff_results$Significance <- significance_status\n\n# \u6784\u9020\u706b\u5c71\u56fe\uff0c\u5e76\u66f4\u65b0\u989c\u8272\u6620\u5c04\uff0c\u4f7f\u7c7b\u522b\u540d\u79f0\u4e0e ifelse \u8fd4\u56de\u4e00\u81f4\nvolcano_plot <- ggplot(all_diff_results, aes(x = logFC, y = -log10(adj.P.Val))) +\n  geom_point(aes(color = Significance), size = 2.5, alpha = 0.8) +\n  scale_color_manual(values = c(\"Down regulated\"  = \"#1E90FF\", \n                 ",
"               \"Not Significant\" = \"#808080\", \n                                \"Up regulated\"    = \"#FF4500\")) +\n  geom_vline(xintercept = c(-threshold_logFC, threshold_logFC), \n             linetype = \"dashed\", color = \"black\", size = 0.5) +\n  geom_hline(yintercept = -log10(threshold_adjP), \n             linetype = \"dashed\", color = \"black\", size = 0.5) +\n  labs(title = \"Volcano Plot of Differential Expression\",\n       x = \"Log2 Fold Change\",\n       y = \"-Log10 Adjusted P-value\") +\n  theme_minimal(base_size = 14) +\n  theme(plot.title    = element_text(face = \"bold\", hjust = 0.5, color = \"#2F4F4F\"),\n        axis.title    = element_text(face = \"bold\", color = \"#2F4F4F\"),\n        axis.text     = element_text(color = \"#2F4F4F\"),\n        panel.grid.major = element_line(color = \"#D3D3D3\", linetype = \"dotted\"),\n        panel.grid.minor = element_blank())\n\n# \u4fdd\u5b58\u706b\u5c71\u56fe\u5230 PDF\npdf(file = \"DE_volcano.pdf\", width = 6, height = 6)\nprint(volcano_plot)\ndev.off()\n\nstep8_end <- Sys.time()\ncat(\"[Step 8] \u8fd0\u884c\u5b8c\u6bd5\uff0c\u8017\u65f6:\", round(difftime(step8_end, step8_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n# ========================== 9. PCA \u4e3b\u6210\u5206\u5206\u6790 ==========================\nstep9_start <- Sys.time()\ncat(\"[Step 9] \u5f00\u59cb\u4f18\u5316 PCA \u4e3b\u6210\u5206\u5206\u6790...\\n\")\n\n# \u786e\u4fdd ggplot2 \u548c ggrepel \u5df2\u5b89\u88c5\uff08\u7528\u4e8e\u7f8e\u5316\u6807\u7b7e\uff09\nif (!requireNamespace(\"ggplot2\", quietly = TRUE)) {\n  install.packages(\"ggplot2\")\n}\nif (!requireNamespace(\"ggrepel\", quietly = TRUE)) {\n  install.packages(\"ggrepel\")  # \u4f7f\u6807\u7b7e\u4e0d\u91cd\u53e0\n}\nif (!requireNamespace(\"ggpubr\", quietly = TRUE)) {\n  install.packages(\"ggpubr\")  # \u7528\u4e8e\u6dfb\u52a0\u7f6e\u4fe1\u692d\u5706\n}\nlibrary(ggplot2)\nlibrary(ggrepel)\nlibrary(ggpubr)\n\n# \u8ba1\u7b97 PCA\npca_result <- prcomp(t(combined_expr), scale. = TRUE)\n\n# \u6784\u5efa PCA \u6570\u636e\u6846\npca_df <- data.frame(\n  Sample = colnames(combined_expr),\n  PC1 = pca_result$x[, 1],\n  PC2 = pca_result$x[, 2],\n  Group = factor(c(rep(\"Control\", num_ctrl), r",
"ep(\"Treatment\", num_treat)))  # \u5206\u7ec4\u4fe1\u606f\n)\n\n# \u8ba1\u7b97 PCA \u8d21\u732e\u7387\uff08\u7528\u4e8e\u5750\u6807\u8f74\u6807\u7b7e\uff09\npca_var <- pca_result$sdev^2\npca_var_perc <- round(100 * pca_var / sum(pca_var), 1)\n\n# \u7ed8\u5236 PCA \u56fe\npca_plot <- ggplot(pca_df, aes(x = PC1, y = PC2, color = Group)) +\n  # \u589e\u52a0\u7f6e\u4fe1\u692d\u5706\uff0c\u63d0\u9ad8\u6570\u636e\u5206\u5e03\u7684\u53ef\u89c6\u5316\n  stat_ellipse(level = 0.95, linetype = \"dashed\", size = 1) +\n  # \u7ed8\u5236\u70b9\uff0c\u8c03\u6574\u5927\u5c0f\u548c\u900f\u660e\u5ea6\uff0c\u907f\u514d\u91cd\u53e0\u5f71\u54cd\n  geom_point(size = 4, alpha = 0.8, shape = 16) +\n  # \u6dfb\u52a0\u4e0d\u91cd\u53e0\u7684\u6587\u672c\u6807\u7b7e\n  geom_text_repel(aes(label = Sample), size = 4, fontface = \"bold\", max.overlaps = 15) +\n  # \u81ea\u5b9a\u4e49\u989c\u8272\uff0c\u63d0\u9ad8\u89c6\u89c9\u51b2\u51fb\u529b\uff08\u6e10\u53d8\u8272\uff09\n  scale_color_manual(values = c(\"Control\" = \"#0072B2\",  # \u6df1\u84dd\n                                \"Treatment\" = \"#E69F00\")) + # \u6a59\u8272\n  # \u4fee\u6539\u5750\u6807\u8f74\u6807\u7b7e\uff0c\u4f7f\u5176\u66f4\u4e13\u4e1a\n  labs(title = \"PCA Analysis of Gene Expression\",\n       x = paste(\"PC1 (\", pca_var_perc[1], \"%)\", sep = \"\"),\n       y = paste(\"PC2 (\", pca_var_perc[2], \"%)\", sep = \"\"),\n       color = \"\") +  # \u79fb\u9664\u56fe\u4f8b\u6807\u9898\n  # \u7f8e\u5316\u4e3b\u9898\n  theme_classic(base_size = 16) +\n  theme(\n    plot.title    = element_text(face = \"bold\", hjust = 0.5, size = 18, color = \"#333333\"),\n    axis.title    = element_text(face = \"bold\", size = 16, color = \"#333333\"),\n    axis.text     = element_text(size = 14, color = \"#555555\"),\n    legend.text   = element_text(size = 14, face = \"bold\"),\n    legend.position = \"top\",\n    panel.grid.major = element_line(color = \"#DDDDDD\", linetype = \"dotted\"),\n    panel.grid.minor = element_blank()\n  )\n\n# \u4fdd\u5b58 PCA \u56fe\nggsave(\"DE_PCA.pdf\", pca_plot, width = 7, height = 7, dpi = 300)\n\nstep9_end <- Sys.time()\ncat(\"[Step 9] PCA \u5206\u6790\u4f18\u5316\u5b8c\u6210\uff0c\u8017\u65f6:\", \n    round(difftime(step9_end, step9_start, units=\"secs\"), 2), \"\u79d2\\n\\n\")\n\n# \u52a0\u8f7d\u5fc5\u8981\u7684\u5e93\nlibrary(ggplot2)\nlibrary(RColorBrewer)\n\n# \u5047\u8bbe\u6211\u4eec\u5df2\u7ecf\u6709\u4e86\u4e00\u4e2a\u6570\u636e\u6846\uff0c\u5305\u542b\u57fa\u56e0\u7684log2FoldChange\uff08logFC\uff09\u548cp\u503c\uff08adj.P.Val\uff09\n# \u751f\u6210\u4e00\u4e2a\u793a\u4f8b\u6570\u636e\u6846\nset.seed(123)\ngene_data <- data.frame(\n  Gene = paste(\"Gene\", 1:10000),\n  logFC = c(rnorm(5000, 2, 1), rnorm(5000, -2, 1)),  ",
"# log2FoldChange\n  adj.P.Val = runif(10000, 0, 1)  # \u8c03\u6574\u540e\u7684p\u503c\n)\n\n# \u6839\u636elogFC\u548cp\u503c\u6392\u5e8f\ngene_data <- gene_data[order(gene_data$logFC, decreasing = TRUE),]\n\n# \u521b\u5efa\u6e10\u53d8\u8272\ncolor_palette <- scale_color_gradientn(\n  colors = rev(brewer.pal(9, \"RdYlBu\")), \n  values = scales::rescale(c(0, 0.25, 0.5, 0.75, 1))\n)\n\n# \u7ed8\u5236\u57fa\u56e0\u6392\u5e8f\u70b9\u56fe\nplot <- ggplot(gene_data, aes(x = seq_along(logFC), y = logFC)) +\n  geom_point(aes(color = adj.P.Val, size = abs(logFC)), alpha = 0.8) +  # \u4f7f\u7528p\u503c\u4f5c\u4e3a\u989c\u8272\uff0clogFC\u7684\u7edd\u5bf9\u503c\u4f5c\u4e3a\u5927\u5c0f\n  color_palette +  # \u4f7f\u7528\u6e10\u53d8\u8272\u6765\u8868\u793ap\u503c\n  scale_size_continuous(range = c(5, 12)) +  # \u589e\u5927\u70b9\u7684\u5927\u5c0f\u8303\u56f4\n  labs(\n    title = \"Gene Ranking Dotplot\", \n    x = \"Ranking of Differentially Expressed Genes\", \n    y = \"Log2 Fold Change\",\n    color = \"Adjusted P-value\",\n    size = \"Log2 Fold Change\"\n  ) +\n  theme_minimal(base_size = 16) +  # \u4f7f\u7528\u6700\u7b80\u6d01\u7684\u80cc\u666f\uff0c\u8c03\u6574\u5b57\u4f53\u5927\u5c0f\n  theme(\n    plot.title = element_text(size = 18, face = \"bold\", color = \"#2F4F4F\", hjust = 0.5),\n    axis.title = element_text(size = 16, face = \"bold\", color = \"#2F4F4F\"),\n    axis.text = element_text(size = 14, color = \"#555555\"),\n    legend.position = \"right\",\n    legend.title = element_text(size = 14, face = \"bold\"),\n    legend.text = element_text(size = 12),\n    panel.grid.major = element_line(color = \"#D3D3D3\", linetype = \"dotted\"),\n    panel.grid.minor = element_blank()\n  )\n\n# \u4fdd\u5b58\u4e3aPDF\uff0c\u8c03\u6574\u5c3a\u5bf8\u548c\u5206\u8fa8\u7387\nggsave(\"123.pdf\", plot, width = 10, height = 8, dpi = 300)\n\n\n# \u5047\u5b9a\u4f60\u7684\u5dee\u5f02\u5206\u6790\u7ed3\u679c\u4e3a all_diff_results\uff0c\u884c\u540d\u4e3a\u57fa\u56e0\u540d\nde_table <- all_diff_results\n\n# \u5148\u7b5b\u9009\u663e\u8457\u5dee\u5f02\u57fa\u56e0\uff08\u53ef\u6309\u4f60\u7684\u9608\u503c\uff0c\u4e5f\u53ef\u4ee5\u5168\u8868top\uff09\nsig_degs <- de_table[with(de_table, abs(logFC) > threshold_logFC & adj.P.Val < threshold_adjP), ]\n\n# \u6309logFC\u6392\u5e8f\uff0c\u4e0a\u8c03Top25&\u4e0b\u8c03Top25\nup_top <- rownames(sig_degs)[order(-sig_degs$logFC)][1:25]     # logFC\u6700\u5927 top25\ndown_top <- rownames(sig_degs)[order(sig_degs$logFC)][1:25]    # logFC\u6700\u5c0f top25\nlabel_genes <- unique(c(up_top, down_top))\n\n# \u6dfb\u52a0ge",
"ne\u5217\u5230\u5168\u7ed3\u679c\u8868\nde_table$Gene <- rownames(de_table)\n\n# \u589e\u52a0\u4e00\u4e2a\u65b0\u5217\uff1a\u4e3atop50\u6807\u8bb0gene name\uff0c\u5426\u5219\u7a7a\nde_table$label <- ifelse(de_table$Gene %in% label_genes, de_table$Gene, \"\")\n\n# \u989c\u8272\u5206\u7ec4\uff08\u53ef\u9009\uff0c\u53ef\u6309\u4f60\u7684Significance\u6216\u91cd\u65b0\u5b9a\u4e49\uff09\nde_table$Group <- \"Not Significant\"\nde_table$Group[de_table$logFC > threshold_logFC & de_table$adj.P.Val < threshold_adjP] <- \"Up regulated\"\nde_table$Group[de_table$logFC < -threshold_logFC & de_table$adj.P.Val < threshold_adjP] <- \"Down regulated\"\n\n# \u7ed8\u5236\u706b\u5c71\u56fe\nvolcano_plot <- ggplot(de_table, aes(x=logFC, y=-log10(adj.P.Val), color=Group)) +\n  geom_point(alpha=0.7, size=2) +\n  geom_text_repel(aes(label=label), # \u53ea\u6807\u6709label\u7684\u70b9\n                  size=3,\n                  max.overlaps=50,\n                  box.padding = 0.3,\n                  point.padding = 0.2,\n                  segment.color=\"grey50\",\n                  show.legend = FALSE) +\n  scale_color_manual(values = c(\"Up regulated\"=\"#FF4500\", \n                                \"Down regulated\"=\"#1E90FF\", \n                                \"Not Significant\"=\"#808080\")) +\n  geom_vline(xintercept = c(-threshold_logFC, threshold_logFC), linetype=\"dashed\", color=\"black\") +\n  geom_hline(yintercept = -log10(threshold_adjP), linetype=\"dashed\", color=\"black\") +\n  labs(title=\"Volcano Plot with Top 25 Genes Labeled\",\n       x=\"Log2 Fold Change\",\n       y=\"-Log10 Adjusted P-value\") +\n  theme_minimal(base_size = 14) +\n  theme(plot.title=element_text(face=\"bold\", hjust=0.5, color=\"#2F4F4F\"))\n\n# \u4fdd\u5b58\nggsave(\"DE_volcano_with_labels.pdf\", volcano_plot, width=8, height=8, dpi=300)\n# ========================== \u5168\u90e8\u6b65\u9aa4\u5b8c\u6210 ==========================\ncat(\"\u6240\u6709\u6b65\u9aa4\u5df2\u6210\u529f\u5b8c\u6210\uff01\\n\")\n"),
"legacy_analysis/11.marching learning/21.\u63d0\u53d6\u4ea4\u96c6\u57fa\u56e0\u77e9\u9635\u6587\u4ef6/\u7814\u7a76\u65b9\u5411\u57fa\u56e0\u63d0\u53d6.R"=paste0("# \u52a0\u8f7dlimma\u5305\nlibrary(limma)  # \u52a0\u8f7dlimma\u5305\n\n# \u5b9a\u4e49\u603b\u6b65\u9aa4\u6570\uff08\u7528\u4e8e\u8fdb\u5ea6\u6761\u663e\u793a\uff09\ntotal_steps <- 8  # \u5b9a\u4e49\u603b\u6b65\u9aa4\u6570\u4e3a8\n# \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\uff0cmin\u4e3a0\uff0cmax\u4e3atotal_steps\uff0cstyle=3\u4e3a\u8fdb\u5ea6\u6761\u6837\u5f0f\npb <- txtProgressBar(min = 0, max = total_steps, style = 3)  # \u521d\u59cb\u5316\u8fdb\u5ea6\u6761\n\n# ---------------------- \u6b65\u9aa41\uff1a\u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55 ---------------------- \nsetwd(\"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\11.marching learning\\\\21.\u63d0\u53d6\u4ea4\u96c6\u57fa\u56e0\u77e9\u9635\u6587\u4ef6\")  # \u8bbe\u7f6e\u5de5\u4f5c\u76ee\u5f55\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\uff0c\u6a21\u62df\u5904\u7406\u5ef6\u8fdf\nsetTxtProgressBar(pb, 1)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa41\n\n# ---------------------- \u6b65\u9aa42\uff1a\u68c0\u67e5\u8f93\u5165\u6587\u4ef6 ----------------------\n# \u5224\u65ad\u8868\u8fbe\u77e9\u9635\u6570\u636e\u6587\u4ef6\nif (!file.exists(\"batch_corrected_data.csv\")) {  # \u5982\u679c\u6587\u4ef6\u4e0d\u5b58\u5728\n  stop(\"\u9519\u8bef:batch_corrected_data.csv \u6587\u4ef6\u4e0d\u5b58\u5728\uff01\")  # \u5219\u7ec8\u6b62\u7a0b\u5e8f\u5e76\u62a5\u9519\n} else {  \n  cat(\"batch_corrected_data.csv\u6587\u4ef6\u5df2\u627e\u5230\u3002\\n\")  # \u5426\u5219\u8f93\u51fa\u63d0\u793a\u4fe1\u606f\n}\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\nsetTxtProgressBar(pb, 2)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa42\n\n# ---------------------- \u6b65\u9aa43\uff1a\u8bfb\u53d6\u8868\u8fbe\u77e9\u9635\u6570\u636e\u6587\u4ef6 ----------------------\nrawData <- read.table(\"batch_corrected_data.csv\", sep = \",\", header = TRUE, check.names = FALSE)  # \u8bfb\u53d6\u57fa\u56e0\u8868\u8fbe\u77e9\u9635\u6570\u636e\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\nsetTxtProgressBar(pb, 3)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa43\n\n# ---------------------- \u6b65\u9aa44\uff1a\u6570\u636e\u9884\u5904\u7406\u4e0e\u8f6c\u6362 ----------------------\nrawDataMatrix <- as.matrix(rawData)  # \u5c06\u6570\u636e\u6846\u8f6c\u6362\u4e3a\u77e9\u9635\u683c\u5f0f\nrownames(rawDataMatrix) <- rawDataMatrix[, 1]  # \u5c06\u77e9\u9635\u7b2c\u4e00\u5217\u8bbe\u4e3a\u884c\u540d\uff08\u5047\u5b9a\u7b2c\u4e00\u5217\u4e3a\u57fa\u56e0\u540d\u79f0\uff09\nexpData <- rawDataMatrix[, 2:ncol(rawDataMatrix)]  # \u63d0\u53d6\u8868\u8fbe\u6570\u636e\uff0c\u4ece\u7b2c\u4e8c\u5217\u5230\u6700\u540e\u4e00\u5217\nbackupExpData <- expData  # \u5197\u4f59\u4ee3\u7801\uff1a\u5907\u4efd\u4e00\u4efd\u539f\u59cb\u8868\u8fbe\u6570\u636e\uff08\u7528\u4e8e\u540e\u7eed\u53ef\u80fd\u7684\u8c03\u8bd5\uff09\ndimnamesList <- list(rownames(expData), colnames(expData))  # \u5b9a\u4e49\u8868\u8fbe\u77e9\u9635\u7684\u884c\u540d\u548c\u5217\u540d\nnumericData <- matrix(as.numeric(as.matrix(expData)), nrow = nrow(expData), dimnames = dimnamesList)  # \u5c06\u8868\u8fbe\u6570\u636e\u8f6c\u6362\u4e3a\u6570\u503c\u578b\u77e9\u9635\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\nsetTxtProgressBar(pb, 4)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa44\n\n# ---------------------- \u6b65\u9aa45\uff1a\u5904\u7406\u91cd\u590d\u503c\u53ca\u4f4e\u8868\u8fbe\u57fa\u56e0\u8fc7\u6ee4 ----------------------\naveragedData <- avereps(numericData)  # \u5bf9\u91cd\u590d\u503c\u8fdb\u884c\u5e73\u5747\u5904\u7406\nfilteredData <- averagedData[rowMeans(averagedData) > 0, ]  # \u8fc7\u6ee4\u6389\u884c\u5747\u503c\u4e3a0\u6216\u4ee5\u4e0b\u7684\u57fa\u56e0\n# \u5224\u65ad\u8fc7\u6ee4\u540e\u7684\u6570\u636e\u662f\u5426\u4e3a\u7a7a\nif (nrow(filteredData) == 0) {  # \u5982\u679c\u8fc7\u6ee4\u540e\u7684\u6570\u636e\u884c\u6570\u4e3a0",
"\n  stop(\"\u9519\u8bef: \u8fc7\u6ee4\u540e\u6ca1\u6709\u5269\u4f59\u6570\u636e\uff01\")  # \u5219\u7ec8\u6b62\u7a0b\u5e8f\u5e76\u62a5\u9519\n}\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\nsetTxtProgressBar(pb, 5)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa45\n\n# ---------------------- \u6b65\u9aa46\uff1a\u68c0\u67e5\u5e76\u8bfb\u53d6\u57fa\u56e0\u5217\u8868\u6587\u4ef6 ----------------------\n# \u5224\u65ad\u57fa\u56e0\u5217\u8868\u6587\u4ef6IntersectionGenes.csv\u662f\u5426\u5b58\u5728\nif (!file.exists(\"IntersectionGenes.csv\")) {  # \u5982\u6587\u4ef6\u4e0d\u5b58\u5728\n  stop(\"\u9519\u8bef: IntersectionGenes.csv\u6587\u4ef6\u4e0d\u5b58\u5728\uff01\")  # \u5219\u7ec8\u6b62\u7a0b\u5e8f\u5e76\u62a5\u9519\n} else {  \n  cat(\"IntersectionGenes.csv \u6587\u4ef6\u5df2\u627e\u5230\u3002\\n\")  # \u5426\u5219\u8f93\u51fa\u63d0\u793a\u4fe1\u606f\n}\ngeneList <- read.table(\"IntersectionGenes.csv\", header = FALSE, check.names = FALSE, sep = \"\\t\")  # \u8bfb\u53d6\u57fa\u56e0\u5217\u8868\u6570\u636e\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\nsetTxtProgressBar(pb, 6)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa46\n\n# ---------------------- \u6b65\u9aa47\uff1a\u5bfb\u627e\u5171\u540c\u57fa\u56e0\u5e76\u63d0\u53d6\u8868\u8fbe\u6570\u636e ----------------------\ngeneNames <- as.vector(geneList[, 1])  # \u63d0\u53d6\u57fa\u56e0\u5217\u8868\u4e2d\u7b2c\u4e00\u5217\u4e3a\u57fa\u56e0\u540d\u79f0\ncommonGenes <- intersect(geneNames, rownames(filteredData))  # \u83b7\u53d6\u8868\u8fbe\u77e9\u9635\u4e0e\u57fa\u56e0\u5217\u8868\u4e2d\u7684\u5171\u540c\u57fa\u56e0\n# \u5224\u65ad\u662f\u5426\u5b58\u5728\u5171\u540c\u57fa\u56e0\nif (length(commonGenes) == 0) {  # \u5982\u679c\u6ca1\u6709\u5171\u540c\u57fa\u56e0\n  stop(\"\u9519\u8bef: \u6ca1\u6709\u627e\u5230\u5171\u540c\u57fa\u56e0\uff01\")  # \u5219\u7ec8\u6b62\u7a0b\u5e8f\u5e76\u62a5\u9519\n} else {\n  cat(\"\u627e\u5230\", length(commonGenes), \"\u4e2a\u5171\u540c\u57fa\u56e0\u3002\\n\")  # \u5426\u5219\u8f93\u51fa\u627e\u5230\u7684\u5171\u540c\u57fa\u56e0\u6570\u91cf\n}\ngeneExpression <- filteredData[commonGenes, ]  # \u63d0\u53d6\u5171\u540c\u57fa\u56e0\u7684\u8868\u8fbe\u6570\u636e\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\nsetTxtProgressBar(pb, 7)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa47\n\n# ---------------------- \u6b65\u9aa48\uff1a\u5c06\u7ed3\u679c\u8f93\u51fa\u5230CSV\u6587\u4ef6 ----------------------\noutputMatrix <- rbind(ID = colnames(geneExpression), geneExpression)  # \u5728\u7ed3\u679c\u77e9\u9635\u4e2d\u6dfb\u52a0\u5217\u540d\u4f5c\u4e3a\u7b2c\u4e00\u884c\nwrite.table(outputMatrix, file = \"geneexp.csv\", sep = \",\", quote = FALSE, col.names = FALSE)  # \u5c06\u7ed3\u679c\u5199\u5165CSV\u6587\u4ef6\nSys.sleep(0.5)  # \u6682\u505c0.5\u79d2\nsetTxtProgressBar(pb, 8)  # \u66f4\u65b0\u8fdb\u5ea6\u6761\u5230\u6b65\u9aa48\n\n# \u5173\u95ed\u8fdb\u5ea6\u6761\nclose(pb)  # \u5173\u95ed\u8fdb\u5ea6\u6761\ncat(\"\\n\u6240\u6709\u6b65\u9aa4\u5b8c\u6210\uff0c\u7ed3\u679c\u5df2\u4fdd\u5b58\u81f3 geneexp.csv \u6587\u4ef6\u3002\\n\")  # \u8f93\u51fa\u5b8c\u6210\u63d0\u793a\u4fe1\u606f\n"),
"legacy_analysis/23.\u8bca\u65ad\u6a21\u578b\u57fa\u56e0\u4e0e22\u79cd\u514d\u75ab\u76f8\u5173\u7ec6\u80de\u6d78\u6da6\u7684\u76f8\u5173\u6027\uff08CIBERSORT\uff09/\u514d\u75ab\u6d78\u6da6\u5206\u6790.R"=paste0("# ==== \u514d\u75ab\u6d78\u6da6\u5206\u6790\u5b8c\u6574\u6d41\u7a0b\uff08CIBERSORT + \u53ef\u89c6\u5316 + \u57fa\u56e0-\u514d\u75ab\u76f8\u5173\u6027\uff09 ====\n\n# ============================ \u52a0\u8f7d\u5fc5\u8981\u5305 =============================\nlibrary(e1071)\nlibrary(parallel)\nlibrary(preprocessCore)\nlibrary(reshape2)\nlibrary(ggplot2)\nlibrary(RColorBrewer)\nlibrary(ggpubr)\nlibrary(dplyr)\nlibrary(broom)\nlibrary(ggsci)\nlibrary(limma)\nlibrary(pheatmap)\n\n# ============================ \u53c2\u6570\u8bbe\u7f6e =============================\nwork_dir       <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\24.\u8bca\u65ad\u6a21\u578b\u57fa\u56e0\u4e0e\u514d\u75ab\u76f8\u5173\u7ec6\u80de\u4e30\u5ea6\u7684\u76f8\u5173\u6027\uff08MCP-counter\uff09\"\ninput_file     <- \"batch_corrected_data.csv\"\nrefer_file     <- \"refer.txt\"\ngene_list_file <- \"Intersect_Genes.csv\"\n\nsetwd(work_dir)\n\n# ============================================================\n# \u7b2c\u4e00\u90e8\u5206\uff1aCIBERSORT \u514d\u75ab\u6d78\u6da6\u53cd\u5377\u79ef\n# ============================================================\ncat(\"==== \u7b2c\u4e00\u90e8\u5206\uff1aCIBERSORT \u514d\u75ab\u6d78\u6da6\u53cd\u5377\u79ef ====\\n\")\n\n# \u6838\u5fc3SVR\u7b97\u6cd5\ncoreAlgorithm <- function(refer_matrix, target_vector) {\n  num_steps <- 3\n  runSVM <- function(step_index) {\n    nu_param <- c(0.25, 0.5, 0.75)[step_index]\n    svm(refer_matrix, target_vector, type=\"nu-regression\", kernel=\"linear\", nu=nu_param, scale=FALSE)\n  }\n  if (Sys.info()['sysname'] == 'Windows') {\n    models_list <- mclapply(1:num_steps, runSVM, mc.cores=1)\n  } else {\n    models_list <- mclapply(1:num_steps, runSVM, mc.cores=num_steps)\n  }\n  rmse_vec <- rep(0, num_steps)\n  corr_vec <- rep(0, num_steps)\n  for (i in 1:num_steps) {\n    current_model <- models_list[[i]]\n    weight_vals <- t(current_model$coefs) %*% current_model$SV\n    weight_vals[which(weight_vals < 0)] <- 0\n    norm_weights <- weight_vals / sum(weight_vals)\n    weighted_refer <- sweep(refer_matrix, MARGIN=2, norm_weights, '*')\n    est_target <- apply(weighted_refer, 1, sum)\n    rmse_vec[i] <- sqrt(mean((est_target - target_vector)^2))\n    corr_vec[i] <- cor(est_target, target_vector)\n  }\n  bes",
"t_idx <- which.min(rmse_vec)\n  best_model <- models_list[[best_idx]]\n  best_weights <- t(best_model$coefs) %*% best_model$SV\n  best_weights[which(best_weights < 0)] <- 0\n  final_weights <- best_weights / sum(best_weights)\n  list(\"final_weights\" = final_weights, \"best_rmse\" = rmse_vec[best_idx], \"best_corr\" = corr_vec[best_idx])\n}\n\n# \u7f6e\u6362\u68c0\u9a8c\u51fd\u6570\ndoPermutation <- function(num_perm, refer_matrix, mix_matrix) {\n  target_list <- as.list(data.matrix(mix_matrix))\n  corr_distribution <- numeric()\n  perm_progress <- txtProgressBar(min = 0, max = num_perm, style = 3)\n  for (perm_counter in 1:num_perm) {\n    permuted_target <- as.numeric(target_list[sample(length(target_list), nrow(refer_matrix), replace = TRUE)])\n    if (sd(permuted_target) == 0) {\n      std_target <- permuted_target\n    } else {\n      std_target <- (permuted_target - mean(permuted_target)) / sd(permuted_target)\n    }\n    perm_result <- coreAlgorithm(refer_matrix, std_target)\n    corr_distribution <- c(corr_distribution, perm_result$best_corr)\n    setTxtProgressBar(perm_progress, perm_counter)\n  }\n  close(perm_progress)\n  list(\"null_distribution\" = sort(corr_distribution))\n}\n\n# CIBERSORT\u4e3b\u51fd\u6570\nCIBERSORTModified <- function(refer_file, mix_file, num_perm = 0, do_QN = TRUE) {\n  if (!file.exists(refer_file)) stop(\"\u53c2\u8003\u6587\u4ef6\u672a\u627e\u5230\uff01\")\n  if (!file.exists(mix_file)) stop(\"\u6df7\u5408\u6587\u4ef6\u672a\u627e\u5230\uff01\")\n  refer_data <- data.matrix(read.table(refer_file, header=TRUE, sep=\"\\t\", row.names=1, check.names=FALSE))\n  mix_data   <- data.matrix(read.table(mix_file, header=TRUE, sep=\",\", row.names=1, check.names=FALSE))\n  refer_data <- refer_data[order(rownames(refer_data)), ]\n  mix_data   <- mix_data[order(rownames(mix_data)), ]\n  if (max(mix_data) < 50) mix_data <- 2^mix_data\n  if (do_QN) {\n    orig_colnames <- colnames(mix_data); orig_rownames <- rownames(mix_dat",
"a)\n    mix_data <- normalize.quantiles(mix_data)\n    colnames(mix_data) <- orig_colnames; rownames(mix_data) <- orig_rownames\n  }\n  common_genes <- intersect(rownames(refer_data), rownames(mix_data))\n  if (length(common_genes) == 0) stop(\"\u53c2\u8003\u6570\u636e\u4e0e\u6df7\u5408\u6570\u636e\u4e4b\u95f4\u6ca1\u6709\u5171\u540c\u57fa\u56e0\uff01\")\n  refer_data <- refer_data[common_genes, , drop=FALSE]\n  mix_data   <- mix_data[common_genes, , drop=FALSE]\n  refer_data <- (refer_data - mean(refer_data)) / sd(as.vector(refer_data))\n  null_dist <- NULL\n  if (num_perm > 0) {\n    null_dist <- doPermutation(num_perm, refer_data, mix_data)$null_distribution\n  }\n  output_header <- c(\"Mixture\", colnames(refer_data), \"P-value\", \"Correlation\", \"RMSE\")\n  output_matrix <- NULL\n  total_samples <- ncol(mix_data)\n  sample_progress <- txtProgressBar(min=0, max=total_samples, style=3)\n  for (sample_idx in 1:total_samples) {\n    curr_sample <- mix_data[, sample_idx]\n    std_sample <- if (sd(curr_sample)==0) curr_sample else (curr_sample - mean(curr_sample)) / sd(curr_sample)\n    alg_result <- coreAlgorithm(refer_data, std_sample)\n    p_val <- NA\n    if (!is.null(null_dist)) {\n      p_val <- 1 - (which.min(abs(null_dist - alg_result$best_corr)) / length(null_dist))\n    }\n    curr_result <- c(colnames(mix_data)[sample_idx], alg_result$final_weights, p_val, alg_result$best_corr, alg_result$best_rmse)\n    output_matrix <- rbind(output_matrix, curr_result)\n    setTxtProgressBar(sample_progress, sample_idx)\n  }\n  close(sample_progress)\n  write.table(rbind(output_header, output_matrix), file=\"CIBERSORT-Results.csv\", sep=\",\", row.names=FALSE, col.names=FALSE, quote=FALSE)\n  result_numeric <- rbind(output_header, output_matrix)\n  result_numeric <- result_numeric[,-1]\n  result_numeric <- result_numeric[-1,]\n  result_numeric <- matrix(as.numeric(unlist(result_numeric)), nrow=nrow(output_ma",
"trix))\n  rownames(result_numeric) <- colnames(mix_data)\n  colnames(result_numeric) <- c(colnames(refer_data), \"P-value\", \"Correlation\", \"RMSE\")\n  return(result_numeric)\n}\n\n# \u8fd0\u884cCIBERSORT\nresult_table <- CIBERSORTModified(refer_file, input_file, num_perm=1000, do_QN=TRUE)\n\n# \u7b5b\u9009\u5e76\u8f93\u51fa\nfiltered_table <- result_table[result_table[,\"P-value\"] < 1, ]\nweight_only <- as.matrix(filtered_table[, 1:(ncol(filtered_table)-3)])\nfinal_output <- rbind(id=colnames(weight_only), weight_only)\nwrite.table(final_output, file=\"CIBERSORT-Results.csv\", sep=\",\", quote=FALSE, col.names=FALSE)\ncat(\">> CIBERSORT\u5206\u6790\u5b8c\u6210\uff0c\u7ed3\u679c\u5df2\u4fdd\u5b58\u81f3 CIBERSORT-Results.csv\\n\")\n\n# ============================================================\n# \u7b2c\u4e8c\u90e8\u5206\uff1a\u514d\u75ab\u6d78\u6da6\u53ef\u89c6\u5316\uff08\u7bb1\u7ebf\u56fe + \u5806\u53e0\u6761\u5f62\u56fe\uff09\n# ============================================================\ncat(\"\\n==== \u7b2c\u4e8c\u90e8\u5206\uff1a\u514d\u75ab\u6d78\u6da6\u53ef\u89c6\u5316 ====\\n\")\n\n# \u8bfb\u53d6CIBERSORT\u7ed3\u679c\nrt <- read.table(\"CIBERSORT-Results.csv\", header=TRUE, sep=\",\", check.names=FALSE, row.names=1)\n\n# \u6839\u636e\u6837\u672c\u540e\u7f00\u5224\u65ad\u5206\u7ec4\nrt$Group <- ifelse(grepl(\"_con$\", rownames(rt), ignore.case=TRUE), \"Control\",\n                   ifelse(grepl(\"_tra$\", rownames(rt), ignore.case=TRUE), \"traat\", NA))\nrt$Sample <- rownames(rt)\n\ncontrol_samples <- rownames(rt)[rt$Group == \"Control\"]\ntraat_samples   <- rownames(rt)[rt$Group == \"traat\"]\nall_samples_ordered <- c(control_samples, \"gap\", traat_samples)\n\n# \u8f6c\u4e3a\u957f\u683c\u5f0f\ndata_long <- melt(rt, id.vars=c(\"Sample\",\"Group\"), variable.name=\"Immune\", value.name=\"Fraction\")\ndata_long$Sample <- factor(data_long$Sample, levels=all_samples_ordered)\n\ncountControl <- length(unique(data_long$Sample[data_long$Group == \"Control\"]))\ncounttraat   <- length(unique(data_long$Sample[data_long$Group == \"traat\"]))\n\n# ---- \u7bb1\u7ebf\u56fe\uff1a\u4e24\u7ec4\u514d\u75ab\u7ec6\u80de\u6bd4\u8f83 ----\nboxplot_immune <- ggboxplot(\n  data_long, x=\"Immune\", y=\"Fraction\", fill=\"Group\",\n  palette=c(\"Control\"=\"#FFC0CB\", \"traat\"=\"#87CEFA",
"\"),\n  xlab=\"\", ylab=\"Fraction\", legend.title=\"Group\", notch=FALSE, width=0.8\n) +\n  stat_compare_means(\n    aes(group=Group), label=\"p.signif\",\n    symnum.args=list(cutpoints=c(0,0.001,0.01,0.05,1), symbols=c(\"***\",\"**\",\"*\",\"ns\")),\n    label.y.npc=\"top\", vjust=-0.5\n  ) +\n  theme_classic(base_size=14) +\n  theme(legend.position=\"top\", axis.text.x=element_text(angle=45, hjust=1),\n        axis.line=element_line(color=\"black\", size=1),\n        axis.ticks=element_line(color=\"black\", size=1),\n        plot.margin=margin(20,10,10,10)) +\n  labs(title=\"Immune Cell Comparison\",\n       subtitle=paste0(\" (Control n=\", countControl, \", traat n=\", counttraat, \")\")) +\n  coord_cartesian(clip=\"off\")\n\nggsave(\"immune_diff-points_n.pdf\", boxplot_immune, width=8, height=6)\ncat(\">> \u7bb1\u7ebf\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1aimmune_diff-points_n.pdf\\n\")\n\n# \u5bfc\u51fa\u7edf\u8ba1\u8868\nsummary_table <- data_long %>%\n  filter(!is.na(Group)) %>%\n  group_by(Immune, Group) %>%\n  summarise(MeanFraction=mean(Fraction, na.rm=TRUE), MedianFraction=median(Fraction, na.rm=TRUE),\n            SD=sd(Fraction, na.rm=TRUE), Count=n(), .groups=\"drop\")\nwrite.csv(summary_table, file=\"boxplot_summary_table.csv\", row.names=FALSE)\n\npvalue_table <- data_long %>%\n  filter(!is.na(Group)) %>%\n  group_by(Immune) %>%\n  do(tidy(wilcox.test(Fraction ~ Group, data=.))) %>%\n  dplyr::select(Immune, p.value)\nwrite.csv(pvalue_table, file=\"immune_pvalues.csv\", row.names=FALSE)\ncat(\">> \u7edf\u8ba1\u6c47\u603b\u8868\u548cp\u503c\u8868\u5df2\u4fdd\u5b58\\n\")\n\n# ---- \u5806\u53e0\u6761\u5f62\u56fe ----\nimmune_types <- unique(data_long$Immune)\nnColors <- length(immune_types)\nmyColors <- colorRampPalette(brewer.pal(12, \"Set3\"))(nColors)\n\nbarplot_immune <- ggplot(data_long, aes(x=Sample, y=Fraction, fill=Immune)) +\n  geom_bar(stat=\"identity\") +\n  scale_fill_manual(values=myColors) +\n  scale_x_discrete(drop=FALSE) +\n  theme_minimal(base_size=18) +\n  theme(text=element_text(",
"face=\"bold\"), axis.text.x=element_blank(),\n        axis.ticks.x=element_blank(), panel.grid.major.x=element_blank()) +\n  labs(x=NULL, y=\"Relative Percent\", fill=\"Immune\\nCell Type\",\n       title=\"Immune Cell Distribution\", subtitle=\"Control vs. traat\") +\n  coord_cartesian(clip=\"off\") +\n  scale_y_continuous(expand=expansion(mult=c(0.1, 0.05)))\n\ncontrol_count <- length(control_samples)\ntraat_count   <- length(traat_samples)\n\nbarplot_immune <- barplot_immune +\n  annotate(\"segment\", x=0.5, xend=control_count+0.5, y=-0.04, yend=-0.04, color=\"#D65DB1\", size=5) +\n  annotate(\"text\", x=(control_count)/2+0.5, y=-0.08, label=\"Control\", color=\"#D65DB1\", size=7, fontface=\"bold\") +\n  annotate(\"segment\", x=control_count+1.5, xend=control_count+traat_count+1.5, y=-0.04, yend=-0.04, color=\"#0089BA\", size=5) +\n  annotate(\"text\", x=control_count+(traat_count)/2+1.5, y=-0.08, label=\"traat\", color=\"#0089BA\", size=7, fontface=\"bold\")\n\nggsave(\"barplot_two_lines_set3_gap.pdf\", barplot_immune, width=12, height=7.5)\ncat(\">> \u5806\u53e0\u6761\u5f62\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1abarplot_two_lines_set3_gap.pdf\\n\")\n\n# ============================================================\n# \u7b2c\u4e09\u90e8\u5206\uff1a\u5173\u952e\u57fa\u56e0\u4e0e\u514d\u75ab\u6d78\u6da6\u7ec6\u80de\u7684\u76f8\u5173\u6027\u5206\u6790\n# ============================================================\ncat(\"\\n==== \u7b2c\u4e09\u90e8\u5206\uff1a\u57fa\u56e0-\u514d\u75ab\u6d78\u6da6\u7ec6\u80de\u76f8\u5173\u6027\u5206\u6790 ====\\n\")\n\n# \u8bfb\u53d6\u57fa\u56e0\u8868\u8fbe\u6570\u636e\nexprRaw <- read.table(input_file, header=TRUE, sep=\",\", check.names=FALSE)\nexprMat <- as.matrix(exprRaw)\nrownames(exprMat) <- exprMat[, 1]\nexprVals <- exprMat[, -1, drop=FALSE]\nrowNamesTmp <- rownames(exprVals)\ncolNamesTmp <- colnames(exprVals)\nnumExpr <- matrix(as.numeric(as.matrix(exprVals)), nrow=nrow(exprVals),\n                  dimnames=list(rowNamesTmp, colNamesTmp))\nnumExpr <- avereps(numExpr)\n\n# \u8bfb\u53d6\u76ee\u6807\u57fa\u56e0\u5217\u8868\uff08CSV\u683c\u5f0f\uff0c\u6709\u8868\u5934Gene\uff09\ngene_list <- read.csv(gene_list_file, header=TRUE, stringsAsFactors=FALSE)\ntargetGene <- as.character(gen",
"e_list[, 1])\ntargetGene <- targetGene[targetGene != \"\"]\n\n# \u7b5b\u9009\u76ee\u6807\u57fa\u56e0\nmatched_genes <- targetGene[targetGene %in% rownames(numExpr)]\ncat(\"\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(targetGene), \"\uff0c\u5339\u914d\u5230\uff1a\", length(matched_genes), \"\\n\")\nexprSelected <- t(numExpr[matched_genes, , drop=FALSE])\n\n# \u4eceCIBERSORT\u7ed3\u679c\u63d0\u53d6\u514d\u75ab\u6d78\u6da6\u77e9\u9635\uff08\u5bbd\u683c\u5f0f\uff09\nimmune_cols <- setdiff(colnames(rt), c(\"Sample\", \"Group\"))\nimmuneMat <- as.matrix(rt[, immune_cols])\nimmuneMat <- apply(immuneMat, 2, as.numeric)\nrownames(immuneMat) <- rownames(rt)\n\n# \u53d6\u5171\u540c\u6837\u672c\ncommonSamples <- intersect(rownames(exprSelected), rownames(immuneMat))\ncat(\"\u5171\u540c\u6837\u672c\u6570\uff1a\", length(commonSamples), \"\\n\")\nexprSelected <- exprSelected[commonSamples, , drop=FALSE]\nimmuneMat    <- immuneMat[commonSamples, , drop=FALSE]\n\n# \u79fb\u9664\u6807\u51c6\u5dee\u4e3a0\u7684\u514d\u75ab\u7ec6\u80de\u5217\nvalidImmune <- immuneMat[, apply(immuneMat, 2, sd) > 0, drop=FALSE]\ncat(\"\u6709\u6548\u514d\u75ab\u7ec6\u80de\u7c7b\u578b\u6570\uff1a\", ncol(validImmune), \"\\n\")\n\n# \u8ba1\u7b97Spearman\u76f8\u5173\u6027\ncor_mat     <- matrix(NA, nrow=ncol(exprSelected), ncol=ncol(validImmune),\n                      dimnames=list(colnames(exprSelected), colnames(validImmune)))\np_val_matrix <- matrix(NA, nrow=ncol(exprSelected), ncol=ncol(validImmune),\n                       dimnames=list(colnames(exprSelected), colnames(validImmune)))\n\nfor (i in seq_len(ncol(exprSelected))) {\n  for (j in seq_len(ncol(validImmune))) {\n    test_result <- cor.test(exprSelected[,i], validImmune[,j], method=\"spearman\", use=\"pairwise.complete.obs\")\n    cor_mat[i,j]     <- test_result$estimate\n    p_val_matrix[i,j] <- test_result$p.value\n  }\n}\n\n# \u521b\u5efa\u6807\u7b7e\u77e9\u9635\uff08\u76f8\u5173\u7cfb\u6570 + \u663e\u8457\u6027\u661f\u53f7\uff09\nlabels_mat <- matrix(\"\", nrow=nrow(cor_mat), ncol=ncol(cor_mat),\n                     dimnames=dimnames(cor_mat))\nfor (i in 1:nrow(cor_mat)) {\n  for (j in 1:ncol(cor_mat)) {\n    stars <- \"\"\n    if (!is.na(p_val_matrix[i,j])) {\n      if (p_val_matrix[i,j] < 0.001) stars <- \"***\"\n      else if (p_val_matrix[i,j] < 0",
".01) stars <- \"**\"\n      else if (p_val_matrix[i,j] < 0.05) stars <- \"*\"\n    }\n    cor_val <- ifelse(is.na(cor_mat[i,j]), \"\", round(cor_mat[i,j], 2))\n    labels_mat[i,j] <- paste0(cor_val, \"\\n\", stars)\n  }\n}\n\n# \u8c03\u8bd5\u8f93\u51fa\ncat(\"cor_mat \u7ef4\u5ea6\uff1a\", nrow(cor_mat), \"x\", ncol(cor_mat), \"\\n\")\ncat(\"cor_mat \u884c\u540d\uff1a\", paste(rownames(cor_mat), collapse=\", \"), \"\\n\")\ncat(\"labels_mat \u7ef4\u5ea6\uff1a\", nrow(labels_mat), \"x\", ncol(labels_mat), \"\\n\")\n\n# \u7ed8\u5236\u76f8\u5173\u6027\u70ed\u56fe\ngene_num   <- nrow(cor_mat)\nimmune_num <- ncol(cor_mat)\npdf_width  <- max(8, 4 + 0.5 * immune_num)\npdf_height <- max(5, 3 + 0.6 * gene_num)\nmy_col_fun <- colorRampPalette(c(\"#6b8e23\", \"white\", \"#ba6262\"))(100)\n\n# \u786e\u4fddcor_mat\u8f6c\u4e3adata.frame\u518d\u8f6c\u56dematrix\uff0c\u907f\u514dpheatmap\u7684\u7ef4\u5ea6\u95ee\u9898\ncor_mat_plot <- as.matrix(as.data.frame(cor_mat))\n\npdf(\"Gene_Immune_Correlation_Heatmap.pdf\", width=pdf_width, height=pdf_height)\npheatmap(\n  cor_mat_plot, color=my_col_fun, display_numbers=labels_mat,\n  number_color=\"black\", cluster_rows=FALSE, cluster_cols=FALSE,\n  fontsize_number=7, fontsize_row=12, fontsize_col=9, border_color=\"grey90\",\n  main=\"Hub Genes - Immune Cell Correlation Heatmap\",\n  angle_col=45\n)\ndev.off()\ncat(\">> \u76f8\u5173\u6027\u70ed\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1aGene_Immune_Correlation_Heatmap.pdf\\n\")\n\n# \u5bfc\u51fa\u76f8\u5173\u6027\u7ed3\u679c\u8868\ncorrDF <- data.frame()\nfor (i in 1:nrow(cor_mat)) {\n  for (j in 1:ncol(cor_mat)) {\n    corrDF <- rbind(corrDF, data.frame(\n      Gene=rownames(cor_mat)[i], ImmuneCell=colnames(cor_mat)[j],\n      Correlation=cor_mat[i,j], P.Value=p_val_matrix[i,j],\n      Significance=ifelse(p_val_matrix[i,j] < 0.05, \"Yes\", \"No\")\n    ))\n  }\n}\nwrite.csv(corrDF, file=\"Gene_Immune_Correlation_Results.csv\", row.names=FALSE)\ncat(\">> \u76f8\u5173\u6027\u7ed3\u679c\u8868\u5df2\u4fdd\u5b58\u4e3a\uff1aGene_Immune_Correlation_Results.csv\\n\")\n\n# ============================================================\n# \u7b2c\u56db\u90e8\u5206\uff1a\u65b9\u5757\u6c14\u6ce1\u56fe\uff08Square Bubble Chart\uff09\u57fa\u56e0-\u514d\u75ab\u7ec6\u80de\u76f8\u5173\u6027\n# ==================================================",
"==========\ncat(\"\\n==== \u7b2c\u56db\u90e8\u5206\uff1a\u65b9\u5757\u6c14\u6ce1\u56fe ====\\n\")\n\nlibrary(ggplot2)\nlibrary(scales)\n\n# \u51c6\u5907\u6570\u636e\uff08\u76f4\u63a5\u7528corrDF\uff0c\u514d\u75ab\u7ec6\u80de\u540d\u4fdd\u6301\u539f\u6837\uff09\nbubble_df <- corrDF[!is.na(corrDF$P.Value) & !is.na(corrDF$Correlation), ]\nbubble_df$AbsCorr <- abs(bubble_df$Correlation)\n\n# \u663e\u8457\u6027\u6807\u8bb0\nbubble_df$Sig <- ifelse(bubble_df$P.Value < 0.001, \"***\",\n                 ifelse(bubble_df$P.Value < 0.01, \"**\",\n                 ifelse(bubble_df$P.Value < 0.05, \"*\", \"\")))\n\n# \u8c03\u8bd5\uff1a\u6253\u5370\u6570\u636e\u786e\u8ba4\ncat(\"bubble_df \u884c\u6570\uff1a\", nrow(bubble_df), \"\\n\")\ncat(\"\u57fa\u56e0\uff1a\", paste(unique(bubble_df$Gene), collapse=\", \"), \"\\n\")\ncat(\"\u514d\u75ab\u7ec6\u80de\uff1a\", paste(unique(bubble_df$ImmuneCell), collapse=\", \"), \"\\n\")\n\n# \u514d\u75ab\u7ec6\u80de\u6309\u540d\u79f0\u6392\u5e8f\nbubble_df$ImmuneCell <- factor(bubble_df$ImmuneCell,\n                               levels = rev(sort(unique(bubble_df$ImmuneCell))))\nbubble_df$Gene <- factor(bubble_df$Gene, levels = sort(unique(as.character(bubble_df$Gene))))\n\n# \u56fe\u5c3a\u5bf8\nn_genes  <- length(unique(bubble_df$Gene))\nn_immune <- length(unique(bubble_df$ImmuneCell))\nfig_width  <- max(6, 3 + n_genes * 1.5)\nfig_height <- max(8, 2 + n_immune * 0.42)\n\npdf(\"Gene_Immune_SquareBubble.pdf\", width = fig_width-2, height = fig_height-4)\np_bubble <- ggplot(bubble_df, aes(x = Gene, y = ImmuneCell)) +\n  geom_point(aes(size = AbsCorr, fill = Correlation),\n             shape = 22, color = \"grey30\", stroke = 0.3) +\n  scale_fill_viridis_c(option = \"viridis\",\n                       limits = c(-max(bubble_df$AbsCorr), max(bubble_df$AbsCorr)),\n                       oob = squish, name = \"Correlation\",\n                       breaks = pretty(range(bubble_df$Correlation), n = 5)) +\n  scale_size_continuous(range = c(2, 10), guide = \"none\") +\n  geom_text(data = bubble_df[bubble_df$Sig != \"\", ],\n            aes(label = Sig), color = \"white\", size = 4, fontface = \"bold\", vjust = 0.5) +\n  theme(\n    panel.background = element_rect(fil",
"l = \"white\", color = \"black\", size = 1.2),\n    panel.grid.major = element_line(color = \"black\", size = 0.6),\n    panel.grid.minor = element_blank(),\n    axis.text.x = element_text(size = 12, color = \"black\", angle = 45, hjust = 1, face = \"italic\"),\n    axis.text.y = element_text(size = 10, color = \"black\"),\n    axis.title = element_blank(),\n    axis.ticks = element_line(color = \"black\", size = 0.8),\n    legend.position = \"right\",\n    legend.key.height = unit(1.8, \"cm\"),\n    legend.key.width = unit(0.4, \"cm\"),\n    legend.title = element_text(size = 11, face = \"bold\"),\n    legend.text = element_text(size = 10),\n    plot.margin = margin(10, 10, 10, 10)\n  )\nprint(p_bubble)\ndev.off()\ncat(\">> \u65b9\u5757\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1aGene_Immune_SquareBubble.pdf\\n\")\n\ncat(\"\\n==== \u5168\u6d41\u7a0b\u6267\u884c\u5b8c\u6bd5\uff01====\\n\")\n"),
"legacy_analysis/23.\u8bca\u65ad\u6a21\u578b\u57fa\u56e0\u4e0e22\u79cd\u514d\u75ab\u76f8\u5173\u7ec6\u80de\u6d78\u6da6\u7684\u76f8\u5173\u6027\uff08CIBERSORT\uff09/\u6765\u6e90.R"=paste0("##\u8fd9\u6bb5\u4ee3\u7801\u6765\u81ea\u4e8e CIBERSORT R script v1.03\uff0c\u7531 Aaron M. Newman\uff08\u65af\u5766\u798f\u5927\u5b66\uff09\u5f00\u53d1\u3002\u8be6\u7ec6\u7684\u4f7f\u7528\u8bf4\u660e\u3001\u4f9d\u8d56\u8981\u6c42\u4ee5\u53ca\u8bb8\u53ef\u6761\u6b3e\u53ef\u4ee5\u5728 CIBERSORT \u5b98\u65b9\u7f51\u7ad9\u4e0a\u627e\u5230\uff0c\u4f8b\u5982\u5728 CIBERSORT \u5b98\u7f51 \u548c \u8bb8\u53ef\u8bf4\u660e \u4e2d\u3002\n#\u539f\u59cb\u6765\u6e90\u662f CIBERSORT R script v1.03\uff0c\u5176\u8be6\u7ec6\u4fe1\u606f\u5982\u4e0b\uff1a\n\n#\u4f5c\u8005\u4e0e\u673a\u6784\uff1a\n#\u8be5\u811a\u672c\u7531 Aaron M. Newman \u7f16\u5199\uff0c\u96b6\u5c5e\u4e8e\u65af\u5766\u798f\u5927\u5b66\uff08\u8054\u7cfb\u65b9\u5f0f\uff1aamnewman@stanford.edu\uff09\u3002\n\n#\u529f\u80fd\u7b80\u4ecb\uff1a\n#CIBERSORT \u662f\u4e00\u79cd\u7528\u4e8e\u4ece\u6df7\u5408\u57fa\u56e0\u8868\u8fbe\u6570\u636e\u4e2d\u4f30\u8ba1\u5404\u4e2a\u7ec6\u80de\u7c7b\u578b\u6bd4\u4f8b\u7684\u8ba1\u7b97\u65b9\u6cd5\u3002\u811a\u672c\u4e3b\u8981\u5229\u7528\u652f\u6301\u5411\u91cf\u56de\u5f52\uff08SVR\uff09\u5bf9\u8f93\u5165\u6570\u636e\u8fdb\u884c\u5206\u89e3\u3002\u5176\u6838\u5fc3\u7b97\u6cd5\u4f1a\u5c1d\u8bd5\u591a\u4e2a nu \u53c2\u6570\uff08\u4f8b\u5982 0.25\u30010.5\u30010.75\uff09\uff0c\u4ee5\u5bfb\u627e\u6700\u4f18\u6a21\u578b\uff0c\u5e76\u8fdb\u4e00\u6b65\u8ba1\u7b97\u76f8\u5173\u7cfb\u6570\u548c\u5747\u65b9\u6839\u8bef\u5dee\uff08RMSE\uff09\uff0c\u4ece\u800c\u8bc4\u4f30\u6a21\u578b\u7684\u8868\u73b0\u3002\n#\u5c06\u8be5 R \u811a\u672c\u4fdd\u5b58\u5230\u672c\u5730\u76ee\u5f55\u4e2d\u3002\n\n#perm \u53c2\u6570\u63a7\u5236\u7f6e\u6362\u68c0\u9a8c\u7684\u6b21\u6570\uff08\u7528\u4e8e\u8ba1\u7b97 p \u503c\uff0c\u5efa\u8bae\u8bbe\u7f6e\u4e3a 100 \u6216\u4ee5\u4e0a\uff09\uff0c\n\n#QN \u53c2\u6570\u63a7\u5236\u662f\u5426\u5bf9\u6df7\u5408\u6570\u636e\u8fdb\u884c\u91cf\u5316\u5f52\u4e00\u5316\uff08\u9ed8\u8ba4 TRUE\uff09\u3002\n\n#\u5176\u4ed6\u8bf4\u660e\uff1a\n\n#\u7b7e\u540d\u77e9\u9635\u6784\u5efa\u529f\u80fd\u5f53\u524d\u672a\u5305\u542b\u5728\u8be5 R \u811a\u672c\u4e2d\uff0c\u82e5\u9700\u8981\u5b8c\u6574\u529f\u80fd\uff08\u5305\u62ec\u7b7e\u540d\u77e9\u9635\u6784\u5efa\uff09\uff0c\u5efa\u8bae\u4f7f\u7528 CIBERSORT \u7684 Java \u7248\u672c\u3002\n\n#\u811a\u672c\u4f1a\u5c06\u5206\u6790\u7ed3\u679c\u8f93\u51fa\u6587\u4ef6\uff0c\u5e76\u9644\u5e26\u4e00\u4e2a\u77e9\u9635\u5bf9\u8c61\uff0c\u5176\u4e2d\u5305\u542b\u5404\u6df7\u5408\u6837\u672c\u7684\u7ec6\u80de\u6bd4\u4f8b\u4f30\u8ba1\u3001p \u503c\u3001\u76f8\u5173\u7cfb\u6570\u548c RMSE\u3002\n\n#\u8bb8\u53ef\u8bc1\u4fe1\u606f\u53ef\u53c2\u8003 CIBERSORT \u8bb8\u53ef\u8bc1\u3002\n\n#\u8fd9\u4e9b\u7ec6\u8282\u53ef\u4ee5\u5728 CIBERSORT \u7684\u5b98\u65b9\u7f51\u7ad9\uff08http://cibersort.stanford.edu\uff09\u4ee5\u53ca\u76f8\u5173\u6559\u7a0b\u4e2d\u627e\u5230\u66f4\u8be6\u7ec6\u7684\u63cf\u8ff0\u3002\n#' CIBERSORT R script v1.03\n#' Note: Signature matrix construction is not currently available; use java version for full functionality.\n#' Author: Aaron M. Newman, Stanford University (amnewman@stanford.edu)\n#' Requirements:\n#'       R v3.0 or later. (dependencies below might not work properly with earlier versions)\n#'       install.packages('e1071')\n#'       install.pacakges('parallel')\n#'       install.packages('preprocessCore')\n#'       if preprocessCore is not available in the repositories you have selected, run the following:\n#'           source(\"http://bioconductor.org/biocLite.R\")\n#'           biocLite(\"preprocessCore\")\n#' Windows users using the R GUI may need to Run as Administrator to install or update packages.\n#' This script uses 3 parallel processes.  Since Windows does not support forking, this script will run\n#' single-threaded in Windows.\n#'\n#' Usage:\n#'       Navigate to directory containing R script\n#'\n#'   In R:\n#'       source('CIBERSORT.R')\n#'       results <- CIBERSORT('sig_matrix_file.txt','mixture_file.txt', perm, QN)\n#'\n#'       Optio",
"ns:\n#'       i)  perm = No. permutations; set to >=100 to calculate p-values (default = 0)\n#'       ii) QN = Quantile normalization of input mixture (default = TRUE)\n#'\n#' Input: signature matrix and mixture file, formatted as specified at http://cibersort.stanford.edu/tutorial.php\n#' Output: matrix object containing all results and tabular data written to disk 'CIBERSORT-Results.txt'\n#' License: http://cibersort.stanford.edu/CIBERSORT_License.txt\n#' Core algorithm\n#' @param X cell-specific gene expression\n#' @param y mixed expression per sample\n#' @export"),
"legacy_analysis/24.\u8bca\u65ad\u6a21\u578b\u57fa\u56e0\u4e0e\u514d\u75ab\u76f8\u5173\u7ec6\u80de\u4e30\u5ea6\u7684\u76f8\u5173\u6027\uff08MCP-counter\uff09/MCP-counte\u5206\u6790.R"=paste0("# ==== MCP-counter \u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u5206\u6790\u5b8c\u6574\u6d41\u7a0b ====\n\n# ============================ \u52a0\u8f7d\u5fc5\u8981\u5305 =============================\nlibrary(MCPcounter)\nlibrary(reshape2)\nlibrary(ggplot2)\nlibrary(RColorBrewer)\nlibrary(ggpubr)\nlibrary(dplyr)\nlibrary(broom)\nlibrary(ggsci)\nlibrary(limma)\nlibrary(pheatmap)\n\n\n\n# ============================ \u53c2\u6570\u8bbe\u7f6e =============================\nwork_dir       <- \"C:\\\\Users\\\\yangbo\\\\Desktop\\\\UC-\u65b0\\\\24.\u8bca\u65ad\u6a21\u578b\u57fa\u56e0\u4e0e\u514d\u75ab\u76f8\u5173\u7ec6\u80de\u4e30\u5ea6\u7684\u76f8\u5173\u6027\uff08MCP-counter\uff09\"\ninput_file     <- \"batch_corrected_data.csv\"\ngene_list_file <- \"Intersect_Genes.csv\"\n\nsetwd(work_dir)\n\n# ============================================================\n# \u7b2c\u4e00\u90e8\u5206\uff1aMCP-counter \u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u4f30\u7b97\n# ============================================================\ncat(\"==== \u7b2c\u4e00\u90e8\u5206\uff1aMCP-counter \u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u4f30\u7b97 ====\\n\")\n\n# \u8bfb\u53d6\u8868\u8fbe\u6570\u636e\nexprRaw <- read.table(input_file, header=TRUE, sep=\",\", check.names=FALSE)\nexprMat <- as.matrix(exprRaw)\nrownames(exprMat) <- exprMat[, 1]\nexprVals <- exprMat[, -1, drop=FALSE]\nrowNamesTmp <- rownames(exprVals)\ncolNamesTmp <- colnames(exprVals)\nnumExpr <- matrix(as.numeric(as.matrix(exprVals)), nrow=nrow(exprVals),\n                  dimnames=list(rowNamesTmp, colNamesTmp))\nnumExpr <- avereps(numExpr)\n\ncat(\"\u8868\u8fbe\u77e9\u9635\u7ef4\u5ea6\uff1a\", nrow(numExpr), \"x\", ncol(numExpr), \"\\n\")\n\n# \u8fd0\u884cMCP-counter\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u4f30\u7b97\ncat(\"\u6b63\u5728\u8fd0\u884cMCP-counter\u7b97\u6cd5...\\n\")\n\n# \u4f7f\u7528\u672c\u5730\u7b7e\u540d\u6587\u4ef6 + HUGO\u57fa\u56e0\u7b26\u53f7\u6a21\u5f0f\u8fdb\u884cMCPcounter\u4f30\u7b97\nimmune_abundance <- MCPcounter.estimate(\n  expression = numExpr,\n  featuresType = \"HUGO_symbols\",\n  genes = read.table(\"genes.txt\", header=TRUE, sep=\"\\t\", stringsAsFactors=FALSE, check.names=FALSE),\n  probesets = read.table(\"probesets.txt\", header=FALSE, sep=\"\\t\", stringsAsFactors=FALSE, check.names=FALSE)\n)\n\n# \u8f6c\u6362\u4e3a\u6570\u636e\u6846\uff08MCPcounter\u8f93\u51fa\uff1a\u884c=\u7ec6\u80de\u7c7b\u578b\uff0c\u5217=\u6837\u672c\uff0c\u9700\u8f6c\u7f6e\uff09\nimmune_df <- as.data.frame(t(immune_abundance))\n\n# \u8f93\u51fa\u7ed3\u679c\nwrite.csv(immune_df, file=\"MCP-counter-Results.csv\", row.names=TRUE)\ncat(\">> MCP-counter\u5206\u6790\u5b8c\u6210",
"\uff0c\u7ed3\u679c\u5df2\u4fdd\u5b58\u81f3 MCP-counter-Results.csv\\n\")\ncat(\">> \u514d\u75ab\u7ec6\u80de\u7c7b\u578b\u6570\uff1a\", ncol(immune_df), \"\\n\")\n\n# ============================================================\n# \u7b2c\u4e8c\u90e8\u5206\uff1a\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u53ef\u89c6\u5316\uff08\u7bb1\u7ebf\u56fe + \u5806\u53e0\u6761\u5f62\u56fe\uff09\n# ============================================================\ncat(\"\\n==== \u7b2c\u4e8c\u90e8\u5206\uff1a\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u53ef\u89c6\u5316 ====\\n\")\n\n# \u8bfb\u53d6MCP-counter\u7ed3\u679c\nrt <- immune_df\n\n# \u6839\u636e\u6837\u672c\u540e\u7f00\u5224\u65ad\u5206\u7ec4\nrt$Group <- ifelse(grepl(\"_con$\", rownames(rt), ignore.case=TRUE), \"Control\",\n                   ifelse(grepl(\"_tra$\", rownames(rt), ignore.case=TRUE), \"Treat\", NA))\nrt$Sample <- rownames(rt)\n\ncontrol_samples <- rownames(rt)[rt$Group == \"Control\"]\ntreat_samples   <- rownames(rt)[rt$Group == \"Treat\"]\nall_samples_ordered <- c(control_samples, \"gap\", treat_samples)\n\n# \u8f6c\u4e3a\u957f\u683c\u5f0f\ndata_long <- melt(rt, id.vars=c(\"Sample\",\"Group\"), variable.name=\"Immune\", value.name=\"Abundance\")\ndata_long$Sample <- factor(data_long$Sample, levels=all_samples_ordered)\n\ncountControl <- length(unique(data_long$Sample[data_long$Group == \"Control\"]))\ncountTreat   <- length(unique(data_long$Sample[data_long$Group == \"Treat\"]))\n\n# ---- \u7bb1\u7ebf\u56fe\uff1a\u4e24\u7ec4\u514d\u75ab\u7ec6\u80de\u6bd4\u8f83 ----\nboxplot_immune <- ggboxplot(\n  data_long, x=\"Immune\", y=\"Abundance\", fill=\"Group\",\n  palette=c(\"Control\"=\"#FFC0CB\", \"Treat\"=\"#87CEFA\"),\n  xlab=\"\", ylab=\"Abundance Score\", legend.title=\"Group\", notch=FALSE, width=0.8\n) +\n  stat_compare_means(\n    aes(group=Group), label=\"p.signif\",\n    symnum.args=list(cutpoints=c(0,0.001,0.01,0.05,1), symbols=c(\"***\",\"**\",\"*\",\"ns\")),\n    label.y.npc=\"top\", vjust=-0.5\n  ) +\n  theme_classic(base_size=14) +\n  theme(legend.position=\"top\", axis.text.x=element_text(angle=45, hjust=1),\n        axis.line=element_line(color=\"black\", size=1),\n        axis.ticks=element_line(color=\"black\", size=1),\n        plot.margin=margin(20,10,10,10)) +\n  labs(title=\"Immune Cell Abundance Comparison\",\n       subtitle=paste0(\" (Cont",
"rol n=\", countControl, \", Treat n=\", countTreat, \")\")) +\n  coord_cartesian(clip=\"off\")\n\nggsave(\"immune_abundance_boxplot.pdf\", boxplot_immune, width=8, height=6)\ncat(\">> \u7bb1\u7ebf\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1aimmune_abundance_boxplot.pdf\\n\")\n\n# \u5bfc\u51fa\u7edf\u8ba1\u8868\nsummary_table <- data_long %>%\n  filter(!is.na(Group)) %>%\n  group_by(Immune, Group) %>%\n  summarise(MeanAbundance=mean(Abundance, na.rm=TRUE), MedianAbundance=median(Abundance, na.rm=TRUE),\n            SD=sd(Abundance, na.rm=TRUE), Count=n(), .groups=\"drop\")\nwrite.csv(summary_table, file=\"boxplot_summary_table.csv\", row.names=FALSE)\n\npvalue_table <- data_long %>%\n  filter(!is.na(Group)) %>%\n  group_by(Immune) %>%\n  do(tidy(wilcox.test(Abundance ~ Group, data=.))) %>%\n  dplyr::select(Immune, p.value)\nwrite.csv(pvalue_table, file=\"immune_pvalues.csv\", row.names=FALSE)\ncat(\">> \u7edf\u8ba1\u6c47\u603b\u8868\u548cp\u503c\u8868\u5df2\u4fdd\u5b58\\n\")\n\n# ---- \u5806\u53e0\u6761\u5f62\u56fe ----\nimmune_types <- unique(data_long$Immune)\nnColors <- length(immune_types)\nmyColors <- colorRampPalette(brewer.pal(12, \"Set3\"))(nColors)\n\nbarplot_immune <- ggplot(data_long, aes(x=Sample, y=Abundance, fill=Immune)) +\n  geom_bar(stat=\"identity\") +\n  scale_fill_manual(values=myColors) +\n  scale_x_discrete(drop=FALSE) +\n  theme_minimal(base_size=18) +\n  theme(text=element_text(face=\"bold\"), axis.text.x=element_blank(),\n        axis.ticks.x=element_blank(), panel.grid.major.x=element_blank()) +\n  labs(x=NULL, y=\"Relative Abundance\", fill=\"Immune\\nCell Type\",\n       title=\"Immune Cell Abundance Distribution\", subtitle=\"Control vs. Treat\") +\n  coord_cartesian(clip=\"off\") +\n  scale_y_continuous(expand=expansion(mult=c(0.1, 0.05)))\n\ncontrol_count <- length(control_samples)\ntreat_count   <- length(treat_samples)\n\nbarplot_immune <- barplot_immune +\n  annotate(\"segment\", x=0.5, xend=control_count+0.5, y=-0.04, yend=-0.04, color=\"#D65DB1\", size=5) +\n  annotate(\"",
"text\", x=(control_count)/2+0.5, y=-0.08, label=\"Control\", color=\"#D65DB1\", size=7, fontface=\"bold\") +\n  annotate(\"segment\", x=control_count+1.5, xend=control_count+treat_count+1.5, y=-0.04, yend=-0.04, color=\"#0089BA\", size=5) +\n  annotate(\"text\", x=control_count+(treat_count)/2+1.5, y=-0.08, label=\"Treat\", color=\"#0089BA\", size=7, fontface=\"bold\")\n\nggsave(\"barplot_abundance_distribution.pdf\", barplot_immune, width=12, height=7.5)\ncat(\">> \u5806\u53e0\u6761\u5f62\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1abarplot_abundance_distribution.pdf\\n\")\n\n# ============================================================\n# \u7b2c\u4e09\u90e8\u5206\uff1a\u5173\u952e\u57fa\u56e0\u4e0e\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u7684\u76f8\u5173\u6027\u5206\u6790\n# ============================================================\ncat(\"\\n==== \u7b2c\u4e09\u90e8\u5206\uff1a\u57fa\u56e0-\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u76f8\u5173\u6027\u5206\u6790 ====\\n\")\n\n# \u8bfb\u53d6\u76ee\u6807\u57fa\u56e0\u5217\u8868\ngene_list <- read.csv(gene_list_file, header=TRUE, stringsAsFactors=FALSE)\ntargetGene <- as.character(gene_list[, 1])\ntargetGene <- targetGene[targetGene != \"\"]\n\n# \u7b5b\u9009\u76ee\u6807\u57fa\u56e0\nmatched_genes <- targetGene[targetGene %in% rownames(numExpr)]\ncat(\"\u76ee\u6807\u57fa\u56e0\u6570\uff1a\", length(targetGene), \"\uff0c\u5339\u914d\u5230\uff1a\", length(matched_genes), \"\\n\")\nexprSelected <- t(numExpr[matched_genes, , drop=FALSE])\n\n# \u4eceMCP-counter\u7ed3\u679c\u63d0\u53d6\u514d\u75ab\u7ec6\u80de\u4e30\u5ea6\u77e9\u9635\nimmune_cols <- colnames(rt)[!colnames(rt) %in% c(\"Sample\", \"Group\")]\nimmuneMat <- as.matrix(rt[, immune_cols])\nimmuneMat <- apply(immuneMat, 2, as.numeric)\nrownames(immuneMat) <- rownames(rt)\n\n# \u53d6\u5171\u540c\u6837\u672c\ncommonSamples <- intersect(rownames(exprSelected), rownames(immuneMat))\ncat(\"\u5171\u540c\u6837\u672c\u6570\uff1a\", length(commonSamples), \"\\n\")\nexprSelected <- exprSelected[commonSamples, , drop=FALSE]\nimmuneMat    <- immuneMat[commonSamples, , drop=FALSE]\n\n# \u79fb\u9664\u6807\u51c6\u5dee\u4e3a0\u7684\u514d\u75ab\u7ec6\u80de\u5217\nvalidImmune <- immuneMat[, apply(immuneMat, 2, sd) > 0, drop=FALSE]\ncat(\"\u6709\u6548\u514d\u75ab\u7ec6\u80de\u7c7b\u578b\u6570\uff1a\", ncol(validImmune), \"\\n\")\n\n# \u8ba1\u7b97Spearman\u76f8\u5173\u6027\ncor_mat     <- matrix(NA, nrow=ncol(exprSelected), ncol=ncol(validImmune),\n                      dimnames=list(colnames(exprSelected), coln",
"ames(validImmune)))\np_val_matrix <- matrix(NA, nrow=ncol(exprSelected), ncol=ncol(validImmune),\n                       dimnames=list(colnames(exprSelected), colnames(validImmune)))\n\nfor (i in seq_len(ncol(exprSelected))) {\n  for (j in seq_len(ncol(validImmune))) {\n    test_result <- cor.test(exprSelected[,i], validImmune[,j], method=\"spearman\", use=\"pairwise.complete.obs\")\n    cor_mat[i,j]     <- test_result$estimate\n    p_val_matrix[i,j] <- test_result$p.value\n  }\n}\n\n# \u521b\u5efa\u6807\u7b7e\u77e9\u9635\uff08\u76f8\u5173\u7cfb\u6570 + \u663e\u8457\u6027\u661f\u53f7\uff09\nlabels_mat <- matrix(\"\", nrow=nrow(cor_mat), ncol=ncol(cor_mat),\n                     dimnames=dimnames(cor_mat))\nfor (i in 1:nrow(cor_mat)) {\n  for (j in 1:ncol(cor_mat)) {\n    stars <- \"\"\n    if (!is.na(p_val_matrix[i,j])) {\n      if (p_val_matrix[i,j] < 0.001) stars <- \"***\"\n      else if (p_val_matrix[i,j] < 0.01) stars <- \"**\"\n      else if (p_val_matrix[i,j] < 0.05) stars <- \"*\"\n    }\n    cor_val <- ifelse(is.na(cor_mat[i,j]), \"\", round(cor_mat[i,j], 2))\n    labels_mat[i,j] <- paste0(cor_val, \"\\n\", stars)\n  }\n}\n\n# \u7ed8\u5236\u76f8\u5173\u6027\u70ed\u56fe\ngene_num   <- nrow(cor_mat)\nimmune_num <- ncol(cor_mat)\npdf_width  <- max(8, 4 + 0.5 * immune_num)\npdf_height <- max(5, 3 + 0.6 * gene_num)\nmy_col_fun <- colorRampPalette(c(\"#6b8e23\", \"white\", \"#ba6262\"))(100)\n\ncor_mat_plot <- as.matrix(as.data.frame(cor_mat))\n\npdf(\"Gene_Immune_Correlation_Heatmap.pdf\", width=pdf_width, height=pdf_height)\npheatmap(\n  cor_mat_plot, color=my_col_fun, display_numbers=labels_mat,\n  number_color=\"black\", cluster_rows=FALSE, cluster_cols=FALSE,\n  fontsize_number=7, fontsize_row=12, fontsize_col=9, border_color=\"grey90\",\n  main=\"Hub Genes - Immune Cell Abundance Correlation Heatmap\",\n  angle_col=45\n)\ndev.off()\ncat(\">> \u76f8\u5173\u6027\u70ed\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1aGene_Immune_Correlation_Heatmap.pdf\\n\")\n\n# \u5bfc\u51fa\u76f8\u5173\u6027\u7ed3\u679c\u8868\ncorrDF <- data.frame()\nfor (i in 1:nrow(cor_mat)) {\n  f",
"or (j in 1:ncol(cor_mat)) {\n    corrDF <- rbind(corrDF, data.frame(\n      Gene=rownames(cor_mat)[i], ImmuneCell=colnames(cor_mat)[j],\n      Correlation=cor_mat[i,j], P.Value=p_val_matrix[i,j],\n      Significance=ifelse(p_val_matrix[i,j] < 0.05, \"Yes\", \"No\")\n    ))\n  }\n}\nwrite.csv(corrDF, file=\"Gene_Immune_Correlation_Results.csv\", row.names=FALSE)\ncat(\">> \u76f8\u5173\u6027\u7ed3\u679c\u8868\u5df2\u4fdd\u5b58\u4e3a\uff1aGene_Immune_Correlation_Results.csv\\n\")\n\n# ============================================================\n# \u7b2c\u56db\u90e8\u5206\uff1a\u65b9\u5757\u6c14\u6ce1\u56fe\uff08Square Bubble Chart\uff09\u57fa\u56e0-\u514d\u75ab\u7ec6\u80de\u76f8\u5173\u6027\n# ============================================================\ncat(\"\\n==== \u7b2c\u56db\u90e8\u5206\uff1a\u65b9\u5757\u6c14\u6ce1\u56fe ====\\n\")\n\nlibrary(scales)\n\n# \u51c6\u5907\u6570\u636e\nbubble_df <- corrDF[!is.na(corrDF$P.Value) & !is.na(corrDF$Correlation), ]\nbubble_df$AbsCorr <- abs(bubble_df$Correlation)\n\n# \u663e\u8457\u6027\u6807\u8bb0\nbubble_df$Sig <- ifelse(bubble_df$P.Value < 0.001, \"***\",\n                 ifelse(bubble_df$P.Value < 0.01, \"**\",\n                 ifelse(bubble_df$P.Value < 0.05, \"*\", \"\")))\n\ncat(\"bubble_df \u884c\u6570\uff1a\", nrow(bubble_df), \"\\n\")\ncat(\"\u57fa\u56e0\uff1a\", paste(unique(bubble_df$Gene), collapse=\", \"), \"\\n\")\ncat(\"\u514d\u75ab\u7ec6\u80de\uff1a\", paste(unique(bubble_df$ImmuneCell), collapse=\", \"), \"\\n\")\n\n# \u514d\u75ab\u7ec6\u80de\u6309\u540d\u79f0\u6392\u5e8f\nbubble_df$ImmuneCell <- factor(bubble_df$ImmuneCell,\n                               levels = rev(sort(unique(bubble_df$ImmuneCell))))\nbubble_df$Gene <- factor(bubble_df$Gene, levels = sort(unique(as.character(bubble_df$Gene))))\n\n# \u56fe\u5c3a\u5bf8\nn_genes  <- length(unique(bubble_df$Gene))\nn_immune <- length(unique(bubble_df$ImmuneCell))\nfig_width  <- max(6, 3 + n_genes * 1.5)\nfig_height <- max(8, 2 + n_immune * 0.42)\n\npdf(\"Gene_Immune_SquareBubble.pdf\", width = fig_width-2, height = fig_height-4)\np_bubble <- ggplot(bubble_df, aes(x = Gene, y = ImmuneCell)) +\n  geom_point(aes(size = AbsCorr, fill = Correlation),\n             shape = 22, color = \"grey30\", stroke = 0.3) ",
"+\n  scale_fill_viridis_c(option = \"viridis\",\n                       limits = c(-max(bubble_df$AbsCorr), max(bubble_df$AbsCorr)),\n                       oob = squish, name = \"Correlation\",\n                       breaks = pretty(range(bubble_df$Correlation), n = 5)) +\n  scale_size_continuous(range = c(2, 10), guide = \"none\") +\n  geom_text(data = bubble_df[bubble_df$Sig != \"\", ],\n            aes(label = Sig), color = \"white\", size = 4, fontface = \"bold\", vjust = 0.5) +\n  theme(\n    panel.background = element_rect(fill = \"white\", color = \"black\", size = 1.2),\n    panel.grid.major = element_line(color = \"black\", size = 0.6),\n    panel.grid.minor = element_blank(),\n    axis.text.x = element_text(size = 12, color = \"black\", angle = 45, hjust = 1, face = \"italic\"),\n    axis.text.y = element_text(size = 10, color = \"black\"),\n    axis.title = element_blank(),\n    axis.ticks = element_line(color = \"black\", size = 0.8),\n    legend.position = \"right\",\n    legend.key.height = unit(1.8, \"cm\"),\n    legend.key.width = unit(0.4, \"cm\"),\n    legend.title = element_text(size = 11, face = \"bold\"),\n    legend.text = element_text(size = 10),\n    plot.margin = margin(10, 10, 10, 10)\n  )\nprint(p_bubble)\ndev.off()\ncat(\">> \u65b9\u5757\u6c14\u6ce1\u56fe\u5df2\u4fdd\u5b58\u4e3a\uff1aGene_Immune_SquareBubble.pdf\\n\")\n\ncat(\"\\n==== \u5168\u6d41\u7a0b\u6267\u884c\u5b8c\u6bd5\uff01====\\n\")\n")
)


list_r_stages <- function() {
  data.frame(stage=names(R_STAGES),
             source_status=vapply(names(R_STAGES),function(k).R_STAGE_META[[k]]$status,character(1)),
             row.names=NULL,check.names=FALSE)
}
check_r_inputs <- function(data_root=file.path(.tyrobp_package_root,"data","r"),stages=names(R_STAGES)) {
  rows <- lapply(stages,function(k) {
    m <- .R_STAGE_META[[k]]
    root <- if(m$root=="r") data_root else file.path(.tyrobp_package_root,"data","immune_inputs")
    files <- file.path(root,m$files)
    missing <- files[!file.exists(files)]
    missing_pkgs <- m$packages[!vapply(m$packages,requireNamespace,logical(1),quietly=TRUE)]
    data.frame(stage=k,status=if(!length(missing)&&!length(missing_pkgs))"ready" else "missing_requirements",
               missing_packages=paste(missing_pkgs,collapse="; "),
               missing_files=paste(missing,collapse="; "),stringsAsFactors=FALSE)
  })
  do.call(rbind,rows)
}
run_r_stage <- function(stage,data_root=file.path(.tyrobp_package_root,"data","r"),
                       output_root=file.path(.tyrobp_package_root,"results","r"),...) {
  if(!stage%in%names(R_STAGES))stop("Unknown stage: ",stage)
  R_STAGES[[stage]](data_root=data_root,output_root=output_root,...)
}
export_original_r_sources <- function(output_dir) {
  for(name in names(.R_ORIGINAL_SOURCES)) {
    path <- file.path(output_dir,name)
    dir.create(dirname(path),recursive=TRUE,showWarnings=FALSE)
    writeLines(.R_ORIGINAL_SOURCES[[name]],path,useBytes=TRUE)
  }
  invisible(output_dir)
}
r_cli <- function(argv=commandArgs(trailingOnly=TRUE)) {
  if(!length(argv)||"--help"%in%argv) {
    cat("TYROBP transcriptome R master\n",
        "  Rscript transcriptome_R.R --list\n",
        "  Rscript transcriptome_R.R --check\n",
        "  Rscript transcriptome_R.R --stage all\n",
        "  Rscript transcriptome_R.R --stage fig3_lasso\n",
        "  --data-root PATH     optional replacement for bundled data/r\n",
        "  --output-root PATH   default: results/r\n",
        "  --export-original-sources PATH   export historical sources without running them\n",
        "Note: image1E exact WGCNA tree and image2C-D GUI layouts are not recovered.\n",sep="")
    return(invisible(NULL))
  }
  val <- function(key,default) {
    pos <- match(key,argv)
    if(is.na(pos))return(default)
    if(pos==length(argv))stop("Missing value for ",key)
    argv[[pos+1L]]
  }
  if("--export-original-sources"%in%argv) {
    export_original_r_sources(val("--export-original-sources",NULL));return(invisible(NULL))
  }
  if("--list"%in%argv) {print(list_r_stages(),row.names=FALSE);return(invisible(NULL))}
  data_root <- val("--data-root",file.path(.tyrobp_package_root,"data","r"))
  output_root <- val("--output-root",file.path(.tyrobp_package_root,"results","r"))
  stage <- val("--stage","all")
  stages <- if(stage=="all")names(R_STAGES) else strsplit(stage,",",fixed=TRUE)[[1]]
  if(any(!stages%in%names(R_STAGES)))stop("Unknown stage(s): ",paste(setdiff(stages,names(R_STAGES)),collapse=", "))
  check <- check_r_inputs(data_root,stages)
  if("--check"%in%argv) {print(check,row.names=FALSE);return(invisible(check))}
  if(any(check$status!="ready")) {print(check,row.names=FALSE);stop("Resolve missing inputs/packages before execution.")}
  dir.create(output_root,recursive=TRUE,showWarnings=FALSE)
  results <- lapply(stages,function(k) {
    cat("Running ",k,"\n",sep="")
    tryCatch({run_r_stage(k,data_root,output_root);data.frame(stage=k,status="pass",message="")},
             error=function(e)data.frame(stage=k,status="failed",message=conditionMessage(e)))
  })
  results <- do.call(rbind,results)
  write.csv(results,file.path(output_root,"run_status.csv"),row.names=FALSE)
  print(results,row.names=FALSE)
  if(any(results$status=="failed"))stop("Some stages failed; see run_status.csv and README.")
  invisible(results)
}
if(sys.nframe()==0L)r_cli()
